#!/usr/bin/env python3
"""Generate C++ source embedding help texts, usage JSON and argument flag tables."""
import json, os, re, sys

here = os.path.dirname(os.path.abspath(__file__))
root_dir = os.path.dirname(here)
data_dir = os.path.join(root_dir, 'data')
out_path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(root_dir, 'build', 'generated_data.cpp')

def cstr_chunks(s):
    """Return C++ literal (possibly concatenated) for a string."""
    b = s.encode('utf-8')
    out = []
    chunk = []
    n = 0
    for ch in b:
        if ch == 0x5c: chunk.append('\\\\')
        elif ch == 0x22: chunk.append('\\"')
        elif ch == 0x0a: chunk.append('\\n')
        elif ch == 0x09: chunk.append('\\t')
        elif ch == 0x0d: chunk.append('\\r')
        elif 0x20 <= ch < 0x7f: chunk.append(chr(ch))
        else: chunk.append('\\%03o' % ch)
        n += 1
        if n >= 100:
            out.append('"' + ''.join(chunk) + '"')
            chunk = []; n = 0
    out.append('"' + ''.join(chunk) + '"')
    return '\n'.join(out)

root = json.load(open(os.path.join(data_dir, 'json', 'root.json')))
nodes = {}
def walk(n, path):
    nodes[tuple(path)] = n
    for s in n.get('sub_algorithms', []):
        walk(s, path + [s['name']])
walk(root, [])
nodes[('convert',)] = json.load(open(os.path.join(data_dir, 'json', 'convert.json')))
nodes[('info',)] = json.load(open(os.path.join(data_dir, 'json', 'info.json')))

def help_name(path):
    return '_'.join(path) or 'root'

entries = []
for path, n in sorted(nodes.items()):
    hp = os.path.join(data_dir, 'help', help_name(path) + '.txt')
    help_txt = open(hp).read()
    args = n.get('input_arguments', []) + n.get('output_arguments', []) + n.get('input_output_arguments', [])
    argflags = {}  # name -> (flags list, positional, metavar)
    section = None
    for line in help_txt.split('\n'):
        if re.match(r'^\S.*:$', line):
            section = line
            if section.startswith('* '):
                section = None
            continue
        if line.startswith('* ') or line.startswith('<PIPELINE>') or line.startswith('Potential steps'):
            section = None
        if section is None:
            # stop parsing once we hit the pipeline steps part
            if line.startswith('* '):
                break
            continue
        m = re.match(r'^  (-[^ ].*?)(  +)(\S.*)$', line)
        if not m:
            continue
        flags_part = m.group(1)
        m2 = re.match(r'^((?:-{1,2}[^ ,]+)(?:, -{1,2}[^ ,]+)*)( (.*))?$', flags_part)
        if not m2:
            continue
        flags = m2.group(1).split(', ')
        metavar = m2.group(3) or ''
        longs = [f[2:] for f in flags if f.startswith('--')]
        shorts = [f[1:] for f in flags if not f.startswith('--')]
        # map to json arg: canonical name is one of the long flags
        cand = None
        for a in args:
            if a['name'] in longs:
                cand = a['name']; break
        if cand is None:
            if set(longs) & {'help', 'json-usage', 'config'}:
                continue
            # 'help-doc' etc
            continue
        argflags[cand] = (shorts, longs, section.startswith('Positional'), metavar)
    # pipeline positional
    for a in args:
        if a['name'] == 'pipeline' and a['name'] not in argflags:
            argflags['pipeline'] = ([], ['pipeline'], True, '<PIPELINE>')
    # subcommand aliases from help text
    aliases = {}
    for line in help_txt.split('\n'):
        m = re.match(r'^  - ([a-z0-9-]+): +(.*?)(?: \(alias: (.*)\))?$', line)
        if m and m.group(3):
            aliases[m.group(1)] = m.group(3).split(', ')
    entries.append((path, help_txt, argflags, aliases, args))

with open(out_path, 'w') as f:
    f.write('// Generated by tools/gen_data.py. Do not edit.\n')
    f.write('#include "generated_data.h"\n\n')
    f.write('namespace gen {\n\n')
    f.write('const char* const kRootUsageJson =\n' + cstr_chunks(open(os.path.join(data_dir,'json','root.json')).read()) + ';\n\n')
    f.write('const char* const kConvertUsageJson =\n' + cstr_chunks(open(os.path.join(data_dir,'json','convert.json')).read()) + ';\n\n')
    f.write('const char* const kInfoUsageJson =\n' + cstr_chunks(open(os.path.join(data_dir,'json','info.json')).read()) + ';\n\n')
    f.write('const ArgFlagsEntry kArgFlags[] = {\n')
    for path, help_txt, argflags, aliases, args in entries:
        p = ' '.join(path)
        for name, (shorts, longs, pos, metavar) in argflags.items():
            f.write('  {%s, %s, %s, %s, %s, %s},\n' % (
                cstr_chunks(p), cstr_chunks(name), cstr_chunks(','.join(shorts)), cstr_chunks(','.join(longs)),
                'true' if pos else 'false', cstr_chunks(metavar)))
    f.write('  {nullptr, nullptr, nullptr, nullptr, false, nullptr}\n};\n\n')
    f.write('const HelpEntry kHelpTexts[] = {\n')
    for path, help_txt, argflags, aliases, args in entries:
        p = ' '.join(path)
        f.write('  {%s,\n%s},\n' % (cstr_chunks(p), cstr_chunks(help_txt)))
    f.write('  {nullptr, nullptr}\n};\n\n')
    f.write('const AliasEntry kSubAliases[] = {\n')
    for path, help_txt, argflags, aliases, args in entries:
        p = ' '.join(path)
        for sub, al in aliases.items():
            f.write('  {%s, %s, %s},\n' % (cstr_chunks(p), cstr_chunks(sub), cstr_chunks(','.join(al))))
    f.write('  {nullptr, nullptr, nullptr}\n};\n\n')
    f.write('} // namespace gen\n')

# sanity report
missing = []
for path, help_txt, argflags, aliases, args in entries:
    for a in args:
        if a['name'] not in argflags and a['name'] not in ('output-string', 'return-code'):
            missing.append((path, a['name']))
if missing:
    sys.stderr.write('WARNING: args without flags: %r\n' % missing)
EOF
