#pragma once
#include <string>
#include <vector>
#include <memory>
#include <utility>
#include <cstdint>

// Minimal JSON value with insertion-ordered objects, and serializers
// mimicking json-c output styles.
class JsonValue {
public:
    enum Type { NUL, BOOL, INT, DOUBLE, STRING, ARRAY, OBJECT };

    JsonValue() : type_(NUL) {}
    static JsonValue null() { return JsonValue(); }
