std::string jsonEscapeString(const std::string& s, bool escapeSlash) {
    std::string out;
    out.reserve(s.size() + 2);
    out += '"';
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            case '/': if (escapeSlash) out += "\\/"; else out += '/'; break;
            default:
                if (c < 0x20) {
                    char buf[8];
                    snprintf(buf, sizeof(buf), "\\u%04x", c);
                    out += buf;
                } else {
                    out += (char)c;
                }
        }
    }
    out += '"';
    return out;
}

std::string jsonFormatDouble(double d, int precision) {
    char buf[128];
    if (std::isnan(d)) return "NaN";
    if (std::isinf(d)) return d > 0 ? "Infinity" : "-Infinity";
    if (precision == -1) {
        snprintf(buf, sizeof(buf), "%.17g", d);
    } else if (precision == -2) {
        // GDAL-style: %.15g if it round trips, else %.17g
        snprintf(buf, sizeof(buf), "%.15g", d);
        if (strtod(buf, nullptr) != d) snprintf(buf, sizeof(buf), "%.17g", d);
    } else {
        snprintf(buf, sizeof(buf), "%.*g", precision, d);
    }
    std::string s = buf;
    bool looksNumeric = (s[0] >= '0' && s[0] <= '9') || (s.size() > 1 && s[0] == '-' && s[1] >= '0' && s[1] <= '9');
    if (looksNumeric && s.find('.') == std::string::npos && s.find('e') == std::string::npos) s += ".0";
    return s;
}

void JsonValue::serializeTo(std::string& out, Style style, int indent, bool escapeSlash) const {
    bool pretty = style != COMPACT;
    const char* colon = (style == PRETTY_SPACED) ? ": " : ":";
    switch (type_) {
        case NUL: out += "null"; break;
        case BOOL: out += b_ ? "true" : "false"; break;
        case INT: out += std::to_string(i_); break;
        case DOUBLE:
            if (!s_.empty()) out += s_;
            else out += jsonFormatDouble(d_, prec_);
            break;
        case STRING: out += jsonEscapeString(s_, escapeSlash); break;
        case ARRAY: {
            out += '[';
            if (arr_.empty()) {
                if (pretty) { out += '\n'; out.append(indent * 2, ' '); }
                out += ']';
                break;
            }
            for (size_t i = 0; i < arr_.size(); i++) {
                if (i) out += ',';
                if (pretty) { out += '\n'; out.append((indent + 1) * 2, ' '); }
                arr_[i].serializeTo(out, style, indent + 1, escapeSlash);
            }
            if (pretty) { out += '\n'; out.append(indent * 2, ' '); }
            out += ']';
            break;
        }
        case OBJECT: {
            out += '{';
            if (obj_.empty()) {
                if (pretty) { out += '\n'; out.append(indent * 2, ' '); }
                out += '}';
                break;
            }
            for (size_t i = 0; i < obj_.size(); i++) {
                if (i) out += ',';
                if (pretty) { out += '\n'; out.append((indent + 1) * 2, ' '); }
                out += jsonEscapeString(obj_[i].first, escapeSlash);
                out += colon;
                obj_[i].second.serializeTo(out, style, indent + 1, escapeSlash);
            }
            if (pretty) { out += '\n'; out.append(indent * 2, ' '); }
            out += '}';
            break;
        }
    }
}

std::string JsonValue::serialize(Style style, bool escapeSlash) const {
    std::string out;
    serializeTo(out, style, 0, escapeSlash);
    return out;
}

// ---------------- Parser ----------------
namespace {
struct Parser {
    const char* p;
    const char* end;
    std::string err;
    void ws() { while (p < end && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++; }
    bool fail(const char* m) { if (err.empty()) err = m; return false; }
    static void appendUtf8(std::string& s, unsigned cp) {
        if (cp < 0x80) s += (char)cp;
        else if (cp < 0x800) { s += (char)(0xC0 | (cp >> 6)); s += (char)(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { s += (char)(0xE0 | (cp >> 12)); s += (char)(0x80 | ((cp >> 6) & 0x3F)); s += (char)(0x80 | (cp & 0x3F)); }
        else { s += (char)(0xF0 | (cp >> 18)); s += (char)(0x80 | ((cp >> 12) & 0x3F)); s += (char)(0x80 | ((cp >> 6) & 0x3F)); s += (char)(0x80 | (cp & 0x3F)); }
    }
    bool parseString(std::string& s) {
        if (p >= end || *p != '"') return fail("expected string");
        p++;
        while (p < end) {
            char c = *p++;
            if (c == '"') return true;
            if (c == '\\') {
                if (p >= end) return fail("bad escape");
                char e = *p++;
                switch (e) {
                    case '"': s += '"'; break;
                    case '\\': s += '\\'; break;
                    case '/': s += '/'; break;
                    case 'b': s += '\b'; break;
                    case 'f': s += '\f'; break;
                    case 'n': s += '\n'; break;
                    case 'r': s += '\r'; break;
                    case 't': s += '\t'; break;
                    case 'u': {
                        if (end - p < 4) return fail("bad unicode escape");
                        unsigned cp = 0;
                        for (int i = 0; i < 4; i++) {
                            char h = *p++;
                            cp <<= 4;
                            if (h >= '0' && h <= '9') cp |= h - '0';
                            else if (h >= 'a' && h <= 'f') cp |= h - 'a' + 10;
                            else if (h >= 'A' && h <= 'F') cp |= h - 'A' + 10;
                            else return fail("bad unicode escape");
                        }
                        if (cp >= 0xD800 && cp <= 0xDBFF && end - p >= 6 && p[0] == '\\' && p[1] == 'u') {
                            unsigned lo = 0;
                            const char* q = p + 2;
                            bool ok = true;
                            for (int i = 0; i < 4; i++) {
                                char h = q[i];
                                lo <<= 4;
                                if (h >= '0' && h <= '9') lo |= h - '0';
                                else if (h >= 'a' && h <= 'f') lo |= h - 'a' + 10;
                                else if (h >= 'A' && h <= 'F') lo |= h - 'A' + 10;
                                else ok = false;
                            }
                            if (ok && lo >= 0xDC00 && lo <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                p = q + 4;
                            }
                        }
                        appendUtf8(s, cp);
                        break;
                    }
                    default: return fail("bad escape");
                }
            } else {
                s += c;
            }
        }
        return fail("unterminated string");
    }
    bool parseValue(JsonValue& v, int depth) {
        if (depth > 512) return fail("too deep");
        ws();
        if (p >= end) return fail("unexpected end");
        char c = *p;
        if (c == '{') {
            p++;
            v = JsonValue::object();
            ws();
            if (p < end && *p == '}') { p++; return true; }
            while (true) {
                ws();
                std::string key;
                if (!parseString(key)) return false;
                ws();
                if (p >= end || *p != ':') return fail("expected ':'");
                p++;
                JsonValue child;
                if (!parseValue(child, depth + 1)) return false;
                v.members().emplace_back(std::move(key), std::move(child));
                ws();
                if (p < end && *p == ',') { p++; continue; }
                if (p < end && *p == '}') { p++; return true; }
                return fail("expected ',' or '}'");
            }
        }
        if (c == '[') {
            p++;
            v = JsonValue::array();
            ws();
            if (p < end && *p == ']') { p++; return true; }
            while (true) {
                JsonValue child;
                if (!parseValue(child, depth + 1)) return false;
                v.push(std::move(child));
                ws();
                if (p < end && *p == ',') { p++; continue; }
                if (p < end && *p == ']') { p++; return true; }
                return fail("expected ',' or ']'");
            }
        }
        if (c == '"') {
            std::string s;
            if (!parseString(s)) return false;
            v = JsonValue::string(s);
            return true;
        }
        if (!strncmp(p, "true", 4) && end - p >= 4) { p += 4; v = JsonValue::boolean(true); return true; }
        if (!strncmp(p, "false", 5) && end - p >= 5) { p += 5; v = JsonValue::boolean(false); return true; }
        if (!strncmp(p, "null", 4) && end - p >= 4) { p += 4; v = JsonValue::null(); return true; }
        if (!strncmp(p, "NaN", 3) && end - p >= 3) { p += 3; v = JsonValue::number(NAN); return true; }
        if (!strncmp(p, "Infinity", 8) && end - p >= 8) { p += 8; v = JsonValue::number(INFINITY); return true; }
        if (!strncmp(p, "-Infinity", 9) && end - p >= 9) { p += 9; v = JsonValue::number(-INFINITY); return true; }
        if (c == '-' || (c >= '0' && c <= '9')) {
            const char* start = p;
            if (*p == '-') p++;
            bool isInt = true;
            while (p < end && *p >= '0' && *p <= '9') p++;
            if (p < end && *p == '.') { isInt = false; p++; while (p < end && *p >= '0' && *p <= '9') p++; }
            if (p < end && (*p == 'e' || *p == 'E')) {
                isInt = false; p++;
                if (p < end && (*p == '+' || *p == '-')) p++;
                while (p < end && *p >= '0' && *p <= '9') p++;
            }
            std::string num(start, p);
            if (isInt) {
                errno = 0;
                long long ll = strtoll(num.c_str(), nullptr, 10);
                if (errno == ERANGE) {
                    v = JsonValue::number(strtod(num.c_str(), nullptr));
                    v.setRawNumber(num);
                } else {
                    v = JsonValue::integer(ll);
                }
            } else {
                v = JsonValue::number(strtod(num.c_str(), nullptr));
                v.setRawNumber(num);
            }
            return true;
        }
        return fail("unexpected character");
    }
};
}

bool JsonValue::parse(const std::string& text, JsonValue& out, std::string* err) {
    Parser ps;
    ps.p = text.data();
    ps.end = text.data() + text.size();
    if (!ps.parseValue(out, 0)) { if (err) *err = ps.err; return false; }
    ps.ws();
    if (ps.p != ps.end) { if (err) *err = "trailing characters"; return false; }
    return true;
}
