static ArgType argTypeFromString(const std::string& s) {
    if (s == "boolean") return ArgType::Boolean;
    if (s == "string") return ArgType::String;
    if (s == "integer") return ArgType::Integer;
    if (s == "real") return ArgType::Real;
    if (s == "string_list") return ArgType::StringList;
    if (s == "integer_list") return ArgType::IntegerList;
    if (s == "real_list") return ArgType::RealList;
    if (s == "dataset") return ArgType::Dataset;
    if (s == "dataset_list") return ArgType::DatasetList;
    return ArgType::String;
}

static void loadArg(ArgDef& a, const JsonValue& j) {
    a.raw = j;
    a.name = j.getString("name");
    a.type = argTypeFromString(j.getString("type"));
    a.description = j.getString("description");
    a.metavar = j.getString("metavar");
    a.category = j.getString("category");
    a.mutexGroup = j.getString("mutual_exclusion_group");
    a.required = j.getBool("required");
    a.packed = j.getBool("packed_values_allowed");
    a.repeated = j.getBool("repeated_arg_allowed", true);
    a.minCount = (int)j.getInt("min_count", 0);
    a.maxCount = (int)j.getInt("max_count", 0x7fffffff);
    if (j.has("min_value")) { a.hasMin = true; a.minVal = j.getDouble("min_value"); a.minIncl = j.getBool("min_value_is_included", true); }
    if (j.has("max_value")) { a.hasMax = true; a.maxVal = j.getDouble("max_value"); a.maxIncl = j.getBool("max_value_is_included", true); }
    if (j.has("default")) a.defaultValue = j.get("default");
    if (j.has("choices")) for (auto& c : j.get("choices").items()) a.choices.push_back(c.asString());
    if (j.has("dataset_type")) for (auto& c : j.get("dataset_type").items()) a.datasetTypes.push_back(c.asString());
    if (j.has("input_flags")) for (auto& c : j.get("input_flags").items()) a.inputFlags.push_back(c.asString());
    if (j.has("output_flags")) for (auto& c : j.get("output_flags").items()) a.outputFlags.push_back(c.asString());
}

void Algorithm::loadFromJson(const JsonValue& j, const std::vector<std::string>& parentPath) {
    rawJson = j;
    path = parentPath;
    if (j.has("name")) { name = j.getString("name"); path.push_back(name); }
    else { name = "gdal"; path = {"gdal"}; }
    description = j.getString("description");
    shortUrl = j.getString("short_url");
    url = j.getString("url");
    supportsStreamedOutput = j.getBool("supports_streamed_output");
    for (auto& ja : j.get("input_arguments").items()) { ArgDef a; loadArg(a, ja); args.push_back(a); }
    for (auto& ja : j.get("output_arguments").items()) { ArgDef a; loadArg(a, ja); a.isOutput = true; a.hidden = true; args.push_back(a); }
    for (auto& ja : j.get("input_output_arguments").items()) { ArgDef a; loadArg(a, ja); a.isInputOutput = true; args.push_back(a); }
    for (auto& js : j.get("sub_algorithms").items()) {
        auto sub = std::make_unique<Algorithm>();
        sub->loadFromJson(js, path);
        subs.push_back(std::move(sub));
    }
}

static std::string pathKey(const std::vector<std::string>& path) {
    std::string s;
    for (size_t i = 1; i < path.size(); i++) { if (i > 1) s += ' '; s += path[i]; }
    return s;
}

void Algorithm::attachFlagsAndHelp() {
    std::string key = pathKey(path);
    for (const gen::HelpEntry* h = gen::kHelpTexts; h->path; h++) {
        if (key == h->path) { helpText = h->text; break; }
    }
    for (const gen::ArgFlagsEntry* e = gen::kArgFlags; e->path; e++) {
        if (key != e->path) continue;
        ArgDef* a = findArg(e->name);
        if (!a) continue;
        a->shortFlags = splitString(e->shorts, ',');
        a->longFlags = splitString(e->longs, ',');
        a->positional = e->positional;
        a->helpMetavar = e->metavar;
    }
    for (auto& a : args) {
        if (a.longFlags.empty() && !a.isOutput) {
            a.longFlags.push_back(a.name);
            a.hidden = true;
        }
    }
    for (const gen::AliasEntry* e = gen::kSubAliases; e->path; e++) {
        if (key != e->path) continue;
        for (auto& al : splitString(e->aliases, ',')) subAliases[al] = e->sub;
    }
    for (auto& s : subs) s->attachFlagsAndHelp();
}

static std::unique_ptr<Algorithm> g_root;

Algorithm* buildAlgorithmTree() {
    if (g_root) return g_root.get();
    JsonValue j;
    std::string err;
    if (!JsonValue::parse(gen::kRootUsageJson, j, &err)) {
        fprintf(stderr, "internal error: cannot parse usage json: %s\n", err.c_str());
        exit(2);
    }
    g_root = std::make_unique<Algorithm>();
    g_root->loadFromJson(j, {});
    // Hidden shortcuts: convert, info
    {
        JsonValue jc;
        JsonValue::parse(gen::kConvertUsageJson, jc, &err);
        auto sub = std::make_unique<Algorithm>();
        sub->loadFromJson(jc, {"gdal"});
        sub->name = "convert"; sub->path = {"gdal", "convert"};
        sub->hiddenFromJson = true;
        g_root->subs.push_back(std::move(sub));
        JsonValue ji;
        JsonValue::parse(gen::kInfoUsageJson, ji, &err);
        auto sub2 = std::make_unique<Algorithm>();
        sub2->loadFromJson(ji, {"gdal"});
        sub2->name = "info"; sub2->path = {"gdal", "info"};
        sub2->hiddenFromJson = true;
        g_root->subs.push_back(std::move(sub2));
    }
    g_root->attachFlagsAndHelp();
    registerCommands(g_root.get());
    return g_root.get();
}

Algorithm* getRootAlgorithm() { return buildAlgorithmTree(); }

Algorithm* Algorithm::findSub(const std::string& n) {
    std::string real = n;
    auto it = subAliases.find(n);
    if (it != subAliases.end()) real = it->second;
    for (auto& s : subs) if (s->name == real) return s.get();
    return nullptr;
}
const ArgDef* Algorithm::findArgByLong(const std::string& n) const {
    for (auto& a : args) for (auto& f : a.longFlags) if (f == n) return &a;
    return nullptr;
}
const ArgDef* Algorithm::findArgByShort(const std::string& n) const {
    for (auto& a : args) for (auto& f : a.shortFlags) if (f == n) return &a;
    return nullptr;
}
ArgDef* Algorithm::findArg(const std::string& n) {
    for (auto& a : args) if (a.name == n) return &a;
    return nullptr;
}
const ArgDef* Algorithm::findArg(const std::string& n) const {
    for (auto& a : args) if (a.name == n) return &a;
    return nullptr;
}

bool Algorithm::isSet(const std::string& n) const {
    auto it = values.find(n);
    return it != values.end() && it->second.specified;
}
const ArgValue& Algorithm::val(const std::string& n) const {
    static ArgValue empty;
    auto it = values.find(n);
    return it != values.end() ? it->second : empty;
}
std::string Algorithm::getString(const std::string& n, const std::string& def) const {
    const ArgValue& v = val(n);
    if (v.specified && !v.values.empty()) return v.values[0];
    const ArgDef* d = findArg(n);
    if (d && d->defaultValue.isString()) return d->defaultValue.asString();
    return def;
}
bool Algorithm::getBool(const std::string& n) const {
    const ArgValue& v = val(n);
    if (v.specified) return v.boolValue;
    const ArgDef* d = findArg(n);
    if (d && d->defaultValue.isBool()) return d->defaultValue.asBool();
    return false;
}
long long Algorithm::getInt(const std::string& n, long long def) const {
    const ArgValue& v = val(n);
    if (v.specified && !v.values.empty()) return v.asInt();
    const ArgDef* d = findArg(n);
    if (d && d->defaultValue.isNumber()) return d->defaultValue.asInt();
    return def;
}
double Algorithm::getReal(const std::string& n, double def) const {
    const ArgValue& v = val(n);
    if (v.specified && !v.values.empty()) return v.asReal();
    const ArgDef* d = findArg(n);
    if (d && d->defaultValue.isNumber()) return d->defaultValue.asDouble();
    return def;
}
std::vector<std::string> Algorithm::getStringList(const std::string& n) const {
    const ArgValue& v = val(n);
    if (v.specified) return v.values;
    const ArgDef* d = findArg(n);
    std::vector<std::string> r;
    if (d && d->defaultValue.isArray()) for (auto& x : d->defaultValue.items()) r.push_back(x.isString() ? x.asString() : x.serialize(JsonValue::COMPACT));
    else if (d && d->defaultValue.isString()) r.push_back(d->defaultValue.asString());
    return r;
}
std::vector<long long> Algorithm::getIntList(const std::string& n) const {
    const ArgValue& v = val(n);
    if (v.specified) return v.asIntList();
    const ArgDef* d = findArg(n);
    std::vector<long long> r;
    if (d && d->defaultValue.isArray()) for (auto& x : d->defaultValue.items()) r.push_back(x.asInt());
    return r;
}
std::vector<double> Algorithm::getRealList(const std::string& n) const {
    const ArgValue& v = val(n);
    if (v.specified) return v.asRealList();
    const ArgDef* d = findArg(n);
    std::vector<double> r;
    if (d && d->defaultValue.isArray()) for (auto& x : d->defaultValue.items()) r.push_back(x.asDouble());
    return r;
}

std::string Algorithm::fullPathStr() const {
    const std::vector<std::string>& p = usagePath.empty() ? path : usagePath;
    std::string s;
    for (size_t i = 0; i < p.size(); i++) { if (i) s += ' '; s += p[i]; }
    return s;
}

static std::string upperMetavarFromName(const std::string& n) {
    std::string s;
    for (char c : n) s += (char)toupper((unsigned char)c);
    return s;
}

std::string Algorithm::usageLine() const {
    if (helpText) {
        // First line of embedded help with possibly substituted path
        const char* nl = strchr(helpText, '\n');
        std::string first(helpText, nl ? nl - helpText : strlen(helpText));
        if (!usagePath.empty()) {
            std::string orig = "Usage: ";
            for (size_t i = 0; i < path.size(); i++) { if (i) orig += ' '; orig += path[i]; }
            if (first.compare(0, orig.size(), orig) == 0) first = "Usage: " + fullPathStr() + first.substr(orig.size());
        }
        return first;
    }
    std::string s = "Usage: " + fullPathStr();
    if (hasSubs()) {
        s += path.size() == 1 ? " <COMMAND> [OPTIONS]" : " <SUBCOMMAND> [OPTIONS]";
        return s;
    }
    s += " [OPTIONS]";
    for (auto& a : args) {
        if (!a.positional || a.hidden) continue;
        std::string mv = a.helpMetavar.empty() ? "<" + upperMetavarFromName(a.name) + ">" : a.helpMetavar;
        s += " " + mv;
        if (a.isList() && a.maxCount > 1) s += "...";
    }
    return s;
}

std::string Algorithm::shortUsage() const {
    std::string s = usageLine() + "\n";
    if (hasSubs() && helpText) {
        // Reproduce the list of subcommands, then "Try" line, then footer bits
        std::string ht = helpText;
        size_t common = ht.find("\nCommon Options:\n");
        std::string head = common != std::string::npos ? ht.substr(0, common + 1) : ht;
        // head includes "Usage..." and subcommand list and trailing blank line
        // Replace first line with usage line
        size_t nl = head.find('\n');
        s = usageLine() + head.substr(nl);
        s += "Try '" + fullPathStr() + " --help' for help.\n";
        // rest: find after options block: first occurrence of "\n\n" after "Options" blocks that is followed by non-option text
        size_t pos = common;
        if (pos != std::string::npos) {
            // skip option sections: find the first blank line followed by a line not starting with space and not "Options"/"Common Options"
            size_t cur = pos + 1;
            while (true) {
                size_t blank = ht.find("\n\n", cur);
                if (blank == std::string::npos) { cur = ht.size(); break; }
                size_t next = blank + 2;
                if (next >= ht.size()) { cur = ht.size(); break; }
                // peek at the next line
                size_t eol = ht.find('\n', next);
                std::string line = ht.substr(next, eol == std::string::npos ? std::string::npos : eol - next);
                if (!line.empty() && line.back() == ':' && line[0] != ' ') { cur = next; continue; }
                cur = next;
                break;
            }
            if (cur < ht.size()) { s += "\n"; s += ht.substr(cur); }
        }
        return s;
    }
    s += "Try '" + fullPathStr() + " --help' for help.\n";
    return s;
}

std::string Algorithm::fullHelp() const {
    if (helpText) {
        std::string ht = helpText;
        if (!usagePath.empty()) {
            size_t nl = ht.find('\n');
            ht = usageLine() + ht.substr(nl);
        }
        return ht;
    }
    return usageLine() + "\n";
}

std::string Algorithm::jsonUsage() const {
    return rawJson.serialize(JsonValue::PRETTY, true);
}

