// ---------------------------------------------------------------------------
static size_t levenshtein(const std::string& a, const std::string& b) {
    size_t n = a.size(), m = b.size();
    std::vector<size_t> prev(m + 1), cur(m + 1);
    for (size_t j = 0; j <= m; j++) prev[j] = j;
    for (size_t i = 1; i <= n; i++) {
        cur[0] = i;
        for (size_t j = 1; j <= m; j++) {
            size_t cost = a[i - 1] == b[j - 1] ? 0 : 1;
            cur[j] = std::min({prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost});
        }
        std::swap(prev, cur);
    }
    return prev[m];
}

std::string levenshteinBest(const std::string& name, const std::vector<std::pair<std::string,bool>>& candidates) {
    std::string best;
    bool bestIsLong = false;
    size_t bestDist = (size_t)-1;
    bool tie = false;
    for (auto& c : candidates) {
        size_t d = levenshtein(name, c.first);
        if (d < bestDist) { bestDist = d; best = c.first; bestIsLong = c.second; tie = false; }
        else if (d == bestDist) { tie = true; }
    }
    if (tie || bestDist > 2 || !bestIsLong) return "";
    return best;
}

std::string Algorithm::suggestArgName(const std::string& n) const {
    std::vector<std::pair<std::string,bool>> cands;
    for (auto& a : args) {
        if (a.isOutput) continue;
        for (auto& f : a.longFlags) cands.emplace_back(f, true);
        for (auto& f : a.shortFlags) cands.emplace_back(f, false);
    }
    cands.emplace_back("help", true);
    cands.emplace_back("json-usage", true);
    cands.emplace_back("config", true);
    cands.emplace_back("h", false);
    return levenshteinBest(n, cands);
}

// ---------------------------------------------------------------------------
static bool isNumericToken(const std::string& s) {
    // mimic CPLGetValueType != STRING : integer or real
    if (s.empty()) return false;
    char* end = nullptr;
    strtod(s.c_str(), &end);
    if (end == s.c_str()) return false;
    while (*end == ' ') end++;
    return *end == 0;
}

static std::vector<std::string> tokenizeCommaHonourStrings(const std::string& s) {
    // Split on commas, honouring double quotes.
    std::vector<std::string> out;
    std::string cur;
    bool inQuote = false;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (c == '"') { inQuote = !inQuote; continue; }
        if (c == ',' && !inQuote) { out.push_back(cur); cur.clear(); continue; }
        cur += c;
    }
    out.push_back(cur);
    return out;
}

static std::string typeNameForList(ArgType t) {
    switch (t) {
        case ArgType::IntegerList: return "integer";
        case ArgType::RealList: return "real";
        default: return "string";
    }
}

static bool parseIntStrict(const std::string& s, long long& out) {
    std::string t = trimString(s);
    if (t.empty()) return false;
    char* end = nullptr;
    errno = 0;
    long long v = strtoll(t.c_str(), &end, 10);
    if (errno == ERANGE || *end != 0) return false;
    if (v < -2147483648LL || v > 2147483647LL) return false;
    out = v;
    return true;
}

bool Algorithm::checkListValue(const ArgDef& def, const std::string& displayName, const std::string& value, std::vector<std::string>& out) {
    std::vector<std::string> toks;
    if (def.packed) {
        toks = splitString(value, ',');
    } else {
        toks.push_back(value);
    }
    for (auto& t : toks) {
        std::string tt = def.packed ? trimString(t) : t;
        if (def.type == ArgType::IntegerList) {
            long long v;
            if (!parseIntStrict(tt, v)) {
                reportError(5, "Expected list of integer value for argument '" + displayName + "', but got '" + value + "'.");
                return false;
            }
        } else if (def.type == ArgType::RealList) {
            if (!isRealString(tt)) {
                reportError(5, "Expected list of real value for argument '" + displayName + "', but got '" + value + "'.");
                return false;
            }
        }
        out.push_back(tt);
    }
    return true;
}

bool Algorithm::setArgValue(const ArgDef& def, const std::string& displayName, const std::string& value, bool fromEqual) {
    (void)fromEqual;
    ArgValue& v = values[def.name];
    if (def.type == ArgType::Boolean) {
        if (v.specified) { reportError(5, "Argument '" + displayName + "' has already been specified."); return false; }
        if (value == "true") v.boolValue = true;
        else if (value == "false") v.boolValue = false;
        else { reportError(5, "Invalid value '" + value + "' for boolean argument '" + displayName + "'. Should be 'true' or 'false'."); return false; }
        v.specified = true; v.explicitlySet = true; v.specCount++;
        v.values = {value};
        return true;
    }
    if (!def.isList()) {
        if (v.specified) { reportError(5, "Argument '" + displayName + "' has already been specified."); return false; }
        if (def.type == ArgType::Integer) {
            long long iv;
            if (!parseIntStrict(value, iv)) { reportError(5, "Expected integer value for argument '" + displayName + "', but got '" + value + "'."); return false; }
        } else if (def.type == ArgType::Real) {
            if (!isRealString(value)) { reportError(5, "Expected real value for argument '" + displayName + "', but got '" + value + "'."); return false; }
        }
        v.specified = true; v.explicitlySet = true; v.specCount++;
        v.values = {value};
        return true;
    }
    // list
    if (v.specified && !def.repeated) { reportError(5, "Argument '" + displayName + "' has already been specified."); return false; }
    std::vector<std::string> toks;
    if (!checkListValue(def, displayName, value, toks)) return false;
    v.specified = true; v.explicitlySet = true; v.specCount++;
    for (auto& t : toks) v.values.push_back(t);
    return true;
}

bool Algorithm::parseOptionsLoop(std::vector<std::string>& lArgs) {
    for (size_t i = 0; i < lArgs.size();) {
        std::string strArg = lArgs[i];
        const ArgDef* arg = nullptr;
        std::string dispName;
        std::string value;
        bool hasValue = false;
        if (strArg == "--help" || strArg == "-h" || strArg == "help") {
            helpRequested = true; return true;
        }
        if (strArg == "--help-doc") { helpDocRequested = true; return true; }
        if (strArg == "--json-usage") { jsonUsageRequested = true; return true; }
        if (strArg == "--config" || strArg.compare(0, 9, "--config=") == 0) {
            if (strArg == "--config") {
                if (i + 1 >= lArgs.size()) { cplError(1, "--config option given without a key and value argument."); return false; }
                std::string kv = lArgs[i + 1];
                if (kv.find('=') == std::string::npos) {
                    if (i + 2 >= lArgs.size()) { cplError(1, "--config option given without a key and value argument."); return false; }
                    kv += "=" + lArgs[i + 2];
                    lArgs.erase(lArgs.begin() + i, lArgs.begin() + i + 3);
                } else {
                    lArgs.erase(lArgs.begin() + i, lArgs.begin() + i + 2);
                }
                configOptions.push_back(kv);
            } else {
                configOptions.push_back(strArg.substr(9));
                lArgs.erase(lArgs.begin() + i);
            }
            continue;
        }
        if (strArg.size() >= 2 && strArg[0] == '-' && strArg[1] == '-') {
            size_t eq = strArg.find('=');
            std::string nm = eq != std::string::npos ? strArg.substr(0, eq) : strArg;
            std::string nmNoDash = nm.substr(2);
            arg = findArgByLong(nmNoDash);
            if (!arg || arg->isOutput) {
                std::string best = suggestArgName(nmNoDash);
                if (!best.empty()) reportError(5, "Option '" + nm + "' is unknown. Do you mean '--" + best + "'?");
                else reportError(5, "Option '" + nm + "' is unknown.");
                return false;
            }
            dispName = nm;
            if (eq != std::string::npos) { hasValue = true; value = strArg.substr(eq + 1); }
        } else if (strArg.size() >= 2 && strArg[0] == '-' && !isNumericToken(strArg)) {
            for (size_t j = 1; j < strArg.size(); j++) {
                std::string nm = strArg.substr(j, 1);
                arg = findArgByShort(nm);
                if (!arg) {
                    std::string best = suggestArgName(strArg.substr(1));
                    if (!best.empty()) reportError(5, "Short name option '" + nm + "' is unknown. Do you mean '--" + best + "' (with leading double dash) ?");
                    else reportError(5, "Short name option '" + nm + "' is unknown.");
                    return false;
                }
                dispName = nm;
                if (strArg.size() > 2) {
                    if (arg->type != ArgType::Boolean) {
                        reportError(5, "Invalid argument '" + strArg + "'. Option '" + nm + "' is not a boolean option.");
                        return false;
                    }
                    if (!setArgValue(*arg, nm, "true", false)) return false;
                }
            }
            if (strArg.size() > 2) { lArgs.erase(lArgs.begin() + i); continue; }
        } else {
            ++i;
            continue;
        }
        if (arg->type == ArgType::Boolean) {
            if (!hasValue) { hasValue = true; value = "true"; }
        } else if (!hasValue) {
            if (i + 1 == lArgs.size()) {
                reportError(5, "Expected value for argument '" + dispName + "', but ran short of tokens");
                return false;
            }
            hasValue = true;
            value = lArgs[i + 1];
            lArgs.erase(lArgs.begin() + i + 1);
        }
        if (!setArgValue(*arg, dispName, value, false)) return false;
        lArgs.erase(lArgs.begin() + i);
    }
    return true;
}

bool Algorithm::parse(const std::vector<std::string>& tokens) {
    if (hasSubs()) {
        if (tokens.empty()) {
            reportError(1, std::string("Missing ") + (path.size() == 1 ? "command" : "subcommand") + " name.");
            return false;
        }
        if (!tokens[0].empty() && tokens[0][0] != '-' && tokens[0] != "help") {
            Algorithm* sub = findSub(tokens[0]);
            if (sub) {
                selectedSub = sub;
                sub->configOptions = configOptions;
                std::vector<std::string> rest(tokens.begin() + 1, tokens.end());
                bool ret = sub->parse(rest);
                if (sub->helpRequested) helpRequested = true;
                if (sub->jsonUsageRequested) jsonUsageRequested = true;
                if (sub->helpDocRequested) helpDocRequested = true;
                return ret;
            }
            reportError(1, "Unknown command: '" + tokens[0] + "'");
            return false;
        }
    }
    std::vector<std::string> lArgs(tokens);
    if (!parseOptionsLoop(lArgs)) return false;
    if (helpRequested || jsonUsageRequested || helpDocRequested) return true;
    if (hasSubs()) {
        if (!lArgs.empty()) {
            // Options followed by subcommand
            Algorithm* sub = findSub(lArgs[0]);
            if (sub && lArgs[0] != "help") {
                selectedSub = sub;
                sub->configOptions = configOptions;
                std::vector<std::string> rest(lArgs.begin() + 1, lArgs.end());
                bool ret = sub->parse(rest);
                if (sub->helpRequested) helpRequested = true;
                if (sub->jsonUsageRequested) jsonUsageRequested = true;
                return ret;
            }
            if (lArgs[0] == "help") { helpRequested = true; return true; }
            reportError(1, "Positional values starting at '" + lArgs[0] + "' are not expected.");
            return false;
        }
        reportError(1, std::string("Missing ") + (path.size() == 1 ? "command" : "subcommand") + " name.");
        return false;
    }

    // Positional arguments
    std::vector<const ArgDef*> positionals;
    for (auto& a : args) if (a.positional && !a.isOutput) positionals.push_back(&a);
    // Count unset positionals and required ones
    size_t iCurPos = 0;
    // Determine which positionals are already set via named options
    std::vector<const ArgDef*> remaining;
    for (auto* p : positionals) if (!values[p->name].specified) remaining.push_back(p);

    // Assign: GDAL logic - fill from start, with a variable-count list taking the leftover
    size_t nValues = lArgs.size();
    // Compute minimum tokens needed by the others
    if (!remaining.empty() && nValues > 0) {
        // Find how many positionals have variable count (list with min != max)
        size_t nFixedAfter = 0;
        size_t idxVar = (size_t)-1;
        for (size_t k = 0; k < remaining.size(); k++) {
            const ArgDef* p = remaining[k];
            bool variable = p->isList() && p->minCount != p->maxCount;
            if (variable && idxVar == (size_t)-1) idxVar = k;
        }
        size_t vi = 0;
        for (size_t k = 0; k < remaining.size() && vi < nValues; k++) {
            const ArgDef* p = remaining[k];
            size_t take = 1;
            if (p->isList()) {
                if (p->minCount == p->maxCount && p->minCount > 0) take = p->minCount;
                else {
                    // variable: take all but what is needed by the following positionals
                    size_t needAfter = 0;
                    for (size_t k2 = k + 1; k2 < remaining.size(); k2++) {
                        const ArgDef* q = remaining[k2];
                        needAfter += (q->isList() && q->minCount == q->maxCount && q->minCount > 0) ? q->minCount : 1;
                    }
                    size_t avail = nValues - vi;
                    take = avail > needAfter ? avail - needAfter : 0;
                    if (p->maxCount > 0 && take > (size_t)p->maxCount) take = p->maxCount;
                    if (take == 0 && k + 1 < remaining.size()) { continue; }
                }
            }
            (void)nFixedAfter;
            if (vi + take > nValues) take = nValues - vi;
            ArgValue& v = values[p->name];
            for (size_t t = 0; t < take; t++) {
                std::vector<std::string> toks;
                if (p->isList()) {
                    if (!checkListValue(*p, p->name, lArgs[vi + t], toks)) return false;
                } else {
                    if (p->type == ArgType::Integer) {
                        long long iv;
                        if (!parseIntStrict(lArgs[vi + t], iv)) { reportError(5, "Expected integer value for argument '" + p->name + "', but got '" + lArgs[vi + t] + "'."); return false; }
                    } else if (p->type == ArgType::Real) {
                        if (!isRealString(lArgs[vi + t])) { reportError(5, "Expected real value for argument '" + p->name + "', but got '" + lArgs[vi + t] + "'."); return false; }
                    }
                    toks.push_back(lArgs[vi + t]);
                }
                for (auto& tk : toks) v.values.push_back(tk);
                v.specified = true;
            }
            vi += take;
            iCurPos++;
        }
        if (vi < nValues) {
            reportError(1, "Positional values starting at '" + lArgs[vi] + "' are not expected.");
            return false;
        }
    } else if (nValues > 0) {
        reportError(1, "Positional values starting at '" + lArgs[0] + "' are not expected.");
        return false;
    } else if (!remaining.empty()) {
        // No positional values given at all: if the first unset positional is required, error
        for (auto* p : remaining) {
            if (p->required) {
                std::string mv = p->helpMetavar.empty() ? upperMetavarFromName(p->name) : p->helpMetavar;
                if (mv.size() >= 2 && mv.front() == '<' && mv.back() == '>') mv = mv.substr(1, mv.size() - 2);
                reportError(1, "Positional arguments starting at '" + mv + "' have not been specified.");
                return false;
            }
        }
    }
    return validate();
}

bool Algorithm::validate() {
    bool ok = true;
    // Mutual exclusion
    std::map<std::string, std::vector<std::string>> groups;
    for (auto& a : args) if (!a.mutexGroup.empty() && values[a.name].specified) groups[a.mutexGroup].push_back(a.name);
    for (auto& g : groups) {
        if (g.second.size() > 1) {
            reportError(1, "Argument '" + g.second[1] + "' is mutually exclusive with '" + g.second[0] + "'.");
            return false;
        }
    }
    for (auto& a : args) {
        if (a.isOutput) continue;
        ArgValue& v = values[a.name];
        if (!v.specified) {
            if (a.required) {
                reportError(1, "Required argument '" + a.name + "' has not been specified.");
                ok = false;
            }
            continue;
        }
        if (a.isList()) {
            int n = (int)v.values.size();
            if (a.minCount == a.maxCount && n != a.minCount) {
                char buf[256];
                snprintf(buf, sizeof(buf), "%d value%s been specified for argument '%s', whereas exactly %d %s expected.",
                         n, n == 1 ? " has" : "s have", a.name.c_str(), a.minCount, a.minCount == 1 ? "was" : "were");
                reportError(1, buf);
                ok = false;
            } else if (n < a.minCount) {
                char buf[256];
                snprintf(buf, sizeof(buf), "Only %d value%s been specified for argument '%s', whereas at least %d %s expected.",
                         n, n == 1 ? " has" : "s have", a.name.c_str(), a.minCount, a.minCount == 1 ? "was" : "were");
                reportError(1, buf);
                ok = false;
            } else if (n > a.maxCount) {
                char buf[256];
                snprintf(buf, sizeof(buf), "%d value%s been specified for argument '%s', whereas at most %d %s expected.",
                         n, n == 1 ? " has" : "s have", a.name.c_str(), a.maxCount, a.maxCount == 1 ? "was" : "were");
                reportError(1, buf);
                ok = false;
            }
        }
        // choices
        if (!a.choices.empty()) {
            for (auto& s : v.values) {
                bool found = false;
                for (auto& c : a.choices) if (strcasecmp(c.c_str(), s.c_str()) == 0) { found = true; break; }
                if (!found) {
                    std::string list;
                    for (size_t k = 0; k < a.choices.size(); k++) { if (k) list += ", "; list += "'" + a.choices[k] + "'"; }
                    cplError(5, "Invalid value '" + s + "' for string argument '" + a.name + "'. Should be one among " + list + ".");
                    return false;
                }
            }
            // normalize to canonical case
            for (auto& s : v.values) for (auto& c : a.choices) if (strcasecmp(c.c_str(), s.c_str()) == 0) { s = c; break; }
        }
        // numeric range
        if (a.type == ArgType::Integer || a.type == ArgType::IntegerList || a.type == ArgType::Real || a.type == ArgType::RealList) {
            for (auto& s : v.values) {
                double d = strtod(s.c_str(), nullptr);
                bool isInt = a.type == ArgType::Integer || a.type == ArgType::IntegerList;
                if (a.hasMin && (a.minIncl ? d < a.minVal : d <= a.minVal)) {
                    std::string sv = isInt ? std::to_string((long long)d) : formatDoubleG(d);
                    std::string smin = isInt ? std::to_string((long long)a.minVal) : formatDoubleG(a.minVal);
                    cplError(5, "Value of argument '" + a.name + "' is " + sv + ", but should be " + (a.minIncl ? ">= " : "> ") + smin);
                    return false;
                }
                if (a.hasMax && (a.maxIncl ? d > a.maxVal : d >= a.maxVal)) {
                    std::string sv = isInt ? std::to_string((long long)d) : formatDoubleG(d);
                    std::string smax = isInt ? std::to_string((long long)a.maxVal) : formatDoubleG(a.maxVal);
                    cplError(5, "Value of argument '" + a.name + "' is " + sv + ", but should be " + (a.maxIncl ? "<= " : "< ") + smax);
                    return false;
                }
            }
        }
    }
    return ok;
}

int Algorithm::run() {
    if (selectedSub) return selectedSub->run();
    if (runFn) return runFn(*this);
    reportError(1, "Not implemented");
    return 1;
}
