// ---------------------------------------------------------------------------
long long ArgValue::asInt() const { return values.empty() ? 0 : strtoll(values[0].c_str(), nullptr, 10); }
double ArgValue::asReal() const { return values.empty() ? 0.0 : strtod(values[0].c_str(), nullptr); }
std::vector<long long> ArgValue::asIntList() const {
    std::vector<long long> r;
    for (auto& v : values) r.push_back(strtoll(v.c_str(), nullptr, 10));
    return r;
}
std::vector<double> ArgValue::asRealList() const {
    std::vector<double> r;
    for (auto& v : values) r.push_back(parseRealStrict(v));
    return r;
