static int runAlgorithmFromParse(Algorithm* alg, bool parseOk) {
    // Find the deepest selected algorithm
    Algorithm* leaf = alg;
    while (leaf->selectedSub) leaf = leaf->selectedSub;
    if (leaf->helpRequested) {
        fputs(leaf->fullHelp().c_str(), stdout);
        return 0;
    }
    if (leaf->helpDocRequested) {
        std::string h = leaf->fullHelp();
        size_t pos = h.find("\nFor more details, consult ");
        if (pos != std::string::npos) h = h.substr(0, pos + 1);
        else {
            pos = h.find("\nWARNING: the gdal command");
            if (pos != std::string::npos) h = h.substr(0, pos + 1);
        }
        // help-doc output omits the footer: strip trailing blank line
        while (h.size() >= 2 && h[h.size() - 1] == '\n' && h[h.size() - 2] == '\n') h.pop_back();
        fputs(h.c_str(), stdout);
        return 0;
    }
    if (leaf->jsonUsageRequested) {
        fputs(leaf->jsonUsage().c_str(), stdout);
        return 0;
    }
    if (!parseOk) {
        leaf->printUsageOnError();
        return 1;
    }
    if (leaf->hasSubs() && !leaf->selectedSub) {
        leaf->printUsageOnError();
        return 1;
    }
    return leaf->run();
}

int main(int argc, char** argv) {
    std::vector<std::string> args;
    for (int i = 1; i < argc; i++) args.push_back(argv[i]);

    // Pre-pass for --version and --config KEY=VALUE
    for (auto& a : args) {
        if (a == "--version") { printf("%s\n", versionString().c_str()); return 0; }
    }
    std::vector<std::string> filtered;
    for (size_t i = 0; i < args.size(); i++) {
        if (args[i] == "--config") {
            if (i + 1 >= args.size()) { cplError(1, "--config option given without a key=value argument."); return 1; }
            std::string kv = args[i + 1];
            if (kv.find('=') == std::string::npos) {
                if (i + 2 >= args.size()) {
                    cplError(1, "--config option given without a key and value argument.");
                    cplError(1, "--config option given without a key and value argument.");
                    return 1;
                }
                setConfigOption(kv, args[i + 2]);
                i += 2;
            } else {
                setConfigOption(kv.substr(0, kv.find('=')), kv.substr(kv.find('=') + 1));
                i += 1;
            }
            continue;
        }
        filtered.push_back(args[i]);
    }
    args = filtered;

    Algorithm* root = getRootAlgorithm();
    initDrivers();

    if (args.empty()) {
        root->reportError(1, "Missing command name.");
        root->printUsageOnError();
        return 1;
    }

    // Known subcommand ?
    if (args[0][0] != '-') {
        Algorithm* sub = root->findSub(args[0]);
        if (sub) {
            root->selectedSub = sub;
            std::vector<std::string> rest(args.begin() + 1, args.end());
            bool ok = sub->parse(rest);
            return runAlgorithmFromParse(sub, ok);
        }
        if (args[0] == "read") {
            Algorithm* pipe = root->findSub("pipeline");
            root->selectedSub = pipe;
            bool ok = pipe->parse(args);
            return runAlgorithmFromParse(pipe, ok);
        }
        if (args[0] == "help") {
            fputs(root->fullHelp().c_str(), stdout);
            return 0;
        }
    }

    // Look for an existing file among args -> 'gdal info' shortcut
    std::string foundFile;
    for (auto& a : args) {
        if (!a.empty() && a[0] != '-' && fileExists(a)) { foundFile = a; break; }
    }
    if (!foundFile.empty()) {
        int rc = 0;
        if (runInfoShortcutOnFile(root, foundFile, args, rc)) return rc;
    }
    if (args[0][0] != '-') {
        root->reportError(1, "Unknown command: '" + args[0] + "'");
        root->printUsageOnError();
        return 1;
    }
    bool ok = root->parse(args);
    if (root->helpRequested) { fputs(root->fullHelp().c_str(), stdout); return 0; }
    if (root->jsonUsageRequested) { fputs(root->jsonUsage().c_str(), stdout); return 0; }
    if (!ok) { root->printUsageOnError(); return 1; }
    if (root->selectedSub) return runAlgorithmFromParse(root->selectedSub, ok);
    return root->run();
}
