            if (!found) continue;
        }
        JsonValue o = JsonValue::object();
        o.set("short_name", JsonValue::string(d.shortName));
        o.set("long_name", JsonValue::string(d.longName));
        JsonValue sc = JsonValue::array();
        for (auto& s : d.scopes) sc.push(JsonValue::string(s));
        o.set("scopes", sc);
        JsonValue cap = JsonValue::array();
        for (auto& s : d.capabilities) cap.push(JsonValue::string(s));
        o.set("capabilities", cap);
        if (!d.extensions.empty()) {
