        if (src) { int t2 = api().get_type(src); api().destroy(src); return t2 == PJ_TYPE_GEOGRAPHIC_2D_CRS || t2 == PJ_TYPE_GEOGRAPHIC_3D_CRS || t2 == PJ_TYPE_GEOGRAPHIC_CRS; }
