bool CRS::axisInfo(int i, std::string& name, std::string& abbrev, std::string& direction, double& convFactor, std::string& unitName) const {
    if (!pj_) return false;
    PJ* target = P(pj_);
    PJ* tmp = nullptr;
    int t = api().get_type(target);
    if (t == PJ_TYPE_BOUND_CRS) { tmp = api().get_source_crs(api().ctx, target); target = tmp; }
    else if (t == PJ_TYPE_COMPOUND_CRS) { tmp = api().crs_get_sub_crs(api().ctx, target, 0); target = tmp; }
    if (!target) return false;
    PJ* cs = api().crs_get_coordinate_system(api().ctx, target);
    if (tmp) api().destroy(tmp);
    if (!cs) return false;
    const char *nm = nullptr, *ab = nullptr, *dir = nullptr, *un = nullptr, *ua = nullptr, *uc = nullptr;
    double cf = 0;
    bool ok = api().cs_get_axis_info(api().ctx, cs, i, &nm, &ab, &dir, &cf, &un, &ua, &uc) != 0;
    if (ok) { name = nm ? nm : ""; abbrev = ab ? ab : ""; direction = dir ? dir : ""; convFactor = cf; unitName = un ? un : ""; }
    api().destroy(cs);
    return ok;
}
std::vector<int> CRS::dataAxisToSRSAxisMapping() const {
    std::vector<int> m;
    if (!pj_) return m;
    int n = axisCount();
    std::string nm, ab, d0, d1, un;
    double cf;
    bool swap = false;
    if (n >= 2 && axisInfo(0, nm, ab, d0, cf, un) && axisInfo(1, nm, ab, d1, cf, un)) {
        bool first_ns = iequals(d0, "north") || iequals(d0, "south");
        bool second_ew = iequals(d1, "east") || iequals(d1, "west");
        swap = first_ns && second_ew;
    }
    if (n < 2) n = 2;
    if (swap) { m.push_back(2); m.push_back(1); } else { m.push_back(1); m.push_back(2); }
    for (int i = 3; i <= n; i++) m.push_back(i);
    return m;
}
