bool CRS::setFromWKT(const std::string& wkt) {
    if (!api().ok) return false;
    const char* opts[] = {"STRICT=NO", nullptr};
    PJ* p = api().create_from_wkt(api().ctx, wkt.c_str(), opts, nullptr, nullptr);
    if (!p) return false;
    if (!api().is_crs(p)) { api().destroy(p); return false; }
