bool CRS::setFromUserInput(const std::string& s0) {
    if (!api().ok) return false;
    std::string s = trimString(s0);
    if (s.empty()) return false;
    if (iequals(s, "WGS84") || iequals(s, "CRS84") || iequals(s, "WGS 84")) {
        if (iequals(s, "CRS84")) return setFromAuthority("OGC", "CRS84");
        return setFromEPSG(4326);
    }
    if (iequals(s, "NAD27")) return setFromEPSG(4267);
    if (iequals(s, "NAD83")) return setFromEPSG(4269);
    // EPSG:xxxx
    if (strncasecmp(s.c_str(), "EPSG:", 5) == 0 || strncasecmp(s.c_str(), "ESRI:", 5) == 0 || strncasecmp(s.c_str(), "IAU:", 4) == 0 ||
        strncasecmp(s.c_str(), "IGNF:", 5) == 0 || strncasecmp(s.c_str(), "OGC:", 4) == 0) {
        size_t c = s.find(':');
        std::string auth = toUpper(s.substr(0, c));
        std::string code = s.substr(c + 1);
        if (code.find('+') != std::string::npos) {
            // compound EPSG:a+b
            PJ* p = api().create(api().ctx, s.c_str());
            if (!p) return false;
            setPj(p);
            return true;
        }
        return setFromAuthority(auth, code);
    }
    if (s[0] == '+' || strncasecmp(s.c_str(), "urn:", 4) == 0 || strncasecmp(s.c_str(), "http", 4) == 0 || s[0] == '{' ) {
        PJ* p = api().create(api().ctx, s.c_str());
        if (!p) return false;
        if (!api().is_crs(p)) { api().destroy(p); return false; }
        setPj(p);
        return true;
    }
    // Pure number -> EPSG
    bool allDigit = !s.empty();
    for (char c : s) if (!isdigit((unsigned char)c)) allDigit = false;
    if (allDigit) return setFromEPSG(atoi(s.c_str()));
    // WKT ?
    if (s.find('[') != std::string::npos) return setFromWKT(s);
    PJ* p = api().create(api().ctx, s.c_str());
    if (!p) return false;
    if (!api().is_crs(p)) { api().destroy(p); return false; }
    setPj(p);
    return true;
}

