int CRS::identifyEPSG(int* confidenceOut) const {
    if (!pj_) return 0;
    std::string a = authName(), c = authCode();
    if (a == "EPSG" && !c.empty()) { if (confidenceOut) *confidenceOut = 100; return atoi(c.c_str()); }
    int* conf = nullptr;
    PJ_OBJ_LIST* list = api().identify(api().ctx, P(pj_), "EPSG", nullptr, &conf);
    int code = 0;
    if (list) {
        int n = api().list_get_count(list);
        int best = 0;
        for (int i = 0; i < n; i++) {
            if (conf && conf[i] > best) {
                PJ* o = api().list_get(api().ctx, list, i);
                const char* cc = api().get_id_code(o, 0);
                if (cc) { code = atoi(cc); best = conf[i]; }
                api().destroy(o);
            }
        }
        if (confidenceOut) *confidenceOut = best;
        api().list_destroy(list);
        if (conf) api().int_list_destroy(conf);
        if (best < 70) code = 0;
    }
    return code;
}
