#include "tiff.h"
#include <cstdio>
#include <cstring>
#include <zlib.h>

static int typeSize(uint16_t t) {
    switch (t) {
        case 1: case 2: case 6: case 7: return 1;
        case 3: case 8: return 2;
        case 4: case 9: case 11: case 13: return 4;
        case 5: case 10: case 12: case 16: case 17: case 18: return 8;
        default: return 0;
    }
}

TiffFile::~TiffFile() { if (fp_) fclose(fp_); }

uint16_t TiffFile::rd16(const uint8_t* p) const { return bigEndian_ ? (uint16_t)((p[0] << 8) | p[1]) : (uint16_t)(p[0] | (p[1] << 8)); }
uint32_t TiffFile::rd32(const uint8_t* p) const { return bigEndian_ ? ((uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 8 | p[3]) : ((uint32_t)p[3] << 24 | (uint32_t)p[2] << 16 | (uint32_t)p[1] << 8 | p[0]); }
uint64_t TiffFile::rd64(const uint8_t* p) const {
    if (bigEndian_) return ((uint64_t)rd32(p) << 32) | rd32(p + 4);
    return ((uint64_t)rd32(p + 4) << 32) | rd32(p);
}

bool TiffFile::readRaw(uint64_t off, uint64_t size, std::vector<uint8_t>& out) const {
    if (!fp_) return false;
    if (off + size > size_) return false;
    out.resize(size);
    if (size == 0) return true;
    if (fseeko(fp_, (off_t)off, SEEK_SET) != 0) return false;
    return fread(out.data(), 1, size, fp_) == size;
}

bool TiffFile::open(const std::string& path, std::string& err) {
    path_ = path;
    fp_ = fopen(path.c_str(), "rb");
    if (!fp_) { err = "cannot open"; return false; }
    fseeko(fp_, 0, SEEK_END);
    size_ = (uint64_t)ftello(fp_);
    uint8_t hdr[16];
    fseeko(fp_, 0, SEEK_SET);
    if (fread(hdr, 1, 8, fp_) != 8) { err = "short header"; return false; }
    if (hdr[0] == 'I' && hdr[1] == 'I') bigEndian_ = false;
    else if (hdr[0] == 'M' && hdr[1] == 'M') bigEndian_ = true;
    else { err = "not a tiff"; return false; }
    uint16_t magic = rd16(hdr + 2);
    uint64_t off;
    if (magic == 42) { bigTiff_ = false; off = rd32(hdr + 4); }
    else if (magic == 43) {
        bigTiff_ = true;
        if (fread(hdr + 8, 1, 8, fp_) != 8) { err = "short header"; return false; }
        off = rd64(hdr + 8);
    } else { err = "bad magic"; return false; }
    std::vector<uint64_t> seen;
    while (off != 0 && ifds_.size() < 1000) {
        for (auto s : seen) if (s == off) { off = 0; break; }
        if (off == 0) break;
        seen.push_back(off);
        TiffIFD ifd;
        if (!readIFD(off, ifd, err)) { if (ifds_.empty()) return false; break; }
        ifds_.push_back(ifd);
        // next
        uint64_t nextPos = ifd.offset;
        (void)nextPos;
        // readIFD stores next offset in offset field temporarily; fix below
        off = ifd.offset;
        ifds_.back().offset = seen.back();
    }
    if (ifds_.empty()) { err = "no directory"; return false; }
    return true;
}

bool TiffFile::readIFD(uint64_t off, TiffIFD& ifd, std::string& err) {
    std::vector<uint8_t> buf;
    uint64_t nEntries;
    size_t entrySize = bigTiff_ ? 20 : 12;
    if (bigTiff_) {
        if (!readRaw(off, 8, buf)) { err = "bad ifd"; return false; }
        nEntries = rd64(buf.data());
    } else {
        if (!readRaw(off, 2, buf)) { err = "bad ifd"; return false; }
        nEntries = rd16(buf.data());
    }
    if (nEntries > 65535) { err = "bad ifd"; return false; }
    uint64_t base = off + (bigTiff_ ? 8 : 2);
    std::vector<uint8_t> entries;
    if (!readRaw(base, nEntries * entrySize + (bigTiff_ ? 8 : 4), entries)) { err = "bad ifd"; return false; }
    for (uint64_t i = 0; i < nEntries; i++) {
        const uint8_t* e = entries.data() + i * entrySize;
        TiffTag t;
        t.tag = rd16(e);
        t.type = rd16(e + 2);
        t.count = bigTiff_ ? rd64(e + 4) : rd32(e + 4);
        int ts = typeSize(t.type);
        if (ts == 0) continue;
        uint64_t total = t.count * ts;
        if (total > 256 * 1024 * 1024) continue;
        size_t inlineSize = bigTiff_ ? 8 : 4;
        const uint8_t* valp = e + (bigTiff_ ? 12 : 8);
        if (total <= inlineSize) {
            t.data.assign(valp, valp + total);
        } else {
            uint64_t voff = bigTiff_ ? rd64(valp) : rd32(valp);
            if (!readRaw(voff, total, t.data)) continue;
        }
        // decode
        if (t.type == 2) {
            t.str.assign((const char*)t.data.data(), t.data.size());
            while (!t.str.empty() && t.str.back() == '\0') t.str.pop_back();
        } else if (t.type != 7) {
            t.nums.reserve((size_t)t.count);
            for (uint64_t k = 0; k < t.count; k++) {
                const uint8_t* p = t.data.data() + k * ts;
                double v = 0;
                switch (t.type) {
                    case 1: v = p[0]; break;
                    case 6: v = (int8_t)p[0]; break;
                    case 3: v = rd16(p); break;
                    case 8: v = (int16_t)rd16(p); break;
                    case 4: case 13: v = rd32(p); break;
                    case 9: v = (int32_t)rd32(p); break;
                    case 5: { uint32_t a = rd32(p), b = rd32(p + 4); v = b ? (double)a / b : 0; break; }
                    case 10: { int32_t a = (int32_t)rd32(p), b = (int32_t)rd32(p + 4); v = b ? (double)a / b : 0; break; }
                    case 11: { uint32_t u = rd32(p); float f; memcpy(&f, &u, 4); v = f; break; }
                    case 12: { uint64_t u = rd64(p); double d; memcpy(&d, &u, 8); v = d; break; }
                    case 16: case 18: v = (double)rd64(p); break;
                    case 17: v = (double)(int64_t)rd64(p); break;
                }
                t.nums.push_back(v);
            }
        }
        ifd.tags[t.tag] = std::move(t);
    }
    const uint8_t* np = entries.data() + nEntries * entrySize;
    ifd.offset = bigTiff_ ? rd64(np) : rd32(np);  // next IFD offset (temporarily)
    return true;
}

bool TiffFile::blockOffsetAndSize(const TiffIFD& ifd, uint32_t tileX, uint32_t tileY, int sample, uint64_t& off, uint64_t& size) const {
    const TiffTag* offs = ifd.isTiled() ? ifd.get(324) : ifd.get(273);
    const TiffTag* cnts = ifd.isTiled() ? ifd.get(325) : ifd.get(279);
    if (!offs) return false;
    uint32_t across = blocksAcross(ifd), down = blocksDown(ifd);
    uint64_t idx = (uint64_t)tileY * across + tileX;
    if (ifd.planarConfig() == 2) idx += (uint64_t)sample * across * down;
    if (idx >= offs->nums.size()) return false;
    off = (uint64_t)offs->nums[idx];
    if (cnts && idx < cnts->nums.size()) size = (uint64_t)cnts->nums[idx];
    else {
        // uncompressed strip without byte counts
        uint64_t bps = ifd.bitsPerSample();
        uint64_t spp = ifd.planarConfig() == 2 ? 1 : ifd.samplesPerPixel();
        size = (uint64_t)ifd.tileWidth() * ifd.tileHeight() * spp * bps / 8;
    }
    return true;
}

static void applyPredictor(std::vector<uint8_t>& buf, uint32_t width, uint32_t height, int spp, int bps, int predictor, bool bigEndianData) {
    (void)bigEndianData;
    if (predictor == 2) {
        int bytes = bps / 8;
        size_t rowLen = (size_t)width * spp * bytes;
        for (uint32_t y = 0; y < height; y++) {
            uint8_t* row = buf.data() + y * rowLen;
            if ((y + 1) * rowLen > buf.size()) break;
            if (bytes == 1) {
                for (size_t i = spp; i < rowLen; i++) row[i] += row[i - spp];
            } else if (bytes == 2) {
                uint16_t* r = (uint16_t*)row;
                for (size_t i = spp; i < (size_t)width * spp; i++) r[i] += r[i - spp];
            } else if (bytes == 4) {
                uint32_t* r = (uint32_t*)row;
                for (size_t i = spp; i < (size_t)width * spp; i++) r[i] += r[i - spp];
            } else if (bytes == 8) {
                uint64_t* r = (uint64_t*)row;
                for (size_t i = spp; i < (size_t)width * spp; i++) r[i] += r[i - spp];
            }
        }
    } else if (predictor == 3) {
        int bytes = bps / 8;
        size_t rowLen = (size_t)width * spp * bytes;
        std::vector<uint8_t> tmp(rowLen);
        for (uint32_t y = 0; y < height; y++) {
            uint8_t* row = buf.data() + y * rowLen;
            if ((y + 1) * rowLen > buf.size()) break;
            for (size_t i = 1; i < rowLen; i++) row[i] += row[i - 1];
            // reorder: bytes are stored big-endian-split planes
            size_t n = (size_t)width * spp;
            for (size_t i = 0; i < n; i++)
                for (int b = 0; b < bytes; b++)
                    tmp[i * bytes + b] = row[(bytes - 1 - b) * n + i];
            memcpy(row, tmp.data(), rowLen);
        }
    }
}

bool TiffFile::readBlock(const TiffIFD& ifd, uint32_t tileX, uint32_t tileY, int sample, std::vector<uint8_t>& out, std::string& err) {
    uint64_t off, size;
    uint32_t tw = ifd.tileWidth(), th = ifd.tileHeight();
    int spp = ifd.planarConfig() == 2 ? 1 : ifd.samplesPerPixel();
    int bps = ifd.bitsPerSample();
    size_t expected = (size_t)tw * th * spp * bps / 8;
    if (bps < 8) expected = ((size_t)tw * spp * bps + 7) / 8 * th;
    if (!blockOffsetAndSize(ifd, tileX, tileY, sample, off, size) || off == 0 || size == 0) {
        // missing block: zero fill
        out.assign(expected, 0);
        return true;
    }
    std::vector<uint8_t> raw;
    if (!readRaw(off, size, raw)) { err = "read error"; return false; }
    int comp = ifd.compression();
    if (comp == 1) {
        out = std::move(raw);
        if (out.size() < expected) out.resize(expected, 0);
    } else if (comp == 5) {
        if (!lzwDecode(raw.data(), raw.size(), out, expected)) { err = "LZW decode error"; return false; }
    } else if (comp == 8 || comp == 32946 || comp == 50000) {
        if (!zlibDecode(raw.data(), raw.size(), out, expected)) { err = "Deflate decode error"; return false; }
    } else if (comp == 32773) {
        if (!packBitsDecode(raw.data(), raw.size(), out, expected)) { err = "PackBits decode error"; return false; }
    } else {
        err = "unsupported compression";
        return false;
    }
    if (out.size() < expected) out.resize(expected, 0);
    if (bps >= 8 && ifd.predictor() > 1) applyPredictor(out, tw, th, spp, bps, ifd.predictor(), bigEndian_);
    // byte swap to host order if needed (host assumed little endian)
    if (bigEndian_ && bps > 8) {
        int bytes = bps / 8;
        for (size_t i = 0; i + bytes <= out.size(); i += bytes)
            for (int b = 0; b < bytes / 2; b++) std::swap(out[i + b], out[i + bytes - 1 - b]);
    }
    return true;
}

// ---------------- Codecs ----------------
bool zlibDecode(const uint8_t* src, size_t srcLen, std::vector<uint8_t>& dst, size_t expected) {
    dst.resize(expected ? expected : srcLen * 4);
    z_stream zs;
    memset(&zs, 0, sizeof(zs));
    if (inflateInit(&zs) != Z_OK) return false;
    zs.next_in = (Bytef*)src;
    zs.avail_in = (uInt)srcLen;
    zs.next_out = dst.data();
    zs.avail_out = (uInt)dst.size();
    int ret = inflate(&zs, Z_FINISH);
    bool ok = ret == Z_STREAM_END || ret == Z_OK || ret == Z_BUF_ERROR;
    size_t produced = dst.size() - zs.avail_out;
    inflateEnd(&zs);
    if (!ok) return false;
    dst.resize(produced);
    return true;
}

bool zlibEncode(const uint8_t* src, size_t srcLen, std::vector<uint8_t>& dst, int level) {
    uLongf destLen = compressBound((uLong)srcLen);
    dst.resize(destLen);
    if (compress2(dst.data(), &destLen, src, (uLong)srcLen, level) != Z_OK) return false;
    dst.resize(destLen);
    return true;
}

bool packBitsDecode(const uint8_t* src, size_t srcLen, std::vector<uint8_t>& dst, size_t expected) {
    dst.clear();
    dst.reserve(expected);
    size_t i = 0;
    while (i < srcLen && dst.size() < expected) {
        int8_t n = (int8_t)src[i++];
        if (n >= 0) {
            size_t cnt = (size_t)n + 1;
            if (i + cnt > srcLen) cnt = srcLen - i;
            dst.insert(dst.end(), src + i, src + i + cnt);
            i += cnt;
        } else if (n != -128) {
            if (i >= srcLen) break;
            uint8_t v = src[i++];
            dst.insert(dst.end(), (size_t)(1 - n), v);
        }
    }
    return true;
}

bool lzwDecode(const uint8_t* src, size_t srcLen, std::vector<uint8_t>& dst, size_t expected) {
    // TIFF LZW (MSB-first, with early change)
    dst.clear();
    dst.reserve(expected);
    std::vector<std::vector<uint8_t>> table;
    auto resetTable = [&]() {
        table.clear();
        table.reserve(4096);
        for (int i = 0; i < 256; i++) table.push_back(std::vector<uint8_t>(1, (uint8_t)i));
        table.push_back({}); // 256 clear
        table.push_back({}); // 257 eoi
    };
    resetTable();
    int codeLen = 9;
    uint32_t bitBuf = 0;
    int bitCnt = 0;
    size_t pos = 0;
    std::vector<uint8_t> prev;
    bool first = true;
    while (true) {
        while (bitCnt < codeLen) {
            if (pos >= srcLen) return true;
            bitBuf = (bitBuf << 8) | src[pos++];
            bitCnt += 8;
        }
        int code = (bitBuf >> (bitCnt - codeLen)) & ((1 << codeLen) - 1);
        bitCnt -= codeLen;
        if (code == 256) { resetTable(); codeLen = 9; first = true; prev.clear(); continue; }
        if (code == 257) return true;
        std::vector<uint8_t> entry;
        if (code < (int)table.size()) {
            entry = table[code];
            if (!first) { std::vector<uint8_t> ne = prev; ne.push_back(entry[0]); table.push_back(ne); }
        } else if (code == (int)table.size() && !first) {
            entry = prev; entry.push_back(prev[0]);
            table.push_back(entry);
        } else {
            return false;
        }
        dst.insert(dst.end(), entry.begin(), entry.end());
        prev = entry;
        first = false;
        if (table.size() + 1 >= (size_t)(1 << codeLen) && codeLen < 12) codeLen++;
        if (dst.size() >= expected && expected) return true;
    }
}

std::vector<uint8_t> lzwEncode(const uint8_t* src, size_t srcLen) {
    // Simple TIFF LZW encoder (MSB-first, early change)
    std::vector<uint8_t> out;
    std::map<std::pair<int, uint8_t>, int> dict;
    int nextCode = 258;
    int codeLen = 9;
    uint64_t bitBuf = 0;
    int bitCnt = 0;
    auto emit = [&](int code) {
        bitBuf = (bitBuf << codeLen) | (uint32_t)code;
        bitCnt += codeLen;
        while (bitCnt >= 8) { out.push_back((uint8_t)(bitBuf >> (bitCnt - 8))); bitCnt -= 8; }
    };
    emit(256);
    if (srcLen == 0) { emit(257); if (bitCnt > 0) out.push_back((uint8_t)(bitBuf << (8 - bitCnt))); return out; }
    int w = src[0];
    for (size_t i = 1; i < srcLen; i++) {
        uint8_t c = src[i];
        auto key = std::make_pair(w, c);
        auto it = dict.find(key);
        if (it != dict.end()) { w = it->second; continue; }
        emit(w);
        dict[key] = nextCode++;
        if (nextCode + 1 >= (1 << codeLen)) {
            if (codeLen < 12) codeLen++;
            else { emit(256); dict.clear(); nextCode = 258; codeLen = 9; }
        }
        w = c;
    }
    emit(w);
    emit(257);
    if (bitCnt > 0) out.push_back((uint8_t)(bitBuf << (8 - bitCnt)));
    return out;
}
