static float halfToFloat(uint16_t h) {
    uint32_t sign = (h >> 15) & 1, exp = (h >> 10) & 0x1f, mant = h & 0x3ff;
    uint32_t f;
    if (exp == 0) {
        if (mant == 0) f = sign << 31;
        else { exp = 127 - 15 + 1; while (!(mant & 0x400)) { mant <<= 1; exp--; } mant &= 0x3ff; f = (sign << 31) | (exp << 23) | (mant << 13); }
    } else if (exp == 31) f = (sign << 31) | 0x7f800000 | (mant << 13);
    else f = (sign << 31) | ((exp + 112) << 23) | (mant << 13);
    float r; memcpy(&r, &f, 4); return r;
}
static uint16_t floatToHalf(float fl) {
    uint32_t f; memcpy(&f, &fl, 4);
    uint32_t sign = (f >> 16) & 0x8000;
    int exp = ((f >> 23) & 0xff) - 127 + 15;
    uint32_t mant = f & 0x7fffff;
    if (((f >> 23) & 0xff) == 0xff) return (uint16_t)(sign | 0x7c00 | (mant ? 0x200 : 0));
    if (exp >= 31) return (uint16_t)(sign | 0x7c00);
    if (exp <= 0) {
        if (exp < -10) return (uint16_t)sign;
        mant |= 0x800000;
        uint32_t shift = (uint32_t)(14 - exp);
        uint32_t hm = mant >> shift;
        if ((mant >> (shift - 1)) & 1) hm++;
        return (uint16_t)(sign | hm);
    }
    uint32_t hm = mant >> 13;
    if (mant & 0x1000) { hm++; if (hm & 0x400) { hm = 0; exp++; if (exp >= 31) return (uint16_t)(sign | 0x7c00); } }
    return (uint16_t)(sign | (exp << 10) | hm);
}

double sampleToDouble(const uint8_t* p, DataType t) {
    switch (t) {
        case DataType::Byte: return *p;
        case DataType::Int8: return *(const int8_t*)p;
        case DataType::UInt16: { uint16_t v; memcpy(&v, p, 2); return v; }
        case DataType::Int16: { int16_t v; memcpy(&v, p, 2); return v; }
        case DataType::UInt32: { uint32_t v; memcpy(&v, p, 4); return v; }
        case DataType::Int32: { int32_t v; memcpy(&v, p, 4); return v; }
        case DataType::UInt64: { uint64_t v; memcpy(&v, p, 8); return (double)v; }
        case DataType::Int64: { int64_t v; memcpy(&v, p, 8); return (double)v; }
        case DataType::Float16: { uint16_t v; memcpy(&v, p, 2); return halfToFloat(v); }
        case DataType::Float32: { float v; memcpy(&v, p, 4); return v; }
        case DataType::Float64: { double v; memcpy(&v, p, 8); return v; }
        case DataType::CInt16: { int16_t v; memcpy(&v, p, 2); return v; }
        case DataType::CInt32: { int32_t v; memcpy(&v, p, 4); return v; }
        case DataType::CFloat16: { uint16_t v; memcpy(&v, p, 2); return halfToFloat(v); }
        case DataType::CFloat32: { float v; memcpy(&v, p, 4); return v; }
        case DataType::CFloat64: { double v; memcpy(&v, p, 8); return v; }
        default: return 0;
    }
}

template <typename T> static T clampRound(double v) {
    if (std::isnan(v)) return 0;
    double r = std::round(v);
    if (r < (double)std::numeric_limits<T>::min()) return std::numeric_limits<T>::min();
    if (r > (double)std::numeric_limits<T>::max()) return std::numeric_limits<T>::max();
    return (T)r;
}

void doubleToSample(double v, uint8_t* p, DataType t) {
    switch (t) {
        case DataType::Byte: *p = clampRound<uint8_t>(v); break;
        case DataType::Int8: *(int8_t*)p = clampRound<int8_t>(v); break;
        case DataType::UInt16: { uint16_t x = clampRound<uint16_t>(v); memcpy(p, &x, 2); break; }
        case DataType::Int16: { int16_t x = clampRound<int16_t>(v); memcpy(p, &x, 2); break; }
        case DataType::UInt32: { uint32_t x = clampRound<uint32_t>(v); memcpy(p, &x, 4); break; }
        case DataType::Int32: { int32_t x = clampRound<int32_t>(v); memcpy(p, &x, 4); break; }
        case DataType::UInt64: { uint64_t x = std::isnan(v) ? 0 : (v < 0 ? 0 : (v >= 1.8446744073709552e19 ? UINT64_MAX : (uint64_t)std::round(v))); memcpy(p, &x, 8); break; }
        case DataType::Int64: { int64_t x = std::isnan(v) ? 0 : (v <= -9.2233720368547758e18 ? INT64_MIN : (v >= 9.2233720368547758e18 ? INT64_MAX : (int64_t)std::round(v))); memcpy(p, &x, 8); break; }
        case DataType::Float16: { uint16_t x = floatToHalf((float)v); memcpy(p, &x, 2); break; }
        case DataType::Float32: { float x = (float)v; memcpy(p, &x, 4); break; }
        case DataType::Float64: memcpy(p, &v, 8); break;
        case DataType::CInt16: { int16_t x = clampRound<int16_t>(v); memcpy(p, &x, 2); int16_t z = 0; memcpy(p + 2, &z, 2); break; }
        case DataType::CInt32: { int32_t x = clampRound<int32_t>(v); memcpy(p, &x, 4); int32_t z = 0; memcpy(p + 4, &z, 4); break; }
        case DataType::CFloat16: { uint16_t x = floatToHalf((float)v); memcpy(p, &x, 2); uint16_t z = 0; memcpy(p + 2, &z, 2); break; }
        case DataType::CFloat32: { float x = (float)v; memcpy(p, &x, 4); float z = 0; memcpy(p + 4, &z, 4); break; }
        case DataType::CFloat64: { memcpy(p, &v, 8); double z = 0; memcpy(p + 8, &z, 8); break; }
        default: break;
    }
}

bool RasterBand::readWindowRaw(int x0, int y0, int w, int h, std::vector<uint8_t>& out, std::string& err) {
    int sz = dataTypeSizeBytes(type);
    out.assign((size_t)w * h * sz, 0);
    if (blockX <= 0 || blockY <= 0) { err = "invalid block size"; return false; }
    int bx0 = x0 / blockX, bx1 = (x0 + w - 1) / blockX;
    int by0 = y0 / blockY, by1 = (y0 + h - 1) / blockY;
    std::vector<uint8_t> blk;
    for (int by = by0; by <= by1; by++) {
        for (int bx = bx0; bx <= bx1; bx++) {
            if (!readBlock(bx, by, blk, err)) return false;
            int xs = std::max(x0, bx * blockX), xe = std::min(x0 + w, (bx + 1) * blockX);
            int ys = std::max(y0, by * blockY), ye = std::min(y0 + h, (by + 1) * blockY);
            for (int y = ys; y < ye; y++) {
                const uint8_t* src = blk.data() + ((size_t)(y - by * blockY) * blockX + (xs - bx * blockX)) * sz;
                uint8_t* dst = out.data() + ((size_t)(y - y0) * w + (xs - x0)) * sz;
                memcpy(dst, src, (size_t)(xe - xs) * sz);
            }
        }
    }
    return true;
}

bool RasterBand::readWindowAsDouble(int x0, int y0, int w, int h, std::vector<double>& out, std::string& err) {
    std::vector<uint8_t> raw;
    if (!readWindowRaw(x0, y0, w, h, raw, err)) return false;
    int sz = dataTypeSizeBytes(type);
    out.resize((size_t)w * h);
    for (size_t i = 0; i < out.size(); i++) out[i] = sampleToDouble(raw.data() + i * sz, type);
    return true;
}

bool RasterBand::readAsDouble(std::vector<double>& out, std::string& err) {
    return readWindowAsDouble(0, 0, xsize, ysize, out, err);
}

bool RasterDataset::geoToPixel(double x, double y, double& px, double& py) const {
    double det = gt[1] * gt[5] - gt[2] * gt[4];
    if (det == 0) return false;
    double dx = x - gt[0], dy = y - gt[3];
    px = (dx * gt[5] - dy * gt[2]) / det;
    py = (dy * gt[1] - dx * gt[4]) / det;
    return true;
}

bool MemBand::readBlock(int bx, int by, std::vector<uint8_t>& buf, std::string& err) {
    (void)err;
    int sz = dataTypeSizeBytes(type);
    buf.assign((size_t)blockX * blockY * sz, 0);
    for (int y = 0; y < blockY; y++) {
        int yy = by * blockY + y;
        if (yy >= ysize) break;
        int xx = bx * blockX;
        int n = std::min(blockX, xsize - xx);
        if (n <= 0) continue;
        memcpy(buf.data() + (size_t)y * blockX * sz, data.data() + ((size_t)yy * xsize + xx) * sz, (size_t)n * sz);
    }
    return true;
}

std::shared_ptr<RasterDataset> createMemDataset(int xsize, int ysize, int nbands, DataType type) {
    auto ds = std::make_shared<RasterDataset>();
    ds->driverShort = "MEM"; ds->driverLong = "In Memory raster, vector and multidimensional raster";
    ds->xsize = xsize; ds->ysize = ysize;
    for (int i = 0; i < nbands; i++) {
        auto b = std::make_shared<MemBand>();
        b->number = i + 1; b->type = type; b->xsize = xsize; b->ysize = ysize;
        b->blockX = xsize; b->blockY = 1;
        b->data.assign((size_t)xsize * ysize * dataTypeSizeBytes(type), 0);
        b->dataset = ds.get();
        ds->bands.push_back(b);
    }
    return ds;
}

// ---------------------------------------------------------------------------
// Statistics (mimic GDAL semantics: nodata excluded; approx uses sampling)

static bool isNoDataValue(const RasterBand& b, double v) {
    if (!b.hasNoData) return false;
    if (std::isnan(b.noData)) return std::isnan(v);
    return v == b.noData;
}

BandStats computeStats(RasterBand& band, bool approx, std::string& err) {
    BandStats st;
    std::vector<double> data;
    int w = band.xsize, h = band.ysize;
    int step = 1;
    if (approx) {
        // GDAL samples to ~ 2500 pixels using overview or decimation; approximate with decimation
        double nPixels = (double)w * h;
        if (nPixels > 2500) step = (int)std::ceil(std::sqrt(nPixels / 2500.0));
    }
    double mn = 0, mx = 0, sum = 0, sumsq = 0;
    uint64_t n = 0;
    bool first = true;
    std::vector<double> row;
    for (int y = 0; y < h; y += step) {
        if (!band.readWindowAsDouble(0, y, w, 1, row, err)) return st;
        for (int x = 0; x < w; x += step) {
            double v = row[x];
            if (std::isnan(v) || isNoDataValue(band, v)) continue;
            if (first) { mn = mx = v; first = false; }
            else { if (v < mn) mn = v; if (v > mx) mx = v; }
            sum += v; sumsq += v * v; n++;
        }
    }
    if (n == 0) { err = "Failed to compute statistics, no valid pixels found in sampling."; return st; }
    st.min = mn; st.max = mx; st.mean = sum / n;
    double var = sumsq / n - st.mean * st.mean;
    st.stddev = var > 0 ? std::sqrt(var) : 0;
    st.validCount = n;
    st.ok = true;
    return st;
}

bool computeMinMax(RasterBand& band, bool approx, double& mn, double& mx, std::string& err) {
    BandStats st = computeStats(band, approx, err);
    if (!st.ok) return false;
    mn = st.min; mx = st.max;
    return true;
}

bool computeHistogram(RasterBand& band, double& mn, double& mx, int nBuckets, std::vector<uint64_t>& counts, bool approx, std::string& err) {
    (void)approx;
    counts.assign(nBuckets, 0);
    std::vector<double> row;
    int w = band.xsize, h = band.ysize;
    double scale = nBuckets / (mx - mn);
    for (int y = 0; y < h; y++) {
        if (!band.readWindowAsDouble(0, y, w, 1, row, err)) return false;
        for (int x = 0; x < w; x++) {
            double v = row[x];
            if (std::isnan(v) || isNoDataValue(band, v)) continue;
            int idx;
            if (dataTypeIsInteger(band.type) && !dataTypeIsComplex(band.type) && nBuckets == 256 && mn == -0.5 && mx == 255.5) idx = (int)v;
            else idx = (int)std::floor((v - mn) * scale);
            if (idx < 0) idx = 0; if (idx >= nBuckets) idx = nBuckets - 1;
            counts[idx]++;
        }
    }
    return true;
}

int computeChecksum(RasterBand& band, int x0, int y0, int w, int h, std::string& err) {
    // GDALChecksumImage algorithm
    int nChecksum = 0;
    bool complex = dataTypeIsComplex(band.type);
    bool floating = dataTypeIsFloating(band.type);
    if (floating || complex) {
        // GDAL: for floating point, read as Float64 (or CFloat64) and use a specific scheme
        std::vector<double> row;
        int nBandWidth = w;
        for (int iLine = y0; iLine < y0 + h; iLine++) {
            if (!band.readWindowAsDouble(x0, iLine, w, 1, row, err)) return -1;
            // For complex, GDAL reads real & imag; we only support real here
            int nCount = nBandWidth * (complex ? 2 : 1);
            for (int i = 0; i < nCount; i++) {
                double dfVal = complex ? (i % 2 == 0 ? row[i / 2] : 0.0) : row[i];
                int nVal;
                if (std::isnan(dfVal) || std::isinf(dfVal)) {
                    // Most compilers seem to cast NaN or Inf to 0x80000000. but not all. Explicitly set the value.
                    nVal = 0x80000000;
                } else {
                    // Standard behavior of GDALChecksumImage
                    double dfPow = (double)(1 << 30); // hmm
                    (void)dfPow;
                    if (dfVal > 2147483647.0) nVal = 0x7FFFFFFF; else if (dfVal < -2147483648.0) nVal = (int)0x80000000; else nVal = (int)dfVal;
                    // GDAL uses frexp-based approach actually
                    int nExp;
                    double dfMant = frexp(dfVal, &nExp);
                    nVal = (int)(dfMant * 1073741824.0 + (double)nExp * 1000.0);  // placeholder, replaced below
                    (void)nVal;
                }
                (void)nVal;
            }
        }
        // Implement GDAL's actual algorithm for floating point:
        nChecksum = 0;
        for (int iLine = y0; iLine < y0 + h; iLine++) {
            if (!band.readWindowAsDouble(x0, iLine, w, 1, row, err)) return -1;
            int nCount = nBandWidth * (complex ? 2 : 1);
            for (int i = 0; i < nCount; i++) {
                double dfVal = complex ? (i % 2 == 0 ? row[i / 2] : 0.0) : row[i];
                int nVal;
                if (std::isnan(dfVal) || std::isinf(dfVal)) nVal = (int)0x80000000;
                else {
                    // Standard behavior of GDAL: cast to int with rounding of fractional
                    double dfIntPart;
                    double dfFrac = modf(dfVal, &dfIntPart);
                    (void)dfFrac;
                    if (dfVal > 2147483647.0 || dfVal < -2147483648.0) nVal = (int)0x80000000;
                    else nVal = (int)dfVal;
                }
                nChecksum += (nVal % 0xffff);
                nChecksum &= 0xffff;
            }
        }
        return nChecksum;
    }
    std::vector<double> row;
    for (int iLine = y0; iLine < y0 + h; iLine++) {
        if (!band.readWindowAsDouble(x0, iLine, w, 1, row, err)) return -1;
        for (int i = 0; i < w; i++) {
            long long v = (long long)row[i];
            int nVal = (int)v;
            nChecksum += (nVal % 0xffff);
            nChecksum &= 0xffff;
        }
    }
    return nChecksum;
}
