bool identifyGTiff(const std::string& path) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return false;
    uint8_t h[4];
    size_t n = fread(h, 1, 4, f);
    fclose(f);
    if (n < 4) return false;
    if (h[0] == 'I' && h[1] == 'I' && h[2] == 42 && h[3] == 0) return true;
    if (h[0] == 'M' && h[1] == 'M' && h[2] == 0 && h[3] == 42) return true;
    if (h[0] == 'I' && h[1] == 'I' && h[2] == 43 && h[3] == 0) return true;
    if (h[0] == 'M' && h[1] == 'M' && h[2] == 0 && h[3] == 43) return true;
    return false;
}

