        } else if (loc == 34737 && asc) {
            std::string s;
            if ((size_t)off < asc->str.size()) s = asc->str.substr(off, cnt);
            while (!s.empty() && (s.back() == '|' || s.back() == '\0')) s.pop_back();
            keys.asciiKeys[key] = s;
        } else if (loc == 34735) {
            std::vector<double> v;
            for (int k = 0; k < cnt && (size_t)(off + k) < dir->nums.size(); k++) v.push_back(dir->nums[off + k]);
            keys.numKeys[key] = v;
        }
    }
    return true;
}

static std::string ctName(int ct) {
    switch (ct) {
        case 1: return "Transverse_Mercator";
        case 2: return "Transverse_Mercator_South_Orientated";
        case 3: return "Oblique_Mercator";
        case 7: return "Mercator_1SP";
        case 8: return "Lambert_Conformal_Conic_2SP";
        case 9: return "Lambert_Conformal_Conic_1SP";
        case 10: return "Lambert_Azimuthal_Equal_Area";
        case 11: return "Albers_Conic_Equal_Area";
        case 12: return "Azimuthal_Equidistant";
        case 13: return "Equidistant_Conic";
        case 14: return "Stereographic";
        case 15: return "Polar_Stereographic";
        case 16: return "Oblique_Stereographic";
        case 17: return "Equirectangular";
        case 18: return "Cassini_Soldner";
        case 19: return "Gnomonic";
        case 20: return "Miller_Cylindrical";
        case 21: return "Orthographic";
        case 22: return "Polyconic";
        case 23: return "Robinson";
        case 24: return "Sinusoidal";
        case 25: return "VanDerGrinten";
        case 26: return "New_Zealand_Map_Grid";
        case 27: return "Transverse_Mercator";
        case 28: return "Cylindrical_Equal_Area";
        default: return "";
    }
}

static std::string fmtD(double d) {
    char buf[64];
    snprintf(buf, sizeof(buf), "%.16g", d);
    return buf;
}

bool geoKeysToCRS(const GeoKeys& keys, CRS& crs) {
    int modelType = keys.getShort(1024, 0);
    int pcs = keys.getShort(3072, -1);
    int gcs = keys.getShort(2048, -1);
    int vert = keys.getShort(4096, -1);
    CRS horiz;
    bool ok = false;
    if (modelType == 1 || (modelType == 0 && pcs > 0)) {
        if (pcs > 0 && pcs != 32767) ok = horiz.setFromEPSG(pcs);
        if (!ok) {
            // user defined projected CRS: build WKT1
            std::string citation = keys.getAscii(3073);
            if (citation.empty()) citation = keys.getAscii(1026);
            if (citation.empty()) citation = "unnamed";
            std::string geogWkt;
            CRS g;
            if (gcs > 0 && gcs != 32767 && g.setFromEPSG(gcs)) geogWkt = g.exportWkt1(false);
            else {
                double a = keys.getDouble(2057, 6378137.0), rf = keys.getDouble(2059, 298.257223563);
                std::string gname = keys.getAscii(2049);
                if (gname.empty()) gname = "unknown";
                geogWkt = "GEOGCS[\"" + gname + "\",DATUM[\"unknown\",SPHEROID[\"unknown\"," + fmtD(a) + "," + fmtD(rf) + "]],PRIMEM[\"Greenwich\",0],UNIT[\"degree\",0.0174532925199433]]";
            }
            int proj = keys.getShort(3074, -1);
            std::string projWkt;
            double unitSize = 1.0;
            int lu = keys.getShort(3076, 9001);
            std::string unitName = "metre";
            if (lu == 9002) { unitName = "foot"; unitSize = 0.3048; }
            else if (lu == 9003) { unitName = "US survey foot"; unitSize = 0.3048006096012192; }
            else if (lu == 32767) { unitSize = keys.getDouble(3077, 1.0); unitName = "unknown"; }
            if (proj >= 16001 && proj <= 16060) {
                int zone = proj - 16000;
                projWkt = "PROJECTION[\"Transverse_Mercator\"],PARAMETER[\"latitude_of_origin\",0],PARAMETER[\"central_meridian\"," + fmtD(-183 + 6 * zone) + "],PARAMETER[\"scale_factor\",0.9996],PARAMETER[\"false_easting\",500000],PARAMETER[\"false_northing\",0]";
            } else if (proj >= 16101 && proj <= 16160) {
                int zone = proj - 16100;
                projWkt = "PROJECTION[\"Transverse_Mercator\"],PARAMETER[\"latitude_of_origin\",0],PARAMETER[\"central_meridian\"," + fmtD(-183 + 6 * zone) + "],PARAMETER[\"scale_factor\",0.9996],PARAMETER[\"false_easting\",500000],PARAMETER[\"false_northing\",10000000]";
            } else {
                int ct = keys.getShort(3075, -1);
                std::string cn = ctName(ct);
                if (cn.empty()) return false;
                projWkt = "PROJECTION[\"" + cn + "\"]";
                auto addP = [&](const char* name, int key, int altKey = -1) {
                    if (keys.has(key)) projWkt += ",PARAMETER[\"" + std::string(name) + "\"," + fmtD(keys.getDouble(key)) + "]";
                    else if (altKey > 0 && keys.has(altKey)) projWkt += ",PARAMETER[\"" + std::string(name) + "\"," + fmtD(keys.getDouble(altKey)) + "]";
                };
                switch (ct) {
                    case 1: case 27: case 2:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3080, 3088); addP("scale_factor", 3092, 3093); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 7:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3080, 3088); addP("scale_factor", 3092, 3093); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 8:
                        addP("standard_parallel_1", 3078); addP("standard_parallel_2", 3079); addP("latitude_of_origin", 3085, 3081); addP("central_meridian", 3084, 3080); addP("false_easting", 3086, 3082); addP("false_northing", 3087, 3083); break;
                    case 9:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3080, 3088); addP("scale_factor", 3092, 3093); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 11:
                        addP("standard_parallel_1", 3078); addP("standard_parallel_2", 3079); addP("latitude_of_center", 3081, 3089); addP("longitude_of_center", 3080, 3088); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 10: case 12: case 19: case 21:
                        addP("latitude_of_center", 3089, 3081); addP("longitude_of_center", 3088, 3080); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 15:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3095, 3080); addP("scale_factor", 3092, 3093); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 14: case 16:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3080, 3088); addP("scale_factor", 3092, 3093); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 17:
                        addP("latitude_of_origin", 3081, 3089); addP("central_meridian", 3080, 3088); addP("standard_parallel_1", 3078); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 24: case 20: case 23: case 25: case 22: case 18:
                        addP("longitude_of_center", 3088, 3080); addP("latitude_of_origin", 3081, 3089); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 28:
                        addP("standard_parallel_1", 3078); addP("central_meridian", 3080, 3088); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    case 3:
                        addP("latitude_of_center", 3089, 3081); addP("longitude_of_center", 3088, 3080); addP("azimuth", 3094); addP("rectified_grid_angle", 3096); addP("scale_factor", 3093, 3092); addP("false_easting", 3082); addP("false_northing", 3083); break;
                    default: break;
                }
            }
            std::string wkt = "PROJCS[\"" + citation + "\"," + geogWkt + "," + projWkt + ",UNIT[\"" + unitName + "\"," + fmtD(unitSize) + "]]";
            ok = horiz.setFromWKT(wkt);
        }
    } else if (modelType == 2 || (modelType == 0 && gcs > 0)) {
        if (gcs > 0 && gcs != 32767) ok = horiz.setFromEPSG(gcs);
        if (!ok) {
            double a = keys.getDouble(2057, 6378137.0), rf = keys.getDouble(2059, 298.257223563);
            std::string gname = keys.getAscii(2049);
            if (gname.empty()) gname = "unknown";
            std::string wkt = "GEOGCS[\"" + gname + "\",DATUM[\"unknown\",SPHEROID[\"unknown\"," + fmtD(a) + "," + fmtD(rf) + "]],PRIMEM[\"Greenwich\",0],UNIT[\"degree\",0.0174532925199433]]";
            ok = horiz.setFromWKT(wkt);
        }
    } else if (modelType == 3) {
        return false;  // geocentric: unsupported
    } else {
        return false;
    }
    if (!ok) return false;
    if (vert > 0 && vert != 32767) {
        // compound CRS: horizontal + vertical
        CRS v;
        if (v.setFromEPSG(vert)) {
            std::string hcode = horiz.authCode(), vcode = v.authCode();
            if (horiz.authName() == "EPSG" && !hcode.empty() && !vcode.empty()) {
                CRS comp;
                if (comp.setFromUserInput("EPSG:" + hcode + "+" + vcode)) { crs = comp; return true; }
            }
        }
    }
    crs = horiz;
    return true;
}

