bool parseGeoKeys(const TiffIFD& ifd, GeoKeys& keys) {
    const TiffTag* dir = ifd.get(34735);
    if (!dir || dir->nums.size() < 4) return false;
    const TiffTag* dbl = ifd.get(34736);
    const TiffTag* asc = ifd.get(34737);
    int nKeys = (int)dir->nums[3];
