        if (loc == 0) keys.numKeys[key] = {(double)off};
        else if (loc == 34736 && dbl) {
            std::vector<double> v;
            for (int k = 0; k < cnt && (size_t)(off + k) < dbl->nums.size(); k++) v.push_back(dbl->nums[off + k]);
            keys.numKeys[key] = v;
