class GTiffBand : public RasterBand {
public:
    std::shared_ptr<TiffFile> tif;
    const TiffIFD* ifd = nullptr;
    int sampleIndex = 0;
    bool readBlock(int bx, int by, std::vector<uint8_t>& buf, std::string& err) override {
        std::vector<uint8_t> raw;
        if (!tif->readBlock(*ifd, bx, by, sampleIndex, raw, err)) return false;
        int bps = ifd->bitsPerSample();
        int spp = ifd->planarConfig() == 2 ? 1 : ifd->samplesPerPixel();
        int sz = dataTypeSizeBytes(type);
        size_t npix = (size_t)blockX * blockY;
        buf.resize(npix * sz);
        if (bps < 8) {
            // unpack bits (1, 2, 4) -> Byte
            size_t rowBytes = ((size_t)blockX * spp * bps + 7) / 8;
            for (int y = 0; y < blockY; y++) {
                const uint8_t* row = raw.data() + y * rowBytes;
                for (int x = 0; x < blockX; x++) {
                    size_t bit = ((size_t)x * spp + sampleIndex) * bps;
                    uint8_t v = (row[bit / 8] >> (8 - bps - (bit % 8))) & ((1 << bps) - 1);
                    if (ifd->photometric() == 0 && !minisWhite) v = ((1 << bps) - 1) - v;  // not applied: GDAL keeps raw
                    buf[(size_t)y * blockX + x] = v;
                }
            }
            return true;
        }
        if (spp == 1) {
            if (raw.size() < npix * sz) raw.resize(npix * sz, 0);
            memcpy(buf.data(), raw.data(), npix * sz);
        } else {
            int pixBytes = spp * sz;
            if (raw.size() < npix * pixBytes) raw.resize(npix * pixBytes, 0);
            for (size_t i = 0; i < npix; i++) memcpy(buf.data() + i * sz, raw.data() + i * pixBytes + sampleIndex * sz, sz);
        }
        return true;
    }
};

static DataType gtiffDataType(int bps, int sf) {
    // sf: 1 uint, 2 int, 3 float, 5 cint, 6 cfloat
    if (bps <= 8) return sf == 2 ? DataType::Int8 : DataType::Byte;
    if (bps == 16) { if (sf == 3) return DataType::Float16; return sf == 2 ? DataType::Int16 : DataType::UInt16; }
    if (bps == 32) {
        if (sf == 3) return DataType::Float32;
        if (sf == 5) return DataType::CInt16;
        if (sf == 6) return DataType::CFloat16;
        return sf == 2 ? DataType::Int32 : DataType::UInt32;
    }
    if (bps == 64) {
        if (sf == 3) return DataType::Float64;
        if (sf == 5) return DataType::CInt32;
        if (sf == 6) return DataType::CFloat32;
        return sf == 2 ? DataType::Int64 : DataType::UInt64;
    }
    if (bps == 128 && sf == 6) return DataType::CFloat64;
    if (bps < 16) return sf == 2 ? DataType::Int16 : DataType::UInt16;
    if (bps < 32) return sf == 2 ? DataType::Int32 : DataType::UInt32;
    return DataType::Unknown;
}

static std::string compressionName(int c) {
    switch (c) {
        case 1: return "";
        case 2: return "CCITTRLE";
        case 3: return "CCITTFAX3";
        case 4: return "CCITTFAX4";
        case 5: return "LZW";
        case 6: case 7: return "JPEG";
        case 8: case 32946: return "DEFLATE";
        case 32773: return "PACKBITS";
        case 34925: return "LZMA";
        case 50000: return "ZSTD";
        case 50001: return "WEBP";
        case 34887: return "LERC";
        case 50002: return "JXL";
        case 32767: return "JXL";
        default: return strprintf("%d", c);
    }
}

static void parseGdalMetadata(const std::string& xml, RasterDataset& ds) {
    std::string err;
    auto root = xmlParse(xml, &err);
    if (!root || root->name != "GDALMetadata") return;
    for (auto& item : root->children) {
        if (item->name != "Item") continue;
        std::string name = item->attr("name");
        std::string value = item->textContent();
        std::string domain = item->attr("domain");
        std::string role = item->attr("role");
        if (item->hasAttr("sample")) {
            int s = atoi(item->attr("sample").c_str());
            if (s < 0 || s >= (int)ds.bands.size()) continue;
            RasterBand& b = *ds.bands[s];
            if (role == "scale") { b.hasScale = true; b.scale = strtod(value.c_str(), nullptr); }
            else if (role == "offset") { b.hasOffset = true; b.offset = strtod(value.c_str(), nullptr); }
            else if (role == "unittype") b.unitType = value;
            else if (role == "description") b.description = value;
            else if (role == "colorinterp") b.colorInterp = value;
            else b.metadata.set(domain, name, value);
        } else {
            if (role.empty()) ds.metadata.set(domain, name, value);
        }
    }
}

std::shared_ptr<RasterDataset> openGTiff(const std::string& path, std::string& err, int& errCode) {
    auto tif = std::make_shared<TiffFile>();
    if (!tif->open(path, err)) { errCode = 4; return nullptr; }
    auto ds = std::make_shared<RasterDataset>();
    ds->driverShort = "GTiff"; ds->driverLong = "GeoTIFF";
    ds->description = path;
    const TiffIFD& ifd = tif->ifds()[0];
    ds->xsize = (int)ifd.width(); ds->ysize = (int)ifd.height();
    int spp = ifd.samplesPerPixel();
    int bps = ifd.bitsPerSample();
    int sf = ifd.sampleFormat();
    int photometric = ifd.photometric();
    int comp = ifd.compression();
    DataType dt = gtiffDataType(bps, sf);
    if (dt == DataType::Unknown) { err = "Unsupported TIFF configuration"; errCode = 6; return nullptr; }
    // Check for subsequent IFDs: with different size and not reduced images -> subdatasets (multi-page)
    std::vector<const TiffIFD*> overviewIfds, maskIfds;
    bool hasPages = false;
    for (size_t i = 1; i < tif->ifds().size(); i++) {
        const TiffIFD& o = tif->ifds()[i];
        uint32_t nsf = o.newSubfileType();
        if (nsf & 4) maskIfds.push_back(&o);
        else if (nsf & 1) overviewIfds.push_back(&o);
        else hasPages = true;
    }
    if (hasPages) {
        // multi-page TIFF: report subdatasets, no bands
        int idx = 1;
        for (size_t i = 0; i < tif->ifds().size(); i++) {
            const TiffIFD& o = tif->ifds()[i];
            uint32_t nsf = o.newSubfileType();
            if (nsf & 1 || nsf & 4) continue;
            ds->subdatasets.emplace_back(strprintf("GTIFF_DIR:%d:%s", idx, path.c_str()), strprintf("Page %d (%dP x %dL x %dB)", idx, (int)o.width(), (int)o.height(), (int)o.samplesPerPixel()));
            idx++;
        }
    }
    // COG detection: ghost header after TIFF header
    {
        std::vector<uint8_t> hdr;
        uint64_t off = tif->isBigTiff() ? 16 : 8;
        if (tif->readRaw(off, 64, hdr)) {
            std::string s((const char*)hdr.data(), hdr.size());
            if (startsWith(s, "GDAL_STRUCTURAL_METADATA_SIZE=")) {
                int n = atoi(s.c_str() + 30);
                std::vector<uint8_t> sm;
                if (tif->readRaw(off, 43 + n, sm)) {
                    std::string ss((const char*)sm.data(), sm.size());
                    if (ss.find("LAYOUT=IFDS_BEFORE_DATA") != std::string::npos) ds->isCOG = true;
                }
            }
        }
    }
    bool isAlpha[64] = {false};
    const TiffTag* extra = ifd.get(338);
    if (extra) {
        int base = spp - (int)extra->nums.size();
        for (size_t i = 0; i < extra->nums.size() && i < 64; i++) {
            int v = (int)extra->nums[i];
            if (base + (int)i >= 0 && base + (int)i < 64) isAlpha[base + i] = (v == 1 || v == 2);
        }
    }
    int blockX = (int)ifd.tileWidth(), blockY = (int)ifd.tileHeight();
    if (!ifd.isTiled()) { blockX = ds->xsize; if (blockY > ds->ysize) blockY = ds->ysize; }
    bool minisWhite = photometric == 0;
    for (int i = 0; i < spp; i++) {
        auto b = std::make_shared<GTiffBand>();
        b->tif = tif; b->ifd = &ifd; b->sampleIndex = i;
        b->number = i + 1; b->type = dt; b->xsize = ds->xsize; b->ysize = ds->ysize;
        b->blockX = blockX; b->blockY = blockY;
        b->dataset = ds.get();
        b->minisWhite = minisWhite;
        if (photometric == 2 || (photometric == 6)) {
            if (i == 0) b->colorInterp = "Red"; else if (i == 1) b->colorInterp = "Green"; else if (i == 2) b->colorInterp = "Blue";
            else if (isAlpha[i]) b->colorInterp = "Alpha"; else b->colorInterp = "Undefined";
        } else if (photometric == 3) {
            if (i == 0) b->colorInterp = "Palette"; else if (isAlpha[i]) b->colorInterp = "Alpha"; else b->colorInterp = "Undefined";
        } else if (photometric == 5) {
            const char* n[] = {"Cyan", "Magenta", "Yellow", "Black"};
            if (i < 4) b->colorInterp = n[i]; else if (isAlpha[i]) b->colorInterp = "Alpha"; else b->colorInterp = "Undefined";
        } else {
            if (i == 0) b->colorInterp = "Gray"; else if (isAlpha[i]) b->colorInterp = "Alpha"; else b->colorInterp = "Undefined";
        }
        if (bps != 8 && bps != 16 && bps != 32 && bps != 64 && bps != 128) b->nbits = bps;
        if (b->nbits) b->metadata.set("IMAGE_STRUCTURE", "NBITS", std::to_string(bps));
        if (sf == 2 && bps == 8) { /* Int8 */ }
        ds->bands.push_back(b);
    }
    // Color table
    const TiffTag* cmap = ifd.get(320);
    if (photometric == 3 && cmap && !ds->bands.empty()) {
        int n = 1 << (bps > 8 ? 8 : bps);
        int per = (int)cmap->nums.size() / 3;
        if (per < n) n = per;
        auto& b = *ds->bands[0];
        b.hasColorTable = true;
        for (int i = 0; i < n; i++) {
            ColorEntry e;
            e.c1 = (short)((int)cmap->nums[i] / 256);
            e.c2 = (short)((int)cmap->nums[per + i] / 256);
            e.c3 = (short)((int)cmap->nums[2 * per + i] / 256);
            e.c4 = 255;
            b.colorTable.push_back(e);
        }
    }
    // NoData
    const TiffTag* nd = ifd.get(42113);
    if (nd && !nd->str.empty()) {
        std::string s = trimString(nd->str);
        for (auto& b : ds->bands) {
            b->hasNoData = true;
            if (iequals(s, "nan")) b->noData = NAN;
            else if (iequals(s, "inf")) b->noData = INFINITY;
            else if (iequals(s, "-inf")) b->noData = -INFINITY;
            else b->noData = strtod(s.c_str(), nullptr);
            if (dt == DataType::Int64) { b->noDataIsInt64 = true; b->noDataInt64 = strtoll(s.c_str(), nullptr, 10); }
            if (dt == DataType::UInt64) { b->noDataIsUInt64 = true; b->noDataUInt64 = strtoull(s.c_str(), nullptr, 10); }
        }
    }
    // Georeferencing
    GeoKeys keys;
    bool hasKeys = parseGeoKeys(ifd, keys);
    const TiffTag* scale = ifd.get(33550);
    const TiffTag* tie = ifd.get(33922);
    const TiffTag* mat = ifd.get(34264);
    bool pixelIsPoint = hasKeys && keys.getShort(1025, 1) == 2;
    if (mat && mat->nums.size() >= 16) {
        ds->hasGeoTransform = true;
        ds->gt[0] = mat->nums[3]; ds->gt[1] = mat->nums[0]; ds->gt[2] = mat->nums[1];
        ds->gt[3] = mat->nums[7]; ds->gt[4] = mat->nums[4]; ds->gt[5] = mat->nums[5];
    } else if (scale && scale->nums.size() >= 2 && tie && tie->nums.size() >= 6) {
        ds->hasGeoTransform = true;
        ds->gt[1] = scale->nums[0]; ds->gt[5] = -fabs(scale->nums[1]);
        ds->gt[2] = 0; ds->gt[4] = 0;
        ds->gt[0] = tie->nums[3] - tie->nums[0] * ds->gt[1];
        ds->gt[3] = tie->nums[4] - tie->nums[1] * ds->gt[5];
        if (tie->nums.size() > 6) {
            // multiple tiepoints -> GCPs instead
            ds->hasGeoTransform = false;
        }
    }
    if (tie && tie->nums.size() >= 12 && !ds->hasGeoTransform) {
        for (size_t i = 0; i + 6 <= tie->nums.size(); i += 6) {
            GCP g;
            g.id = std::to_string(i / 6 + 1);
            g.pixel = tie->nums[i]; g.line = tie->nums[i + 1];
            g.x = tie->nums[i + 3]; g.y = tie->nums[i + 4]; g.z = tie->nums[i + 5];
            ds->gcps.push_back(g);
        }
    }
    if (ds->hasGeoTransform && pixelIsPoint) {
        // GDAL shifts by half a pixel for PixelIsPoint
        ds->gt[0] -= ds->gt[1] * 0.5 + ds->gt[2] * 0.5;
        ds->gt[3] -= ds->gt[4] * 0.5 + ds->gt[5] * 0.5;
    }
    if (hasKeys) {
        CRS c;
        if (geoKeysToCRS(keys, c)) {
            if (!ds->gcps.empty()) { ds->hasGcpCRS = true; ds->gcpCRS = c; }
            else { ds->hasCRS = true; ds->crs = c; }
        }
    }
    // World file fallback
    if (!ds->hasGeoTransform && ds->gcps.empty()) {
        std::string base = stripExtension(path);
        const char* exts[] = {".tfw", ".tifw", ".wld", nullptr};
        for (int i = 0; exts[i]; i++) {
            std::string wf = base + exts[i];
            std::string content;
            if (readFile(wf, content)) {
                std::vector<double> v;
                char* p = const_cast<char*>(content.c_str());
                while (*p && v.size() < 6) { char* e; double d = strtod(p, &e); if (e == p) break; v.push_back(d); p = e; }
                if (v.size() == 6) {
                    ds->hasGeoTransform = true;
                    ds->gt[1] = v[0]; ds->gt[4] = v[1]; ds->gt[2] = v[2]; ds->gt[5] = v[3];
                    ds->gt[0] = v[4] - 0.5 * v[0] - 0.5 * v[2];
                    ds->gt[3] = v[5] - 0.5 * v[1] - 0.5 * v[3];
                    ds->files.push_back(wf);
                    break;
                }
            }
        }
    }
    // Metadata
    ds->metadata.set("", "AREA_OR_POINT", pixelIsPoint ? "Point" : "Area");
    struct { int tag; const char* name; } asciiTags[] = {
        {269, "TIFFTAG_DOCUMENTNAME"}, {270, "TIFFTAG_IMAGEDESCRIPTION"}, {305, "TIFFTAG_SOFTWARE"}, {306, "TIFFTAG_DATETIME"},
        {315, "TIFFTAG_ARTIST"}, {316, "TIFFTAG_HOSTCOMPUTER"}, {33432, "TIFFTAG_COPYRIGHT"}, {0, nullptr}};
    for (int i = 0; asciiTags[i].name; i++) {
        const TiffTag* t = ifd.get(asciiTags[i].tag);
        if (t && !t->str.empty()) ds->metadata.set("", asciiTags[i].name, t->str);
    }
    if (ifd.has(282)) ds->metadata.set("", "TIFFTAG_XRESOLUTION", formatDoubleG(ifd.num(282)));
    if (ifd.has(283)) ds->metadata.set("", "TIFFTAG_YRESOLUTION", formatDoubleG(ifd.num(283)));
    if (ifd.has(296)) {
        int ru = (int)ifd.num(296);
        ds->metadata.set("", "TIFFTAG_RESOLUTIONUNIT", ru == 1 ? "1 (unitless)" : ru == 2 ? "2 (pixels/inch)" : ru == 3 ? "3 (pixels/cm)" : std::to_string(ru));
    }
    if (ifd.has(280)) ds->metadata.set("", "TIFFTAG_MINSAMPLEVALUE", std::to_string((int)ifd.num(280)));
    if (ifd.has(281)) ds->metadata.set("", "TIFFTAG_MAXSAMPLEVALUE", std::to_string((int)ifd.num(281)));
    const TiffTag* gm = ifd.get(42112);
    if (gm && !gm->str.empty()) parseGdalMetadata(gm->str, *ds);
    // Image structure
    std::string cn = compressionName(comp);
    if (!cn.empty()) {
        if (comp == 7 && photometric == 6) cn = "YCbCr JPEG";
        ds->metadata.set("IMAGE_STRUCTURE", "COMPRESSION", cn);
    }
    if ((comp == 5 || comp == 8 || comp == 32946 || comp == 50000 || comp == 34925) && ifd.predictor() > 1)
        ds->metadata.set("IMAGE_STRUCTURE", "PREDICTOR", std::to_string(ifd.predictor()));
    if (minisWhite) ds->metadata.set("IMAGE_STRUCTURE", "MINISWHITE", "YES");
    ds->metadata.set("IMAGE_STRUCTURE", "INTERLEAVE", (spp > 1 && ifd.planarConfig() == 1) ? "PIXEL" : "BAND");
    if (ds->isCOG) ds->metadata.set("IMAGE_STRUCTURE", "LAYOUT", "COG");
    // Overviews
    for (auto* o : overviewIfds) {
        if ((int)o->samplesPerPixel() != spp) continue;
        for (int i = 0; i < spp; i++) {
            auto b = std::make_shared<GTiffBand>();
            b->tif = tif; b->ifd = o; b->sampleIndex = i;
            b->number = i + 1; b->type = gtiffDataType(o->bitsPerSample(), o->sampleFormat());
            b->xsize = (int)o->width(); b->ysize = (int)o->height();
            b->blockX = (int)o->tileWidth(); b->blockY = (int)o->tileHeight();
            if (!o->isTiled()) { b->blockX = b->xsize; if (b->blockY > b->ysize) b->blockY = b->ysize; }
            b->colorInterp = ds->bands[i]->colorInterp;
            b->hasNoData = ds->bands[i]->hasNoData; b->noData = ds->bands[i]->noData;
            ds->bands[i]->overviews.push_back(b);
        }
    }
    // Mask
    if (!maskIfds.empty()) {
        for (auto& b : ds->bands) b->maskFlags = 2;  // GMF_PER_DATASET
    } else {
        for (auto& b : ds->bands) {
            if (b->colorInterp == "Alpha" && spp > 1) { for (auto& bb : ds->bands) if (bb->colorInterp != "Alpha") bb->maskFlags = 2 | 8; break; }
        }
        for (auto& b : ds->bands) if (b->hasNoData && b->maskFlags == 1) b->maskFlags = 8;  // GMF_NODATA
    }
    // Files
    ds->files.insert(ds->files.begin(), path);
    if (fileExists(path + ".aux.xml")) { ds->pamPath = path + ".aux.xml"; ds->files.push_back(path + ".aux.xml"); }
    else ds->pamPath = path + ".aux.xml";
    // External overviews
    if (fileExists(path + ".ovr")) ds->files.push_back(path + ".ovr");
    if (fileExists(path + ".msk")) ds->files.push_back(path + ".msk");
    loadPam(*ds);
    errCode = 0;
    return ds;
}
