#include "raster.h"
#include "xml.h"
#include "util.h"
#include <cstring>
#include <cmath>

static std::string fmt14g(double v) {
    char buf[64];
    snprintf(buf, sizeof(buf), "%.14g", v);
    return buf;
}

bool loadPam(RasterDataset& ds) {
    if (ds.pamPath.empty() || !fileExists(ds.pamPath)) return false;
    std::string content;
    if (!readFile(ds.pamPath, content)) return false;
    auto root = xmlParse(content);
    if (!root || root->name != "PAMDataset") return false;
    // Dataset level
    for (auto& c : root->children) {
        if (c->name == "SRS" && !ds.hasCRS) {
            CRS crs;
            if (crs.setFromUserInput(c->textContent())) { ds.hasCRS = true; ds.crs = crs; }
        } else if (c->name == "GeoTransform" && !ds.hasGeoTransform) {
            auto parts = splitString(c->textContent(), ',');
            if (parts.size() == 6) { ds.hasGeoTransform = true; for (int i = 0; i < 6; i++) ds.gt[i] = strtod(parts[i].c_str(), nullptr); }
        } else if (c->name == "Metadata") {
            std::string domain = c->attr("domain");
            for (auto& m : c->children) if (m->name == "MDI") ds.metadata.set(domain, m->attr("key"), m->textContent());
        } else if (c->name == "PAMRasterBand") {
            int band = atoi(c->attr("band").c_str());
            if (band < 1 || band > (int)ds.bands.size()) continue;
            RasterBand& b = *ds.bands[band - 1];
            for (auto& e : c->children) {
                if (e->name == "Description") b.description = e->textContent();
                else if (e->name == "NoDataValue") { b.hasNoData = true; std::string t = trimString(e->textContent()); b.noData = iequals(t, "nan") ? NAN : strtod(t.c_str(), nullptr); }
                else if (e->name == "UnitType") b.unitType = e->textContent();
                else if (e->name == "Offset") { b.hasOffset = true; b.offset = strtod(e->textContent().c_str(), nullptr); }
                else if (e->name == "Scale") { b.hasScale = true; b.scale = strtod(e->textContent().c_str(), nullptr); }
                else if (e->name == "ColorInterp") b.colorInterp = e->textContent();
                else if (e->name == "Metadata") {
                    std::string domain = e->attr("domain");
                    for (auto& m : e->children) if (m->name == "MDI") b.metadata.set(domain, m->attr("key"), m->textContent());
                } else if (e->name == "Histograms") {
                    // stored in metadata domain "__pam_hist__" as serialized text for later use
                    for (auto& hi : e->children) {
                        if (hi->name != "HistItem") continue;
                        std::string s = hi->childText("HistMin") + "|" + hi->childText("HistMax") + "|" + hi->childText("BucketCount") + "|" + hi->childText("IncludeOutOfRange") + "|" + hi->childText("Approximate") + "|" + hi->childText("HistCounts");
                        b.metadata.set("__pam_hist__", "hist", s);
                    }
                }
            }
        }
    }
    return true;
}

bool savePam(RasterDataset& ds) {
    if (ds.pamPath.empty()) return false;
    XmlNode root;
    root.name = "PAMDataset";
    // Existing PAM content: we regenerate from the in-memory state (stats + histograms only, plus pre-existing items)
    std::string existing;
    std::shared_ptr<XmlNode> old;
    if (readFile(ds.pamPath, existing)) old = xmlParse(existing);
    // dataset-level metadata domains from old file retained
    if (old) {
        for (auto& c : old->children) if (c->name != "PAMRasterBand") root.children.push_back(c);
    }
    for (auto& b : ds.bands) {
        bool hasStats = b->metadata.has("", "STATISTICS_MINIMUM");
        bool hasHist = b->metadata.has("__pam_hist__", "hist");
        std::shared_ptr<XmlNode> oldBand;
        if (old) for (auto& c : old->children) if (c->name == "PAMRasterBand" && atoi(c->attr("band").c_str()) == b->number) oldBand = c;
        if (!hasStats && !hasHist && !oldBand) continue;
        auto bn = root.addChild("PAMRasterBand");
        bn->setAttr("band", std::to_string(b->number));
        if (oldBand) {
            for (auto& c : oldBand->children) if (c->name != "Metadata" && c->name != "Histograms") bn->children.push_back(c);
        }
        if (hasStats) {
            auto md = bn->addChild("Metadata");
            const MetadataList* l = b->metadata.domain("");
            for (auto& kv : *l) {
                if (!startsWith(kv.first, "STATISTICS_")) continue;
                auto mdi = md->addChildWithText("MDI", kv.second);
                mdi->setAttr("key", kv.first);
            }
        } else if (oldBand) {
            for (auto& c : oldBand->children) if (c->name == "Metadata") bn->children.push_back(c);
        }
        if (hasHist) {
            auto hs = bn->addChild("Histograms");
            auto parts = splitString(b->metadata.get("__pam_hist__", "hist"), '|');
            if (parts.size() == 6) {
                auto hi = hs->addChild("HistItem");
                hi->addChildWithText("HistMin", parts[0]);
                hi->addChildWithText("HistMax", parts[1]);
                hi->addChildWithText("BucketCount", parts[2]);
                hi->addChildWithText("IncludeOutOfRange", parts[3]);
                hi->addChildWithText("Approximate", parts[4]);
                hi->addChildWithText("HistCounts", parts[5]);
            }
        } else if (oldBand) {
            for (auto& c : oldBand->children) if (c->name == "Histograms") bn->children.push_back(c);
        }
    }
    if (root.children.empty()) return true;
    std::string out = xmlSerialize(root);
    return writeFile(ds.pamPath, out);
}

void setBandStatistics(RasterBand& b, const BandStats& st, bool approx, uint64_t totalPixels) {
    b.metadata.set("", "STATISTICS_MINIMUM", fmt14g(st.min));
    b.metadata.set("", "STATISTICS_MAXIMUM", fmt14g(st.max));
    b.metadata.set("", "STATISTICS_MEAN", fmt14g(st.mean));
    b.metadata.set("", "STATISTICS_STDDEV", fmt14g(st.stddev));
    if (approx) b.metadata.set("", "STATISTICS_APPROXIMATE", "YES");
    double pct = totalPixels ? st.validCount * 100.0 / totalPixels : 0;
    char buf[64];
    snprintf(buf, sizeof(buf), "%.4g", pct);
    b.metadata.set("", "STATISTICS_VALID_PERCENT", buf);
}
