            }
        } else if (oldBand) {
            for (auto& c : oldBand->children) if (c->name == "Metadata") bn->children.push_back(c);
        }
        if (hasHist) {
            auto hs = bn->addChild("Histograms");
            auto parts = splitString(b->metadata.get("__pam_hist__", "hist"), '|');
            if (parts.size() == 6) {
                auto hi = hs->addChild("HistItem");
                hi->addChildWithText("HistMin", parts[0]);
                hi->addChildWithText("HistMax", parts[1]);
                hi->addChildWithText("BucketCount", parts[2]);
                hi->addChildWithText("IncludeOutOfRange", parts[3]);
                hi->addChildWithText("Approximate", parts[4]);
                hi->addChildWithText("HistCounts", parts[5]);
            }
        } else if (oldBand) {
            for (auto& c : oldBand->children) if (c->name == "Histograms") bn->children.push_back(c);
        }
    }
    if (root.children.empty()) return true;
    std::string out = xmlSerialize(root);
    return writeFile(ds.pamPath, out);
}

void setBandStatistics(RasterBand& b, const BandStats& st, bool approx, uint64_t totalPixels) {
    b.metadata.set("", "STATISTICS_MINIMUM", fmt14g(st.min));
    b.metadata.set("", "STATISTICS_MAXIMUM", fmt14g(st.max));
    b.metadata.set("", "STATISTICS_MEAN", fmt14g(st.mean));
    b.metadata.set("", "STATISTICS_STDDEV", fmt14g(st.stddev));
    if (approx) b.metadata.set("", "STATISTICS_APPROXIMATE", "YES");
    double pct = totalPixels ? st.validCount * 100.0 / totalPixels : 0;
    char buf[64];
    snprintf(buf, sizeof(buf), "%.4g", pct);
    b.metadata.set("", "STATISTICS_VALID_PERCENT", buf);
}
