cat > src/raster_info.cpp <<'EOF'
#include "raster_info.h"
#include "util.h"
#include <cmath>
#include <cstring>
#include <algorithm>

std::string decToDMS(double dfAngle, const char* pszAxis, int nPrecision) {
    if (std::isnan(dfAngle)) return "Invalid angle";
    const double dfEpsilon = (0.5 / 3600.0) * pow(0.1, nPrecision);
    const double dfABSAngle = std::abs(dfAngle) + dfEpsilon;
    if (dfABSAngle > 361.0) return "Invalid angle";
    const int nDegrees = (int)dfABSAngle;
    const int nMinutes = (int)((dfABSAngle - nDegrees) * 60);
    double dfSeconds = dfABSAngle * 3600 - nDegrees * 3600 - nMinutes * 60;
    if (dfSeconds > dfEpsilon * 3600.0) dfSeconds -= dfEpsilon * 3600.0;
    const char* pszHemisphere;
    if (iequals(pszAxis, "Long") && dfAngle < 0.0) pszHemisphere = "W";
    else if (iequals(pszAxis, "Long")) pszHemisphere = "E";
    else if (dfAngle < 0.0) pszHemisphere = "S";
    else pszHemisphere = "N";
    char szFormat[30];
    snprintf(szFormat, sizeof(szFormat), "%%3dd%%2d'%%%d.%df\"%s", nPrecision + 3, nPrecision, pszHemisphere);
    char buf[64];
    snprintf(buf, sizeof(buf), szFormat, nDegrees, nMinutes, dfSeconds);
    return buf;
}

std::string crsSummaryText(const CRS& crs, const std::string& indent) {
    std::string s;
    s += indent + "- name: " + crs.name() + "\n";
    std::string an = crs.authName(), ac = crs.authCode();
    if (!an.empty() && !ac.empty()) s += indent + "- ID: " + an + ":" + ac + "\n";
    s += indent + "- type: " + crs.typeString() + "\n";
    double w, so, e, n;
    std::string area;
    if (crs.areaOfUse(w, so, e, n, area)) {
        s += indent + strprintf("- area of use: %s, west %.2f, south %.2f, east %.2f, north %.2f\n", area.c_str(), w, so, e, n);
    }
    return s;
}

static std::string metadataText(const Metadata& md, const std::string& domain, const std::string& title, const std::string& indent) {
    const MetadataList* l = md.domain(domain);
    if (!l || l->empty()) return "";
    std::string s = indent + title + ":\n";
    for (auto& kv : *l) s += indent + "  " + kv.first + "=" + kv.second + "\n";
    return s;
}

static JsonValue metadataJson(const Metadata& md, const std::vector<std::string>& domains) {
    JsonValue o = JsonValue::object();
    for (auto& d : domains) {
        const MetadataList* l = md.domain(d);
        if (!l || l->empty()) continue;
        JsonValue dom = JsonValue::object();
        for (auto& kv : *l) dom.set(kv.first, JsonValue::string(kv.second));
        o.set(d, dom);
    }
    return o;
}

static std::vector<std::string> reportDomains(const Metadata& md, const RasterInfoOptions& o, bool isBand) {
    std::vector<std::string> doms;
    if (!o.mdd.empty()) {
        if (iequals(o.mdd, "all")) { for (auto& d : md.domainNames()) if (d != "__pam_hist__") doms.push_back(d); return doms; }
        for (auto& d : splitString(o.mdd, ',')) doms.push_back(d);
        return doms;
    }
    doms.push_back("");
    if (!isBand) { doms.push_back("IMAGE_STRUCTURE"); doms.push_back("SUBDATASETS"); doms.push_back("GEOLOCATION"); doms.push_back("RPC"); }
    else doms.push_back("IMAGE_STRUCTURE");
    return doms;
}

static std::string domainTitle(const std::string& d) {
    if (d.empty()) return "Metadata";
    if (d == "IMAGE_STRUCTURE") return "Image Structure Metadata";
    if (d == "SUBDATASETS") return "Subdatasets";
    if (d == "GEOLOCATION") return "Geolocation";
    if (d == "RPC") return "RPC Metadata";
    return "Metadata (" + d + ")";
}

static bool getCornerGeo(const RasterDataset& ds, double px, double py, double& x, double& y) {
    if (!ds.hasGeoTransform) { x = px; y = py; return false; }
    ds.pixelToGeo(px, py, x, y);
    return true;
}

static const char* dataTypeStac(DataType t) {
    switch (t) {
        case DataType::Byte: return "uint8";
        case DataType::Int8: return "int8";
        case DataType::UInt16: return "uint16";
        case DataType::Int16: return "int16";
        case DataType::UInt32: return "uint32";
        case DataType::Int32: return "int32";
        case DataType::UInt64: return "uint64";
        case DataType::Int64: return "int64";
        case DataType::Float16: return "float16";
        case DataType::Float32: return "float32";
        case DataType::Float64: return "float64";
        case DataType::CInt16: return "cint16";
        case DataType::CInt32: return "cint32";
        case DataType::CFloat16: return "cfloat16";
        case DataType::CFloat32: return "cfloat32";
        case DataType::CFloat64: return "cfloat64";
        default: return "unknown";
    }
}

// Helper: get stored stats from metadata
static bool getStoredStats(const RasterBand& b, double& mn, double& mx, double& mean, double& sd, bool* approx = nullptr) {
    if (!b.metadata.has("", "STATISTICS_MINIMUM") || !b.metadata.has("", "STATISTICS_MAXIMUM") || !b.metadata.has("", "STATISTICS_MEAN") || !b.metadata.has("", "STATISTICS_STDDEV")) return false;
    mn = strtod(b.metadata.get("", "STATISTICS_MINIMUM").c_str(), nullptr);
    mx = strtod(b.metadata.get("", "STATISTICS_MAXIMUM").c_str(), nullptr);
    mean = strtod(b.metadata.get("", "STATISTICS_MEAN").c_str(), nullptr);
    sd = strtod(b.metadata.get("", "STATISTICS_STDDEV").c_str(), nullptr);
    if (approx) *approx = iequals(b.metadata.get("", "STATISTICS_APPROXIMATE"), "YES");
    return true;
}

struct BandReport {
    bool gotMin = false, gotMax = false; double mn = 0, mx = 0;
    bool computedMM = false; double cmn = 0, cmx = 0;
    bool gotStats = false; double smin = 0, smax = 0, smean = 0, ssd = 0;
    bool gotHist = false; double hmin = 0, hmax = 0; std::vector<uint64_t> hist;
    bool gotChecksum = false; int checksum = 0;
    std::vector<int> ovChecksums;
};

static void prepareBand(RasterDataset& ds, RasterBand& b, const RasterInfoOptions& o, BandReport& r) {
    std::string err;
    double smin, smax, smean, ssd;
    bool haveStored = getStoredStats(b, smin, smax, smean, ssd);
    if (haveStored) { r.gotMin = r.gotMax = true; r.mn = smin; r.mx = smax; }
    if (o.computeMinMax) {
        if (computeMinMax(b, false, r.cmn, r.cmx, err)) r.computedMM = true;
    }
    if (haveStored) { r.gotStats = true; r.smin = smin; r.smax = smax; r.smean = smean; r.ssd = ssd; }
    else if (o.stats || o.approxStats) {
        BandStats st = computeStats(b, o.approxStats, err);
        if (st.ok) {
            r.gotStats = true; r.smin = st.min; r.smax = st.max; r.smean = st.mean; r.ssd = st.stddev;
            setBandStatistics(b, st, o.approxStats, (uint64_t)b.xsize * b.ysize);
            ds.pamDirty = true;
            r.gotMin = r.gotMax = true; r.mn = st.min; r.mx = st.max;
        } else if (!err.empty()) {
            cplError(1, err);
        }
    }
    if (o.hist) {
        // stored histogram?
        std::string stored = b.metadata.get("__pam_hist__", "hist");
        bool ok = false;
        if (!stored.empty()) {
            auto parts = splitString(stored, '|');
            if (parts.size() == 6) {
                r.hmin = strtod(parts[0].c_str(), nullptr); r.hmax = strtod(parts[1].c_str(), nullptr);
                int n = atoi(parts[2].c_str());
                auto cs = splitString(parts[5], '|');
                r.hist.clear();
                for (auto& c : splitString(parts[5], '|')) r.hist.push_back(strtoull(c.c_str(), nullptr, 10));
                (void)cs;
                if ((int)r.hist.size() == n) ok = true;
            }
        }
        if (!ok) {
            int nBuckets = 256;
            if (b.type == DataType::Byte) { r.hmin = -0.5; r.hmax = 255.5; }
            else if (b.type == DataType::Int8) { r.hmin = -128.5; r.hmax = 127.5; }
            else {
                double mn, mx;
                if (!computeMinMax(b, true, mn, mx, err)) { cplError(1, err); return; }
                double half = (mx - mn) / (2 * (nBuckets - 1));
                r.hmin = mn - half; r.hmax = mx + half;
            }
            if (computeHistogram(b, r.hmin, r.hmax, nBuckets, r.hist, false, err)) {
                ok = true;
                std::string counts;
                for (size_t i = 0; i < r.hist.size(); i++) { if (i) counts += "|"; counts += std::to_string(r.hist[i]); }
                b.metadata.set("__pam_hist__", "hist", strprintf("%.14g", r.hmin) + "|" + strprintf("%.14g", r.hmax) + "|" + std::to_string(nBuckets) + "|0|0|" + counts);
                ds.pamDirty = true;
            }
        }
        r.gotHist = ok;
    }
    if (o.checksum) {
        int cs = computeChecksum(b, 0, 0, b.xsize, b.ysize, err);
        if (cs >= 0) { r.gotChecksum = true; r.checksum = cs; }
        for (auto& ov : b.overviews) {
            int c2 = computeChecksum(*ov, 0, 0, ov->xsize, ov->ysize, err);
            r.ovChecksums.push_back(c2);
        }
    }
}

static std::string nodataText(const RasterBand& b) {
    if (b.noDataIsInt64) return std::to_string(b.noDataInt64);
    if (b.noDataIsUInt64) return std::to_string(b.noDataUInt64);
    if (std::isnan(b.noData)) return "nan";
    if (std::isinf(b.noData)) return b.noData > 0 ? "inf" : "-inf";
    return strprintf("%.18g", b.noData);
}

static std::string maskFlagsText(int f) {
    std::string s;
    if (f & 1) s += "ALL_VALID ";
    if (f & 2) s += "PER_DATASET ";
    if (f & 4) s += "ALPHA ";
    if (f & 8) s += "NODATA ";
    return s;
}

std::string rasterInfoText(RasterDataset& ds, const RasterInfoOptions& o) {
    std::string s;
    s += "Driver: " + ds.driverShort + "/" + ds.driverLong + "\n";
    if (!o.noFl) {
        if (ds.files.empty()) s += "Files: none associated\n";
        else {
            s += "Files: " + ds.files[0] + "\n";
            for (size_t i = 1; i < ds.files.size(); i++) s += "       " + ds.files[i] + "\n";
        }
    }
    s += strprintf("Size is %d, %d\n", ds.xsize, ds.ysize);
    CRS geogCRS;
    bool haveGeog = false;
    if (ds.hasCRS) {
        if (iequals(o.crsFormat, "WKT2")) s += "Coordinate System is:\n" + ds.crs.exportWkt2_2019(true) + "\n";
        else if (iequals(o.crsFormat, "PROJJSON")) s += "Coordinate System is:\n" + ds.crs.exportProjjson() + "\n";
        else s += "Coordinate Reference System:\n" + crsSummaryText(ds.crs, "  ");
        auto m = ds.crs.dataAxisToSRSAxisMapping();
        std::string ms;
        for (size_t i = 0; i < m.size(); i++) { if (i) ms += ","; ms += std::to_string(m[i]); }
        s += "Data axis to CRS axis mapping: " + ms + "\n";
        haveGeog = ds.crs.geographicCRS(geogCRS);
    }
    if (ds.hasGeoTransform) {
        if (ds.gt[2] == 0.0 && ds.gt[4] == 0.0) {
            s += strprintf("Origin = (%.15f,%.15f)\n", ds.gt[0], ds.gt[3]);
            s += strprintf("Pixel Size = (%.15f,%.15f)\n", ds.gt[1], ds.gt[5]);
        } else {
            s += strprintf("GeoTransform =\n  %.16g, %.16g, %.16g\n  %.16g, %.16g, %.16g\n", ds.gt[0], ds.gt[1], ds.gt[2], ds.gt[3], ds.gt[4], ds.gt[5]);
        }
    }
    if (!o.noGcp && !ds.gcps.empty()) {
        if (ds.hasGcpCRS) {
            s += "GCP Projection = \n" + ds.gcpCRS.exportWkt1(true) + "\n";
        }
        for (size_t i = 0; i < ds.gcps.size(); i++) {
            const GCP& g = ds.gcps[i];
            s += strprintf("GCP[%3d]: Id=%s, Info=%s\n          (%.15g,%.15g) -> (%.15g,%.15g,%.15g)\n", (int)i, g.id.c_str(), g.info.c_str(), g.pixel, g.line, g.x, g.y, g.z);
        }
    }
    if (o.listMdd) {
        auto names = ds.metadata.domainNames();
        s += "Metadata domains:\n";
        for (auto& n : names) {
            if (n == "__pam_hist__") continue;
            if (n.empty()) s += "  (default)\n"; else s += "  " + n + "\n";
        }
    }
    if (!o.noMd) {
        for (auto& d : reportDomains(ds.metadata, o, false)) s += metadataText(ds.metadata, d, domainTitle(d), "");
    }
    if (!ds.subdatasets.empty() && !o.noMd) {
        s += "Subdatasets:\n";
        for (size_t i = 0; i < ds.subdatasets.size(); i++) {
            s += strprintf("  SUBDATASET_%d_NAME=%s\n  SUBDATASET_%d_DESC=%s\n", (int)i + 1, ds.subdatasets[i].first.c_str(), (int)i + 1, ds.subdatasets[i].second.c_str());
        }
    }
    // Corners
    s += "Corner Coordinates:\n";
    CoordTransform ct;
    bool haveCT = false;
    if (ds.hasCRS && haveGeog && ds.hasGeoTransform) haveCT = ct.init(ds.crs, geogCRS);
    auto corner = [&](const char* name, double px, double py) {
        s += strprintf("%-11s ", name);
        double x, y;
        if (!ds.hasGeoTransform) { s += strprintf("(%7.1f,%7.1f)\n", px, py); return; }
        getCornerGeo(ds, px, py, x, y);
        if (fabs(x) < 181 && fabs(y) < 91) s += strprintf("(%12.7f,%12.7f) ", x, y);
        else s += strprintf("(%12.3f,%12.3f) ", x, y);
        if (haveCT) {
            double lx = x, ly = y;
            if (ct.transform(lx, ly)) {
                s += "(" + decToDMS(lx, "Long", 2) + "," + decToDMS(ly, "Lat", 2) + ")";
            }
        }
        s += "\n";
    };
    corner("Upper Left", 0, 0);
    corner("Lower Left", 0, ds.ysize);
    corner("Upper Right", ds.xsize, 0);
    corner("Lower Right", ds.xsize, ds.ysize);
    corner("Center", ds.xsize / 2.0, ds.ysize / 2.0);
    // Bands
    for (auto& bp : ds.bands) {
        RasterBand& b = *bp;
        BandReport r;
        prepareBand(ds, b, o, r);
        s += strprintf("Band %d Block=%dx%d Type=%s, ColorInterp=%s\n", b.number, b.blockX, b.blockY, dataTypeName(b.type), b.colorInterp.c_str());
        if (!b.description.empty()) s += "  Description = " + b.description + "\n";
        if (r.gotMin || r.gotMax || o.computeMinMax) {
            s += "  ";
            if (r.gotMin) s += strprintf("Min=%.3f ", r.mn);
            if (r.gotMax) s += strprintf("Max=%.3f ", r.mx);
            if (o.computeMinMax && r.computedMM) s += strprintf("  Computed Min/Max=%.3f,%.3f", r.cmn, r.cmx);
            s += "\n";
        }
        if (r.gotStats) s += strprintf("  Minimum=%.3f, Maximum=%.3f, Mean=%.3f, StdDev=%.3f\n", r.smin, r.smax, r.smean, r.ssd);
        if (r.gotHist) {
            s += strprintf("  %d buckets from %g to %g:\n  ", (int)r.hist.size(), r.hmin, r.hmax);
            for (auto c : r.hist) s += strprintf("%llu ", (unsigned long long)c);
            s += "\n";
        }
        if (r.gotChecksum) s += strprintf("  Checksum=%d\n", r.checksum);
        if (b.hasNoData && !o.noNodata) s += "  NoData Value=" + nodataText(b) + "\n";
        if (!b.overviews.empty()) {
            s += "  Overviews: ";
            for (size_t i = 0; i < b.overviews.size(); i++) {
                if (i) s += ", ";
                s += strprintf("%dx%d", b.overviews[i]->xsize, b.overviews[i]->ysize);
            }
            s += "\n";
            if (o.checksum && !r.ovChecksums.empty()) {
                s += "  Overviews checksum: ";
                for (size_t i = 0; i < r.ovChecksums.size(); i++) { if (i) s += ", "; s += strprintf("%d", r.ovChecksums[i]); }
                s += "\n";
            }
        }
        if (!o.noMask) {
            int f = b.maskFlags;
            if ((f & (8 | 1)) == 0) {
                s += "  Mask Flags: " + maskFlagsText(f) + "\n";
            }
        }
        if (!b.unitType.empty()) s += "  Unit Type: " + b.unitType + "\n";
        if (!b.categoryNames.empty()) {
            s += "  Categories:\n";
            for (size_t i = 0; i < b.categoryNames.size(); i++) s += strprintf("    %3d: %s\n", (int)i, b.categoryNames[i].c_str());
        }
        if (b.hasOffset || b.hasScale) {
            double off = b.hasOffset ? b.offset : 0, sc = b.hasScale ? b.scale : 1;
            if (off != 0.0 || sc != 1.0) s += strprintf("  Offset: %.15g,   Scale:%.15g\n", off, sc);
        }
        if (!o.noMd) {
            for (auto& d : reportDomains(b.metadata, o, true)) {
                if (d == "__pam_hist__") continue;
                s += metadataText(b.metadata, d, domainTitle(d), "  ");
            }
        }
        if (b.hasColorTable && !o.noCt) {
            s += strprintf("  Color Table (RGB with %d entries)\n", (int)b.colorTable.size());
            for (size_t i = 0; i < b.colorTable.size(); i++) {
                const ColorEntry& e = b.colorTable[i];
                s += strprintf("  %3d: %d,%d,%d,%d\n", (int)i, e.c1, e.c2, e.c3, e.c4);
            }
        }
    }
    if (ds.pamDirty) savePam(ds);
    return s;
}

static JsonValue dbl(double v, int prec) {
    JsonValue j = JsonValue::number(v);
    j.setRawNumber(ogrFormatDouble(v, prec));
    return j;
}

JsonValue rasterInfoJson(RasterDataset& ds, const RasterInfoOptions& o) {
    JsonValue root = JsonValue::object();
    root.set("description", JsonValue::string(ds.description));
    root.set("driverShortName", JsonValue::string(ds.driverShort));
    root.set("driverLongName", JsonValue::string(ds.driverLong));
    if (!o.noFl) {
        JsonValue files = JsonValue::array();
        for (auto& f : ds.files) files.push(JsonValue::string(f));
        root.set("files", files);
    }
    JsonValue size = JsonValue::array();
    size.push(JsonValue::integer(ds.xsize)); size.push(JsonValue::integer(ds.ysize));
    root.set("size", size);
    CRS geogCRS;
    bool haveGeog = false;
    if (ds.hasCRS) {
        JsonValue cs = JsonValue::object();
        if (iequals(o.crsFormat, "PROJJSON")) cs.set("projjson", ds.crs.projjsonValue());
        else cs.set("wkt", JsonValue::string(ds.crs.exportWkt2_2019(true)));
        JsonValue m = JsonValue::array();
        for (int v : ds.crs.dataAxisToSRSAxisMapping()) m.push(JsonValue::integer(v));
        cs.set("dataAxisToSRSAxisMapping", m);
        root.set("coordinateSystem", cs);
        haveGeog = ds.crs.geographicCRS(geogCRS);
    }
    if (ds.hasGeoTransform) {
        JsonValue gt = JsonValue::array();
        for (int i = 0; i < 6; i++) gt.push(dbl(ds.gt[i], 16));
        root.set("geoTransform", gt);
    }
    if (!o.noGcp && !ds.gcps.empty()) {
        JsonValue gcps = JsonValue::object();
        if (ds.hasGcpCRS) {
            JsonValue cs = JsonValue::object();
            cs.set("wkt", JsonValue::string(ds.gcpCRS.exportWkt2_2019(true)));
            JsonValue m = JsonValue::array();
            for (int v : ds.gcpCRS.dataAxisToSRSAxisMapping()) m.push(JsonValue::integer(v));
            cs.set("dataAxisToSRSAxisMapping", m);
            gcps.set("coordinateSystem", cs);
        }
        JsonValue list = JsonValue::array();
        for (auto& g : ds.gcps) {
            JsonValue j = JsonValue::object();
            j.set("id", JsonValue::string(g.id));
            j.set("info", JsonValue::string(g.info));
            j.set("pixel", dbl(g.pixel, 15));
            j.set("line", dbl(g.line, 15));
            j.set("x", dbl(g.x, 15));
            j.set("y", dbl(g.y, 15));
            j.set("z", dbl(g.z, 15));
            list.push(j);
        }
        gcps.set("gcpList", list);
        root.set("gcps", gcps);
    }
    if (!o.noMd) {
        std::vector<std::string> doms = reportDomains(ds.metadata, o, false);
        root.set("metadata", metadataJson(ds.metadata, doms));
    }
    // corners
    CoordTransform ct;
    bool haveCT = false;
    if (ds.hasCRS && haveGeog && ds.hasGeoTransform) haveCT = ct.init(ds.crs, geogCRS);
    CoordTransform ctWgs;
    bool haveWgs = false;
    if (ds.hasCRS && ds.hasGeoTransform) { CRS w = CRS::wgs84(); haveWgs = ctWgs.init(ds.crs, w); }
    if (ds.hasGeoTransform) {
        JsonValue cc = JsonValue::object();
        JsonValue ring = JsonValue::array();
        auto corner = [&](const char* name, double px, double py, bool inRing) {
            double x, y;
            getCornerGeo(ds, px, py, x, y);
            JsonValue c = JsonValue::array();
            c.push(dbl(x, 7)); c.push(dbl(y, 7));
            cc.set(name, c);
            if (inRing && haveWgs) {
                double lx = x, ly = y;
                if (ctWgs.transform(lx, ly)) {
                    JsonValue p = JsonValue::array();
                    p.push(dbl(lx, 7)); p.push(dbl(ly, 7));
                    ring.push(p);
                }
            }
        };
        corner("upperLeft", 0, 0, true);
        corner("lowerLeft", 0, ds.ysize, true);
        corner("lowerRight", ds.xsize, ds.ysize, true);
        corner("upperRight", ds.xsize, 0, true);
        corner("center", ds.xsize / 2.0, ds.ysize / 2.0, false);
        root.set("cornerCoordinates", cc);
        if (haveWgs && ring.size() == 4) {
            ring.push(ring[0]);
            JsonValue ext = JsonValue::object();
            ext.set("type", JsonValue::string("Polygon"));
            JsonValue coords = JsonValue::array();
            coords.push(ring);
            ext.set("coordinates", coords);
            root.set("wgs84Extent", ext);
        }
    }
    (void)haveCT;
    JsonValue bands = JsonValue::array();
    JsonValue stacRasterBands = JsonValue::array();
    JsonValue stacEOBands = JsonValue::array();
    for (auto& bp : ds.bands) {
        RasterBand& b = *bp;
        BandReport r;
        prepareBand(ds, b, o, r);
        JsonValue j = JsonValue::object();
        j.set("band", JsonValue::integer(b.number));
        JsonValue blk = JsonValue::array();
        blk.push(JsonValue::integer(b.blockX)); blk.push(JsonValue::integer(b.blockY));
        j.set("block", blk);
        j.set("type", JsonValue::string(dataTypeName(b.type)));
        j.set("colorInterpretation", JsonValue::string(b.colorInterp));
        if (!b.description.empty()) j.set("description", JsonValue::string(b.description));
        if (r.gotMin) j.set("min", dbl(r.mn, 3));
        if (r.gotMax) j.set("max", dbl(r.mx, 3));
        if (o.computeMinMax && r.computedMM) { j.set("computedMin", dbl(r.cmn, 3)); j.set("computedMax", dbl(r.cmx, 3)); }
        JsonValue stacBand = JsonValue::object();
        stacBand.set("data_type", JsonValue::string(dataTypeStac(b.type)));
        if (r.gotStats) {
            j.set("minimum", dbl(r.smin, 3));
            j.set("maximum", dbl(r.smax, 3));
            j.set("mean", dbl(r.smean, 3));
            j.set("stdDev", dbl(r.ssd, 3));
            JsonValue st = JsonValue::object();
            st.set("minimum", dbl(r.smin, 3));
            st.set("maximum", dbl(r.smax, 3));
            st.set("mean", dbl(r.smean, 3));
            st.set("stddev", dbl(r.ssd, 3));
            if (b.metadata.has("", "STATISTICS_VALID_PERCENT")) st.set("valid_percent", dbl(strtod(b.metadata.get("", "STATISTICS_VALID_PERCENT").c_str(), nullptr), 3));
            stacBand.set("statistics", st);
        }
        if (r.gotHist) {
            JsonValue h = JsonValue::object();
            h.set("count", JsonValue::integer((long long)r.hist.size()));
            h.set("min", dbl(r.hmin, 3));
            h.set("max", dbl(r.hmax, 3));
            JsonValue buckets = JsonValue::array();
            for (auto c : r.hist) buckets.push(JsonValue::integer((long long)c));
            h.set("buckets", buckets);
            j.set("histogram", h);
        }
        if (r.gotChecksum) j.set("checksum", JsonValue::integer(r.checksum));
        if (b.hasNoData && !o.noNodata) {
            if (b.noDataIsInt64) j.set("noDataValue", JsonValue::integer(b.noDataInt64));
            else if (b.noDataIsUInt64) { JsonValue v = JsonValue::number(0); v.setRawNumber(std::to_string(b.noDataUInt64)); j.set("noDataValue", v); }
            else if (std::isnan(b.noData)) j.set("noDataValue", JsonValue::string("nan"));
            else if (std::isinf(b.noData)) j.set("noDataValue", JsonValue::string(b.noData > 0 ? "inf" : "-inf"));
            else j.set("noDataValue", dbl(b.noData, 18));
            if (!std::isnan(b.noData) && !std::isinf(b.noData)) stacBand.set("nodata", dbl(b.noData, 18));
            else stacBand.set("nodata", JsonValue::string(std::isnan(b.noData) ? "nan" : (b.noData > 0 ? "inf" : "-inf")));
        }
        if (!b.overviews.empty()) {
            JsonValue ovs = JsonValue::array();
            for (size_t i = 0; i < b.overviews.size(); i++) {
                JsonValue ov = JsonValue::object();
                JsonValue sz = JsonValue::array();
                sz.push(JsonValue::integer(b.overviews[i]->xsize)); sz.push(JsonValue::integer(b.overviews[i]->ysize));
                ov.set("size", sz);
                if (o.checksum && i < r.ovChecksums.size()) ov.set("checksum", JsonValue::integer(r.ovChecksums[i]));
                ovs.push(ov);
            }
            j.set("overviews", ovs);
        }
        if (!o.noMask) {
            int f = b.maskFlags;
            if ((f & (8 | 1)) == 0) {
                JsonValue mask = JsonValue::object();
                JsonValue flags = JsonValue::array();
                if (f & 1) flags.push(JsonValue::string("ALL_VALID"));
                if (f & 2) flags.push(JsonValue::string("PER_DATASET"));
                if (f & 4) flags.push(JsonValue::string("ALPHA"));
                if (f & 8) flags.push(JsonValue::string("NODATA"));
                mask.set("flags", flags);
                j.set("mask", mask);
            }
        }
        if (!b.unitType.empty()) { j.set("unit", JsonValue::string(b.unitType)); stacBand.set("unit", JsonValue::string(b.unitType)); }
        if (b.hasOffset || b.hasScale) {
            double off = b.hasOffset ? b.offset : 0, sc = b.hasScale ? b.scale : 1;
            if (off != 0.0 || sc != 1.0) {
                j.set("offset", dbl(off, 15)); j.set("scale", dbl(sc, 15));
                stacBand.set("scale", dbl(sc, 15)); stacBand.set("offset", dbl(off, 15));
            }
        }
        if (!o.noMd) {
            std::vector<std::string> doms = reportDomains(b.metadata, o, true);
            doms.erase(std::remove(doms.begin(), doms.end(), std::string("__pam_hist__")), doms.end());
            j.set("metadata", metadataJson(b.metadata, doms));
        }
        if (b.hasColorTable && !o.noCt) {
            JsonValue ctj = JsonValue::object();
            ctj.set("palette", JsonValue::string("RGB"));
            ctj.set("count", JsonValue::integer((long long)b.colorTable.size()));
            JsonValue entries = JsonValue::array();
            for (auto& e : b.colorTable) {
                JsonValue en = JsonValue::array();
                en.push(JsonValue::integer(e.c1)); en.push(JsonValue::integer(e.c2)); en.push(JsonValue::integer(e.c3)); en.push(JsonValue::integer(e.c4));
                entries.push(en);
            }
            ctj.set("entries", entries);
            j.set("colorTable", ctj);
        }
        bands.push(j);
        stacRasterBands.push(stacBand);
        JsonValue eo = JsonValue::object();
        eo.set("name", JsonValue::string(strprintf("b%d", b.number)));
        if (!b.description.empty()) eo.set("description", JsonValue::string(b.description));
        else if (b.colorInterp != "Undefined") eo.set("description", JsonValue::string(b.colorInterp));
        if (b.colorInterp == "Red") eo.set("common_name", JsonValue::string("red"));
        else if (b.colorInterp == "Green") eo.set("common_name", JsonValue::string("green"));
        else if (b.colorInterp == "Blue") eo.set("common_name", JsonValue::string("blue"));
        stacEOBands.push(eo);
    }
    root.set("bands", bands);
    // STAC
    JsonValue stac = JsonValue::object();
    JsonValue shape = JsonValue::array();
    shape.push(JsonValue::integer(ds.ysize)); shape.push(JsonValue::integer(ds.xsize));
    stac.set("proj:shape", shape);
    if (ds.hasCRS) {
        stac.set("proj:wkt2", JsonValue::string(ds.crs.exportWkt2_2019(true)));
        std::string an = ds.crs.authName(), ac = ds.crs.authCode();
        if (an == "EPSG" && !ac.empty()) stac.set("proj:epsg", JsonValue::integer(atoll(ac.c_str())));
        else stac.set("proj:epsg", JsonValue::null());
        stac.set("proj:projjson", ds.crs.projjsonValue());
    }
    if (ds.hasGeoTransform) {
        JsonValue t = JsonValue::array();
        t.push(dbl(ds.gt[1], 16)); t.push(dbl(ds.gt[2], 16)); t.push(dbl(ds.gt[0], 16));
        t.push(dbl(ds.gt[4], 16)); t.push(dbl(ds.gt[5], 16)); t.push(dbl(ds.gt[3], 16));
        stac.set("proj:transform", t);
    }
    stac.set("raster:bands", stacRasterBands);
    stac.set("eo:bands", stacEOBands);
    root.set("stac", stac);
    if (ds.pamDirty) savePam(ds);
    return root;
}
