static bool readHead(const std::string& path, std::string& head, size_t n = 1024) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return false;
    std::vector<char> buf(n);
    size_t r = fread(buf.data(), 1, n, f);
    fclose(f);
