static bool looksLikeGeoJSON(const std::string& head, const std::string& ext) {
    // Mimic GDAL's GeoJSON identification: must contain "type" and one of the GeoJSON object types
    std::string h = head;
    size_t i = 0;
    while (i < h.size() && isspace((unsigned char)h[i])) i++;
    if (i >= h.size()) return false;
    if (h[i] != '{' && h[i] != '[') return false;
