    if (head.find("<VRTDataset") != std::string::npos) { if (isRaster) *isRaster = true; return "VRT"; }
    if (head.size() >= 4 && (uint8_t)head[0] == 0 && (uint8_t)head[1] == 0 && (uint8_t)head[2] == 0x27 && (uint8_t)head[3] == 0x0a) { if (isVector) *isVector = true; return "ESRI Shapefile"; }
