#include "geometry.h"
#include "util.h"
#include <cstring>
#include <cmath>
#include <cstdio>

std::string geomTypeName(GeomType t, bool z, bool m) {
    std::string base;
    switch (t) {
        case GeomType::Unknown: base = "Unknown (any)"; break;
        case GeomType::Point: base = "Point"; break;
        case GeomType::LineString: base = "Line String"; break;
        case GeomType::Polygon: base = "Polygon"; break;
        case GeomType::MultiPoint: base = "Multi Point"; break;
        case GeomType::MultiLineString: base = "Multi Line String"; break;
        case GeomType::MultiPolygon: base = "Multi Polygon"; break;
        case GeomType::GeometryCollection: base = "Geometry Collection"; break;
        case GeomType::None: return "None";
    }
    if (t == GeomType::Unknown) {
        if (z && m) return "3D Measured Unknown (any)";
        if (z) return "3D Unknown (any)";
        if (m) return "Measured Unknown (any)";
        return base;
    }
    if (z && m) return "3D Measured " + base;
    if (z) return "3D " + base;
    if (m) return "Measured " + base;
    return base;
}
std::string geomTypeToString(GeomType t, bool z, bool m) { return geomTypeName(t, z, m); }

int geomTypeToWkbCode(GeomType t, bool z, bool m) {
    int c = (int)t;
    if (t == GeomType::None) return 100;
    if (z) c += 1000;
    if (m) c += 2000;
    return c;
}
bool wkbCodeToGeomType(int code, GeomType& t, bool& z, bool& m) {
    z = false; m = false;
    if (code & 0x80000000) { z = true; code &= 0x7fffffff; }
    if (code >= 3000) { z = true; m = true; code -= 3000; }
    else if (code >= 2000) { m = true; code -= 2000; }
    else if (code >= 1000) { z = true; code -= 1000; }
    if (code < 0 || code > 7) return false;
    t = (GeomType)code;
    return true;
}

std::string formatWktCoord(double v) {
    return ogrFormatDouble(v, 15);
}

static bool isIntegerStr(const std::string& s) {
    for (char c : s) if (c != '-' && !isdigit((unsigned char)c)) return false;
    return true;
}

static bool isDoubleAnInt(double d) { return d >= -2147483648.0 && d <= 2147483647.0 && d == (double)(int)d; }

std::string wktCoordinate(const Coord& c, bool hasZ, bool hasM) {
    std::string s;
    if (isDoubleAnInt(c.x) && isDoubleAnInt(c.y)) s = std::to_string((int)c.x) + " " + std::to_string((int)c.y);
    else {
        std::string x = formatWktCoord(c.x); if (isIntegerStr(x)) x += ".0";
        std::string y = formatWktCoord(c.y); if (isIntegerStr(y)) y += ".0";
        s = x + " " + y;
    }
    if (hasZ) {
        if (isDoubleAnInt(c.z)) s += " " + std::to_string((int)c.z);
        else { std::string z = formatWktCoord(c.z); if (isIntegerStr(z)) z += ".0"; s += " " + z; }
    }
    if (hasM) {
        if (isDoubleAnInt(c.m)) s += " " + std::to_string((int)c.m);
        else { std::string mm = formatWktCoord(c.m); if (isIntegerStr(mm)) mm += ".0"; s += " " + mm; }
    }
    return s;
}

bool Geometry::isEmpty() const {
    switch (type) {
        case GeomType::Point: return points.empty();
        case GeomType::LineString: return points.empty();
        case GeomType::Polygon: return rings.empty();
        default: return parts.empty();
    }
}

size_t Geometry::pointCount() const {
    switch (type) {
        case GeomType::Point: case GeomType::LineString: return points.size();
        case GeomType::Polygon: { size_t n = 0; for (auto& r : rings) n += r.size(); return n; }
        default: { size_t n = 0; for (auto& p : parts) n += p->pointCount(); return n; }
    }
}

void Geometry::setZM(bool z, bool m) {
    hasZ = z; hasM = m;
    for (auto& p : parts) p->setZM(z, m);
}

std::string Geometry::typeName() const { return geomTypeName(type, hasZ, hasM); }
std::string Geometry::geoJsonTypeName() const {
    switch (type) {
        case GeomType::Point: return "Point";
        case GeomType::LineString: return "LineString";
        case GeomType::Polygon: return "Polygon";
        case GeomType::MultiPoint: return "MultiPoint";
        case GeomType::MultiLineString: return "MultiLineString";
        case GeomType::MultiPolygon: return "MultiPolygon";
        case GeomType::GeometryCollection: return "GeometryCollection";
        default: return "";
    }
}

Envelope Geometry::envelope() const {
    Envelope e;
    switch (type) {
        case GeomType::Point: case GeomType::LineString:
            for (auto& c : points) e.merge(c.x, c.y, c.z);
            break;
        case GeomType::Polygon:
            for (auto& r : rings) for (auto& c : r) e.merge(c.x, c.y, c.z);
            break;
        default:
            for (auto& p : parts) e.merge(p->envelope());
    }
    return e;
}

static std::string wktTypeWord(GeomType t) {
    switch (t) {
        case GeomType::Point: return "POINT";
        case GeomType::LineString: return "LINESTRING";
        case GeomType::Polygon: return "POLYGON";
        case GeomType::MultiPoint: return "MULTIPOINT";
        case GeomType::MultiLineString: return "MULTILINESTRING";
        case GeomType::MultiPolygon: return "MULTIPOLYGON";
        case GeomType::GeometryCollection: return "GEOMETRYCOLLECTION";
        default: return "GEOMETRY";
    }
}

static std::string coordList(const std::vector<Coord>& pts, bool z, bool m) {
    std::string s;
    for (size_t i = 0; i < pts.size(); i++) { if (i) s += ","; s += wktCoordinate(pts[i], z, m); }
    return s;
}

static std::string wktBody(const Geometry& g);

static std::string wktFull(const Geometry& g) {
    std::string s = wktTypeWord(g.type);
    if (g.hasZ && g.hasM) s += " ZM";
    else if (g.hasZ) s += " Z";
    else if (g.hasM) s += " M";
    if (g.isEmpty()) return s + " EMPTY";
    return s + " " + wktBody(g);
}

static std::string wktBody(const Geometry& g) {
    switch (g.type) {
        case GeomType::Point: return "(" + wktCoordinate(g.points[0], g.hasZ, g.hasM) + ")";
        case GeomType::LineString: return "(" + coordList(g.points, g.hasZ, g.hasM) + ")";
        case GeomType::Polygon: {
            std::string s = "(";
            for (size_t i = 0; i < g.rings.size(); i++) { if (i) s += ","; s += "(" + coordList(g.rings[i], g.hasZ, g.hasM) + ")"; }
            return s + ")";
        }
        case GeomType::MultiPoint: {
            std::string s = "(";
            for (size_t i = 0; i < g.parts.size(); i++) {
                if (i) s += ",";
                if (g.parts[i]->isEmpty()) s += "EMPTY";
                else s += "(" + wktCoordinate(g.parts[i]->points[0], g.hasZ, g.hasM) + ")";
            }
            return s + ")";
        }
        case GeomType::MultiLineString: case GeomType::MultiPolygon: {
            std::string s = "(";
            for (size_t i = 0; i < g.parts.size(); i++) { if (i) s += ","; if (g.parts[i]->isEmpty()) s += "EMPTY"; else s += wktBody(*g.parts[i]); }
            return s + ")";
        }
        case GeomType::GeometryCollection: {
            std::string s = "(";
            for (size_t i = 0; i < g.parts.size(); i++) { if (i) s += ","; s += wktFull(*g.parts[i]); }
            return s + ")";
        }
        default: return "";
    }
}

std::string Geometry::toWkt() const { return wktFull(*this); }

// ---------------- WKB ----------------
static void put32(std::vector<uint8_t>& b, uint32_t v) { for (int i = 0; i < 4; i++) b.push_back((uint8_t)(v >> (8 * i))); }
static void putD(std::vector<uint8_t>& b, double d) { uint8_t t[8]; memcpy(t, &d, 8); b.insert(b.end(), t, t + 8); }
static void putCoord(std::vector<uint8_t>& b, const Coord& c, bool z, bool m) { putD(b, c.x); putD(b, c.y); if (z) putD(b, c.z); if (m) putD(b, c.m); }

static void wkbWrite(const Geometry& g, std::vector<uint8_t>& b) {
    b.push_back(1);
    put32(b, (uint32_t)geomTypeToWkbCode(g.type, g.hasZ, g.hasM));
    switch (g.type) {
        case GeomType::Point:
            if (g.points.empty()) { Coord c; c.x = c.y = c.z = c.m = NAN; putCoord(b, c, g.hasZ, g.hasM); }
            else putCoord(b, g.points[0], g.hasZ, g.hasM);
            break;
        case GeomType::LineString:
            put32(b, (uint32_t)g.points.size());
            for (auto& c : g.points) putCoord(b, c, g.hasZ, g.hasM);
            break;
        case GeomType::Polygon:
            put32(b, (uint32_t)g.rings.size());
            for (auto& r : g.rings) { put32(b, (uint32_t)r.size()); for (auto& c : r) putCoord(b, c, g.hasZ, g.hasM); }
            break;
        default:
            put32(b, (uint32_t)g.parts.size());
            for (auto& p : g.parts) wkbWrite(*p, b);
    }
}
std::vector<uint8_t> Geometry::toWkb() const { std::vector<uint8_t> b; wkbWrite(*this, b); return b; }

namespace {
struct WkbReader {
    const uint8_t* p; size_t len; size_t pos = 0; bool ok = true;
    uint32_t rd32(bool be) { if (pos + 4 > len) { ok = false; return 0; } uint32_t v = be ? ((uint32_t)p[pos] << 24 | (uint32_t)p[pos+1] << 16 | (uint32_t)p[pos+2] << 8 | p[pos+3]) : ((uint32_t)p[pos+3] << 24 | (uint32_t)p[pos+2] << 16 | (uint32_t)p[pos+1] << 8 | p[pos]); pos += 4; return v; }
    double rdD(bool be) { if (pos + 8 > len) { ok = false; return 0; } uint8_t t[8]; for (int i = 0; i < 8; i++) t[i] = be ? p[pos + 7 - i] : p[pos + i]; pos += 8; double d; memcpy(&d, t, 8); return d; }
    Coord rdCoord(bool be, bool z, bool m) { Coord c; c.x = rdD(be); c.y = rdD(be); if (z) c.z = rdD(be); if (m) c.m = rdD(be); return c; }
    std::shared_ptr<Geometry> read() {
        if (pos >= len) { ok = false; return nullptr; }
        bool be = p[pos++] == 0;
        uint32_t code = rd32(be);
        auto g = std::make_shared<Geometry>();
        if (!wkbCodeToGeomType((int)code, g->type, g->hasZ, g->hasM)) { ok = false; return nullptr; }
        switch (g->type) {
            case GeomType::Point: { Coord c = rdCoord(be, g->hasZ, g->hasM); if (!std::isnan(c.x)) g->points.push_back(c); break; }
            case GeomType::LineString: { uint32_t n = rd32(be); for (uint32_t i = 0; i < n && ok; i++) g->points.push_back(rdCoord(be, g->hasZ, g->hasM)); break; }
            case GeomType::Polygon: { uint32_t n = rd32(be); for (uint32_t i = 0; i < n && ok; i++) { uint32_t k = rd32(be); std::vector<Coord> r; for (uint32_t j = 0; j < k && ok; j++) r.push_back(rdCoord(be, g->hasZ, g->hasM)); g->rings.push_back(r); } break; }
            default: { uint32_t n = rd32(be); for (uint32_t i = 0; i < n && ok; i++) { auto s = read(); if (!s) { ok = false; break; } g->parts.push_back(s); } }
        }
        return ok ? g : nullptr;
    }
};
}

std::shared_ptr<Geometry> Geometry::fromWkb(const uint8_t* data, size_t len, size_t* consumed) {
    WkbReader r{data, len};
    auto g = r.read();
    if (consumed) *consumed = r.pos;
    return g;
}

// ---------------- WKT parsing ----------------
namespace {
struct WktParser {
    const std::string& s; size_t i = 0; std::string err;
    WktParser(const std::string& str) : s(str) {}
    void ws() { while (i < s.size() && isspace((unsigned char)s[i])) i++; }
    std::string word() { ws(); size_t st = i; while (i < s.size() && (isalpha((unsigned char)s[i]))) i++; return toUpper(s.substr(st, i - st)); }
    bool expect(char c) { ws(); if (i < s.size() && s[i] == c) { i++; return true; } err = std::string("expected ") + c; return false; }
    bool peek(char c) { ws(); return i < s.size() && s[i] == c; }
    bool number(double& d) { ws(); char* e; d = strtod(s.c_str() + i, &e); if (e == s.c_str() + i) { err = "expected number"; return false; } i = e - s.c_str(); return true; }
    bool coord(Coord& c, bool z, bool m, int& dimSeen) {
        if (!number(c.x) || !number(c.y)) return false;
        dimSeen = 2;
        ws();
        if (i < s.size() && (isdigit((unsigned char)s[i]) || s[i] == '-' || s[i] == '.' || s[i] == '+')) {
            double v; if (!number(v)) return false;
            if (z) c.z = v; else if (m) c.m = v; else c.z = v;
            dimSeen = 3;
            ws();
            if (i < s.size() && (isdigit((unsigned char)s[i]) || s[i] == '-' || s[i] == '.' || s[i] == '+')) { double w; if (!number(w)) return false; c.m = w; dimSeen = 4; }
        }
        return true;
    }
    bool coordList(std::vector<Coord>& out, bool z, bool m, int& dimMax) {
        if (!expect('(')) return false;
        while (true) {
            Coord c; int d = 0;
            if (!coord(c, z, m, d)) return false;
            if (d > dimMax) dimMax = d;
            out.push_back(c);
            if (peek(',')) { i++; continue; }
            if (!expect(')')) return false;
            return true;
        }
    }
    std::shared_ptr<Geometry> parse() {
        std::string w = word();
        auto g = std::make_shared<Geometry>();
        if (w == "POINT") g->type = GeomType::Point;
        else if (w == "LINESTRING") g->type = GeomType::LineString;
        else if (w == "POLYGON") g->type = GeomType::Polygon;
        else if (w == "MULTIPOINT") g->type = GeomType::MultiPoint;
        else if (w == "MULTILINESTRING") g->type = GeomType::MultiLineString;
        else if (w == "MULTIPOLYGON") g->type = GeomType::MultiPolygon;
        else if (w == "GEOMETRYCOLLECTION") g->type = GeomType::GeometryCollection;
        else { err = "unknown geometry type"; return nullptr; }
        ws();
        size_t save = i;
        std::string zm = word();
        if (zm == "Z") g->hasZ = true;
        else if (zm == "M") g->hasM = true;
        else if (zm == "ZM") { g->hasZ = g->hasM = true; }
        else if (zm == "EMPTY") { g->empty = true; return g; }
        else i = save;
        ws();
        if (word() == "EMPTY") { g->empty = true; return g; }
        i = save; ws();
        // skip ZM token again
        if (g->hasZ || g->hasM) { word(); }
        int dimMax = 2;
        bool explicitZM = g->hasZ || g->hasM;
        switch (g->type) {
            case GeomType::Point: {
                if (!expect('(')) return nullptr;
                Coord c; int d = 0;
                if (!coord(c, g->hasZ, g->hasM, d)) return nullptr;
                dimMax = d;
                g->points.push_back(c);
                if (!expect(')')) return nullptr;
                break;
            }
            case GeomType::LineString:
                if (!coordList(g->points, g->hasZ, g->hasM, dimMax)) return nullptr;
                break;
            case GeomType::Polygon: {
                if (!expect('(')) return nullptr;
                while (true) {
                    std::vector<Coord> r;
                    if (peek('E')) { word(); } else if (!coordList(r, g->hasZ, g->hasM, dimMax)) return nullptr;
                    g->rings.push_back(r);
                    if (peek(',')) { i++; continue; }
                    if (!expect(')')) return nullptr;
                    break;
                }
                break;
            }
            case GeomType::MultiPoint: {
                if (!expect('(')) return nullptr;
                while (true) {
                    auto pt = std::make_shared<Geometry>();
