namespace {
struct WktParser {
    const std::string& s; size_t i = 0; std::string err;
    WktParser(const std::string& str) : s(str) {}
    void ws() { while (i < s.size() && isspace((unsigned char)s[i])) i++; }
    std::string word() { ws(); size_t st = i; while (i < s.size() && (isalpha((unsigned char)s[i]))) i++; return toUpper(s.substr(st, i - st)); }
    bool expect(char c) { ws(); if (i < s.size() && s[i] == c) { i++; return true; } err = std::string("expected ") + c; return false; }
    bool peek(char c) { ws(); return i < s.size() && s[i] == c; }
    bool number(double& d) { ws(); char* e; d = strtod(s.c_str() + i, &e); if (e == s.c_str() + i) { err = "expected number"; return false; } i = e - s.c_str(); return true; }
