                            pg->rings.push_back(r);
                            if (peek(',')) { i++; continue; }
                            if (!expect(')')) return nullptr;
                            break;
                        }
                    }
                    g->parts.push_back(pg);
                    if (peek(',')) { i++; continue; }
                    if (!expect(')')) return nullptr;
                    break;
                }
                break;
            }
            case GeomType::GeometryCollection: {
                if (!expect('(')) return nullptr;
                while (true) {
                    auto sub = parse();
                    if (!sub) return nullptr;
                    g->parts.push_back(sub);
                    if (sub->hasZ) g->hasZ = true;
                    if (sub->hasM) g->hasM = true;
                    if (peek(',')) { i++; continue; }
                    if (!expect(')')) return nullptr;
                    break;
                }
                break;
            }
            default: return nullptr;
        }
        if (!explicitZM) {
            if (dimMax >= 3) g->hasZ = true;
            if (dimMax >= 4) g->hasM = true;
            g->setZM(g->hasZ, g->hasM);
        }
        return g;
    }
};
}

std::shared_ptr<Geometry> Geometry::fromWkt(const std::string& wkt, std::string* err) {
    WktParser p(wkt);
    auto g = p.parse();
    if (!g && err) *err = p.err;
    return g;
}
