static std::string fmtReal(double d, const FieldDef& def) {
    if (def.width != 0 && def.precision != 0) {
        return strprintf("%.*f", def.precision, d);
    }
    if (def.subType == FieldSubType::Float32) {
        // OGR: %.8g for Float32
        char buf[64]; snprintf(buf, sizeof(buf), "%.8g", d); return buf;
    }
    char buf[64];
    snprintf(buf, sizeof(buf), "%.15g", d);
    return buf;
}

std::string fieldValueAsString(const FieldValue& v, const FieldDef& d) {
    if (v.isNull() || v.unset) return "";
    switch (d.type) {
        case FieldType::Integer: case FieldType::Integer64: return std::to_string(v.i);
        case FieldType::Real: return fmtReal(v.d, d);
        case FieldType::String: return v.s;
        case FieldType::IntegerList: case FieldType::Integer64List: {
            std::string s = "(" + std::to_string(v.il.size()) + ":";
            for (size_t i = 0; i < v.il.size(); i++) { if (i) s += ","; s += std::to_string(v.il[i]); }
            return s + ")";
        }
        case FieldType::RealList: {
            std::string s = "(" + std::to_string(v.dl.size()) + ":";
            for (size_t i = 0; i < v.dl.size(); i++) { if (i) s += ","; s += fmtReal(v.dl[i], d); }
            return s + ")";
        }
        case FieldType::StringList: {
            std::string s = "(" + std::to_string(v.sl.size()) + ":";
            for (size_t i = 0; i < v.sl.size(); i++) { if (i) s += ","; s += v.sl[i]; }
            return s + ")";
        }
        case FieldType::Binary: {
            std::string s;
            for (auto b : v.bin) s += strprintf("%02X", b);
            return s;
        }
        case FieldType::Date: return strprintf("%04d/%02d/%02d", v.year, v.month, v.day);
        case FieldType::Time: {
            if (v.second == (int)v.second) return strprintf("%02d:%02d:%02d", v.hour, v.minute, (int)v.second);
            return strprintf("%02d:%02d:%06.3f", v.hour, v.minute, v.second);
        }
        case FieldType::DateTime: {
            std::string s;
            if (v.second == (int)v.second) s = strprintf("%04d/%02d/%02d %02d:%02d:%02d", v.year, v.month, v.day, v.hour, v.minute, (int)v.second);
            else s = strprintf("%04d/%02d/%02d %02d:%02d:%06.3f", v.year, v.month, v.day, v.hour, v.minute, v.second);
            if (v.tz > 1) {
                int off = (v.tz - 100) * 15;
                if (off == 0) s += "+00";
                else {
                    int ah = abs(off) / 60, am = abs(off) % 60;
                    s += strprintf("%c%02d", off < 0 ? '-' : '+', ah);
                    if (am) s += strprintf("%02d", am);
                }
            }
            return s;
        }
    }
    return "";
}
std::string fieldValueAsStringList(const FieldValue& v, const FieldDef& d) { return fieldValueAsString(v, d); }

// ---------------- GeoJSON geometry ----------------
static bool readCoord(const JsonValue& a, Coord& c, bool& z) {
    if (!a.isArray() || a.size() < 2 || !a[0].isNumber() || !a[1].isNumber()) return false;
    c.x = a[0].asDouble(); c.y = a[1].asDouble();
    if (a.size() >= 3 && a[2].isNumber()) { c.z = a[2].asDouble(); z = true; }
    return true;
}

std::shared_ptr<Geometry> geometryFromGeoJson(const JsonValue& j, std::string* err) {
    if (!j.isObject()) { if (err) *err = "not an object"; return nullptr; }
    std::string type = j.getString("type");
    auto g = std::make_shared<Geometry>();
    const JsonValue& coords = j.get("coordinates");
    bool z = false;
    if (type == "Point") {
        g->type = GeomType::Point;
        Coord c;
        if (coords.isArray() && coords.size() == 0) { g->empty = true; return g; }
        if (!readCoord(coords, c, z)) { if (err) *err = "bad coordinates"; return nullptr; }
        g->points.push_back(c);
    } else if (type == "LineString") {
        g->type = GeomType::LineString;
        if (!coords.isArray()) return nullptr;
        for (auto& p : coords.items()) { Coord c; if (!readCoord(p, c, z)) return nullptr; g->points.push_back(c); }
    } else if (type == "Polygon") {
        g->type = GeomType::Polygon;
        if (!coords.isArray()) return nullptr;
        for (auto& r : coords.items()) {
            std::vector<Coord> ring;
            if (!r.isArray()) return nullptr;
            for (auto& p : r.items()) { Coord c; if (!readCoord(p, c, z)) return nullptr; ring.push_back(c); }
            g->rings.push_back(ring);
        }
    } else if (type == "MultiPoint") {
        g->type = GeomType::MultiPoint;
        if (!coords.isArray()) return nullptr;
        for (auto& p : coords.items()) { auto pt = std::make_shared<Geometry>(); pt->type = GeomType::Point; Coord c; if (!readCoord(p, c, z)) return nullptr; pt->points.push_back(c); g->parts.push_back(pt); }
    } else if (type == "MultiLineString") {
        g->type = GeomType::MultiLineString;
        if (!coords.isArray()) return nullptr;
        for (auto& l : coords.items()) {
            auto ls = std::make_shared<Geometry>(); ls->type = GeomType::LineString;
            if (!l.isArray()) return nullptr;
            for (auto& p : l.items()) { Coord c; if (!readCoord(p, c, z)) return nullptr; ls->points.push_back(c); }
            g->parts.push_back(ls);
        }
    } else if (type == "MultiPolygon") {
        g->type = GeomType::MultiPolygon;
        if (!coords.isArray()) return nullptr;
        for (auto& pg : coords.items()) {
            auto poly = std::make_shared<Geometry>(); poly->type = GeomType::Polygon;
            if (!pg.isArray()) return nullptr;
            for (auto& r : pg.items()) {
                std::vector<Coord> ring;
                if (!r.isArray()) return nullptr;
                for (auto& p : r.items()) { Coord c; if (!readCoord(p, c, z)) return nullptr; ring.push_back(c); }
                poly->rings.push_back(ring);
            }
            g->parts.push_back(poly);
        }
    } else if (type == "GeometryCollection") {
        g->type = GeomType::GeometryCollection;
        const JsonValue& geoms = j.get("geometries");
        if (!geoms.isArray()) return nullptr;
        for (auto& sg : geoms.items()) {
            auto s = geometryFromGeoJson(sg, err);
            if (!s) return nullptr;
            if (s->hasZ) z = true;
            g->parts.push_back(s);
        }
    } else {
        if (err) *err = "unknown geometry type";
        return nullptr;
    }
    g->setZM(z, false);
    return g;
}

static JsonValue coordJson(const Coord& c, bool z, int precision) {
    JsonValue a = JsonValue::array();
    auto num = [&](double v) {
        JsonValue n = JsonValue::number(v);
        if (precision >= 0) n.setRawNumber(ogrFormatDouble(v, precision));
        else {
            // json_object_new_double_with_significant_figures semantics (17 sig figs with 999999/000000 fix)
            char buf[64];
            snprintf(buf, sizeof(buf), "%.17g", v);
            const char* dot = strchr(buf, '.');
            if (dot && (strstr(dot, "999999") || strstr(dot, "000000"))) {
                bool ok = false;
                for (int i = 1; i <= 3; i++) {
                    snprintf(buf, sizeof(buf), "%.*g", 17 - i, v);
                    dot = strchr(buf, '.');
                    if (dot && !strstr(dot, "999999") && !strstr(dot, "000000")) { ok = true; break; }
                }
                if (!ok) snprintf(buf, sizeof(buf), "%.17g", v);
            }
            std::string s = buf;
            if (s.find('.') == std::string::npos && s.find('e') == std::string::npos && s.find('n') == std::string::npos && s.find('i') == std::string::npos) s += ".0";
            n.setRawNumber(s);
        }
        return n;
    };
    a.push(num(c.x)); a.push(num(c.y));
    if (z) a.push(num(c.z));
    return a;
}

JsonValue geometryToGeoJson(const Geometry& g, int precision) {
    JsonValue o = JsonValue::object();
    o.set("type", JsonValue::string(g.geoJsonTypeName()));
    bool z = g.hasZ;
    switch (g.type) {
        case GeomType::Point:
            if (g.isEmpty()) o.set("coordinates", JsonValue::array());
            else o.set("coordinates", coordJson(g.points[0], z, precision));
            break;
        case GeomType::LineString: {
            JsonValue a = JsonValue::array();
            for (auto& c : g.points) a.push(coordJson(c, z, precision));
            o.set("coordinates", a);
            break;
        }
        case GeomType::Polygon: {
            JsonValue a = JsonValue::array();
            for (auto& r : g.rings) { JsonValue ra = JsonValue::array(); for (auto& c : r) ra.push(coordJson(c, z, precision)); a.push(ra); }
            o.set("coordinates", a);
            break;
        }
        case GeomType::MultiPoint: {
            JsonValue a = JsonValue::array();
            for (auto& p : g.parts) if (!p->isEmpty()) a.push(coordJson(p->points[0], z, precision));
            o.set("coordinates", a);
            break;
        }
        case GeomType::MultiLineString: {
            JsonValue a = JsonValue::array();
            for (auto& p : g.parts) { JsonValue la = JsonValue::array(); for (auto& c : p->points) la.push(coordJson(c, z, precision)); a.push(la); }
            o.set("coordinates", a);
            break;
        }
        case GeomType::MultiPolygon: {
            JsonValue a = JsonValue::array();
            for (auto& p : g.parts) { JsonValue pa = JsonValue::array(); for (auto& r : p->rings) { JsonValue ra = JsonValue::array(); for (auto& c : r) ra.push(coordJson(c, z, precision)); pa.push(ra); } a.push(pa); }
            o.set("coordinates", a);
            break;
        }
        case GeomType::GeometryCollection: {
            JsonValue a = JsonValue::array();
            for (auto& p : g.parts) a.push(geometryToGeoJson(*p, precision));
            o.set("geometries", a);
            break;
        }
        default: break;
    }
    return o;
}
