static std::string fmtReal(double d, const FieldDef& def) {
    if (def.width != 0 && def.precision != 0) {
        return strprintf("%.*f", def.precision, d);
    }
    if (def.subType == FieldSubType::Float32) {
        // OGR: %.8g for Float32
        char buf[64]; snprintf(buf, sizeof(buf), "%.8g", d); return buf;
    }
    char buf[64];
    snprintf(buf, sizeof(buf), "%.15g", d);
    return buf;
}

std::string fieldValueAsString(const FieldValue& v, const FieldDef& d) {
    if (v.isNull() || v.unset) return "";
    switch (d.type) {
        case FieldType::Integer: case FieldType::Integer64: return std::to_string(v.i);
        case FieldType::Real: return fmtReal(v.d, d);
        case FieldType::String: return v.s;
        case FieldType::IntegerList: case FieldType::Integer64List: {
            std::string s = "(" + std::to_string(v.il.size()) + ":";
            for (size_t i = 0; i < v.il.size(); i++) { if (i) s += ","; s += std::to_string(v.il[i]); }
            return s + ")";
        }
        case FieldType::RealList: {
            std::string s = "(" + std::to_string(v.dl.size()) + ":";
            for (size_t i = 0; i < v.dl.size(); i++) { if (i) s += ","; s += fmtReal(v.dl[i], d); }
            return s + ")";
        }
        case FieldType::StringList: {
            std::string s = "(" + std::to_string(v.sl.size()) + ":";
            for (size_t i = 0; i < v.sl.size(); i++) { if (i) s += ","; s += v.sl[i]; }
            return s + ")";
        }
        case FieldType::Binary: {
            std::string s;
            for (auto b : v.bin) s += strprintf("%02X", b);
            return s;
        }
        case FieldType::Date: return strprintf("%04d/%02d/%02d", v.year, v.month, v.day);
        case FieldType::Time: {
            if (v.second == (int)v.second) return strprintf("%02d:%02d:%02d", v.hour, v.minute, (int)v.second);
            return strprintf("%02d:%02d:%06.3f", v.hour, v.minute, v.second);
        }
        case FieldType::DateTime: {
            std::string s;
            if (v.second == (int)v.second) s = strprintf("%04d/%02d/%02d %02d:%02d:%02d", v.year, v.month, v.day, v.hour, v.minute, (int)v.second);
            else s = strprintf("%04d/%02d/%02d %02d:%02d:%06.3f", v.year, v.month, v.day, v.hour, v.minute, v.second);
