static void typeFromJson(const JsonValue& v, FieldType& t, FieldSubType& st, bool& known) {
    known = true;
    st = FieldSubType::None;
    if (v.isNull()) { known = false; t = FieldType::String; return; }
    if (v.isBool()) { t = FieldType::Integer; st = FieldSubType::Boolean; return; }
    if (v.isInt()) { long long i = v.asInt(); t = (i >= INT32_MIN && i <= INT32_MAX) ? FieldType::Integer : FieldType::Integer64; return; }
    if (v.isDouble()) { t = FieldType::Real; return; }
    if (v.isString()) {
        FieldValue tmp; FieldType dt;
        if (parseDateTime(v.asString(), tmp, dt)) { t = dt; return; }
        t = FieldType::String; return;
    }
    if (v.isArray()) {
        bool allInt = true, allNum = true, allStr = true, anyBig = false, allBool = true;
        for (auto& e : v.items()) {
            if (e.isBool()) { allInt = false; allNum = false; allStr = false; continue; }
            allBool = false;
            if (e.isInt()) { if (e.asInt() < INT32_MIN || e.asInt() > INT32_MAX) anyBig = true; allStr = false; }
            else if (e.isDouble()) { allInt = false; allStr = false; }
            else if (e.isString()) { allInt = false; allNum = false; }
            else { allInt = allNum = allStr = false; }
        }
        if (v.size() == 0) { t = FieldType::StringList; return; }
        if (allBool) { t = FieldType::IntegerList; st = FieldSubType::Boolean; return; }
        if (allInt) { t = anyBig ? FieldType::Integer64List : FieldType::IntegerList; return; }
        if (allNum) { t = FieldType::RealList; return; }
        if (allStr) { t = FieldType::StringList; return; }
        t = FieldType::String; st = FieldSubType::JSON; return;
    }
    if (v.isObject()) { t = FieldType::String; st = FieldSubType::JSON; return; }
    t = FieldType::String;
}

static bool isListType(FieldType t) { return t == FieldType::IntegerList || t == FieldType::Integer64List || t == FieldType::RealList || t == FieldType::StringList; }

static void mergeType(PendingField& f, FieldType nt, FieldSubType nst) {
    if (!f.typeKnown) { f.def.type = nt; f.def.subType = nst; f.typeKnown = true; return; }
    FieldType ot = f.def.type; FieldSubType ost = f.def.subType;
    if (ot == nt) {
        if (ost != nst) {
            // Boolean + Integer -> Integer; JSON + none -> String with JSON? keep JSON
            if (ost == FieldSubType::JSON || nst == FieldSubType::JSON) f.def.subType = FieldSubType::JSON;
            else f.def.subType = FieldSubType::None;
        }
        return;
    }
    auto isIntT = [](FieldType t) { return t == FieldType::Integer || t == FieldType::Integer64; };
    if (isIntT(ot) && isIntT(nt)) { f.def.type = FieldType::Integer64; f.def.subType = FieldSubType::None; return; }
    if ((isIntT(ot) || ot == FieldType::Real) && (isIntT(nt) || nt == FieldType::Real)) { f.def.type = FieldType::Real; f.def.subType = FieldSubType::None; return; }
    if ((ot == FieldType::Date || ot == FieldType::DateTime) && (nt == FieldType::Date || nt == FieldType::DateTime)) { f.def.type = FieldType::DateTime; return; }
    if (isListType(ot) || isListType(nt)) {
        FieldType a = ot, b = nt;
        auto listOf = [](FieldType t) { if (t == FieldType::Integer) return FieldType::IntegerList; if (t == FieldType::Integer64) return FieldType::Integer64List; if (t == FieldType::Real) return FieldType::RealList; if (t == FieldType::String) return FieldType::StringList; return t; };
        a = listOf(a); b = listOf(b);
        if (a == b) { f.def.type = a; f.def.subType = FieldSubType::None; return; }
        if ((a == FieldType::IntegerList || a == FieldType::Integer64List) && (b == FieldType::IntegerList || b == FieldType::Integer64List)) { f.def.type = FieldType::Integer64List; return; }
        if ((a == FieldType::IntegerList || a == FieldType::Integer64List || a == FieldType::RealList) && (b == FieldType::IntegerList || b == FieldType::Integer64List || b == FieldType::RealList)) { f.def.type = FieldType::RealList; return; }
        if (a == FieldType::StringList || b == FieldType::StringList) { f.def.type = FieldType::StringList; return; }
        f.def.type = FieldType::String; f.def.subType = FieldSubType::JSON; return;
    }
    f.def.type = FieldType::String;
    f.def.subType = (ost == FieldSubType::JSON || nst == FieldSubType::JSON) ? FieldSubType::JSON : FieldSubType::None;
}

static void setValueFromJson(const JsonValue& v, const FieldDef& d, FieldValue& out) {
    out.unset = false;
