            for (; pos < content.size(); pos++) {
                char c = content[pos];
                if (inStr) { if (c == '\\') pos++; else if (c == '"') inStr = false; continue; }
                if (c == '"') inStr = true;
                else if (c == '{' || c == '[') depth++;
                else if (c == '}' || c == ']') { depth--; if (depth == 0) { pos++; break; } }
            }
            JsonValue j;
            if (JsonValue::parse(content.substr(st, pos - st), j)) {
                if (j.getString("type") == "FeatureCollection") for (auto& f : j.get("features").items()) featureObjs.push_back(f);
                else featureObjs.push_back(j);
            }
        }
    } else {
        std::string perr;
        if (!JsonValue::parse(content, root, &perr)) { err = "JSON parsing error"; return nullptr; }
        std::string type = root.getString("type");
        if (type == "FeatureCollection") {
            for (auto& f : root.get("features").items()) featureObjs.push_back(f);
            if (root.has("name") && root.get("name").isString()) layer->name = root.getString("name");
            // other top-level members as native data / metadata? skip
        } else if (type == "Feature") {
            featureObjs.push_back(root);
        } else {
            // bare geometry
            JsonValue f = JsonValue::object();
            f.set("type", JsonValue::string("Feature"));
            f.set("properties", JsonValue::object());
            f.set("geometry", root);
            featureObjs.push_back(f);
        }
        if (root.isObject() && root.has("crs")) {
            const JsonValue& crs = root.get("crs");
            if (crs.isNull()) crsNull = true;
            else if (crs.isObject()) {
                std::string ctype = crs.getString("type");
                const JsonValue& props = crs.get("properties");
                if (ctype == "name" && props.isObject()) crsName = props.getString("name");
                else if (ctype == "EPSG" && props.isObject()) crsName = "EPSG:" + std::to_string(props.getInt("code"));
                else if (ctype == "link" && props.isObject()) crsName = props.getString("href");
            }
        }
    }
    // Schema detection
    std::vector<PendingField> pending;
    std::vector<std::string> order;
    bool hasStringId = false;
    GeomType gtype = GeomType::Unknown; bool gset = false; bool anyGeom = false; bool anyZ = false;
    for (auto& f : featureObjs) {
        if (!f.isObject()) continue;
        const JsonValue& id = f.get("id");
        if (id.isString()) hasStringId = true;
        const JsonValue& props = f.get("properties");
        if (props.isObject()) {
            for (auto& kv : props.members()) {
                FieldType t; FieldSubType st; bool known;
                typeFromJson(kv.second, t, st, known);
                size_t idx = pending.size();
                for (size_t k = 0; k < pending.size(); k++) if (pending[k].def.name == kv.first) { idx = k; break; }
                if (idx == pending.size()) {
                    PendingField pf; pf.def.name = kv.first; pf.def.type = t; pf.def.subType = st; pf.typeKnown = known;
                    pending.push_back(pf);
                } else if (known) {
                    mergeType(pending[idx], t, st);
                }
            }
        }
        const JsonValue& geom = f.get("geometry");
        if (geom.isObject()) {
            auto g = geometryFromGeoJson(geom);
            if (g) {
                anyGeom = true;
                gtype = mergeGeomType(gtype, g->type, gset); gset = true;
                if (g->hasZ) anyZ = true;
            }
        }
    }
    if (hasStringId) {
        bool exists = false;
        for (auto& p : pending) if (p.def.name == "id") exists = true;
        if (!exists) {
            PendingField pf; pf.def.name = "id"; pf.def.type = FieldType::String; pf.typeKnown = true;
            pending.insert(pending.begin(), pf);
        }
    }
    for (auto& p : pending) layer->fields.push_back(p.def);
    GeomFieldDef gf;
    gf.name = "";
    gf.type = anyGeom ? gtype : GeomType::None;
    gf.hasZ = anyZ;
    if (!crsNull) {
        CRS c;
        bool ok = false;
        if (!crsName.empty()) {
            std::string n = crsName;
            if (startsWith(n, "urn:ogc:def:crs:OGC:1.3:CRS84") || n == "urn:ogc:def:crs:OGC::CRS84" || n == "OGC:CRS84") ok = c.setFromWKT(kWktWgs84LatLong);
            else if (startsWith(n, "urn:ogc:def:crs:EPSG::")) ok = c.setFromEPSG(atoi(n.c_str() + 22));
            else if (startsWith(n, "urn:ogc:def:crs:EPSG:")) { size_t p2 = n.rfind(':'); ok = c.setFromEPSG(atoi(n.c_str() + p2 + 1)); }
            else ok = c.setFromUserInput(n);
        } else ok = c.setFromWKT(kWktWgs84LatLong);
        if (ok) { gf.hasCRS = true; gf.crs = c; }
    }
    if (anyGeom || !crsNull) layer->geomFields.push_back(gf);
    else layer->geomFields.push_back(gf);
    // Features
    long long nextFid = 0;
    for (auto& f : featureObjs) {
        if (!f.isObject()) continue;
        Feature feat;
        const JsonValue& id = f.get("id");
        if (id.isInt()) { feat.fid = id.asInt(); }
        else feat.fid = nextFid;
        nextFid = feat.fid + 1;
        feat.fields.resize(layer->fields.size());
        if (id.isString()) {
            int idx = layer->findField("id");
            if (idx >= 0 && layer->fields[idx].type == FieldType::String) { feat.fields[idx].unset = false; feat.fields[idx].s = id.asString(); }
        }
        const JsonValue& props = f.get("properties");
        if (props.isObject()) {
            for (auto& kv : props.members()) {
                int idx = -1;
                for (size_t k = 0; k < layer->fields.size(); k++) if (layer->fields[k].name == kv.first) { idx = (int)k; break; }
                if (idx < 0) continue;
                setValueFromJson(kv.second, layer->fields[idx], feat.fields[idx]);
            }
        }
        const JsonValue& geom = f.get("geometry");
        std::shared_ptr<Geometry> g;
        if (geom.isObject()) g = geometryFromGeoJson(geom);
        feat.geoms.push_back(g);
        layer->features.push_back(feat);
    }
    ds->layers.push_back(layer);
    return ds;
}

// ---------------------------------------------------------------------------
// Writer
static std::string jsonSpaced(const JsonValue& v);

static std::string jsonSpacedStr(const std::string& s) { return jsonEscapeString(s, true); }

static std::string jsonSpaced(const JsonValue& v) {
    switch (v.type()) {
        case JsonValue::NUL: return "null";
        case JsonValue::BOOL: return v.asBool() ? "true" : "false";
        case JsonValue::INT: return std::to_string(v.asInt());
        case JsonValue::DOUBLE: return v.rawNumber().empty() ? jsonFormatDouble(v.asDouble(), v.precision()) : v.rawNumber();
        case JsonValue::STRING: return jsonSpacedStr(v.asString());
        case JsonValue::ARRAY: {
            if (v.size() == 0) return "[ ]";
            std::string s = "[ ";
            for (size_t i = 0; i < v.size(); i++) { if (i) s += ", "; s += jsonSpaced(v[i]); }
            return s + " ]";
        }
        case JsonValue::OBJECT: {
            if (v.size() == 0) return "{ }";
            std::string s = "{ ";
            bool first = true;
            for (auto& kv : v.members()) { if (!first) s += ", "; first = false; s += jsonSpacedStr(kv.first) + ": " + jsonSpaced(kv.second); }
            return s + " }";
        }
    }
    return "";
}

static JsonValue sigFigDouble(double d) {
    JsonValue n = JsonValue::number(d);
    char buf[64];
    if (std::isnan(d) || std::isinf(d)) { n.setRawNumber(std::isnan(d) ? "NaN" : (d > 0 ? "Infinity" : "-Infinity")); return n; }
    snprintf(buf, sizeof(buf), "%.17g", d);
    const char* dot = strchr(buf, '.');
    if (dot && (strstr(dot, "999999") || strstr(dot, "000000"))) {
        bool ok = false;
        for (int i = 1; i <= 3; i++) {
            snprintf(buf, sizeof(buf), "%.*g", 17 - i, d);
            dot = strchr(buf, '.');
            if (dot && !strstr(dot, "999999") && !strstr(dot, "000000")) { ok = true; break; }
        }
        if (!ok) snprintf(buf, sizeof(buf), "%.17g", d);
    }
    std::string s = buf;
    if (s.find('.') == std::string::npos && s.find('e') == std::string::npos) s += ".0";
    n.setRawNumber(s);
    return n;
}

static JsonValue fieldToJson(const FieldValue& v, const FieldDef& d) {
    if (v.isNull() || v.unset) return JsonValue::null();
    switch (d.type) {
        case FieldType::Integer: case FieldType::Integer64:
            if (d.subType == FieldSubType::Boolean) return JsonValue::boolean(v.i != 0);
            return JsonValue::integer(v.i);
        case FieldType::Real: return sigFigDouble(v.d);
        case FieldType::String:
            if (d.subType == FieldSubType::JSON) { JsonValue j; if (JsonValue::parse(v.s, j)) return j; }
            return JsonValue::string(v.s);
        case FieldType::IntegerList: case FieldType::Integer64List: { JsonValue a = JsonValue::array(); for (auto i : v.il) a.push(d.subType == FieldSubType::Boolean ? JsonValue::boolean(i != 0) : JsonValue::integer(i)); return a; }
        case FieldType::RealList: { JsonValue a = JsonValue::array(); for (auto x : v.dl) a.push(sigFigDouble(x)); return a; }
        case FieldType::StringList: { JsonValue a = JsonValue::array(); for (auto& x : v.sl) a.push(JsonValue::string(x)); return a; }
        case FieldType::Date: return JsonValue::string(strprintf("%04d-%02d-%02d", v.year, v.month, v.day));
        case FieldType::Time: return JsonValue::string(v.second == (int)v.second ? strprintf("%02d:%02d:%02d", v.hour, v.minute, (int)v.second) : strprintf("%02d:%02d:%06.3f", v.hour, v.minute, v.second));
        case FieldType::DateTime: {
            std::string s = v.second == (int)v.second ? strprintf("%04d-%02d-%02dT%02d:%02d:%02d", v.year, v.month, v.day, v.hour, v.minute, (int)v.second) : strprintf("%04d-%02d-%02dT%02d:%02d:%06.3f", v.year, v.month, v.day, v.hour, v.minute, v.second);
            if (v.tz == 100) s += "Z";
            else if (v.tz > 1) { int off = (v.tz - 100) * 15; s += strprintf("%c%02d:%02d", off < 0 ? '-' : '+', abs(off) / 60, abs(off) % 60); }
            return JsonValue::string(s);
        }
        case FieldType::Binary: { std::string s; for (auto b : v.bin) s += strprintf("%02X", b); return JsonValue::string(s); }
    }
    return JsonValue::null();
}

bool writeGeoJSON(VectorDataset& ds, Layer& layer, const std::string& path, const std::vector<std::string>& lco, std::string& err, bool seq) {
    (void)ds;
    bool rfc7946 = false;
    bool writeName = true;
    for (auto& o : lco) {
        auto kv = splitString(o, '=');
        if (kv.size() == 2 && iequals(kv[0], "RFC7946") && (iequals(kv[1], "YES") || iequals(kv[1], "TRUE") || iequals(kv[1], "ON"))) rfc7946 = true;
        if (kv.size() == 2 && iequals(kv[0], "WRITE_NAME") && (iequals(kv[1], "NO") || iequals(kv[1], "FALSE") || iequals(kv[1], "OFF"))) writeName = false;
    }
    std::string out;
    if (!seq) {
        out += "{\n\"type\": \"FeatureCollection\",\n";
        if (writeName) out += "\"name\": " + jsonEscapeString(layer.name, true) + ",\n";
        if (!layer.geomFields.empty() && layer.geomFields[0].hasCRS && !rfc7946) {
            const CRS& c = layer.geomFields[0].crs;
            std::string an = c.authName(), ac = c.authCode();
            std::string urn;
            if (an == "EPSG" && ac == "4326") urn = "urn:ogc:def:crs:OGC:1.3:CRS84";
            else if (!an.empty() && !ac.empty()) urn = "urn:ogc:def:crs:" + an + "::" + ac;
            if (!urn.empty()) out += "\"crs\": { \"type\": \"name\", \"properties\": { \"name\": \"" + urn + "\" } },\n";
        }
        out += "\"features\": [\n";
    }
    bool first = true;
    for (auto& f : layer.features) {
        JsonValue fo = JsonValue::object();
        fo.set("type", JsonValue::string("Feature"));
        JsonValue props = JsonValue::object();
        for (size_t i = 0; i < layer.fields.size() && i < f.fields.size(); i++) props.set(layer.fields[i].name, fieldToJson(f.fields[i], layer.fields[i]));
        fo.set("properties", props);
        if (!f.geoms.empty() && f.geoms[0]) fo.set("geometry", geometryToGeoJson(*f.geoms[0], -1));
        else fo.set("geometry", JsonValue::null());
        if (!seq) { if (!first) out += ",\n"; first = false; out += jsonSpaced(fo); }
        else { out += jsonSpaced(fo) + "\n"; }
    }
    if (!seq) out += "\n]\n}\n";
    if (!writeFile(path, out)) { err = "cannot write " + path; return false; }
    return true;
}
