#include "vector.h"
#include "util.h"
#include <cstring>
#include <cmath>
#include <algorithm>

// Parse date/time strings like OGRParseDate (lax)
static bool parseDateTime(const std::string& s, FieldValue& v, FieldType& t) {
    int Y = 0, M = 0, D = 0, h = 0, m = 0; float sec = 0;
    char tzs[16] = {0};
    bool hasDate = false, hasTime = false;
    const char* p = s.c_str();
    int n = 0;
    if (sscanf(p, "%d-%d-%d%n", &Y, &M, &D, &n) == 3 && n > 0 && s.size() >= 8 && (s[4] == '-')) {
        hasDate = true;
        p += n;
        if (*p == 'T' || *p == ' ') {
            p++;
            int n2 = 0;
            if (sscanf(p, "%d:%d%n", &h, &m, &n2) == 2) {
                hasTime = true; p += n2;
                if (*p == ':') { p++; char* e; sec = (float)strtod(p, &e); p = e; }
            } else return false;
        }
    } else {
        int n2 = 0;
        if (sscanf(p, "%d:%d%n", &h, &m, &n2) == 2 && n2 > 0 && s.size() >= 5 && (s[2] == ':' || s[1] == ':')) {
            hasTime = true; p += n2;
            if (*p == ':') { p++; char* e; sec = (float)strtod(p, &e); p = e; }
        } else return false;
    }
    int tz = 0;
    if (hasTime) {
        if (*p == 'Z') { tz = 100; p++; }
        else if (*p == '+' || *p == '-') {
            int sign = *p == '-' ? -1 : 1; p++;
            int th = 0, tm = 0; int n3 = 0;
            if (sscanf(p, "%2d%n", &th, &n3) == 1) { p += n3; if (*p == ':') p++; if (sscanf(p, "%2d%n", &tm, &n3) == 1) p += n3; tz = 100 + sign * (th * 4 + tm / 15); }
            else return false;
        }
    }
    if (*p != 0) return false;
    if (hasDate && (M < 1 || M > 12 || D < 1 || D > 31)) return false;
    if (hasTime && (h < 0 || h > 24 || m < 0 || m > 59 || sec < 0 || sec >= 61)) return false;
    strcpy(tzs, "");
    v.year = Y; v.month = M; v.day = D; v.hour = h; v.minute = m; v.second = sec; v.tz = tz;
    if (hasDate && hasTime) t = FieldType::DateTime;
    else if (hasDate) t = FieldType::Date;
    else t = FieldType::Time;
    return true;
}

namespace {
struct PendingField {
    FieldDef def;
    bool typeKnown = false;   // false while only nulls seen
};
}

static void typeFromJson(const JsonValue& v, FieldType& t, FieldSubType& st, bool& known) {
    known = true;
    st = FieldSubType::None;
    if (v.isNull()) { known = false; t = FieldType::String; return; }
    if (v.isBool()) { t = FieldType::Integer; st = FieldSubType::Boolean; return; }
    if (v.isInt()) { long long i = v.asInt(); t = (i >= INT32_MIN && i <= INT32_MAX) ? FieldType::Integer : FieldType::Integer64; return; }
    if (v.isDouble()) { t = FieldType::Real; return; }
    if (v.isString()) {
        FieldValue tmp; FieldType dt;
        if (parseDateTime(v.asString(), tmp, dt)) { t = dt; return; }
        t = FieldType::String; return;
    }
    if (v.isArray()) {
        bool allInt = true, allNum = true, allStr = true, anyBig = false, allBool = true;
        for (auto& e : v.items()) {
            if (e.isBool()) { allInt = false; allNum = false; allStr = false; continue; }
            allBool = false;
            if (e.isInt()) { if (e.asInt() < INT32_MIN || e.asInt() > INT32_MAX) anyBig = true; allStr = false; }
            else if (e.isDouble()) { allInt = false; allStr = false; }
            else if (e.isString()) { allInt = false; allNum = false; }
            else { allInt = allNum = allStr = false; }
        }
        if (v.size() == 0) { t = FieldType::StringList; return; }
        if (allBool) { t = FieldType::IntegerList; st = FieldSubType::Boolean; return; }
        if (allInt) { t = anyBig ? FieldType::Integer64List : FieldType::IntegerList; return; }
        if (allNum) { t = FieldType::RealList; return; }
        if (allStr) { t = FieldType::StringList; return; }
        t = FieldType::String; st = FieldSubType::JSON; return;
    }
    if (v.isObject()) { t = FieldType::String; st = FieldSubType::JSON; return; }
    t = FieldType::String;
}

static bool isListType(FieldType t) { return t == FieldType::IntegerList || t == FieldType::Integer64List || t == FieldType::RealList || t == FieldType::StringList; }

static void mergeType(PendingField& f, FieldType nt, FieldSubType nst) {
    if (!f.typeKnown) { f.def.type = nt; f.def.subType = nst; f.typeKnown = true; return; }
    FieldType ot = f.def.type; FieldSubType ost = f.def.subType;
    if (ot == nt) {
        if (ost != nst) {
            // Boolean + Integer -> Integer; JSON + none -> String with JSON? keep JSON
            if (ost == FieldSubType::JSON || nst == FieldSubType::JSON) f.def.subType = FieldSubType::JSON;
            else f.def.subType = FieldSubType::None;
        }
        return;
    }
    auto isIntT = [](FieldType t) { return t == FieldType::Integer || t == FieldType::Integer64; };
    if (isIntT(ot) && isIntT(nt)) { f.def.type = FieldType::Integer64; f.def.subType = FieldSubType::None; return; }
    if ((isIntT(ot) || ot == FieldType::Real) && (isIntT(nt) || nt == FieldType::Real)) { f.def.type = FieldType::Real; f.def.subType = FieldSubType::None; return; }
    if ((ot == FieldType::Date || ot == FieldType::DateTime) && (nt == FieldType::Date || nt == FieldType::DateTime)) { f.def.type = FieldType::DateTime; return; }
    if (isListType(ot) || isListType(nt)) {
        FieldType a = ot, b = nt;
        auto listOf = [](FieldType t) { if (t == FieldType::Integer) return FieldType::IntegerList; if (t == FieldType::Integer64) return FieldType::Integer64List; if (t == FieldType::Real) return FieldType::RealList; if (t == FieldType::String) return FieldType::StringList; return t; };
        a = listOf(a); b = listOf(b);
        if (a == b) { f.def.type = a; f.def.subType = FieldSubType::None; return; }
        if ((a == FieldType::IntegerList || a == FieldType::Integer64List) && (b == FieldType::IntegerList || b == FieldType::Integer64List)) { f.def.type = FieldType::Integer64List; return; }
        if ((a == FieldType::IntegerList || a == FieldType::Integer64List || a == FieldType::RealList) && (b == FieldType::IntegerList || b == FieldType::Integer64List || b == FieldType::RealList)) { f.def.type = FieldType::RealList; return; }
        if (a == FieldType::StringList || b == FieldType::StringList) { f.def.type = FieldType::StringList; return; }
        f.def.type = FieldType::String; f.def.subType = FieldSubType::JSON; return;
    }
    f.def.type = FieldType::String;
    f.def.subType = (ost == FieldSubType::JSON || nst == FieldSubType::JSON) ? FieldSubType::JSON : FieldSubType::None;
}

static void setValueFromJson(const JsonValue& v, const FieldDef& d, FieldValue& out) {
    out.unset = false;
    if (v.isNull()) { out.null = true; return; }
    switch (d.type) {
        case FieldType::Integer: case FieldType::Integer64:
            if (v.isBool()) out.i = v.asBool() ? 1 : 0;
            else if (v.isNumber()) out.i = v.asInt();
            else out.i = atoll(v.asString().c_str());
            break;
        case FieldType::Real:
            if (v.isNumber()) out.d = v.asDouble();
            else if (v.isBool()) out.d = v.asBool() ? 1 : 0;
            else out.d = strtod(v.asString().c_str(), nullptr);
            break;
        case FieldType::String:
            if (v.isString()) out.s = v.asString();
            else if (v.isBool()) out.s = v.asBool() ? "1" : "0";
            else if (v.isInt()) out.s = std::to_string(v.asInt());
            else if (v.isDouble()) { char buf[64]; snprintf(buf, sizeof(buf), "%.17g", v.asDouble()); out.s = buf; }
            else out.s = v.serialize(JsonValue::COMPACT, false);
            break;
        case FieldType::IntegerList: case FieldType::Integer64List:
            if (v.isArray()) for (auto& e : v.items()) out.il.push_back(e.isBool() ? (e.asBool() ? 1 : 0) : e.asInt());
            else out.il.push_back(v.asInt());
            break;
        case FieldType::RealList:
            if (v.isArray()) for (auto& e : v.items()) out.dl.push_back(e.asDouble());
            else out.dl.push_back(v.asDouble());
            break;
        case FieldType::StringList:
            if (v.isArray()) for (auto& e : v.items()) out.sl.push_back(e.isString() ? e.asString() : e.serialize(JsonValue::COMPACT, false));
            else out.sl.push_back(v.isString() ? v.asString() : v.serialize(JsonValue::COMPACT, false));
            break;
        case FieldType::Date: case FieldType::Time: case FieldType::DateTime: {
            FieldType t;
            if (v.isString() && parseDateTime(v.asString(), out, t)) {}
            else out.null = true;
            break;
        }
        default: out.s = v.isString() ? v.asString() : v.serialize(JsonValue::COMPACT, false);
    }
}

static GeomType mergeGeomType(GeomType a, GeomType b, bool firstSet) {
    if (!firstSet) return b;
    if (a == b) return a;
    return GeomType::Unknown;
}

std::shared_ptr<VectorDataset> openGeoJSON(const std::string& path, std::string& err, const std::string& driverName) {
    std::string content;
    if (!readFile(path, content)) { err = "cannot read"; return nullptr; }
    auto ds = std::make_shared<VectorDataset>();
    ds->driverShort = driverName;
    ds->driverLong = driverName == "GeoJSONSeq" ? "GeoJSON Sequence" : driverName;
    ds->description = path;
    ds->files.push_back(path);
    auto layer = std::make_shared<Layer>();
    layer->name = stripExtension(getBasename(path));
    std::vector<JsonValue> featureObjs;
    JsonValue root;
    bool crsNull = false;
    std::string crsName;
    if (driverName == "GeoJSONSeq") {
        // one JSON object per line (optionally RS-prefixed)
        size_t pos = 0;
        while (pos < content.size()) {
            while (pos < content.size() && (content[pos] == '\x1e' || isspace((unsigned char)content[pos]))) pos++;
            if (pos >= content.size()) break;
            // find end: parse incrementally by brace matching
            int depth = 0; bool inStr = false; size_t st = pos;
            for (; pos < content.size(); pos++) {
                char c = content[pos];
                if (inStr) { if (c == '\\') pos++; else if (c == '"') inStr = false; continue; }
                if (c == '"') inStr = true;
                else if (c == '{' || c == '[') depth++;
