static uint32_t be32(const uint8_t* p) { return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; }
static uint32_t le32(const uint8_t* p) { return ((uint32_t)p[3] << 24) | ((uint32_t)p[2] << 16) | ((uint32_t)p[1] << 8) | p[0]; }
static uint16_t le16(const uint8_t* p) { return (uint16_t)(((uint16_t)p[1] << 8) | p[0]); }
static double led(const uint8_t* p) { double d; memcpy(&d, p, 8); return d; }

static std::string findSibling(const std::string& base, const char* ext) {
    std::string a = base + "." + ext;
    if (fileExists(a)) return a;
    std::string up = base + "." + toUpper(ext);
    if (fileExists(up)) return up;
    return "";
}

static double ringArea(const std::vector<Coord>& r) {
    double a = 0;
    for (size_t i = 0; i + 1 < r.size(); i++) a += r[i].x * r[i + 1].y - r[i + 1].x * r[i].y;
    return a / 2;  // positive = CCW
}

static bool pointInRing(const std::vector<Coord>& r, double x, double y) {
    bool in = false;
    size_t n = r.size();
    for (size_t i = 0, j = n - 1; i < n; j = i++) {
        if (((r[i].y > y) != (r[j].y > y)) && (x < (r[j].x - r[i].x) * (y - r[i].y) / (r[j].y - r[i].y) + r[i].x)) in = !in;
    }
    return in;
}

static std::shared_ptr<Geometry> assemblePolygons(std::vector<std::vector<Coord>>& rings, bool z, bool m) {
    std::vector<size_t> outer, inner;
    for (size_t i = 0; i < rings.size(); i++) { if (ringArea(rings[i]) < 0) outer.push_back(i); else inner.push_back(i); }
    if (outer.empty()) { outer = inner; inner.clear(); }
    std::vector<std::shared_ptr<Geometry>> polys;
    for (size_t o : outer) {
        auto p = std::make_shared<Geometry>();
        p->type = GeomType::Polygon; p->hasZ = z; p->hasM = m;
        p->rings.push_back(rings[o]);
        polys.push_back(p);
    }
    for (size_t h : inner) {
        // assign to containing outer
        size_t best = 0;
        bool found = false;
        for (size_t k = 0; k < outer.size(); k++) {
            if (!rings[h].empty() && pointInRing(rings[outer[k]], rings[h][0].x, rings[h][0].y)) { best = k; found = true; break; }
        }
        if (!found && !polys.empty()) best = 0;
        if (!polys.empty()) polys[best]->rings.push_back(rings[h]);
    }
    if (polys.size() == 1) return polys[0];
    auto mp = std::make_shared<Geometry>();
    mp->type = GeomType::MultiPolygon; mp->hasZ = z; mp->hasM = m;
    mp->parts = polys;
    return mp;
}

