            } else if (st == 3 || st == 5 || st == 13 || st == 15 || st == 23 || st == 25) {
                uint32_t nParts = le32(r + 36), nPoints = le32(r + 40);
                size_t o = 44;
                std::vector<uint32_t> parts(nParts);
                for (uint32_t i = 0; i < nParts; i++) { parts[i] = le32(r + o); o += 4; }
                std::vector<Coord> pts(nPoints);
                for (uint32_t i = 0; i < nPoints; i++) { pts[i].x = led(r + o); pts[i].y = led(r + o + 8); o += 16; }
                if (recZ && o + 16 + 8 * nPoints <= contentLen) { o += 16; for (uint32_t i = 0; i < nPoints; i++) { pts[i].z = led(r + o); o += 8; } }
                bool hasMvals = false;
                if ((recZ || recM) && o + 16 + 8 * nPoints <= contentLen) { o += 16; for (uint32_t i = 0; i < nPoints; i++) { pts[i].m = led(r + o); o += 8; if (pts[i].m > -1e38) hasMvals = true; } }
                if (hasMvals) anyM = true;
                bool useM = recM || (recZ && hasMvals);
                std::vector<std::vector<Coord>> rings;
                for (uint32_t i = 0; i < nParts; i++) {
                    uint32_t a = parts[i], b = (i + 1 < nParts) ? parts[i + 1] : nPoints;
                    if (a > b || b > nPoints) continue;
                    rings.emplace_back(pts.begin() + a, pts.begin() + b);
                }
                if (st == 3 || st == 13 || st == 23) {
                    if (rings.size() == 1) { g = std::make_shared<Geometry>(); g->type = GeomType::LineString; g->points = rings[0]; }
                    else { g = std::make_shared<Geometry>(); g->type = GeomType::MultiLineString; for (auto& rr : rings) { auto ls = std::make_shared<Geometry>(); ls->type = GeomType::LineString; ls->points = rr; g->parts.push_back(ls); } }
                    g->setZM(recZ, useM);
                } else {
                    g = assemblePolygons(rings, recZ, useM);
                }
            } else if (st == 8 || st == 18 || st == 28) {
                uint32_t nPoints = le32(r + 36);
                size_t o = 40;
                g = std::make_shared<Geometry>(); g->type = GeomType::MultiPoint;
                std::vector<Coord> pts(nPoints);
                for (uint32_t i = 0; i < nPoints; i++) { pts[i].x = led(r + o); pts[i].y = led(r + o + 8); o += 16; }
                if (recZ && o + 16 + 8 * nPoints <= contentLen) { o += 16; for (uint32_t i = 0; i < nPoints; i++) { pts[i].z = led(r + o); o += 8; } }
                bool hasMvals = false;
                if ((recZ || recM) && o + 16 + 8 * nPoints <= contentLen) { o += 16; for (uint32_t i = 0; i < nPoints; i++) { pts[i].m = led(r + o); o += 8; if (pts[i].m > -1e38) hasMvals = true; } }
                for (auto& c : pts) { auto pt = std::make_shared<Geometry>(); pt->type = GeomType::Point; pt->points.push_back(c); g->parts.push_back(pt); }
                g->setZM(recZ, recM || hasMvals);
                if (hasMvals) anyM = true;
            } else {
                g = nullptr;  // null shape
            }
            if (!firstShapeChecked && g) { firstShapeChecked = true; if (z && anyM) gf.hasM = true; }
            if (idx < feats.size()) feats[idx].geoms.push_back(g);
            else { Feature f; f.fid = (long long)idx; f.fields.resize(layer->fields.size()); f.geoms.push_back(g); feats.push_back(f); }
            idx++;
            pos += contentLen;
        }
        for (auto& f : feats) if (f.geoms.empty()) f.geoms.push_back(nullptr);
    } else {
        gf.type = GeomType::None;
    }
    if (!prj.empty()) {
        std::string wkt;
        if (readFile(prj, wkt)) {
            CRS c;
            if (c.setFromWKT(trimString(wkt))) {
                int conf = 0;
                int code = c.identifyEPSG(&conf);
                if (code > 0 && conf >= 90) { CRS e; if (e.setFromEPSG(code)) c = e; }
                gf.hasCRS = true; gf.crs = c;
            }
        }
    }
    if (!shp.empty()) layer->geomFields.push_back(gf);
    layer->features = feats;
    ds->layers.push_back(layer);
    return ds;
}

// ---------------------------------------------------------------------------
// Writer
static void putLE32(std::string& s, uint32_t v) { for (int i = 0; i < 4; i++) s += (char)((v >> (8 * i)) & 0xff); }
static void putBE32(std::string& s, uint32_t v) { for (int i = 3; i >= 0; i--) s += (char)((v >> (8 * i)) & 0xff); }
static void putLE16(std::string& s, uint16_t v) { s += (char)(v & 0xff); s += (char)((v >> 8) & 0xff); }
static void putD(std::string& s, double d) { char b[8]; memcpy(b, &d, 8); s.append(b, 8); }

static void orientRing(std::vector<Coord>& r, bool clockwise) {
    double a = ringArea(r);
    if ((a > 0 && clockwise) || (a < 0 && !clockwise)) std::reverse(r.begin(), r.end());
}

bool writeShapefile(VectorDataset& ds, Layer& layer, const std::string& path, const std::vector<std::string>& lco, std::string& err) {
    (void)ds; (void)lco;
    std::string base = stripExtension(path);
    if (iequals(getExtension(path), "shp") == false && isDirectory(path)) base = path + "/" + layer.name;
    // Determine shape type
    GeomType lt = layer.geomFields.empty() ? GeomType::None : layer.geomFields[0].type;
    bool z = !layer.geomFields.empty() && layer.geomFields[0].hasZ;
    bool m = !layer.geomFields.empty() && layer.geomFields[0].hasM;
    if (lt == GeomType::Unknown) {
        for (auto& f : layer.features) if (!f.geoms.empty() && f.geoms[0]) { lt = f.geoms[0]->type; z = f.geoms[0]->hasZ; m = f.geoms[0]->hasM; break; }
    }
    int shapeType = 0;
    switch (lt) {
        case GeomType::Point: shapeType = z ? 11 : (m ? 21 : 1); break;
        case GeomType::LineString: case GeomType::MultiLineString: shapeType = z ? 13 : (m ? 23 : 3); break;
        case GeomType::Polygon: case GeomType::MultiPolygon: shapeType = z ? 15 : (m ? 25 : 5); break;
        case GeomType::MultiPoint: shapeType = z ? 18 : (m ? 28 : 8); break;
        default: shapeType = 0;
    }
    bool writeZ = (shapeType == 11 || shapeType == 13 || shapeType == 15 || shapeType == 18);
    bool writeM = writeZ || (shapeType == 21 || shapeType == 23 || shapeType == 25 || shapeType == 28);
    std::string shp, shx;
    shp.resize(100, '\0'); shx.resize(100, '\0');
    Envelope env;
    int recNo = 1;
    for (auto& f : layer.features) {
        std::string rec;
        std::shared_ptr<Geometry> g = f.geoms.empty() ? nullptr : f.geoms[0];
        if (!g || g->isEmpty() || shapeType == 0) {
            putLE32(rec, 0);
        } else {
            putLE32(rec, (uint32_t)shapeType);
            Envelope e = g->envelope();
            env.merge(e);
            if (g->type == GeomType::Point) {
                const Coord& c = g->points[0];
                putD(rec, c.x); putD(rec, c.y);
                if (writeZ) putD(rec, c.z);
                if (writeM) putD(rec, g->hasM ? c.m : -1e39);
            } else {
                std::vector<std::vector<Coord>> parts;
                if (g->type == GeomType::LineString) parts.push_back(g->points);
                else if (g->type == GeomType::MultiLineString) for (auto& p : g->parts) parts.push_back(p->points);
                else if (g->type == GeomType::Polygon) { for (size_t i = 0; i < g->rings.size(); i++) { auto r = g->rings[i]; orientRing(r, i == 0); parts.push_back(r); } }
                else if (g->type == GeomType::MultiPolygon) { for (auto& p : g->parts) for (size_t i = 0; i < p->rings.size(); i++) { auto r = p->rings[i]; orientRing(r, i == 0); parts.push_back(r); } }
                else if (g->type == GeomType::MultiPoint) { std::vector<Coord> pts; for (auto& p : g->parts) if (!p->points.empty()) pts.push_back(p->points[0]); parts.push_back(pts); }
                size_t nPoints = 0;
                for (auto& p : parts) nPoints += p.size();
                putD(rec, e.minx); putD(rec, e.miny); putD(rec, e.maxx); putD(rec, e.maxy);
                if (g->type != GeomType::MultiPoint) {
                    putLE32(rec, (uint32_t)parts.size());
                    putLE32(rec, (uint32_t)nPoints);
                    uint32_t start = 0;
                    for (auto& p : parts) { putLE32(rec, start); start += (uint32_t)p.size(); }
                } else putLE32(rec, (uint32_t)nPoints);
                for (auto& p : parts) for (auto& c : p) { putD(rec, c.x); putD(rec, c.y); }
                if (writeZ) {
                    putD(rec, e.minz); putD(rec, e.maxz);
                    for (auto& p : parts) for (auto& c : p) putD(rec, c.z);
                }
                if (writeM) {
                    double mmin = 1e300, mmax = -1e300;
                    if (g->hasM) { for (auto& p : parts) for (auto& c : p) { mmin = std::min(mmin, c.m); mmax = std::max(mmax, c.m); } }
                    else { mmin = mmax = -1e39; }
                    putD(rec, mmin); putD(rec, mmax);
                    for (auto& p : parts) for (auto& c : p) putD(rec, g->hasM ? c.m : -1e39);
                }
            }
        }
        putBE32(shx, (uint32_t)(shp.size() / 2));
        putBE32(shx, (uint32_t)(rec.size() / 2));
        putBE32(shp, (uint32_t)recNo++);
        putBE32(shp, (uint32_t)(rec.size() / 2));
        shp += rec;
    }
    auto writeHeader = [&](std::string& s) {
        std::string h;
        putBE32(h, 9994); for (int i = 0; i < 5; i++) putBE32(h, 0);
        putBE32(h, (uint32_t)(s.size() / 2));
        putLE32(h, 1000); putLE32(h, (uint32_t)shapeType);
        if (env.valid) { putD(h, env.minx); putD(h, env.miny); putD(h, env.maxx); putD(h, env.maxy); putD(h, writeZ ? env.minz : 0); putD(h, writeZ ? env.maxz : 0); putD(h, 0); putD(h, 0); }
        else { for (int i = 0; i < 8; i++) putD(h, 0); }
        memcpy(&s[0], h.data(), 100);
    };
    writeHeader(shp); writeHeader(shx);
    if (!writeFile(base + ".shp", shp) || !writeFile(base + ".shx", shx)) { err = "cannot write shapefile"; return false; }
    // DBF
    std::string dbf;
    struct FieldSpec { char type; int width, dec; };
    std::vector<FieldSpec> specs;
    for (auto& fd : layer.fields) {
        FieldSpec sp;
        switch (fd.type) {
            case FieldType::Integer:
                if (fd.subType == FieldSubType::Boolean) { sp.type = 'L'; sp.width = 1; sp.dec = 0; }
                else { sp.type = 'N'; sp.width = fd.width ? fd.width : 9; sp.dec = 0; }
                break;
            case FieldType::Integer64: sp.type = 'N'; sp.width = fd.width ? fd.width : 18; sp.dec = 0; break;
            case FieldType::Real: sp.type = 'N'; if (fd.width) { sp.width = fd.width; sp.dec = fd.precision; } else { sp.width = 24; sp.dec = 15; } break;
            case FieldType::Date: sp.type = 'D'; sp.width = 8; sp.dec = 0; break;
            case FieldType::DateTime: sp.type = 'C'; sp.width = fd.width ? fd.width : 24; sp.dec = 0; break;
            default: sp.type = 'C'; sp.width = fd.width ? std::min(fd.width, 254) : 80; sp.dec = 0; break;
        }
        specs.push_back(sp);
    }
    size_t recLen = 1;
    for (auto& sp : specs) recLen += sp.width;
    size_t headerLen = 32 + 32 * specs.size() + 1;
    time_t now = time(nullptr);
    struct tm* tmv = localtime(&now);
    dbf += (char)0x03;
    dbf += (char)(tmv->tm_year); dbf += (char)(tmv->tm_mon + 1); dbf += (char)tmv->tm_mday;
    putLE32(dbf, (uint32_t)layer.features.size());
    putLE16(dbf, (uint16_t)headerLen); putLE16(dbf, (uint16_t)recLen);
    dbf.append(20, '\0');
    for (size_t i = 0; i < specs.size(); i++) {
        std::string nm = layer.fields[i].name.substr(0, 10);
        std::string fd(32, '\0');
        memcpy(&fd[0], nm.data(), nm.size());
        fd[11] = specs[i].type;
        fd[16] = (char)specs[i].width; fd[17] = (char)specs[i].dec;
        dbf += fd;
    }
    dbf += (char)0x0D;
    for (auto& f : layer.features) {
        std::string rec(recLen, ' ');
        size_t off = 1;
        for (size_t i = 0; i < specs.size(); i++) {
            const FieldSpec& sp = specs[i];
            const FieldValue* v = i < f.fields.size() ? &f.fields[i] : nullptr;
            std::string txt;
            if (v && !v->isNull() && !v->unset) {
                const FieldDef& fd = layer.fields[i];
                if (sp.type == 'L') txt = v->i ? "T" : "F";
                else if (sp.type == 'D') txt = strprintf("%04d%02d%02d", v->year, v->month, v->day);
                else if (sp.type == 'N') {
                    if (fd.type == FieldType::Real) {
                        txt = strprintf("%*.*f", sp.width, sp.dec, v->d);
                        if ((int)txt.size() > sp.width) { int dec = sp.dec; while ((int)txt.size() > sp.width && dec > 0) { dec--; txt = strprintf("%*.*f", sp.width, dec, v->d); } }
                    } else txt = strprintf("%*lld", sp.width, v->i);
                    if ((int)txt.size() > sp.width) txt = std::string(sp.width, '*');
                } else {
                    txt = fieldValueAsString(*v, fd);
                    if ((int)txt.size() > sp.width) txt = txt.substr(0, sp.width);
                }
            } else if (sp.type == 'L') txt = "?";
            if (sp.type == 'N' && !txt.empty()) memcpy(&rec[off + sp.width - txt.size()], txt.data(), txt.size());
            else memcpy(&rec[off], txt.data(), std::min(txt.size(), (size_t)sp.width));
            off += sp.width;
        }
        dbf += rec;
    }
    dbf += (char)0x1A;
    if (!writeFile(base + ".dbf", dbf)) { err = "cannot write dbf"; return false; }
    if (!layer.geomFields.empty() && layer.geomFields[0].hasCRS) {
        std::string esri = layer.geomFields[0].crs.exportWkt1(false);
        // ESRI flavour via PROJ
        extern std::string crsExportEsri(const CRS&);
        std::string e = crsExportEsri(layer.geomFields[0].crs);
        if (!e.empty()) esri = e;
        writeFile(base + ".prj", esri);
    }
    writeFile(base + ".cpg", "UTF-8");
    return true;
}
