    o.sql = a.getString("sql");
    o.where = a.getString("where");
    o.dialect = a.getString("dialect");
    if (a.isSet("fid")) { o.hasFid = true; o.fid = a.getInt("fid"); }
    o.crsFormat = a.getString("crs-format", "AUTO");
    if (!o.where.empty() && o.where[0] == '@') { std::string c; if (readFile(o.where.substr(1), c)) o.where = trimString(c); }
