std::string ogcGeomTypeName(GeomType t, bool z, bool m, bool camel, bool space) {
    std::string base;
    switch (t) {
        case GeomType::Point: base = camel ? "Point" : "POINT"; break;
        case GeomType::LineString: base = camel ? "LineString" : "LINESTRING"; break;
        case GeomType::Polygon: base = camel ? "Polygon" : "POLYGON"; break;
        case GeomType::MultiPoint: base = camel ? "MultiPoint" : "MULTIPOINT"; break;
        case GeomType::MultiLineString: base = camel ? "MultiLineString" : "MULTILINESTRING"; break;
        case GeomType::MultiPolygon: base = camel ? "MultiPolygon" : "MULTIPOLYGON"; break;
        case GeomType::GeometryCollection: base = camel ? "GeometryCollection" : "GEOMETRYCOLLECTION"; break;
        case GeomType::None: return "None";
        default: base = camel ? "Geometry" : "GEOMETRY"; break;
    }
    if (z || m) { if (space) base += " "; if (z) base += "Z"; if (m) base += "M"; }
    return base;
}

static std::string fieldTypeStr(const FieldDef& f) { return f.typeNameWithSub(); }

static bool layerSelected(const VectorInfoOptions& o, const Layer& l) {
    if (o.layers.empty()) return true;
    for (auto& n : o.layers) if (n == l.name) return true;
    return false;
}

// Very small WHERE evaluator: supports <field> <op> <value> combined with AND/OR, IS NULL, IS NOT NULL, LIKE (basic), IN (...)
namespace {
struct WhereEval {
    const Layer& layer;
    std::string expr;
    size_t i = 0;
    bool err = false;
    WhereEval(const Layer& l, const std::string& e) : layer(l), expr(e) {}
    void ws() { while (i < expr.size() && isspace((unsigned char)expr[i])) i++; }
    std::string token() {
        ws();
        if (i >= expr.size()) return "";
        char c = expr[i];
        if (c == '(' || c == ')' || c == ',') { i++; return std::string(1, c); }
        if (c == '\'' ) { size_t st = ++i; std::string s; while (i < expr.size()) { if (expr[i] == '\'' ) { if (i + 1 < expr.size() && expr[i + 1] == '\'') { s += '\''; i += 2; continue; } break; } s += expr[i++]; } i++; (void)st; return "'" + s; }
        if (c == '"') { size_t st = ++i; while (i < expr.size() && expr[i] != '"') i++; std::string s = expr.substr(st, i - st); i++; return "\"" + s; }
        if (c == '<' || c == '>' || c == '=' || c == '!') { std::string s(1, c); i++; if (i < expr.size() && (expr[i] == '=' || expr[i] == '>')) s += expr[i++]; return s; }
        size_t st = i;
        while (i < expr.size() && (isalnum((unsigned char)expr[i]) || expr[i] == '_' || expr[i] == '.' || expr[i] == '-' || expr[i] == '+')) i++;
        if (i == st) { i++; err = true; return ""; }
        return expr.substr(st, i - st);
    }
    std::string peek() { size_t save = i; bool e = err; std::string t = token(); i = save; err = e; return t; }
    bool evalOr(const Feature& f) { bool v = evalAnd(f); while (iequals(peek(), "OR")) { token(); bool r = evalAnd(f); v = v || r; } return v; }
    bool evalAnd(const Feature& f) { bool v = evalNot(f); while (iequals(peek(), "AND")) { token(); bool r = evalNot(f); v = v && r; } return v; }
    bool evalNot(const Feature& f) { if (iequals(peek(), "NOT")) { token(); return !evalNot(f); } return evalPrimary(f); }
    bool evalPrimary(const Feature& f) {
        std::string t = peek();
        if (t == "(") { token(); bool v = evalOr(f); if (peek() == ")") token(); return v; }
        std::string field = token();
        if (!field.empty() && (field[0] == '"')) field = field.substr(1);
        int idx = layer.findField(field);
        bool isFid = iequals(field, "FID");
        if (idx < 0 && !isFid) { err = true; return false; }
        std::string op = token();
        if (iequals(op, "IS")) {
            bool neg = false;
            std::string n = token();
            if (iequals(n, "NOT")) { neg = true; n = token(); }
            bool isNull = isFid ? false : (idx >= (int)f.fields.size() || f.fields[idx].isNull() || f.fields[idx].unset);
            return neg ? !isNull : isNull;
        }
        bool neg = false;
        if (iequals(op, "NOT")) { neg = true; op = token(); }
        if (iequals(op, "IN")) {
            std::vector<std::string> vals;
            if (token() != "(") { err = true; return false; }
            while (true) { std::string v = token(); if (v == ")") break; if (v == ",") continue; vals.push_back(v); }
            bool found = false;
            for (auto& v : vals) if (compare(f, idx, isFid, "=", v)) found = true;
            return neg ? !found : found;
        }
        std::string val = token();
        if (iequals(op, "LIKE") || iequals(op, "ILIKE")) {
            if (val.empty() || val[0] != '\'') { err = true; return false; }
            std::string s = isFid ? std::to_string(f.fid) : fieldValueAsString(f.fields[idx], layer.fields[idx]);
            bool r = likeMatch(s, val.substr(1), iequals(op, "ILIKE"));
            return neg ? !r : r;
        }
        bool r = compare(f, idx, isFid, op, val);
        return neg ? !r : r;
    }
    static bool likeMatch(const std::string& s, const std::string& pat, bool ci) {
        size_t si = 0, pi = 0, star = std::string::npos, mark = 0;
        while (si < s.size()) {
            if (pi < pat.size() && (pat[pi] == '_' || (ci ? tolower(pat[pi]) == tolower(s[si]) : pat[pi] == s[si]))) { si++; pi++; }
            else if (pi < pat.size() && pat[pi] == '%') { star = pi++; mark = si; }
            else if (star != std::string::npos) { pi = star + 1; si = ++mark; }
            else return false;
        }
        while (pi < pat.size() && pat[pi] == '%') pi++;
        return pi == pat.size();
    }
    bool compare(const Feature& f, int idx, bool isFid, const std::string& op, const std::string& val) {
        if (!isFid && (idx >= (int)f.fields.size() || f.fields[idx].isNull() || f.fields[idx].unset)) return false;
        bool strVal = !val.empty() && val[0] == '\'';
        if (strVal) {
            std::string s = isFid ? std::to_string(f.fid) : fieldValueAsString(f.fields[idx], layer.fields[idx]);
            std::string v = val.substr(1);
            int c = s.compare(v);
            if (op == "=") return c == 0;
            if (op == "<>" || op == "!=") return c != 0;
            if (op == "<") return c < 0;
            if (op == ">") return c > 0;
            if (op == "<=") return c <= 0;
            if (op == ">=") return c >= 0;
            err = true; return false;
        }
        double a;
        if (isFid) a = (double)f.fid;
        else {
            const FieldDef& d = layer.fields[idx];
            const FieldValue& v = f.fields[idx];
            if (d.type == FieldType::Integer || d.type == FieldType::Integer64) a = (double)v.i;
            else if (d.type == FieldType::Real) a = v.d;
            else a = strtod(v.s.c_str(), nullptr);
        }
        double b = strtod(val.c_str(), nullptr);
        if (op == "=") return a == b;
        if (op == "<>" || op == "!=") return a != b;
        if (op == "<") return a < b;
        if (op == ">") return a > b;
        if (op == "<=") return a <= b;
        if (op == ">=") return a >= b;
        err = true; return false;
    }
};
}

static bool featurePasses(const Layer& l, const Feature& f, const VectorInfoOptions& o) {
    if (o.hasFid && f.fid != o.fid) return false;
    if (!o.where.empty()) {
        WhereEval w(l, o.where);
        bool r = w.evalOr(f);
        if (w.err) return false;
        return r;
    }
    return true;
}

static std::string dumpFeature(const Layer& l, const Feature& f) {
    std::string s = strprintf("OGRFeature(%s):%lld\n", l.name.c_str(), f.fid);
    for (size_t i = 0; i < l.fields.size(); i++) {
        const FieldValue* v = i < f.fields.size() ? &f.fields[i] : nullptr;
        if (!v || v->unset) continue;
        const FieldDef& d = l.fields[i];
        std::string val = v->isNull() ? "(null)" : fieldValueAsString(*v, d);
        s += "  " + d.name + " (" + fieldTypeStr(d) + ") = " + val + "\n";
    }
    if (!f.style.empty()) s += "  Style = " + f.style + "\n";
    for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
        std::shared_ptr<Geometry> g = gi < f.geoms.size() ? f.geoms[gi] : nullptr;
        if (!g) continue;
        if (l.geomFields.size() > 1 || !l.geomFields[gi].name.empty()) s += "  " + l.geomFields[gi].name + " = " + g->toWkt() + "\n";
        else s += "  " + g->toWkt() + "\n";
    }
    s += "\n";
    return s;
}

static std::string layerSummaryText(Layer& l, const VectorInfoOptions& o) {
    std::string s;
    s += "Layer name: " + l.name + "\n";
    const MetadataList* md = l.metadata.domain("");
    if (md && !md->empty()) { s += "Metadata:\n"; for (auto& kv : *md) s += "  " + kv.first + "=" + kv.second + "\n"; }
    for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
        const GeomFieldDef& gf = l.geomFields[gi];
        if (l.geomFields.size() == 1) s += "Geometry: " + geomTypeName(gf.type, gf.hasZ, gf.hasM) + "\n";
        else s += "Geometry (" + gf.name + "): " + geomTypeName(gf.type, gf.hasZ, gf.hasM) + "\n";
    }
    if (l.geomFields.empty()) s += "Geometry: None\n";
    long long count = 0;
    for (auto& f : l.features) if (featurePasses(l, f, o)) count++;
    s += strprintf("Feature Count: %lld\n", count);
    for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
        const GeomFieldDef& gf = l.geomFields[gi];
        if (gf.type == GeomType::None) continue;
        Envelope e;
        for (auto& f : l.features) if (featurePasses(l, f, o) && gi < f.geoms.size() && f.geoms[gi] && !f.geoms[gi]->isEmpty()) e.merge(f.geoms[gi]->envelope());
        if (!e.valid) continue;
        if (l.geomFields.size() == 1) s += strprintf("Extent: (%f, %f) - (%f, %f)\n", e.minx, e.miny, e.maxx, e.maxy);
        else s += strprintf("Extent (%s): (%f, %f) - (%f, %f)\n", gf.name.c_str(), e.minx, e.miny, e.maxx, e.maxy);
    }
    for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
        const GeomFieldDef& gf = l.geomFields[gi];
        if (gf.type == GeomType::None && l.geomFields.size() == 1) continue;
        std::string prefix = l.geomFields.size() == 1 ? "Layer" : "SRS WKT (" + gf.name + ")";
        if (gf.hasCRS) {
            if (iequals(o.crsFormat, "WKT2")) s += (l.geomFields.size() == 1 ? "Layer SRS WKT:\n" : prefix + ":\n") + gf.crs.exportWkt2_2019(true) + "\n";
            else if (iequals(o.crsFormat, "PROJJSON")) s += "Layer SRS PROJJSON:\n" + gf.crs.exportProjjson() + "\n";
            else s += (l.geomFields.size() == 1 ? "Layer Coordinate Reference System:\n" : "Coordinate Reference System (" + gf.name + "):\n") + crsSummaryText(gf.crs, "  ");
            auto m = gf.crs.dataAxisToSRSAxisMapping();
            std::string ms;
            for (size_t i = 0; i < m.size(); i++) { if (i) ms += ","; ms += std::to_string(m[i]); }
            s += "Data axis to CRS axis mapping: " + ms + "\n";
        } else {
            s += (l.geomFields.size() == 1 ? "Layer SRS WKT:\n(unknown)\n" : prefix + ":\n(unknown)\n");
        }
        if (gf.xyRes > 0) s += strprintf("Geometry coordinate precision: XY=%g", gf.xyRes) + "\n";
    }
    if (!l.fidColumn.empty()) s += "FID Column = " + l.fidColumn + "\n";
    for (size_t gi = 0; gi < l.geomFields.size(); gi++) if (!l.geomFields[gi].name.empty() && l.geomFields.size() == 1) s += "Geometry Column = " + l.geomFields[gi].name + "\n";
    for (auto& f : l.fields) {
        s += f.name + ": " + fieldTypeStr(f) + strprintf(" (%d.%d)", f.width, f.precision);
        if (!f.nullable) s += " NOT NULL";
        if (f.unique) s += " UNIQUE";
        if (!f.defaultValue.empty()) s += " DEFAULT " + f.defaultValue;
        if (!f.alias.empty()) s += ", alias=" + f.alias;
        if (!f.domainName.empty()) s += ", domain name=" + f.domainName;
        if (!f.comment.empty()) s += ", comment=" + f.comment;
        s += "\n";
    }
    return s;
}

std::string vectorInfoText(VectorDataset& ds, const VectorInfoOptions& o) {
    std::string s;
    s += "INFO: Open of `" + ds.description + "'\n      using driver `" + ds.driverShort + "' successful.\n";
    const MetadataList* md = ds.metadata.domain("");
    if (md && !md->empty()) { s += "Metadata:\n"; for (auto& kv : *md) s += "  " + kv.first + "=" + kv.second + "\n"; }
    if (o.summary && !o.features) {
        for (size_t i = 0; i < ds.layers.size(); i++) {
            Layer& l = *ds.layers[i];
            if (!layerSelected(o, l)) continue;
            s += strprintf("%d: %s", (int)i + 1, l.name.c_str());
            if (l.geomFields.size() > 1) {
                s += " (";
                for (size_t g = 0; g < l.geomFields.size(); g++) { if (g) s += ", "; s += geomTypeName(l.geomFields[g].type, l.geomFields[g].hasZ, l.geomFields[g].hasM); }
                s += ")";
            } else if (l.geomFields.empty()) s += " (None)";
            else if (l.geomFields[0].type != GeomType::Unknown || l.geomFields[0].hasZ || l.geomFields[0].hasM) s += " (" + geomTypeName(l.geomFields[0].type, l.geomFields[0].hasZ, l.geomFields[0].hasM) + ")";
            s += "\n";
        }
        return s;
    }
    for (auto& lp : ds.layers) {
        Layer& l = *lp;
        if (!layerSelected(o, l)) continue;
        s += "\n";
        s += layerSummaryText(l, o);
        if (o.features || o.limit >= 0 || o.hasFid) {
            long long n = 0;
            for (auto& f : l.features) {
                if (!featurePasses(l, f, o)) continue;
                if (o.limit >= 0 && n >= o.limit) break;
                s += dumpFeature(l, f);
                n++;
            }
        }
    }
    return s;
}

static JsonValue crsJson(const CRS& crs, const std::string& crsFormat) {
    JsonValue cs = JsonValue::object();
    if (iequals(crsFormat, "PROJJSON")) cs.set("projjson", crs.projjsonValue());
    else if (iequals(crsFormat, "WKT2")) cs.set("wkt", JsonValue::string(crs.exportWkt2_2019(true)));
    else { cs.set("wkt", JsonValue::string(crs.exportWkt2_2019(true))); cs.set("projjson", crs.projjsonValue()); }
    JsonValue m = JsonValue::array();
    for (int v : crs.dataAxisToSRSAxisMapping()) m.push(JsonValue::integer(v));
    cs.set("dataAxisToSRSAxisMapping", m);
    return cs;
}

static JsonValue fieldJson(const FieldValue& v, const FieldDef& d) {
    if (v.isNull() || v.unset) return JsonValue::null();
    switch (d.type) {
        case FieldType::Integer: case FieldType::Integer64:
            if (d.subType == FieldSubType::Boolean) return JsonValue::boolean(v.i != 0);
            return JsonValue::integer(v.i);
        case FieldType::Real: { JsonValue n = JsonValue::number(v.d); n.setRawNumber(jsonFormatDouble(v.d, -1)); return n; }
        case FieldType::String: return JsonValue::string(v.s);
        case FieldType::IntegerList: case FieldType::Integer64List: { JsonValue a = JsonValue::array(); for (auto i : v.il) a.push(JsonValue::integer(i)); return a; }
        case FieldType::RealList: { JsonValue a = JsonValue::array(); for (auto x : v.dl) a.push(JsonValue::number(x)); return a; }
        case FieldType::StringList: { JsonValue a = JsonValue::array(); for (auto& x : v.sl) a.push(JsonValue::string(x)); return a; }
        default: return JsonValue::string(fieldValueAsString(v, d));
    }
}

JsonValue vectorInfoJson(VectorDataset& ds, const VectorInfoOptions& o) {
    JsonValue root = JsonValue::object();
    root.set("description", JsonValue::string(ds.description));
    root.set("driverShortName", JsonValue::string(ds.driverShort));
    root.set("driverLongName", JsonValue::string(ds.driverLong));
    JsonValue layers = JsonValue::array();
    for (auto& lp : ds.layers) {
        Layer& l = *lp;
        if (!layerSelected(o, l)) continue;
        JsonValue lj = JsonValue::object();
        lj.set("name", JsonValue::string(l.name));
        if (o.summary && !o.features) {
            JsonValue gfs = JsonValue::array();
            for (auto& gf : l.geomFields) { JsonValue g = JsonValue::object(); g.set("name", JsonValue::string(gf.name)); g.set("type", JsonValue::string(ogcGeomTypeName(gf.type, gf.hasZ, gf.hasM, true, false))); gfs.push(g); }
            lj.set("geometryFields", gfs);
            layers.push(lj);
            continue;
        }
        if (!l.fidColumn.empty()) lj.set("fidColumnName", JsonValue::string(l.fidColumn));
        JsonValue md = JsonValue::object();
        for (auto& dom : l.metadata.domains) { JsonValue d = JsonValue::object(); for (auto& kv : dom.second) d.set(kv.first, JsonValue::string(kv.second)); md.set(dom.first, d); }
        lj.set("metadata", md);
        JsonValue gfs = JsonValue::array();
        for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
            const GeomFieldDef& gf = l.geomFields[gi];
            if (gf.type == GeomType::None && l.geomFields.size() == 1) continue;
            JsonValue g = JsonValue::object();
            g.set("name", JsonValue::string(gf.name));
            g.set("type", JsonValue::string(ogcGeomTypeName(gf.type, gf.hasZ, gf.hasM, true, false)));
            g.set("nullable", JsonValue::boolean(gf.nullable));
            Envelope e;
            for (auto& f : l.features) if (featurePasses(l, f, o) && gi < f.geoms.size() && f.geoms[gi] && !f.geoms[gi]->isEmpty()) e.merge(f.geoms[gi]->envelope());
            if (e.valid) {
                JsonValue ext = JsonValue::array();
                ext.push(JsonValue::number(e.minx)); ext.push(JsonValue::number(e.miny)); ext.push(JsonValue::number(e.maxx)); ext.push(JsonValue::number(e.maxy));
                g.set("extent", ext);
            }
            if (gf.hasCRS) g.set("coordinateSystem", crsJson(gf.crs, o.crsFormat));
            gfs.push(g);
        }
        lj.set("geometryFields", gfs);
        long long count = 0;
        for (auto& f : l.features) if (featurePasses(l, f, o)) count++;
        lj.set("featureCount", JsonValue::integer(count));
        JsonValue fields = JsonValue::array();
        for (auto& f : l.fields) {
            JsonValue fj = JsonValue::object();
            fj.set("name", JsonValue::string(f.name));
            fj.set("type", JsonValue::string(fieldTypeName(f.type)));
            if (f.subType != FieldSubType::None) fj.set("subType", JsonValue::string(fieldSubTypeName(f.subType)));
            if (f.width) fj.set("width", JsonValue::integer(f.width));
            if (f.precision) fj.set("precision", JsonValue::integer(f.precision));
            fj.set("nullable", JsonValue::boolean(f.nullable));
            fj.set("uniqueConstraint", JsonValue::boolean(f.unique));
            if (!f.defaultValue.empty()) fj.set("defaultValue", JsonValue::string(f.defaultValue));
            if (!f.domainName.empty()) fj.set("domainName", JsonValue::string(f.domainName));
            if (!f.alias.empty()) fj.set("alias", JsonValue::string(f.alias));
            if (!f.comment.empty()) fj.set("comment", JsonValue::string(f.comment));
            fields.push(fj);
        }
        lj.set("fields", fields);
        if (o.features || o.limit >= 0 || o.hasFid) {
            JsonValue feats = JsonValue::array();
            long long n = 0;
            for (auto& f : l.features) {
                if (!featurePasses(l, f, o)) continue;
                if (o.limit >= 0 && n >= o.limit) break;
                JsonValue fj = JsonValue::object();
                fj.set("type", JsonValue::string("Feature"));
                JsonValue props = JsonValue::object();
                for (size_t i = 0; i < l.fields.size() && i < f.fields.size(); i++) if (!f.fields[i].unset) props.set(l.fields[i].name, fieldJson(f.fields[i], l.fields[i]));
                fj.set("properties", props);
                fj.set("fid", JsonValue::integer(f.fid));
                if (!f.style.empty()) fj.set("style", JsonValue::string(f.style));
                if (l.geomFields.size() <= 1) {
                    if (!f.geoms.empty() && f.geoms[0]) fj.set("geometry", geometryToGeoJson(*f.geoms[0], -1));
                    else fj.set("geometry", JsonValue::null());
                } else {
                    JsonValue gs = JsonValue::object();
                    for (size_t gi = 0; gi < l.geomFields.size(); gi++) gs.set(l.geomFields[gi].name, (gi < f.geoms.size() && f.geoms[gi]) ? geometryToGeoJson(*f.geoms[gi], -1) : JsonValue::null());
                    fj.set("geometryFields", gs);
                }
                feats.push(fj);
                n++;
            }
            lj.set("features", feats);
        }
        layers.push(lj);
    }
    root.set("layers", layers);
    JsonValue md = JsonValue::object();
    for (auto& dom : ds.metadata.domains) { JsonValue d = JsonValue::object(); for (auto& kv : dom.second) d.set(kv.first, JsonValue::string(kv.second)); md.set(dom.first, d); }
    root.set("metadata", md);
    root.set("domains", JsonValue::object());
    root.set("relationships", JsonValue::object());
    return root;
}
