#include "vector.h"
#include "util.h"

std::shared_ptr<VectorDataset> openVector(const std::string& path, std::string& err, int& errCode, const std::vector<std::string>& allowedDrivers, const std::vector<std::string>& openOptions) {
    (void)openOptions;
    if (!fileExists(path)) { err = path + ": No such file or directory"; errCode = 4; return nullptr; }
    bool isR = false, isV = false;
    std::string drv = identifyDriver(path, &isR, &isV);
    if (!allowedDrivers.empty()) {
        bool ok = false;
        for (auto& d : allowedDrivers) if (iequals(d, drv)) ok = true;
        if (!ok) drv = "";
    }
    std::shared_ptr<VectorDataset> ds;
    if (drv == "GeoJSON" || drv == "GeoJSONSeq" || drv == "ESRIJSON" || drv == "TopoJSON") ds = openGeoJSON(path, err, drv);
    else if (drv == "ESRI Shapefile") {
        if (isDirectory(path)) {
            ds = std::make_shared<VectorDataset>();
            ds->driverShort = "ESRI Shapefile"; ds->driverLong = "ESRI Shapefile"; ds->description = path;
            auto files = listDirectory(path);
            std::sort(files.begin(), files.end());
            for (auto& f : files) {
                if (!iequals(getExtension(f), "shp")) continue;
                auto sub = openShapefile(path + "/" + f, err);
                if (sub) for (auto& l : sub->layers) ds->layers.push_back(l);
            }
            if (ds->layers.empty()) ds = nullptr;
        } else ds = openShapefile(path, err);
    }
    if (!ds) { err = "`" + path + "' not recognized as being in a supported file format."; errCode = 4; return nullptr; }
    errCode = 0;
    return ds;
}
