#include <cstdio>
#include <set>

int runRasterInfo(Algorithm& a, bool shortcutMode);
int runVectorInfo(Algorithm& a, bool shortcutMode);

// Options of raster/vector info taking a value
static bool optionTakesValue(const std::string& tok) {
    static const std::set<std::string> withValue = {"-f", "--of", "--format", "--output-format", "-i", "--dataset", "--input", "--if", "--input-format", "--oo", "--open-option",
        "--mdd", "--metadata-domain", "--subdataset", "--crs-format", "-l", "--layer", "--input-layer", "--limit", "--sql", "--where", "--fid", "--dialect", "--config"};
    return withValue.count(tok) != 0;
}

static std::vector<std::string> positionalTokens(const std::vector<std::string>& args) {
    std::vector<std::string> pos;
    for (size_t i = 0; i < args.size(); i++) {
        const std::string& t = args[i];
        if (!t.empty() && t[0] == '-' && t.size() > 1) {
            if (t.find('=') == std::string::npos && optionTakesValue(t)) i++;
            continue;
        }
        pos.push_back(t);
    }
    return pos;
}

// Shared implementation. mode 0: 'gdal info ...' ; mode 1: 'gdal <file> ...' (root fallback)
static int infoShortcutImpl(Algorithm* root, const std::vector<std::string>& args, int mode, bool& handled) {
    handled = true;
    Algorithm* info = root->findSub("info");
    std::vector<std::string> pos = positionalTokens(args);
    // help / json-usage handling for the shortcut algorithm itself
    bool wantHelp = false, wantJson = false;
    for (auto& t : args) { if (t == "--help" || t == "-h" || t == "help") wantHelp = true; if (t == "--json-usage") wantJson = true; }
    if (pos.empty()) {
        if (wantHelp && mode == 0) { fputs(info->fullHelp().c_str(), stdout); return 0; }
        if (wantJson && mode == 0) { fputs(info->jsonUsage().c_str(), stdout); return 0; }
        // Let the generic parser report
        bool ok = info->parse(args);
        if (info->helpRequested) { fputs(info->fullHelp().c_str(), stdout); return 0; }
        if (info->jsonUsageRequested) { fputs(info->jsonUsage().c_str(), stdout); return 0; }
        if (!ok) { info->printUsageOnError(); return 1; }
        info->reportError(1, "Positional arguments starting at 'INPUT' have not been specified.");
        info->printUsageOnError();
        return 1;
    }
    std::string file = pos[0];
    if (!fileExists(file)) {
        if (wantHelp && mode == 0) { fputs(info->fullHelp().c_str(), stdout); return 0; }
        cplError(4, file + ": No such file or directory");
        info->printUsageOnError();
        return 1;
    }
    bool isR = false, isV = false;
    std::string drv = identifyDriver(file, &isR, &isV);
    if (drv.empty()) {
        if (wantHelp && mode == 0) { fputs(info->fullHelp().c_str(), stdout); return 0; }
        cplError(4, "`" + file + "' not recognized as being in a supported file format.");
        if (mode == 1) { handled = false; return 1; }
        info->printUsageOnError();
        return 1;
    }
    Algorithm* parent = root->findSub(isR ? "raster" : "vector");
    Algorithm* sub = parent->findSub("info");
    if (wantHelp) {
        if (mode == 0) { fputs(info->fullHelp().c_str(), stdout); return 0; }
        sub->usagePath = {"gdal", isR ? "raster" : "vector"};
        fputs(sub->fullHelp().c_str(), stdout);
        return 0;
    }
    if (wantJson) {
        if (mode == 0) { fputs(info->jsonUsage().c_str(), stdout); return 0; }
        JsonValue j = sub->rawJson;
        JsonValue fp = JsonValue::array();
        fp.push(JsonValue::string("gdal")); fp.push(JsonValue::string(isR ? "raster" : "vector"));
        j.set("full_path", fp);
        for (auto& a : j.getOrAdd("input_arguments").items()) {
            if (a.getString("name") == "input-format" && a.has("metadata")) {
                JsonValue caps = JsonValue::array();
                caps.push(JsonValue::string("DCAP_RASTER")); caps.push(JsonValue::string("DCAP_VECTOR"));
                a.getOrAdd("metadata").set("required_capabilities", caps);
            }
        }
        fputs(j.serialize(JsonValue::PRETTY, true).c_str(), stdout);
        return 0;
    }
    sub->usagePath = {"gdal", "info", isR ? "raster" : "vector"};
    sub->helpText = nullptr;  // use generated usage line without positional
    // mark input as pre-set so the generated usage line omits it
    ArgDef* inArg = sub->findArg("input");
    if (inArg) inArg->positional = false;
    if (pos.size() > 1) {
        for (int k = 0; k < (mode == 1 ? 2 : 1); k++) sub->reportError(1, "Positional values starting at '" + pos[0] + "' are not expected.");
        if (mode == 1) { handled = false; return 1; }
        sub->printUsageOnError();
        return 1;
    }
    // Build args without the file token
    std::vector<std::string> rest;
    bool removed = false;
    for (size_t i = 0; i < args.size(); i++) {
        const std::string& t = args[i];
        if (!removed && t == file && !(i > 0 && optionTakesValue(args[i - 1]) && args[i - 1].find('=') == std::string::npos)) { removed = true; continue; }
        rest.push_back(t);
    }
    ArgValue& v = sub->values["input"];
    v.specified = true; v.values = {file};
    bool ok = sub->parse(rest);
    if (!ok) {
        if (mode == 1) { handled = false; return 1; }
        sub->printUsageOnError();
        return 1;
    }
    return isR ? runRasterInfo(*sub, true) : runVectorInfo(*sub, true);
}

int runInfoShortcut(Algorithm* root, const std::vector<std::string>& args) {
    bool handled;
    return infoShortcutImpl(root, args, 0, handled);
}

bool runInfoShortcutOnFile(Algorithm* root, const std::string& file, const std::vector<std::string>& args, int& rc) {
    (void)file;
    bool handled;
    rc = infoShortcutImpl(root, args, 1, handled);
    return handled;
}
