#include "alg.h"
#include "util.h"
#include "json.h"
#include "raster.h"
#include "vector.h"
#include "drivers.h"
#include <cstdio>
#include <unistd.h>
#include <sys/stat.h>
#include <algorithm>
#include <functional>

// Sidecar files that belong to a dataset of a given driver
static std::vector<std::string> datasetFiles(const std::string& path, const std::string& drv) {
    std::vector<std::string> files;
    if (drv == "ESRI Shapefile") {
        std::string base = stripExtension(path);
        const char* exts[] = {"shp", "shx", "dbf", "prj", "cpg", "qix", "sbn", "sbx", "shp.xml", "qpj", nullptr};
        for (int i = 0; exts[i]; i++) {
            std::string f = base + "." + exts[i];
            if (fileExists(f)) files.push_back(f);
            std::string up = base + "." + toUpper(exts[i]);
            if (up != f && fileExists(up)) files.push_back(up);
        }
    } else {
        files.push_back(path);
        if (fileExists(path + ".aux.xml")) files.push_back(path + ".aux.xml");
        if (drv == "GTiff") {
            if (fileExists(path + ".ovr")) files.push_back(path + ".ovr");
            if (fileExists(path + ".msk")) files.push_back(path + ".msk");
            std::string base = stripExtension(path);
            for (const char* e : {".tfw", ".tifw", ".wld"}) if (fileExists(base + e)) files.push_back(base + e);
        }
    }
    return files;
}

static int runIdentify(Algorithm& a) {
    std::vector<std::string> inputs = a.getStringList("filename");
    bool rec = a.getBool("recursive") || a.getBool("force-recursive");
    bool reportFailures = a.getBool("report-failures");
    bool detailed = a.getBool("detailed");
    bool json = iequals(a.getString("output-format"), "json");
    JsonValue arr = JsonValue::array();
    std::string out;
    std::function<void(const std::string&)> process = [&](const std::string& f) {
        bool isR = false, isV = false;
        std::string drv = identifyDriver(f, &isR, &isV);
        if (drv.empty() && isDirectory(f) && rec) {
            auto names = listDirectory(f);
            std::sort(names.begin(), names.end());
            for (auto& n : names) process(f + "/" + n);
            return;
        }
        if (drv.empty()) {
            if (reportFailures) {
                if (json) { JsonValue o = JsonValue::object(); o.set("name", JsonValue::string(f)); o.set("driver", JsonValue::null()); arr.push(o); }
                else out += f + ": unrecognized\n";
            }
            return;
        }
        if (json) {
            JsonValue o = JsonValue::object();
            o.set("name", JsonValue::string(f));
            o.set("driver", JsonValue::string(drv));
            if (detailed && isR) {
                std::string err; int code;
                auto ds = openRaster(f, err, code);
                if (ds) {
                    o.set("has_georeferencing", JsonValue::boolean(ds->hasGeoTransform || !ds->gcps.empty()));
                    if (drv == "GTiff") o.set("is_cloud_optimized", JsonValue::boolean(ds->isCOG));
                }
            }
            arr.push(o);
        } else {
            out += f + ": " + drv;
            if (detailed && isR) {
                std::string err; int code;
                auto ds = openRaster(f, err, code);
                if (ds) {
                    out += (ds->hasGeoTransform || !ds->gcps.empty()) ? " (georeferenced)" : " (not georeferenced)";
                    if (drv == "GTiff" && ds->isCOG) out += " (cloud optimized)";
                }
            }
            out += "\n";
        }
    };
    for (auto& f : inputs) process(f);
    if (json) fputs(arr.serialize(JsonValue::PRETTY_SPACED, false).c_str(), stdout);
    else fputs(out.c_str(), stdout);
    return 0;
}

static std::string resolveDriver(Algorithm& a, const std::string& path) {
    std::string fmt = a.getString("format");
    if (!fmt.empty()) return fmt;
    std::string drv = identifyDriver(path);
    return drv;
}

static int runDatasetCopy(Algorithm& a) {
    std::string src = a.getString("source"), dst = a.getString("destination");
    bool overwrite = a.getBool("overwrite");
    if (!fileExists(src)) { a.reportError(4, src + ": No such file or directory"); return 1; }
    std::string drv = resolveDriver(a, src);
    if (drv.empty()) { a.reportError(1, "Cannot identify driver for " + src); return 1; }
    if (fileExists(dst) && !overwrite) { a.reportError(1, "File " + dst + " already exists. Specify the --overwrite option to overwrite it."); return 1; }
    auto files = datasetFiles(src, drv);
    for (auto& f : files) {
        std::string target;
        if (drv == "ESRI Shapefile") target = stripExtension(dst) + f.substr(stripExtension(src).size());
        else target = dst + f.substr(src.size());
        std::string data;
        if (!readFile(f, data) || !writeFile(target, data)) { a.reportError(1, "Cannot copy " + f + " to " + target); return 1; }
    }
    return 0;
}

static int runDatasetRename(Algorithm& a) {
    std::string src = a.getString("source"), dst = a.getString("destination");
    bool overwrite = a.getBool("overwrite");
    if (!fileExists(src)) { a.reportError(4, src + ": No such file or directory"); return 1; }
    std::string drv = resolveDriver(a, src);
    if (drv.empty()) { a.reportError(1, "Cannot identify driver for " + src); return 1; }
    if (fileExists(dst) && !overwrite) { a.reportError(1, "File " + dst + " already exists. Specify the --overwrite option to overwrite it."); return 1; }
    auto files = datasetFiles(src, drv);
    for (auto& f : files) {
        std::string target;
        if (drv == "ESRI Shapefile") target = stripExtension(dst) + f.substr(stripExtension(src).size());
        else target = dst + f.substr(src.size());
        if (rename(f.c_str(), target.c_str()) != 0) { a.reportError(1, "Cannot rename " + f + " to " + target); return 1; }
    }
    return 0;
}

static int runDatasetDelete(Algorithm& a) {
    std::vector<std::string> inputs = a.getStringList("filename");
    int rc = 0;
    for (auto& src : inputs) {
        if (!fileExists(src)) { a.reportError(4, src + ": No such file or directory"); rc = 1; continue; }
        std::string drv = resolveDriver(a, src);
        if (drv.empty()) { a.reportError(1, "Cannot identify driver for " + src); rc = 1; continue; }
        for (auto& f : datasetFiles(src, drv)) unlink(f.c_str());
    }
    return rc;
}

static int runDatasetCheck(Algorithm& a) {
    std::vector<std::string> inputs = a.getStringList("input");
    if (inputs.empty()) return 1;
    std::string err; int code = 0;
    bool isR = false, isV = false;
    std::string drv = identifyDriver(inputs[0], &isR, &isV);
    if (isR) {
        auto ds = openRaster(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
        if (!ds) { cplError(code, err); return 1; }
        for (auto& b : ds->bands) {
            std::vector<uint8_t> blk;
            for (int by = 0; by < b->blocksDown(); by++) for (int bx = 0; bx < b->blocksAcross(); bx++) {
                if (!b->readBlock(bx, by, blk, err)) { a.reportError(1, err); return 1; }
            }
        }
        return 0;
    }
    auto ds = openVector(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
    if (!ds) { cplError(code, err); return 1; }
    return 0;
}

void registerDatasetCommands(Algorithm* root) {
    Algorithm* d = root->findSub("dataset");
    if (!d) return;
    if (Algorithm* c = d->findSub("identify")) c->runFn = runIdentify;
    if (Algorithm* c = d->findSub("copy")) c->runFn = runDatasetCopy;
    if (Algorithm* c = d->findSub("rename")) c->runFn = runDatasetRename;
    if (Algorithm* c = d->findSub("delete")) c->runFn = runDatasetDelete;
    if (Algorithm* c = d->findSub("check")) c->runFn = runDatasetCheck;
}
