static std::string permString(mode_t m, bool isDir) {
    std::string s;
    s += isDir ? 'd' : '-';
    s += (m & S_IRUSR) ? 'r' : '-'; s += (m & S_IWUSR) ? 'w' : '-'; s += (m & S_IXUSR) ? 'x' : '-';
    s += (m & S_IRGRP) ? 'r' : '-'; s += (m & S_IWGRP) ? 'w' : '-'; s += (m & S_IXGRP) ? 'x' : '-';
    s += (m & S_IROTH) ? 'r' : '-'; s += (m & S_IWOTH) ? 'w' : '-'; s += (m & S_IXOTH) ? 'x' : '-';
    return s;
}

static std::string fmtTime(time_t t, bool withSeconds) {
    struct tm tmv;
    gmtime_r(&t, &tmv);
    char buf[64];
    if (withSeconds) strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tmv);
    else strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M", &tmv);
    return buf;
}

struct ListEntry { std::string path; std::string display; struct stat st; bool isDir; int depth; };

static void collect(const std::string& dir, const std::string& prefix, int depth, int maxDepth, bool recursive, std::vector<ListEntry>& out) {
    auto names = listDirectory(dir);
    std::sort(names.begin(), names.end());
    for (auto& n : names) {
        ListEntry e;
        e.path = dir + "/" + n;
        e.display = prefix.empty() ? n : prefix + "/" + n;
        if (stat(e.path.c_str(), &e.st) != 0) continue;
        e.isDir = S_ISDIR(e.st.st_mode);
        e.depth = depth;
        out.push_back(e);
        if (e.isDir && recursive && (maxDepth < 0 || depth + 1 < maxDepth)) collect(e.path, e.display, depth + 1, maxDepth, recursive, out);
    }
}

static int runVsiList(Algorithm& a) {
    std::string fn = a.getString("filename");
    bool json = iequals(a.getString("output-format", "text"), "json");
    bool lng = a.getBool("long-listing");
    bool rec = a.getBool("recursive");
    int depth = a.isSet("depth") ? (int)a.getInt("depth") : -1;
    bool abs = a.getBool("absolute-path");
    bool tree = a.getBool("tree");
    struct stat st;
    if (stat(fn.c_str(), &st) != 0) {
        a.reportError(1, "'" + fn + "' does not exist");
        return 1;
    }
    std::vector<ListEntry> entries;
    std::string base = fn;
    while (base.size() > 1 && base.back() == '/') base.pop_back();
    if (S_ISDIR(st.st_mode)) collect(base, "", 0, depth, rec, entries);
    else {
        ListEntry e; e.path = fn; e.display = fn; e.st = st; e.isDir = false; e.depth = 0;
        entries.push_back(e);
    }
    std::string absBase = getAbsolutePath(base);
    auto displayName = [&](const ListEntry& e) {
        if (abs) return S_ISDIR(st.st_mode) ? absBase + "/" + e.display : getAbsolutePath(e.display);
        return e.display;
    };
    if (json) {
        if (tree) {
            std::function<JsonValue(const std::string&, const std::string&, int)> build = [&](const std::string& dir, const std::string& prefix, int d) -> JsonValue {
                JsonValue arr = JsonValue::array();
                auto names = listDirectory(dir);
                std::sort(names.begin(), names.end());
                for (auto& n : names) {
                    std::string p = dir + "/" + n;
                    struct stat s2;
                    if (stat(p.c_str(), &s2) != 0) continue;
                    std::string disp = abs ? getAbsolutePath(p) : n;
                    if (S_ISDIR(s2.st_mode) && (depth < 0 || d + 1 < depth)) {
                        JsonValue o = JsonValue::object();
                        o.set("name", JsonValue::string(disp));
                        if (lng) { o.set("type", JsonValue::string("directory")); o.set("size", JsonValue::integer(0)); o.set("last_modification_date", JsonValue::string(fmtTime(s2.st_mtime, true))); o.set("permissions", JsonValue::string(permString(s2.st_mode, true))); }
                        o.set("entries", build(p, prefix + n + "/", d + 1));
                        arr.push(o);
                    } else if (lng) {
                        JsonValue o = JsonValue::object();
                        o.set("name", JsonValue::string(disp));
                        o.set("type", JsonValue::string(S_ISDIR(s2.st_mode) ? "directory" : "file"));
                        o.set("size", JsonValue::integer((long long)s2.st_size));
                        o.set("last_modification_date", JsonValue::string(fmtTime(s2.st_mtime, true)));
                        o.set("permissions", JsonValue::string(permString(s2.st_mode, S_ISDIR(s2.st_mode))));
                        arr.push(o);
                    } else arr.push(JsonValue::string(disp));
                }
                return arr;
            };
            JsonValue arr = S_ISDIR(st.st_mode) ? build(base, "", 0) : JsonValue::array();
            if (!S_ISDIR(st.st_mode)) arr.push(JsonValue::string(displayName(entries[0])));
            fputs(arr.serialize(JsonValue::PRETTY_SPACED, false).c_str(), stdout);
            return 0;
        }
        JsonValue arr = JsonValue::array();
        for (auto& e : entries) {
            if (lng) {
                JsonValue o = JsonValue::object();
                o.set("name", JsonValue::string(displayName(e)));
                o.set("type", JsonValue::string(e.isDir ? "directory" : "file"));
                o.set("size", JsonValue::integer((long long)e.st.st_size));
                o.set("last_modification_date", JsonValue::string(fmtTime(e.st.st_mtime, true)));
                o.set("permissions", JsonValue::string(permString(e.st.st_mode, e.isDir)));
                arr.push(o);
            } else arr.push(JsonValue::string(displayName(e)));
        }
        fputs(arr.serialize(JsonValue::PRETTY_SPACED, false).c_str(), stdout);
        return 0;
    }
    for (auto& e : entries) {
        if (lng) {
            printf("%s 1 unknown unknown %12lld %s %s\n", permString(e.st.st_mode, e.isDir).c_str(), (long long)e.st.st_size, fmtTime(e.st.st_mtime, false).c_str(), displayName(e).c_str());
        } else {
            printf("%s\n", displayName(e).c_str());
        }
    }
    return 0;
}

static bool copyFile(const std::string& src, const std::string& dst, std::string& err) {
    std::string data;
    if (!readFile(src, data)) { err = "Cannot open " + src; return false; }
    if (!writeFile(dst, data)) { err = "Cannot create " + dst; return false; }
    return true;
}

static bool copyRecursive(const std::string& src, const std::string& dst, bool recursive, bool skipErrors, Algorithm& a) {
    if (isDirectory(src)) {
        if (!recursive) { a.reportError(1, "'" + src + "' is a directory. Use -r/--recursive to copy directories"); return false; }
        mkdir(dst.c_str(), 0755);
        bool ok = true;
        for (auto& n : listDirectory(src)) {
            if (!copyRecursive(src + "/" + n, dst + "/" + n, recursive, skipErrors, a)) { ok = false; if (!skipErrors) return false; }
        }
        return ok;
    }
    std::string err;
    if (!copyFile(src, dst, err)) { a.reportError(1, err); return false; }
    return true;
}

static int runVsiCopy(Algorithm& a) {
    std::string src = a.getString("source"), dst = a.getString("destination");
    bool rec = a.getBool("recursive"), skip = a.getBool("skip-errors");
    if (!fileExists(src)) { a.reportError(1, "'" + src + "' does not exist"); return 1; }
    std::string target = dst;
    if (isDirectory(dst) && !isDirectory(src)) target = dst + "/" + getBasename(src);
    else if (isDirectory(dst) && isDirectory(src) && rec) target = dst + "/" + getBasename(src);
    return copyRecursive(src, target, rec, skip, a) ? 0 : 1;
}

static bool deleteRecursive(const std::string& p) {
    if (isDirectory(p)) {
        for (auto& n : listDirectory(p)) if (!deleteRecursive(p + "/" + n)) return false;
        return rmdir(p.c_str()) == 0;
    }
    return unlink(p.c_str()) == 0;
}

static int runVsiDelete(Algorithm& a) {
    std::string fn = a.getString("filename");
    bool rec = a.getBool("recursive");
    struct stat st;
    if (stat(fn.c_str(), &st) != 0) { a.reportError(1, "'" + fn + "' does not exist"); return 1; }
    if (S_ISDIR(st.st_mode)) {
        if (!rec) {
            if (rmdir(fn.c_str()) != 0) { a.reportError(1, "Cannot delete " + fn); return 1; }
            return 0;
        }
        if (!deleteRecursive(fn)) { a.reportError(1, "Cannot delete " + fn); return 1; }
        return 0;
    }
    if (unlink(fn.c_str()) != 0) { a.reportError(1, "Cannot delete " + fn); return 1; }
    return 0;
}

static int runVsiMove(Algorithm& a) {
    std::string src = a.getString("source"), dst = a.getString("destination");
    if (!fileExists(src)) { a.reportError(1, "'" + src + "' does not exist"); return 1; }
    std::string target = dst;
    if (isDirectory(dst)) target = dst + "/" + getBasename(src);
    if (rename(src.c_str(), target.c_str()) != 0) { a.reportError(1, "Cannot move " + src + " to " + target); return 1; }
    return 0;
}

static int runVsiSync(Algorithm& a) {
    std::string src = a.getString("source"), dst = a.getString("destination");
    bool rec = a.getBool("recursive");
    std::string strategy = a.getString("strategy", "timestamp");
    if (!fileExists(src)) { a.reportError(1, "'" + src + "' does not exist"); return 1; }
    std::function<bool(const std::string&, const std::string&)> sync = [&](const std::string& s, const std::string& d) -> bool {
        if (isDirectory(s)) {
            if (!rec) { a.reportError(1, "'" + s + "' is a directory. Use -r/--recursive to synchronize directories"); return false; }
            mkdir(d.c_str(), 0755);
            for (auto& n : listDirectory(s)) if (!sync(s + "/" + n, d + "/" + n)) return false;
            return true;
        }
        struct stat ss, ds;
        if (stat(d.c_str(), &ds) == 0 && stat(s.c_str(), &ss) == 0) {
            if (iequals(strategy, "timestamp") && ds.st_mtime >= ss.st_mtime && ds.st_size == ss.st_size) return true;
            if (iequals(strategy, "ETag") && ds.st_size == ss.st_size) { std::string c1, c2; readFile(s, c1); readFile(d, c2); if (c1 == c2) return true; }
        }
        std::string err;
        if (!copyFile(s, d, err)) { a.reportError(1, err); return false; }
        return true;
    };
    std::string target = dst;
    if (isDirectory(dst) && isDirectory(src)) target = dst + "/" + getBasename(src);
    else if (isDirectory(dst)) target = dst + "/" + getBasename(src);
    return sync(src, target) ? 0 : 1;
}

void registerVsiCommands(Algorithm* root) {
    Algorithm* vsi = root->findSub("vsi");
    if (!vsi) return;
    if (Algorithm* c = vsi->findSub("list")) c->runFn = runVsiList;
    if (Algorithm* c = vsi->findSub("copy")) c->runFn = runVsiCopy;
    if (Algorithm* c = vsi->findSub("delete")) c->runFn = runVsiDelete;
    if (Algorithm* c = vsi->findSub("move")) c->runFn = runVsiMove;
    if (Algorithm* c = vsi->findSub("sync")) c->runFn = runVsiSync;
}
