static TagEntry longTag(uint16_t tag, const std::vector<uint32_t>& vals) { TagEntry e; e.tag = tag; e.type = 4; e.count = (uint32_t)vals.size(); for (auto x : vals) p32(e.data, x); return e; }
static TagEntry doubleTag(uint16_t tag, const std::vector<double>& vals) { TagEntry e; e.tag = tag; e.type = 12; e.count = (uint32_t)vals.size(); for (auto x : vals) pd(e.data, x); return e; }
static TagEntry asciiTag(uint16_t tag, const std::string& s) { TagEntry e; e.tag = tag; e.type = 2; e.data.assign(s.begin(), s.end()); e.data.push_back(0); e.count = (uint32_t)e.data.size(); return e; }
