static int angularUnitCode(const CRS& crs) {
    std::string u = toLower(crs.angularUnitName());
    if (u == "degree") return 9102;
    if (u == "grad") return 9105;
    if (u == "radian") return 9101;
    if (u == "arc-second") return 9104;
    if (u == "arc-minute") return 9103;
    return 32767;
}
static int linearUnitCode(const CRS& crs) {
    std::string u = toLower(crs.linearUnitName());
    if (u == "metre" || u == "meter") return 9001;
    if (u == "foot") return 9002;
    if (u == "us survey foot") return 9003;
    if (u == "kilometre") return 9036;
    return 32767;
}

static void buildGeoKeys(const RasterDataset& ds, bool pixelIsPoint, std::vector<uint16_t>& dir, std::vector<double>& doubles, std::string& ascii) {
    struct Key { uint16_t id; uint16_t loc; uint16_t count; uint16_t off; };
    std::vector<Key> keys;
    auto addShort = [&](uint16_t id, uint16_t v) { keys.push_back({id, 0, 1, v}); };
    auto addAscii = [&](uint16_t id, const std::string& s) { keys.push_back({id, 34737, (uint16_t)(s.size() + 1), (uint16_t)ascii.size()}); ascii += s + "|"; };
