        addDouble(2057, crs.semiMajor());
    } else if (proj) {
        addShort(1024, 1);
        addShort(1025, pixelIsPoint ? 2 : 1);
        addAscii(1026, crs.name());
        CRS g;
        if (crs.geographicCRS(g)) {
            addAscii(2049, g.name());
            addShort(2054, (uint16_t)angularUnitCode(crs));
        }
        addDouble(2059, crs.invFlattening());
        addDouble(2057, crs.semiMajor());
        if (epsg) addShort(3072, (uint16_t)epsg); else addShort(3072, 32767);
