#include <algorithm>

namespace {
struct TagEntry {
    uint16_t tag, type; uint32_t count;
    std::vector<uint8_t> data;  // raw little-endian bytes
};
static void p16(std::vector<uint8_t>& v, uint16_t x) { v.push_back(x & 0xff); v.push_back(x >> 8); }
static void p32(std::vector<uint8_t>& v, uint32_t x) { for (int i = 0; i < 4; i++) v.push_back((x >> (8 * i)) & 0xff); }
static void pd(std::vector<uint8_t>& v, double d) { uint8_t b[8]; memcpy(b, &d, 8); v.insert(v.end(), b, b + 8); }

static TagEntry shortTag(uint16_t tag, const std::vector<uint16_t>& vals) { TagEntry e; e.tag = tag; e.type = 3; e.count = (uint32_t)vals.size(); for (auto x : vals) p16(e.data, x); return e; }
static TagEntry shortOrLongTag(uint16_t tag, uint32_t val) { if (val <= 0xffff) return shortTag(tag, {(uint16_t)val}); TagEntry e; e.tag = tag; e.type = 4; e.count = 1; p32(e.data, val); return e; }
static TagEntry longTag(uint16_t tag, const std::vector<uint32_t>& vals) { TagEntry e; e.tag = tag; e.type = 4; e.count = (uint32_t)vals.size(); for (auto x : vals) p32(e.data, x); return e; }
static TagEntry doubleTag(uint16_t tag, const std::vector<double>& vals) { TagEntry e; e.tag = tag; e.type = 12; e.count = (uint32_t)vals.size(); for (auto x : vals) pd(e.data, x); return e; }
static TagEntry asciiTag(uint16_t tag, const std::string& s) { TagEntry e; e.tag = tag; e.type = 2; e.data.assign(s.begin(), s.end()); e.data.push_back(0); e.count = (uint32_t)e.data.size(); return e; }
}

static int angularUnitCode(const CRS& crs) {
    std::string u = toLower(crs.angularUnitName());
    if (u == "degree") return 9102;
    if (u == "grad") return 9105;
    if (u == "radian") return 9101;
    if (u == "arc-second") return 9104;
    if (u == "arc-minute") return 9103;
    return 32767;
}
static int linearUnitCode(const CRS& crs) {
    std::string u = toLower(crs.linearUnitName());
    if (u == "metre" || u == "meter") return 9001;
    if (u == "foot") return 9002;
    if (u == "us survey foot") return 9003;
    if (u == "kilometre") return 9036;
    return 32767;
}

static void buildGeoKeys(const RasterDataset& ds, bool pixelIsPoint, std::vector<uint16_t>& dir, std::vector<double>& doubles, std::string& ascii) {
    struct Key { uint16_t id; uint16_t loc; uint16_t count; uint16_t off; };
    std::vector<Key> keys;
    auto addShort = [&](uint16_t id, uint16_t v) { keys.push_back({id, 0, 1, v}); };
    auto addAscii = [&](uint16_t id, const std::string& s) { keys.push_back({id, 34737, (uint16_t)(s.size() + 1), (uint16_t)ascii.size()}); ascii += s + "|"; };
    auto addDouble = [&](uint16_t id, double d) { keys.push_back({id, 34736, 1, (uint16_t)doubles.size()}); doubles.push_back(d); };
    const CRS& crs = ds.crs;
    bool geog = crs.isGeographic();
    bool proj = crs.isProjected();
    std::string an = crs.authName(), ac = crs.authCode();
    int epsg = (an == "EPSG") ? atoi(ac.c_str()) : 0;
    if (geog) {
        addShort(1024, 2);
        addShort(1025, pixelIsPoint ? 2 : 1);
        if (epsg) addShort(2048, (uint16_t)epsg); else addShort(2048, 32767);
        addAscii(2049, crs.name());
        addShort(2054, (uint16_t)angularUnitCode(crs));
        addDouble(2059, crs.invFlattening());
        addDouble(2057, crs.semiMajor());
    } else if (proj) {
        addShort(1024, 1);
        addShort(1025, pixelIsPoint ? 2 : 1);
        addAscii(1026, crs.name());
        CRS g;
        if (crs.geographicCRS(g)) {
            addAscii(2049, g.name());
            addShort(2054, (uint16_t)angularUnitCode(crs));
        }
        addDouble(2059, crs.invFlattening());
        addDouble(2057, crs.semiMajor());
        if (epsg) addShort(3072, (uint16_t)epsg); else addShort(3072, 32767);
        addShort(3076, (uint16_t)linearUnitCode(crs));
    } else {
        addShort(1024, 32767);
        addShort(1025, pixelIsPoint ? 2 : 1);
        addAscii(1026, crs.name());
    }
    std::sort(keys.begin(), keys.end(), [](const Key& a, const Key& b) { return a.id < b.id; });
    dir = {1, 1, 0, (uint16_t)keys.size()};
    for (auto& k : keys) { dir.push_back(k.id); dir.push_back(k.loc); dir.push_back(k.count); dir.push_back(k.off); }
}

static std::string nodataString(const RasterBand& b) {
    if (b.noDataIsInt64) return std::to_string(b.noDataInt64);
    if (b.noDataIsUInt64) return std::to_string(b.noDataUInt64);
    if (std::isnan(b.noData)) return "nan";
    if (std::isinf(b.noData)) return b.noData > 0 ? "inf" : "-inf";
    if (b.type == DataType::Float32 || b.type == DataType::CFloat32) {
        // GDAL writes with %.9g for Float32-castable? use %.18g generally
    }
    return strprintf("%.18g", b.noData);
}

static std::string buildGdalMetadata(const RasterDataset& ds) {
    XmlNode root;
    root.name = "GDALMetadata";
    bool any = false;
    for (auto& dom : ds.metadata.domains) {
        if (dom.first == "IMAGE_STRUCTURE" || dom.first == "SUBDATASETS" || dom.first == "__pam_hist__" || dom.first == "DERIVED_SUBDATASETS") continue;
        for (auto& kv : dom.second) {
            if (dom.first.empty() && kv.first == "AREA_OR_POINT") continue;
            if (dom.first.empty() && startsWith(kv.first, "TIFFTAG_")) continue;
            auto it = root.addChildWithText("Item", kv.second);
            it->setAttr("name", kv.first);
            if (!dom.first.empty()) it->setAttr("domain", dom.first);
            any = true;
        }
    }
    for (size_t i = 0; i < ds.bands.size(); i++) {
        const RasterBand& b = *ds.bands[i];
        if (!b.description.empty()) { auto it = root.addChildWithText("Item", b.description); it->setAttr("name", "DESCRIPTION"); it->setAttr("sample", std::to_string(i)); it->setAttr("role", "description"); any = true; }
        if (b.hasOffset && b.offset != 0.0) { auto it = root.addChildWithText("Item", strprintf("%.18g", b.offset)); it->setAttr("name", "OFFSET"); it->setAttr("sample", std::to_string(i)); it->setAttr("role", "offset"); any = true; }
        if (b.hasScale && b.scale != 1.0) { auto it = root.addChildWithText("Item", strprintf("%.18g", b.scale)); it->setAttr("name", "SCALE"); it->setAttr("sample", std::to_string(i)); it->setAttr("role", "scale"); any = true; }
        if (!b.unitType.empty()) { auto it = root.addChildWithText("Item", b.unitType); it->setAttr("name", "UNITTYPE"); it->setAttr("sample", std::to_string(i)); it->setAttr("role", "unittype"); any = true; }
        for (auto& dom : b.metadata.domains) {
            if (dom.first == "IMAGE_STRUCTURE" || dom.first == "__pam_hist__") continue;
            for (auto& kv : dom.second) {
                if (startsWith(kv.first, "STATISTICS_")) continue;
                auto it = root.addChildWithText("Item", kv.second);
                it->setAttr("name", kv.first); it->setAttr("sample", std::to_string(i));
                if (!dom.first.empty()) it->setAttr("domain", dom.first);
                any = true;
            }
        }
    }
    if (!any) return "";
    return xmlSerialize(root);
}

static void applyPredictorEncode(std::vector<uint8_t>& buf, int width, int height, int spp, int bytes, int predictor) {
    size_t rowLen = (size_t)width * spp * bytes;
    if (predictor == 2) {
        for (int y = 0; y < height; y++) {
            uint8_t* row = buf.data() + y * rowLen;
            if (bytes == 1) { for (size_t i = rowLen - 1; i >= (size_t)spp; i--) row[i] -= row[i - spp]; }
            else if (bytes == 2) { uint16_t* r = (uint16_t*)row; for (size_t i = (size_t)width * spp - 1; i >= (size_t)spp; i--) r[i] -= r[i - spp]; }
            else if (bytes == 4) { uint32_t* r = (uint32_t*)row; for (size_t i = (size_t)width * spp - 1; i >= (size_t)spp; i--) r[i] -= r[i - spp]; }
            else if (bytes == 8) { uint64_t* r = (uint64_t*)row; for (size_t i = (size_t)width * spp - 1; i >= (size_t)spp; i--) r[i] -= r[i - spp]; }
        }
    } else if (predictor == 3) {
        std::vector<uint8_t> tmp(rowLen);
        size_t n = (size_t)width * spp;
        for (int y = 0; y < height; y++) {
            uint8_t* row = buf.data() + y * rowLen;
            for (size_t i = 0; i < n; i++) for (int b = 0; b < bytes; b++) tmp[(bytes - 1 - b) * n + i] = row[i * bytes + b];
            for (size_t i = rowLen - 1; i >= 1; i--) tmp[i] -= tmp[i - 1];
            memcpy(row, tmp.data(), rowLen);
        }
    }
}

void printProgress(double ratio, bool& started, int& lastPrinted);

bool writeGTiff(RasterDataset& src, const std::string& path, const GTiffWriteOptions& opts, std::string& err, bool progress) {
    int nb = (int)src.bands.size();
    if (nb == 0) { err = "no bands"; return false; }
    DataType dt = src.bands[0]->type;
    int bytes = dataTypeSizeBytes(dt);
    int bps = bytes * 8;
    int sf = 1;
    if (dataTypeIsComplex(dt)) sf = dataTypeIsFloating(dt) ? 6 : 5;
    else if (dataTypeIsFloating(dt)) sf = 3;
    else if (dataTypeIsSigned(dt)) sf = 2;
    int W = src.xsize, H = src.ysize;
    bool contig = true;
    if (!opts.interleave.empty()) contig = iequals(opts.interleave, "PIXEL");
    if (nb == 1) contig = true;
    int spp = nb;
    int planar = contig ? 1 : 2;
    int compression = 1;
    std::string comp = toUpper(opts.compress);
    if (comp == "LZW") compression = 5;
    else if (comp == "DEFLATE") compression = 8;
    else if (comp == "PACKBITS") compression = 32773;
    else if (!comp.empty() && comp != "NONE") { err = "Unsupported compression " + comp; return false; }
    int predictor = opts.predictor;
    int photometric = 1;
    if (!opts.photometric.empty()) {
        std::string p = toUpper(opts.photometric);
        if (p == "RGB") photometric = 2; else if (p == "MINISBLACK") photometric = 1; else if (p == "MINISWHITE") photometric = 0; else if (p == "PALETTE") photometric = 3; else if (p == "CMYK") photometric = 5; else if (p == "YCBCR") photometric = 6;
    } else {
        if (nb >= 3 && dt == DataType::Byte && src.bands[0]->colorInterp == "Red" && src.bands[1]->colorInterp == "Green" && src.bands[2]->colorInterp == "Blue") photometric = 2;
        else if (nb >= 3 && dt == DataType::Byte && src.bands[0]->colorInterp == "Gray") photometric = 1;
        else if (nb >= 3 && dt == DataType::Byte) photometric = 2;
        if (src.bands[0]->hasColorTable && nb == 1) photometric = 3;
    }
    // Block layout
    int tileW = W, tileH;
    bool tiled = opts.tiled;
    if (tiled) { tileW = opts.blockXSize; tileH = opts.blockYSize; }
    else {
        size_t scan = (size_t)W * (contig ? spp : 1) * bytes;
        int rps = scan ? (int)(8192 / scan) : 1;
        if (rps == 0) rps = 1;
        if (opts.blockYSize > 0 && opts.blockYSize != 256) rps = opts.blockYSize;
        tileH = std::min(H, rps);
    }
    int blocksAcross = (W + tileW - 1) / tileW, blocksDown = (H + tileH - 1) / tileH;
    int nPlanes = contig ? 1 : nb;
    size_t nBlocks = (size_t)blocksAcross * blocksDown * nPlanes;
    // Tags
    std::vector<TagEntry> tags;
    tags.push_back(shortOrLongTag(256, W));
    tags.push_back(shortOrLongTag(257, H));
    { std::vector<uint16_t> v(spp, (uint16_t)bps); tags.push_back(shortTag(258, v)); }
    tags.push_back(shortTag(259, {(uint16_t)compression}));
    tags.push_back(shortTag(262, {(uint16_t)photometric}));
    size_t stripOffsetsIdx, stripCountsIdx;
    if (!tiled) {
        tags.push_back(longTag(273, std::vector<uint32_t>(nBlocks, 0))); stripOffsetsIdx = tags.size() - 1;
    }
    tags.push_back(shortTag(277, {(uint16_t)spp}));
    if (!tiled) {
        tags.push_back(shortOrLongTag(278, tileH));
        tags.push_back(longTag(279, std::vector<uint32_t>(nBlocks, 0))); stripCountsIdx = tags.size() - 1;
    }
    tags.push_back(shortTag(284, {(uint16_t)planar}));
    if (compression != 1 && predictor > 1 && compression != 32773) tags.push_back(shortTag(317, {(uint16_t)predictor}));
    if (photometric == 3 && src.bands[0]->hasColorTable) {
        int n = 1 << bps;
        std::vector<uint16_t> cmap(3 * n, 0);
        for (int i = 0; i < n && i < (int)src.bands[0]->colorTable.size(); i++) {
            const ColorEntry& e = src.bands[0]->colorTable[i];
            cmap[i] = (uint16_t)(e.c1 * 257); cmap[n + i] = (uint16_t)(e.c2 * 257); cmap[2 * n + i] = (uint16_t)(e.c3 * 257);
        }
        tags.push_back(shortTag(320, cmap));
    }
    if (tiled) {
        tags.push_back(shortOrLongTag(322, tileW));
        tags.push_back(shortOrLongTag(323, tileH));
        tags.push_back(longTag(324, std::vector<uint32_t>(nBlocks, 0))); stripOffsetsIdx = tags.size() - 1;
        tags.push_back(longTag(325, std::vector<uint32_t>(nBlocks, 0))); stripCountsIdx = tags.size() - 1;
    }
    int nColorBands = photometric == 2 ? 3 : (photometric == 5 ? 4 : 1);
    if (spp > nColorBands) {
        std::vector<uint16_t> ex;
        for (int i = nColorBands; i < spp; i++) ex.push_back(src.bands[i]->colorInterp == "Alpha" ? 2 : 0);
        tags.push_back(shortTag(338, ex));
    }
    { std::vector<uint16_t> v(spp, (uint16_t)sf); tags.push_back(shortTag(339, v)); }
    bool pixelIsPoint = iequals(src.metadata.get("", "AREA_OR_POINT"), "Point");
    if (src.hasGeoTransform) {
        double gt[6]; memcpy(gt, src.gt, sizeof(gt));
        if (pixelIsPoint) { gt[0] += gt[1] * 0.5 + gt[2] * 0.5; gt[3] += gt[4] * 0.5 + gt[5] * 0.5; }
        if (gt[2] == 0 && gt[4] == 0 && gt[5] < 0) {
            tags.push_back(doubleTag(33550, {gt[1], fabs(gt[5]), 0.0}));
            tags.push_back(doubleTag(33922, {0, 0, 0, gt[0], gt[3], 0}));
        } else {
            tags.push_back(doubleTag(34264, {gt[1], gt[2], 0, gt[0], gt[4], gt[5], 0, gt[3], 0, 0, 0, 0, 0, 0, 0, 1}));
        }
    } else if (!src.gcps.empty()) {
        std::vector<double> tp;
        for (auto& g : src.gcps) { tp.push_back(g.pixel); tp.push_back(g.line); tp.push_back(0); tp.push_back(g.x); tp.push_back(g.y); tp.push_back(g.z); }
        tags.push_back(doubleTag(33922, tp));
    }
    if (src.hasCRS || (!src.gcps.empty() && src.hasGcpCRS)) {
        std::vector<uint16_t> dir; std::vector<double> dbl; std::string asc;
        RasterDataset tmp;
        tmp.crs = src.hasCRS ? src.crs : src.gcpCRS;
        buildGeoKeys(tmp, pixelIsPoint, dir, dbl, asc);
        tags.push_back(shortTag(34735, dir));
        if (!dbl.empty()) tags.push_back(doubleTag(34736, dbl));
        if (!asc.empty()) tags.push_back(asciiTag(34737, asc));
    } else if (src.hasGeoTransform || pixelIsPoint) {
        // GDAL writes RasterType key even without CRS when georeferenced? Only AREA_OR_POINT=Point matters
        if (pixelIsPoint) tags.push_back(shortTag(34735, {1, 1, 0, 1, 1025, 0, 1, 2}));
    }
    std::string gmd = buildGdalMetadata(src);
    if (!gmd.empty()) tags.push_back(asciiTag(42112, gmd));
    if (src.bands[0]->hasNoData) tags.push_back(asciiTag(42113, nodataString(*src.bands[0])));
    std::sort(tags.begin(), tags.end(), [](const TagEntry& a, const TagEntry& b) { return a.tag < b.tag; });
    // Layout
    size_t ifdOff = 8;
    size_t ifdSize = 2 + tags.size() * 12 + 4;
    size_t dataOff = ifdOff + ifdSize;
    std::vector<size_t> extOffsets(tags.size(), 0);
    for (size_t i = 0; i < tags.size(); i++) {
        if (tags[i].data.size() > 4) { extOffsets[i] = dataOff; dataOff += tags[i].data.size(); if (dataOff & 1) dataOff++; }
    }
    size_t imageOff = dataOff;
    // Build image data
    std::vector<uint8_t> image;
    std::vector<uint32_t> offsets(nBlocks, 0), counts(nBlocks, 0);
    size_t cur = imageOff;
    bool started = false; int lastPrinted = -1;
    std::vector<uint8_t> blk, raw, enc;
    size_t blkIdx = 0;
    for (int plane = 0; plane < nPlanes; plane++) {
        for (int by = 0; by < blocksDown; by++) {
            for (int bx = 0; bx < blocksAcross; bx++) {
                int x0 = bx * tileW, y0 = by * tileH;
                int bw = tiled ? tileW : std::min(tileW, W - x0);
                int bh = tiled ? tileH : std::min(tileH, H - y0);
                int rw = std::min(bw, W - x0), rh = std::min(bh, H - y0);
                int sppBlk = contig ? spp : 1;
                raw.assign((size_t)bw * bh * sppBlk * bytes, 0);
                for (int s = 0; s < sppBlk; s++) {
                    int band = contig ? s : plane;
                    if (!src.bands[band]->readWindowRaw(x0, y0, rw, rh, blk, err)) return false;
                    for (int y = 0; y < rh; y++) {
                        for (int x = 0; x < rw; x++) {
                            memcpy(raw.data() + (((size_t)y * bw + x) * sppBlk + s) * bytes, blk.data() + ((size_t)y * rw + x) * bytes, bytes);
                        }
                    }
                }
                bool allZero = false;
                if (opts.sparseOk) { allZero = true; for (auto c : raw) if (c) { allZero = false; break; } }
                if (allZero) { offsets[blkIdx] = 0; counts[blkIdx] = 0; blkIdx++; continue; }
                if (compression != 1 && predictor > 1) applyPredictorEncode(raw, bw, bh, sppBlk, bytes, predictor);
                const std::vector<uint8_t>* out = &raw;
                if (compression == 8) { if (!zlibEncode(raw.data(), raw.size(), enc, opts.zlevel)) { err = "deflate error"; return false; } out = &enc; }
                else if (compression == 5) { enc = lzwEncode(raw.data(), raw.size()); out = &enc; }
                else if (compression == 32773) {
                    // packbits per row
                    enc.clear();
                    size_t rowLen = (size_t)bw * sppBlk * bytes;
                    for (int y = 0; y < bh; y++) {
                        const uint8_t* row = raw.data() + y * rowLen;
                        size_t i = 0;
                        while (i < rowLen) {
                            size_t run = 1;
                            while (i + run < rowLen && row[i + run] == row[i] && run < 128) run++;
                            if (run >= 2) { enc.push_back((uint8_t)(257 - run)); enc.push_back(row[i]); i += run; }
                            else {
                                size_t lit = 1;
                                while (i + lit < rowLen && lit < 128 && !(i + lit + 1 < rowLen && row[i + lit] == row[i + lit + 1])) lit++;
                                enc.push_back((uint8_t)(lit - 1));
                                enc.insert(enc.end(), row + i, row + i + lit);
                                i += lit;
                            }
                        }
                    }
                    out = &enc;
                }
                offsets[blkIdx] = (uint32_t)cur;
                counts[blkIdx] = (uint32_t)out->size();
                image.insert(image.end(), out->begin(), out->end());
                cur += out->size();
                blkIdx++;
                if (progress) printProgress((double)blkIdx / nBlocks, started, lastPrinted);
            }
        }
    }
    if (cur > 0xffffffffULL) { err = "File too large for classic TIFF"; return false; }
    // Fill strip arrays
    tags[stripOffsetsIdx] = longTag(tags[stripOffsetsIdx].tag, offsets);
    tags[stripCountsIdx] = longTag(tags[stripCountsIdx].tag, counts);
    // Assemble file
    std::string file;
    file.reserve(imageOff + image.size());
    file += "II"; file += (char)42; file += (char)0; { std::vector<uint8_t> t; p32(t, 8); file.append((const char*)t.data(), 4); }
    std::vector<uint8_t> ifd;
    p16(ifd, (uint16_t)tags.size());
    for (size_t i = 0; i < tags.size(); i++) {
        const TagEntry& t = tags[i];
        p16(ifd, t.tag); p16(ifd, t.type); p32(ifd, t.count);
        if (t.data.size() <= 4) { ifd.insert(ifd.end(), t.data.begin(), t.data.end()); for (size_t k = t.data.size(); k < 4; k++) ifd.push_back(0); }
        else p32(ifd, (uint32_t)extOffsets[i]);
    }
    p32(ifd, 0);
    file.append((const char*)ifd.data(), ifd.size());
    for (size_t i = 0; i < tags.size(); i++) {
        if (tags[i].data.size() > 4) {
            while (file.size() < extOffsets[i]) file += '\0';
            file.append((const char*)tags[i].data.data(), tags[i].data.size());
        }
    }
    while (file.size() < imageOff) file += '\0';
    file.append((const char*)image.data(), image.size());
    if (!writeFile(path, file)) { err = "Cannot create " + path; return false; }
    if (progress) printProgress(1.0, started, lastPrinted);
    return true;
}
