#include <cstdio>
#include <algorithm>

void printProgress(double ratio, bool& started, int& lastTick) {
    if (!started) { lastTick = -1; started = true; }
    int thisTick = std::min(40, std::max(0, (int)(ratio * 40.0)));
    if (thisTick < lastTick && lastTick >= 39) lastTick = -1;
    if (thisTick <= lastTick) return;
    while (thisTick > lastTick) {
        ++lastTick;
        if (lastTick % 4 == 0) fprintf(stdout, "%d", (lastTick / 4) * 10);
        else fprintf(stdout, ".");
    }
    if (thisTick == 40) fprintf(stdout, " - done.\n");
    fflush(stdout);
}
