        else if (ku == "PHOTOMETRIC") o.photometric = v;
        else if (ku == "NBITS") o.nbits = atoi(v.c_str());
        else if (ku == "SPARSE_OK") o.sparseOk = iequals(v, "YES") || iequals(v, "TRUE") || iequals(v, "ON");
