    std::string drv = fmt.empty() ? guessOutputDriver(out, true) : fmt;
    if (drv.empty()) { a.reportError(1, "Cannot guess driver for " + out); return false; }
    if (!iequals(drv, "GTiff") && !iequals(drv, "COG")) {
