    auto ds = openRaster(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
    if (!ds) { cplError(code, err); a.printUsageOnError(); return 1; }
    bool progress = !a.getBool("quiet");
    if (!writeRasterOutput(a, *ds, out, a.getString("output-format"), a.getStringList("creation-option"), progress)) return 1;
    return 0;
}

static bool parseNoData(const std::string& s, double& v, bool& none) {
    none = false;
    if (iequals(s, "none")) { none = true; return true; }
    if (iequals(s, "nan")) { v = NAN; return true; }
    if (iequals(s, "inf")) { v = INFINITY; return true; }
    if (iequals(s, "-inf")) { v = -INFINITY; return true; }
    if (!isRealString(s)) return false;
    v = strtod(s.c_str(), nullptr);
    return true;
}

static int runRasterCreate(Algorithm& a) {
    std::string out = a.getString("output");
    if (!checkOutputExists(a, out)) { a.printUsageOnError(); return 1; }
    std::vector<std::string> inputs = a.getStringList("input");
    std::shared_ptr<RasterDataset> like;
    if (!inputs.empty()) {
        std::string err; int code = 0;
        like = openRaster(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
        if (!like) { cplError(code, err); a.printUsageOnError(); return 1; }
    }
    std::vector<long long> size = a.getIntList("size");
    int W = 0, H = 0;
    if (size.size() == 2) { W = (int)size[0]; H = (int)size[1]; }
    else if (like) { W = like->xsize; H = like->ysize; }
    else { a.reportError(1, "--size must be specified when --like is not specified."); a.printUsageOnError(); return 1; }
    if (W <= 0 || H <= 0) { a.reportError(5, "Invalid value for --size: width and height must be positive"); return 1; }
    int nb = a.isSet("band-count") ? (int)a.getInt("band-count") : (like ? (int)like->bands.size() : 1);
    DataType dt = DataType::Byte;
    if (a.isSet("output-data-type")) dt = dataTypeFromName(a.getString("output-data-type"));
    else if (like && !like->bands.empty()) dt = like->bands[0]->type;
    auto ds = createMemDataset(W, H, nb, dt);
    ds->description = out;
    if (like) {
        if (like->hasCRS) { ds->hasCRS = true; ds->crs = like->crs; }
        if (like->hasGeoTransform) { ds->hasGeoTransform = true; memcpy(ds->gt, like->gt, sizeof(ds->gt)); }
        if (a.getBool("copy-metadata")) ds->metadata = like->metadata;
    }
    if (a.isSet("crs")) {
        std::string c = a.getString("crs");
        if (iequals(c, "none") || iequals(c, "null")) ds->hasCRS = false;
        else {
            CRS crs;
            if (!crs.setFromUserInput(c)) { a.reportError(5, "Invalid value for 'crs' argument"); return 1; }
            ds->hasCRS = true; ds->crs = crs;
        }
    }
    std::vector<double> bbox = a.getRealList("bbox");
    if (bbox.size() == 4) {
        ds->hasGeoTransform = true;
        ds->gt[0] = bbox[0]; ds->gt[1] = (bbox[2] - bbox[0]) / W; ds->gt[2] = 0;
        ds->gt[3] = bbox[3]; ds->gt[4] = 0; ds->gt[5] = -(bbox[3] - bbox[1]) / H;
    }
    if (a.isSet("nodata")) {
        double nd; bool none;
        if (!parseNoData(a.getString("nodata"), nd, none)) { a.reportError(5, "Invalid value for 'nodata' argument"); return 1; }
        if (!none) for (auto& b : ds->bands) { b->hasNoData = true; b->noData = nd; }
    }
    std::vector<double> burn = a.getRealList("burn");
    if (!burn.empty()) {
        if (burn.size() != 1 && (int)burn.size() != nb) {
            if (nb == 1) a.reportError(5, "One value should be provided for argument 'burn', given there is one band");
            else a.reportError(5, strprintf("One or %d values should be provided for argument 'burn', given there are %d bands", nb, nb));
            a.printUsageOnError();
            return 1;
        }
        for (int i = 0; i < nb; i++) {
            double v = burn.size() == 1 ? burn[0] : burn[i];
            MemBand* mb = static_cast<MemBand*>(ds->bands[i].get());
            int sz = dataTypeSizeBytes(dt);
            std::vector<uint8_t> px(sz);
            doubleToSample(v, px.data(), dt);
            for (size_t p = 0; p < (size_t)W * H; p++) memcpy(mb->data.data() + p * sz, px.data(), sz);
        }
    }
    for (auto& md : a.getStringList("metadata")) {
        size_t eq = md.find('=');
        if (eq == std::string::npos) { a.reportError(1, "Invalid value for argument 'metadata'. <KEY>=<VALUE> expected"); return 1; }
        ds->metadata.set("", md.substr(0, eq), md.substr(eq + 1));
    }
    if (nb >= 3 && dt == DataType::Byte) { ds->bands[0]->colorInterp = "Red"; ds->bands[1]->colorInterp = "Green"; ds->bands[2]->colorInterp = "Blue"; if (nb == 4) ds->bands[3]->colorInterp = "Alpha"; }
    else if (nb >= 1) ds->bands[0]->colorInterp = "Gray";
    bool progress = !a.getBool("quiet");
    if (!writeRasterOutput(a, *ds, out, a.getString("output-format"), a.getStringList("creation-option"), progress)) return 1;
    return 0;
}

void registerRasterConvertCommands(Algorithm* root) {
    Algorithm* r = root->findSub("raster");
    if (!r) return;
    if (Algorithm* c = r->findSub("convert")) c->runFn = runRasterConvert;
    if (Algorithm* c = r->findSub("create")) c->runFn = runRasterCreate;
}
