#include "pipeline.h"
#include "util.h"
#include "generated_data.h"
#include "drivers.h"
#include <cstdio>
#include <map>
#include <set>

static std::map<std::string, StepFn>& rasterSteps() { static std::map<std::string, StepFn> m; return m; }
static std::map<std::string, StepFn>& vectorSteps() { static std::map<std::string, StepFn> m; return m; }
void registerRasterStep(const std::string& name, StepFn fn) { rasterSteps()[name] = fn; }
void registerVectorStep(const std::string& name, StepFn fn) { vectorSteps()[name] = fn; }
StepFn findRasterStep(const std::string& name) { auto it = rasterSteps().find(name); return it == rasterSteps().end() ? nullptr : it->second; }
StepFn findVectorStep(const std::string& name) { auto it = vectorSteps().find(name); return it == vectorSteps().end() ? nullptr : it->second; }

static const JsonValue* findStepJson(bool raster, const std::string& stepName) {
    Algorithm* root = getRootAlgorithm();
    Algorithm* parent = root->findSub(raster ? "raster" : "vector");
    Algorithm* pipe = parent ? parent->findSub("pipeline") : nullptr;
    if (!pipe) return nullptr;
    const JsonValue& pa = pipe->rawJson.get("pipeline_algorithms");
    for (auto& s : pa.items()) if (s.getString("name") == stepName) return &s;
    return nullptr;
}

std::vector<std::string> stepNames(bool raster) {
    std::vector<std::string> r;
    Algorithm* root = getRootAlgorithm();
    Algorithm* parent = root->findSub(raster ? "raster" : "vector");
    Algorithm* pipe = parent ? parent->findSub("pipeline") : nullptr;
    if (!pipe) return r;
    for (auto& s : pipe->rawJson.get("pipeline_algorithms").items()) r.push_back(s.getString("name"));
    return r;
}

std::unique_ptr<Algorithm> makeStepAlgorithm(bool raster, const std::string& stepName) {
    const JsonValue* j = findStepJson(raster, stepName);
    if (!j) return nullptr;
    auto a = std::make_unique<Algorithm>();
    a->loadFromJson(*j, {"gdal", raster ? "raster" : "vector", "pipeline"});
    a->path = {"gdal", raster ? "raster" : "vector", "pipeline", stepName};
    std::string key = std::string(raster ? "raster" : "vector") + " pipeline /" + stepName;
    for (const gen::ArgFlagsEntry* e = gen::kArgFlags; e->path; e++) {
        if (key != e->path) continue;
        ArgDef* d = a->findArg(e->name);
        if (!d) continue;
        d->shortFlags = splitString(e->shorts, ',');
        d->longFlags = splitString(e->longs, ',');
        d->positional = e->positional;
        d->helpMetavar = e->metavar;
    }
    for (auto& d : a->args) if (d.longFlags.empty() && !d.isOutput) { d.longFlags.push_back(d.name); d.hidden = true; }
    for (const gen::HelpEntry* h = gen::kHelpTexts; h->path; h++) if (key == h->path) { a->helpText = h->text; break; }
    return a;
}

// ---------------------------------------------------------------------------
std::shared_ptr<RasterDataset> cloneRasterHeader(const RasterDataset& src) {
    auto ds = std::make_shared<RasterDataset>();
    ds->driverShort = "MEM"; ds->driverLong = "In Memory raster, vector and multidimensional raster";
    ds->description = src.description;
    ds->xsize = src.xsize; ds->ysize = src.ysize;
    ds->hasGeoTransform = src.hasGeoTransform; memcpy(ds->gt, src.gt, sizeof(ds->gt));
    ds->hasCRS = src.hasCRS; ds->crs = src.crs;
    ds->metadata = src.metadata;
    ds->gcps = src.gcps; ds->hasGcpCRS = src.hasGcpCRS; ds->gcpCRS = src.gcpCRS;
    return ds;
}

std::shared_ptr<MemBand> copyBandToMem(RasterBand& b, std::string& err, int xsize, int ysize) {
    auto mb = std::make_shared<MemBand>();
    mb->number = b.number; mb->type = b.type; mb->xsize = xsize; mb->ysize = ysize;
    mb->blockX = xsize; mb->blockY = 1;
    mb->colorInterp = b.colorInterp; mb->hasNoData = b.hasNoData; mb->noData = b.noData;
    mb->noDataIsInt64 = b.noDataIsInt64; mb->noDataInt64 = b.noDataInt64; mb->noDataIsUInt64 = b.noDataIsUInt64; mb->noDataUInt64 = b.noDataUInt64;
    mb->description = b.description; mb->metadata = b.metadata; mb->colorTable = b.colorTable; mb->hasColorTable = b.hasColorTable;
    mb->unitType = b.unitType; mb->hasOffset = b.hasOffset; mb->hasScale = b.hasScale; mb->offset = b.offset; mb->scale = b.scale;
    mb->nbits = b.nbits; mb->maskFlags = b.maskFlags;
    if (!b.readWindowRaw(0, 0, b.xsize, b.ysize, mb->data, err)) return nullptr;
    return mb;
}

std::shared_ptr<RasterDataset> materializeRaster(RasterDataset& src, std::string& err) {
    auto ds = cloneRasterHeader(src);
    for (auto& b : src.bands) {
        auto mb = copyBandToMem(*b, err, src.xsize, src.ysize);
        if (!mb) return nullptr;
        mb->dataset = ds.get();
        ds->bands.push_back(mb);
    }
    return ds;
}

bool openInputRaster(Algorithm& a, PipelineData& data) {
    std::vector<std::string> inputs = a.getStringList("input");
    if (inputs.empty()) { a.reportError(1, "Required argument 'input' has not been specified."); return false; }
    data.rasterInputs.clear();
    for (auto& in : inputs) {
        std::string err; int code = 0;
        auto ds = openRaster(in, err, code, a.getStringList("input-format"), a.getStringList("open-option"));
        if (!ds) { cplError(code, err); return false; }
        data.rasterInputs.push_back(ds);
    }
    data.raster = data.rasterInputs[0];
    return true;
}

bool openInputVector(Algorithm& a, PipelineData& data) {
    std::vector<std::string> inputs = a.getStringList("input");
    if (inputs.empty()) { a.reportError(1, "Required argument 'input' has not been specified."); return false; }
    std::string err; int code = 0;
    auto ds = openVector(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
    if (!ds) { cplError(code, err); return false; }
    std::vector<std::string> sel = a.getStringList("input-layer");
    if (!sel.empty()) {
        std::vector<std::shared_ptr<Layer>> layers;
        for (auto& n : sel) {
            auto l = ds->layerByName(n);
            if (!l) { a.reportError(1, "Couldn't fetch requested layer '" + n + "'!"); return false; }
            layers.push_back(l);
        }
        ds->layers = layers;
    }
    data.vector = ds;
    return true;
}

bool writeRasterOutput(Algorithm& a, RasterDataset& ds, const std::string& out, const std::string& fmt, const std::vector<std::string>& co, bool progress);
bool checkOutputExists(Algorithm& a, const std::string& out);
bool writeVectorOutput(Algorithm& a, VectorDataset& ds, const std::vector<std::shared_ptr<Layer>>& layers, const std::string& out, const std::string& fmt, const std::vector<std::string>& lco, bool progress, const std::string& outLayerName);

bool writeOutputRaster(Algorithm& a, PipelineData& data) {
    std::string out = a.getString("output");
    if (out.empty()) { a.reportError(1, "Required argument 'output' has not been specified."); return false; }
    if (!data.raster) { a.reportError(1, "No input dataset"); return false; }
    bool progress = !data.quiet && !a.getBool("quiet");
    if (!writeRasterOutput(a, *data.raster, out, a.getString("output-format"), a.getStringList("creation-option"), progress)) return false;
    data.outputWritten = true;
    return true;
}

bool writeOutputVector(Algorithm& a, PipelineData& data) {
    std::string out = a.getString("output");
    if (out.empty()) { a.reportError(1, "Required argument 'output' has not been specified."); return false; }
    if (!data.vector) { a.reportError(1, "No input dataset"); return false; }
    bool progress = !data.quiet && !a.getBool("quiet");
    if (fileExists(out) && a.getBool("overwrite")) {
        std::string drv = identifyDriver(out);
        if (drv == "ESRI Shapefile" && !isDirectory(out)) {
            std::string base = stripExtension(out);
            for (const char* e : {".shp", ".shx", ".dbf", ".prj", ".cpg", ".qix"}) unlink((base + e).c_str());
        } else if (!isDirectory(out)) unlink(out.c_str());
    }
    if (!writeVectorOutput(a, *data.vector, data.vector->layers, out, a.getString("output-format"), a.getStringList("layer-creation-option"), progress, a.getString("output-layer"))) return false;
    data.outputWritten = true;
    return true;
}

static bool outputPreCheck(Algorithm& a) {
    std::string out = a.getString("output");
    if (out.empty()) return true;
    const ArgDef* d = a.findArg("output");
    if (!d || !d->isInputOutput) return true;
    if (fileExists(out) && !a.getBool("overwrite") && !a.getBool("append") && !a.getBool("update") && !a.getBool("overwrite-layer") && !a.getBool("upsert")) {
        a.reportError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite/--append option.");
        return false;
    }
    return true;
}

int runRasterStandalone(Algorithm& a, const std::string& stepName) {
    if (!outputPreCheck(a)) { a.printUsageOnError(); return 1; }
    PipelineData data;
    data.quiet = a.getBool("quiet");
    if (!openInputRaster(a, data)) { a.printUsageOnError(); return 1; }
    StepFn fn = findRasterStep(stepName);
    if (!fn) { a.reportError(1, "Step '" + stepName + "' is not implemented in this build."); return 1; }
    if (!fn(a, data)) return 1;
    if (a.findArg("output") && !data.outputWritten) { if (!writeOutputRaster(a, data)) return 1; }
    return 0;
}

int runVectorStandalone(Algorithm& a, const std::string& stepName) {
    if (!outputPreCheck(a)) { a.printUsageOnError(); return 1; }
    PipelineData data;
    data.quiet = a.getBool("quiet");
    if (!openInputVector(a, data)) { a.printUsageOnError(); return 1; }
    StepFn fn = findVectorStep(stepName);
    if (!fn) { a.reportError(1, "Step '" + stepName + "' is not implemented in this build."); return 1; }
    if (!fn(a, data)) return 1;
    if (a.findArg("output") && !data.outputWritten) { if (!writeOutputVector(a, data)) return 1; }
    return 0;
}

// ---------------------------------------------------------------------------
// Pipeline parsing & execution
static std::vector<std::string> tokenizeQuoted(const std::string& s) {
    std::vector<std::string> out;
    std::string cur;
    bool inTok = false;
    char q = 0;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (q) { if (c == q) q = 0; else cur += c; continue; }
        if (c == '"' || c == '\'') { q = c; inTok = true; continue; }
        if (isspace((unsigned char)c)) { if (inTok) { out.push_back(cur); cur.clear(); inTok = false; } continue; }
        cur += c; inTok = true;
    }
    if (inTok) out.push_back(cur);
    return out;
}

static int runPipeline(Algorithm& pipeAlg, bool raster, const std::vector<std::string>& rawTokens) {
    std::vector<std::string> tokens;
    // Pipeline-level options
    bool quiet = false;
    std::vector<std::string> work = rawTokens;
    // Expand a single token containing '!' into multiple tokens
    bool anyBang = false;
    for (auto& t : work) if (t == "!" || t == "|") anyBang = true;
    if (!anyBang) {
        std::vector<std::string> expanded;
        for (auto& t : work) {
            if (t.find('!') != std::string::npos || t.find(' ') != std::string::npos) { auto sub = tokenizeQuoted(t); expanded.insert(expanded.end(), sub.begin(), sub.end()); }
            else expanded.push_back(t);
        }
        work = expanded;
    }
    for (size_t i = 0; i < work.size(); i++) {
        const std::string& t = work[i];
        if (t == "--quiet" || t == "-q") { quiet = true; continue; }
        if (t == "--progress") continue;
        if (t == "--help" || t == "-h" || t == "help") { fputs(pipeAlg.fullHelp().c_str(), stdout); return 0; }
        if (t == "--json-usage") { fputs(pipeAlg.jsonUsage().c_str(), stdout); return 0; }
        tokens.push_back(t);
    }
    // Split steps
    std::vector<std::vector<std::string>> steps;
    std::vector<std::string> cur;
    for (auto& t : tokens) {
        if (t == "!" || t == "|") { if (!cur.empty()) steps.push_back(cur); cur.clear(); continue; }
        cur.push_back(t);
    }
    if (!cur.empty()) steps.push_back(cur);
    if (steps.empty()) {
        pipeAlg.reportError(1, "pipeline: at least one step must be provided");
        pipeAlg.printUsageOnError();
        return 1;
    }
    std::vector<std::string> names = stepNames(raster);
    std::set<std::string> nameSet(names.begin(), names.end());
    for (auto& s : steps) {
        if (!nameSet.count(s[0])) {
            pipeAlg.reportError(1, "unknown step name: " + s[0]);
            pipeAlg.printUsageOnError();
            return 1;
        }
    }
    std::set<std::string> firstSteps = raster ? std::set<std::string>{"read", "mosaic", "stack", "calc", "create"} : std::set<std::string>{"read", "concat", "sql"};
    std::set<std::string> lastSteps = raster ? std::set<std::string>{"write", "info", "compare", "tile"} : std::set<std::string>{"write", "info"};
    if (!firstSteps.count(steps[0][0])) {
        pipeAlg.reportError(1, raster ? "First step should be 'read', 'mosaic', 'stack' or 'calc'" : "First step should be 'read'");
        pipeAlg.printUsageOnError();
        return 1;
    }
    for (size_t i = 1; i < steps.size(); i++) {
        if (firstSteps.count(steps[i][0]) && steps[i][0] == "read") { pipeAlg.reportError(1, "Only first step can be 'read'"); pipeAlg.printUsageOnError(); return 1; }
    }
    if (!lastSteps.count(steps.back()[0])) {
        pipeAlg.reportError(1, raster ? "Last step should be 'write', 'info', 'compare' or 'tile'" : "Last step should be 'write' or 'info'");
        pipeAlg.printUsageOnError();
        return 1;
    }
    for (size_t i = 0; i + 1 < steps.size(); i++) {
        if (lastSteps.count(steps[i][0]) && steps[i][0] != "info") { pipeAlg.reportError(1, "Only last step can be '" + steps[i][0] + "'"); pipeAlg.printUsageOnError(); return 1; }
    }
    // Build and parse step algorithms
    std::vector<std::unique_ptr<Algorithm>> algs;
    for (auto& s : steps) {
        auto a = makeStepAlgorithm(raster, s[0]);
        if (!a) { pipeAlg.reportError(1, "unknown step name: " + s[0]); return 1; }
        std::vector<std::string> rest(s.begin() + 1, s.end());
        if (!a->parse(rest)) { a->printUsageOnError(); return 1; }
        if (a->helpRequested) { fputs(a->fullHelp().c_str(), stdout); return 0; }
        algs.push_back(std::move(a));
    }
    // Pre-check output existence of write step
    for (auto& a : algs) if (a->name == "write") { if (!outputPreCheck(*a)) { a->printUsageOnError(); return 1; } }
    PipelineData data;
    data.quiet = quiet;
    for (auto& a : algs) {
        StepFn fn = raster ? findRasterStep(a->name) : findVectorStep(a->name);
        if (!fn) { a->reportError(1, "Step '" + a->name + "' is not implemented in this build."); return 1; }
        if (!fn(*a, data)) return 1;
    }
    return 0;
}

static int runRasterPipeline(Algorithm& a) { return runPipeline(a, true, a.pipelineTokens); }
static int runVectorPipeline(Algorithm& a) { return runPipeline(a, false, a.pipelineTokens); }

static int runGenericPipeline(Algorithm& a) {
    // Determine raster vs vector from the read input
    const std::vector<std::string>& toks = a.pipelineTokens;
    std::string input;
    for (size_t i = 0; i < toks.size(); i++) {
        if (toks[i] == "read" || toks[i] == "!" || toks[i] == "--progress" || toks[i] == "-q" || toks[i] == "--quiet") continue;
        if (toks[i] == "--input" || toks[i] == "-i") { if (i + 1 < toks.size()) input = toks[i + 1]; break; }
        if (!toks[i].empty() && toks[i][0] != '-') { input = toks[i]; break; }
    }
    bool isR = false, isV = false;
    if (!input.empty()) identifyDriver(input, &isR, &isV);
    if (!isR && !isV) {
        if (input.empty()) a.reportError(1, "Unable to determine the type of the input dataset");
        else if (!fileExists(input)) cplError(4, input + ": No such file or directory");
        else cplError(4, "`" + input + "' not recognized as being in a supported file format.");
        a.printUsageOnError();
        return 1;
    }
    Algorithm* root = getRootAlgorithm();
    Algorithm* p = root->findSub(isR ? "raster" : "vector")->findSub("pipeline");
    return runPipeline(*p, isR, toks);
}

void registerPipelineCommands(Algorithm* root) {
    registerRasterSteps();
    registerVectorSteps();
    if (Algorithm* r = root->findSub("raster")) if (Algorithm* p = r->findSub("pipeline")) { p->runFn = runRasterPipeline; p->rawTokenMode = true; }
    if (Algorithm* v = root->findSub("vector")) if (Algorithm* p = v->findSub("pipeline")) { p->runFn = runVectorPipeline; p->rawTokenMode = true; }
    if (Algorithm* p = root->findSub("pipeline")) { p->runFn = runGenericPipeline; p->rawTokenMode = true; }
    // Standalone commands using steps
    if (Algorithm* r = root->findSub("raster")) {
        for (auto& n : stepNames(true)) {
            if (n == "read" || n == "write" || n == "info" || n == "create" || n == "tee" || n == "external" || n == "materialize") continue;
            Algorithm* c = r->findSub(n);
            if (c && !c->runFn) { std::string nn = n; c->runFn = [nn](Algorithm& a) { return runRasterStandalone(a, nn); }; }
        }
    }
    if (Algorithm* v = root->findSub("vector")) {
        for (auto& n : stepNames(false)) {
            if (n == "read" || n == "write" || n == "info") continue;
            Algorithm* c = v->findSub(n);
            if (c && !c->runFn) { std::string nn = n; c->runFn = [nn](Algorithm& a) { return runVectorStandalone(a, nn); }; }
        }
    }
}
