        if (py0 > py1) std::swap(py0, py1);
        int ix0 = std::max(0, (int)std::floor(px0 + 1e-8)), iy0 = std::max(0, (int)std::floor(py0 + 1e-8));
        int ix1 = std::min(src.xsize, (int)std::ceil(px1 - 1e-8)), iy1 = std::min(src.ysize, (int)std::ceil(py1 - 1e-8));
        x0 = ix0; y0 = iy0; w = ix1 - ix0; h = iy1 - iy0;
