    if (a.isSet("nodata")) {
        std::string s = a.getString("nodata");
        for (auto& b : out->bands) {
            if (iequals(s, "none")) b->hasNoData = false;
            else { b->hasNoData = true; b->noData = iequals(s, "nan") ? NAN : (iequals(s, "inf") ? INFINITY : (iequals(s, "-inf") ? -INFINITY : strtod(s.c_str(), nullptr))); }
        }
    }
    d.raster = out;
    return true;
}

static bool stepScale(Algorithm& a, PipelineData& d) {
    RasterDataset& src = *d.raster;
    auto out = cloneRasterHeader(src);
    DataType dt = DataType::Unknown;
    if (a.isSet("output-data-type")) dt = dataTypeFromName(a.getString("output-data-type"));
    int band = a.isSet("band") ? (int)a.getInt("band") : 0;
    bool noClip = a.getBool("no-clip");
    double exponent = a.isSet("exponent") ? a.getReal("exponent") : 1.0;
    std::string err;
    for (auto& b : src.bands) {
        std::vector<double> vals;
        if (!b->readAsDouble(vals, err)) { a.reportError(1, err); return false; }
        DataType odt = dt == DataType::Unknown ? b->type : dt;
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = odt; mb->xsize = src.xsize; mb->ysize = src.ysize; mb->blockX = src.xsize; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->hasNoData = b->hasNoData; mb->noData = b->noData; mb->description = b->description;
        bool apply = band == 0 || band == b->number;
        if (apply) {
            double smin, smax;
            if (a.isSet("src-min") && a.isSet("src-max")) { smin = a.getReal("src-min"); smax = a.getReal("src-max"); }
            else {
                smin = 1e300; smax = -1e300;
                for (double v : vals) { if (b->hasNoData && v == b->noData) continue; if (std::isnan(v)) continue; smin = std::min(smin, v); smax = std::max(smax, v); }
                if (smin > smax) { smin = 0; smax = 0; }
            }
            double dmin, dmax;
            if (a.isSet("dst-min") && a.isSet("dst-max")) { dmin = a.getReal("dst-min"); dmax = a.getReal("dst-max"); }
            else {
                switch (odt) {
                    case DataType::Byte: dmin = 0; dmax = 255; break;
                    case DataType::Int8: dmin = -128; dmax = 127; break;
                    case DataType::UInt16: dmin = 0; dmax = 65535; break;
                    case DataType::Int16: dmin = -32768; dmax = 32767; break;
                    case DataType::UInt32: dmin = 0; dmax = 4294967295.0; break;
                    case DataType::Int32: dmin = -2147483648.0; dmax = 2147483647.0; break;
                    default: dmin = 0; dmax = 255;
                }
            }
            double scale = (smax == smin) ? 0 : (dmax - dmin) / (smax - smin);
            for (auto& v : vals) {
                if (b->hasNoData && v == b->noData) continue;
                double nv;
                if (exponent != 1.0) {
                    double t = smax == smin ? 0 : (v - smin) / (smax - smin);
                    if (t < 0) t = 0; if (t > 1) t = 1;
                    nv = dmin + pow(t, exponent) * (dmax - dmin);
