                if (!noClip) { if (nv < std::min(dmin, dmax)) nv = std::min(dmin, dmax); if (nv > std::max(dmin, dmax)) nv = std::max(dmin, dmax); }
                v = nv;
            }
        }
        int sz = dataTypeSizeBytes(odt);
        mb->data.assign(vals.size() * sz, 0);
        for (size_t i = 0; i < vals.size(); i++) doubleToSample(vals[i], mb->data.data() + i * sz, odt);
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

static bool stepResize(Algorithm& a, PipelineData& d) {
    RasterDataset& src = *d.raster;
    std::vector<std::string> size = a.getStringList("size");
    if (size.size() != 2) { a.reportError(5, "Invalid size"); return false; }
    auto parseDim = [&](const std::string& s, int full) -> int {
        if (!s.empty() && s.back() == '%') return (int)std::round(full * atof(s.c_str()) / 100.0);
        return atoi(s.c_str());
    };
    int W = parseDim(size[0], src.xsize), H = parseDim(size[1], src.ysize);
    if (W == 0 && H == 0) { a.reportError(5, "Invalid size"); return false; }
    if (W == 0) W = (int)std::round((double)H * src.xsize / src.ysize);
    if (H == 0) H = (int)std::round((double)W * src.ysize / src.xsize);
    std::string resampling = a.getString("resampling", "nearest");
    auto out = cloneRasterHeader(src);
    out->xsize = W; out->ysize = H;
    if (src.hasGeoTransform) {
        out->gt[1] = src.gt[1] * src.xsize / W; out->gt[2] = src.gt[2] * src.ysize / H;
        out->gt[4] = src.gt[4] * src.xsize / W; out->gt[5] = src.gt[5] * src.ysize / H;
    }
    std::string err;
    for (auto& b : src.bands) {
        std::vector<double> vals;
        if (!b->readAsDouble(vals, err)) { a.reportError(1, err); return false; }
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = b->type; mb->xsize = W; mb->ysize = H; mb->blockX = W; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->hasNoData = b->hasNoData; mb->noData = b->noData; mb->description = b->description;
        mb->colorTable = b->colorTable; mb->hasColorTable = b->hasColorTable;
        int sz = dataTypeSizeBytes(b->type);
        mb->data.assign((size_t)W * H * sz, 0);
        double sx = (double)src.xsize / W, sy = (double)src.ysize / H;
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                double v;
                if (iequals(resampling, "nearest") || true) {
                    int srcx = std::min(src.xsize - 1, (int)((x + 0.5) * sx));
                    int srcy = std::min(src.ysize - 1, (int)((y + 0.5) * sy));
                    v = vals[(size_t)srcy * src.xsize + srcx];
                }
                doubleToSample(v, mb->data.data() + ((size_t)y * W + x) * sz, b->type);
            }
        }
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

void registerRasterSteps() {
    registerRasterStep("read", stepRead);
    registerRasterStep("write", stepWrite);
    registerRasterStep("info", stepInfo);
    registerRasterStep("select", stepSelect);
    registerRasterStep("set-type", stepSetType);
    registerRasterStep("clip", stepClip);
    registerRasterStep("edit", stepEdit);
    registerRasterStep("scale", stepScale);
    registerRasterStep("resize", stepResize);
}
