    auto out = cloneDataset(*d.vector);
    std::string where = a.getString("where");
    if (!where.empty() && where[0] == '@') { std::string c; if (readFile(where.substr(1), c)) where = trimString(c); }
    std::vector<double> bbox = a.getRealList("bbox");
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        std::vector<Feature> kept;
        for (auto& f : l.features) {
            bool ok = true;
            if (!where.empty()) { bool e = false; ok = evalWhere(l, f, where, e); if (e) { a.reportError(1, "Failed to evaluate WHERE expression"); return false; } }
            if (ok && bbox.size() == 4) {
                if (f.geoms.empty() || !f.geoms[0] || f.geoms[0]->isEmpty()) ok = false;
                else { Envelope e = f.geoms[0]->envelope(); ok = !(e.maxx < bbox[0] || e.minx > bbox[2] || e.maxy < bbox[1] || e.miny > bbox[3]); }
            }
            if (ok) kept.push_back(f);
        }
        l.features = kept;
    }
    d.vector = out;
    return true;
}

static void swapXY(Geometry& g) {
    for (auto& c : g.points) std::swap(c.x, c.y);
    for (auto& r : g.rings) for (auto& c : r) std::swap(c.x, c.y);
    for (auto& p : g.parts) swapXY(*p);
}

static bool stepSwapXY(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    for (auto& lp : out->layers) {
        if (!layerActive(a, *lp)) continue;
        for (auto& f : lp->features) for (auto& g : f.geoms) if (g) { auto ng = std::make_shared<Geometry>(*g); swapXY(*ng); g = ng; }
    }
    d.vector = out;
    return true;
}

static std::shared_ptr<Geometry> deepCopy(const Geometry& g) {
    auto n = std::make_shared<Geometry>(g);
    n->parts.clear();
    for (auto& p : g.parts) n->parts.push_back(deepCopy(*p));
    return n;
}

static bool stepExplode(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        std::vector<Feature> nf;
        long long fid = 0;
        for (auto& f : l.features) {
            std::shared_ptr<Geometry> g = f.geoms.empty() ? nullptr : f.geoms[0];
            if (g && (g->type == GeomType::MultiPoint || g->type == GeomType::MultiLineString || g->type == GeomType::MultiPolygon || g->type == GeomType::GeometryCollection) && !g->parts.empty()) {
                for (auto& p : g->parts) { Feature c = f; c.fid = fid++; c.geoms[0] = deepCopy(*p); nf.push_back(c); }
            } else { Feature c = f; c.fid = fid++; nf.push_back(c); }
        }
        l.features = nf;
        for (auto& gf : l.geomFields) {
            if (gf.type == GeomType::MultiPoint) gf.type = GeomType::Point;
            else if (gf.type == GeomType::MultiLineString) gf.type = GeomType::LineString;
            else if (gf.type == GeomType::MultiPolygon) gf.type = GeomType::Polygon;
            else if (gf.type == GeomType::GeometryCollection) gf.type = GeomType::Unknown;
        }
    }
    d.vector = out;
    return true;
}

static bool stepReproject(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    CRS dst;
    if (!dst.setFromUserInput(a.getString("dst-crs"))) { a.reportError(5, "Invalid value for 'dst-crs' argument"); return false; }
    CRS srcOverride;
    bool hasSrcOverride = false;
    if (a.isSet("src-crs")) { if (!srcOverride.setFromUserInput(a.getString("src-crs"))) { a.reportError(5, "Invalid value for 'src-crs' argument"); return false; } hasSrcOverride = true; }
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        for (size_t gi = 0; gi < l.geomFields.size(); gi++) {
            GeomFieldDef& gf = l.geomFields[gi];
            CRS src = hasSrcOverride ? srcOverride : gf.crs;
            if (!hasSrcOverride && !gf.hasCRS) { a.reportError(1, "Layer '" + l.name + "' has no spatial reference system, and --src-crs has not been specified"); return false; }
            CoordTransform ct;
            if (!ct.init(src, dst)) { a.reportError(1, "Cannot create coordinate transformation"); return false; }
            std::function<void(Geometry&)> tr = [&](Geometry& g) {
                for (auto& c : g.points) ct.transform(c.x, c.y, c.z);
                for (auto& r : g.rings) for (auto& c : r) ct.transform(c.x, c.y, c.z);
                for (auto& p : g.parts) tr(*p);
            };
            for (auto& f : l.features) if (gi < f.geoms.size() && f.geoms[gi]) { auto ng = deepCopy(*f.geoms[gi]); tr(*ng); f.geoms[gi] = ng; }
            gf.hasCRS = true; gf.crs = dst;
        }
    }
    d.vector = out;
    return true;
}

static bool stepSetGeomType(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::string gt = a.getString("geometry-type");
    bool multi = a.getBool("multi"), single = a.getBool("single");
    std::string dim = a.getString("dim");
    bool skip = a.getBool("skip");
    bool layerOnly = a.getBool("layer-only"), featureOnly = a.getBool("feature-geometry-only");
    GeomType target = GeomType::Unknown; bool tz = false, tm = false; bool hasTarget = false;
    if (!gt.empty()) {
        std::string u = toUpper(gt);
        bool z = false, m = false;
        if (endsWith(u, "ZM")) { z = m = true; u = u.substr(0, u.size() - 2); }
        else if (endsWith(u, "Z")) { z = true; u = u.substr(0, u.size() - 1); }
        else if (endsWith(u, "M")) { m = true; u = u.substr(0, u.size() - 1); }
        u = trimString(u);
        if (u == "POINT") target = GeomType::Point; else if (u == "LINESTRING") target = GeomType::LineString; else if (u == "POLYGON") target = GeomType::Polygon;
        else if (u == "MULTIPOINT") target = GeomType::MultiPoint; else if (u == "MULTILINESTRING") target = GeomType::MultiLineString; else if (u == "MULTIPOLYGON") target = GeomType::MultiPolygon;
        else if (u == "GEOMETRYCOLLECTION") target = GeomType::GeometryCollection; else if (u == "GEOMETRY") target = GeomType::Unknown; else if (u == "NONE") target = GeomType::None;
        else { a.reportError(5, "Invalid geometry type '" + gt + "'"); return false; }
        tz = z; tm = m; hasTarget = true;
    }
    auto convert = [&](std::shared_ptr<Geometry> g) -> std::shared_ptr<Geometry> {
        if (!g) return g;
        auto n = deepCopy(*g);
        GeomType tt = n->type; bool z = n->hasZ, m = n->hasM;
        if (hasTarget) { tt = target; z = tz; m = tm; }
        if (multi) { if (tt == GeomType::Point) tt = GeomType::MultiPoint; else if (tt == GeomType::LineString) tt = GeomType::MultiLineString; else if (tt == GeomType::Polygon) tt = GeomType::MultiPolygon; }
        if (single) { if (tt == GeomType::MultiPoint) tt = GeomType::Point; else if (tt == GeomType::MultiLineString) tt = GeomType::LineString; else if (tt == GeomType::MultiPolygon) tt = GeomType::Polygon; }
        if (!dim.empty()) { std::string du = toUpper(dim); z = du.find('Z') != std::string::npos; m = du.find('M') != std::string::npos; }
        if (tt != n->type && tt != GeomType::Unknown) {
            if ((tt == GeomType::MultiPoint && n->type == GeomType::Point) || (tt == GeomType::MultiLineString && n->type == GeomType::LineString) || (tt == GeomType::MultiPolygon && n->type == GeomType::Polygon)) {
                auto mg = std::make_shared<Geometry>(); mg->type = tt; mg->parts.push_back(n); n = mg;
            } else if ((tt == GeomType::Point && n->type == GeomType::MultiPoint) || (tt == GeomType::LineString && n->type == GeomType::MultiLineString) || (tt == GeomType::Polygon && n->type == GeomType::MultiPolygon)) {
                if (n->parts.size() == 1) n = n->parts[0];
                else if (skip) return nullptr;
            } else if (tt == GeomType::GeometryCollection) { auto mg = std::make_shared<Geometry>(); mg->type = tt; mg->parts.push_back(n); n = mg; }
            else if (skip) return nullptr;
        }
        n->setZM(z, m);
        return n;
    };
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        if (!featureOnly) for (auto& gf : l.geomFields) {
            GeomType tt = gf.type; bool z = gf.hasZ, m = gf.hasM;
            if (hasTarget) { tt = target; z = tz; m = tm; }
            if (multi) { if (tt == GeomType::Point) tt = GeomType::MultiPoint; else if (tt == GeomType::LineString) tt = GeomType::MultiLineString; else if (tt == GeomType::Polygon) tt = GeomType::MultiPolygon; }
            if (single) { if (tt == GeomType::MultiPoint) tt = GeomType::Point; else if (tt == GeomType::MultiLineString) tt = GeomType::LineString; else if (tt == GeomType::MultiPolygon) tt = GeomType::Polygon; }
            if (!dim.empty()) { std::string du = toUpper(dim); z = du.find('Z') != std::string::npos; m = du.find('M') != std::string::npos; }
            gf.type = tt; gf.hasZ = z; gf.hasM = m;
        }
        if (!layerOnly) {
            std::vector<Feature> kept;
            for (auto& f : l.features) {
                bool drop = false;
                for (auto& g : f.geoms) { if (!g) continue; auto ng = convert(g); if (!ng && skip) { drop = true; break; } g = ng; }
                if (!drop) kept.push_back(f);
            }
            l.features = kept;
        }
    }
    d.vector = out;
    return true;
}

static bool stepMakePoint(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::string xf = a.getString("x"), yf = a.getString("y"), zf = a.getString("z"), mf = a.getString("m");
    std::string crsStr = a.getString("crs");
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        int xi = l.findField(xf), yi = l.findField(yf), zi = zf.empty() ? -1 : l.findField(zf), mi = mf.empty() ? -1 : l.findField(mf);
        if (xi < 0) { a.reportError(1, "Field '" + xf + "' does not exist in layer '" + l.name + "'"); return false; }
        if (yi < 0) { a.reportError(1, "Field '" + yf + "' does not exist in layer '" + l.name + "'"); return false; }
        GeomFieldDef gf; gf.name = ""; gf.type = GeomType::Point; gf.hasZ = zi >= 0; gf.hasM = mi >= 0;
        if (!crsStr.empty()) { CRS c; if (c.setFromUserInput(crsStr)) { gf.hasCRS = true; gf.crs = c; } }
        l.geomFields.clear(); l.geomFields.push_back(gf);
        auto num = [&](const FieldValue& v, const FieldDef& fd) -> double {
            if (fd.type == FieldType::Integer || fd.type == FieldType::Integer64) return (double)v.i;
            if (fd.type == FieldType::Real) return v.d;
            return strtod(v.s.c_str(), nullptr);
        };
        for (auto& f : l.features) {
            f.geoms.clear();
            if (f.fields[xi].isNull() || f.fields[yi].isNull()) { f.geoms.push_back(nullptr); continue; }
            auto g = std::make_shared<Geometry>(); g->type = GeomType::Point; g->hasZ = zi >= 0; g->hasM = mi >= 0;
            Coord c; c.x = num(f.fields[xi], l.fields[xi]); c.y = num(f.fields[yi], l.fields[yi]);
            if (zi >= 0) c.z = num(f.fields[zi], l.fields[zi]);
            if (mi >= 0) c.m = num(f.fields[mi], l.fields[mi]);
            g->points.push_back(c);
            f.geoms.push_back(g);
        }
    }
    d.vector = out;
    return true;
}

static void segmentize(Geometry& g, double maxLen) {
    auto seg = [&](std::vector<Coord>& pts) {
        if (pts.size() < 2) return;
        std::vector<Coord> out;
        for (size_t i = 0; i + 1 < pts.size(); i++) {
            out.push_back(pts[i]);
            double dx = pts[i + 1].x - pts[i].x, dy = pts[i + 1].y - pts[i].y;
            double len = sqrt(dx * dx + dy * dy);
            int n = (int)std::ceil(len / maxLen);
            for (int k = 1; k < n; k++) { Coord c; double t = (double)k / n; c.x = pts[i].x + dx * t; c.y = pts[i].y + dy * t; c.z = pts[i].z + (pts[i + 1].z - pts[i].z) * t; c.m = pts[i].m + (pts[i + 1].m - pts[i].m) * t; out.push_back(c); }
        }
        out.push_back(pts.back());
        pts = out;
    };
    if (g.type == GeomType::LineString) seg(g.points);
    for (auto& r : g.rings) seg(r);
    for (auto& p : g.parts) segmentize(*p, maxLen);
}

static bool stepSegmentize(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    double maxLen = a.getReal("max-length");
    for (auto& lp : out->layers) {
        if (!layerActive(a, *lp)) continue;
        for (auto& f : lp->features) for (auto& g : f.geoms) if (g) { auto ng = deepCopy(*g); segmentize(*ng, maxLen); g = ng; }
    }
    d.vector = out;
    return true;
}

static bool stepEdit(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        if (a.isSet("crs")) {
            std::string c = a.getString("crs");
            for (auto& gf : l.geomFields) {
                if (iequals(c, "none") || iequals(c, "null")) gf.hasCRS = false;
                else { CRS crs; if (!crs.setFromUserInput(c)) { a.reportError(5, "Invalid value for 'crs' argument"); return false; } gf.hasCRS = true; gf.crs = crs; }
            }
        }
        for (auto& md : a.getStringList("layer-metadata")) { size_t eq = md.find('='); if (eq != std::string::npos) l.metadata.set("", md.substr(0, eq), md.substr(eq + 1)); }
        for (auto& k : a.getStringList("unset-layer-metadata")) { MetadataList* ml = l.metadata.domain("", false); if (ml) for (size_t i = 0; i < ml->size(); i++) if ((*ml)[i].first == k) { ml->erase(ml->begin() + i); break; } }
        if (a.isSet("geometry-type")) {
            std::string u = toUpper(a.getString("geometry-type"));
            GeomType t = GeomType::Unknown; bool z = false, m = false;
            if (endsWith(u, "ZM")) { z = m = true; u = u.substr(0, u.size() - 2); } else if (endsWith(u, "Z")) { z = true; u = u.substr(0, u.size() - 1); } else if (endsWith(u, "M")) { m = true; u = u.substr(0, u.size() - 1); }
            if (u == "POINT") t = GeomType::Point; else if (u == "LINESTRING") t = GeomType::LineString; else if (u == "POLYGON") t = GeomType::Polygon; else if (u == "MULTIPOINT") t = GeomType::MultiPoint; else if (u == "MULTILINESTRING") t = GeomType::MultiLineString; else if (u == "MULTIPOLYGON") t = GeomType::MultiPolygon; else if (u == "GEOMETRYCOLLECTION") t = GeomType::GeometryCollection; else if (u == "NONE") t = GeomType::None;
            for (auto& gf : l.geomFields) { gf.type = t; gf.hasZ = z; gf.hasM = m; }
        }
    }
    for (auto& md : a.getStringList("metadata")) { size_t eq = md.find('='); if (eq != std::string::npos) out->metadata.set("", md.substr(0, eq), md.substr(eq + 1)); }
    for (auto& k : a.getStringList("unset-metadata")) { MetadataList* ml = out->metadata.domain("", false); if (ml) for (size_t i = 0; i < ml->size(); i++) if ((*ml)[i].first == k) { ml->erase(ml->begin() + i); break; } }
    d.vector = out;
    return true;
}

void registerVectorSteps() {
    registerVectorStep("read", stepRead);
    registerVectorStep("write", stepWrite);
    registerVectorStep("info", stepInfo);
    registerVectorStep("select", stepSelect);
    registerVectorStep("filter", stepFilter);
    registerVectorStep("swap-xy", stepSwapXY);
    registerVectorStep("explode-collections", stepExplode);
    registerVectorStep("reproject", stepReproject);
    registerVectorStep("set-geom-type", stepSetGeomType);
    registerVectorStep("make-point", stepMakePoint);
    registerVectorStep("segmentize", stepSegmentize);
    registerVectorStep("edit", stepEdit);
}
