#include "pipeline.h"
#include "util.h"
#include "raster_info.h"
#include <cstdio>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <set>

int rasterInfoOnDataset(Algorithm& a, std::shared_ptr<RasterDataset> ds);
std::shared_ptr<MemBand> copyBandToMem(RasterBand& b, std::string& err, int xsize, int ysize);

static bool stepRead(Algorithm& a, PipelineData& d) { return openInputRaster(a, d); }
static bool stepWrite(Algorithm& a, PipelineData& d) { return writeOutputRaster(a, d); }
static bool stepInfo(Algorithm& a, PipelineData& d) {
    if (!d.raster) { a.reportError(1, "No input dataset"); return false; }
    d.outputWritten = true;
    return rasterInfoOnDataset(a, d.raster) == 0;
}

static bool stepSelect(Algorithm& a, PipelineData& d) {
    std::vector<std::string> bands = a.getStringList("band");
    bool exclude = a.getBool("exclude");
    RasterDataset& src = *d.raster;
    std::vector<int> idx;
    std::vector<bool> isMask;
    for (auto& b : bands) {
        if (iequals(b, "mask")) { idx.push_back(-1); isMask.push_back(true); continue; }
        if (!isdigit((unsigned char)b[0])) { a.reportError(5, "Invalid band specification."); return false; }
        int n = atoi(b.c_str());
        if (n < 1 || n > (int)src.bands.size()) { a.reportError(5, strprintf("Invalid band specification: %d. Valid values are between 1 and %d", n, (int)src.bands.size())); return false; }
        idx.push_back(n - 1); isMask.push_back(false);
    }
    if (exclude) {
        std::set<int> ex(idx.begin(), idx.end());
        idx.clear();
        for (int i = 0; i < (int)src.bands.size(); i++) if (!ex.count(i)) idx.push_back(i);
    }
    auto out = cloneRasterHeader(src);
    std::string err;
    int n = 1;
    for (int i : idx) {
        if (i < 0) {
            auto mb = std::make_shared<MemBand>();
            mb->number = n++; mb->type = DataType::Byte; mb->xsize = src.xsize; mb->ysize = src.ysize; mb->blockX = src.xsize; mb->blockY = 1;
            mb->data.assign((size_t)src.xsize * src.ysize, 255);
            mb->colorInterp = "Undefined";
            if (!src.bands.empty() && src.bands[0]->hasNoData) {
                std::vector<double> v;
                if (src.bands[0]->readAsDouble(v, err)) for (size_t k = 0; k < v.size(); k++) if (v[k] == src.bands[0]->noData || (std::isnan(src.bands[0]->noData) && std::isnan(v[k]))) mb->data[k] = 0;
            }
            mb->dataset = out.get();
            out->bands.push_back(mb);
            continue;
        }
        auto mb = copyBandToMem(*src.bands[i], err, src.xsize, src.ysize);
        if (!mb) { a.reportError(1, err); return false; }
        mb->number = n++;
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    if (a.isSet("mask")) {
        // not supported: ignore
    }
    out->metadata.domain("IMAGE_STRUCTURE", false);
    d.raster = out;
    return true;
}

static bool stepSetType(Algorithm& a, PipelineData& d) {
    std::string t = a.getString("output-data-type");
    DataType dt = dataTypeFromName(t);
    if (dt == DataType::Unknown) { a.reportError(5, "Invalid value for 'output-data-type'"); return false; }
    RasterDataset& src = *d.raster;
    auto out = cloneRasterHeader(src);
    std::string err;
    for (auto& b : src.bands) {
        std::vector<double> vals;
        if (!b->readAsDouble(vals, err)) { a.reportError(1, err); return false; }
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = dt; mb->xsize = src.xsize; mb->ysize = src.ysize; mb->blockX = src.xsize; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->description = b->description; mb->metadata = b->metadata; mb->unitType = b->unitType;
        mb->hasOffset = b->hasOffset; mb->hasScale = b->hasScale; mb->offset = b->offset; mb->scale = b->scale;
        mb->colorTable = b->colorTable; mb->hasColorTable = b->hasColorTable;
        int sz = dataTypeSizeBytes(dt);
        mb->data.assign(vals.size() * sz, 0);
        for (size_t i = 0; i < vals.size(); i++) doubleToSample(vals[i], mb->data.data() + i * sz, dt);
        if (b->hasNoData) {
            mb->hasNoData = true;
            // nodata converted to the new type
            std::vector<uint8_t> tmp(sz);
            doubleToSample(b->noData, tmp.data(), dt);
            mb->noData = std::isnan(b->noData) ? b->noData : sampleToDouble(tmp.data(), dt);
            if (std::isnan(b->noData) && !dataTypeIsFloating(dt)) mb->hasNoData = false;
        }
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

static bool stepClip(Algorithm& a, PipelineData& d) {
    RasterDataset& src = *d.raster;
    int x0 = 0, y0 = 0, w = src.xsize, h = src.ysize;
    if (a.isSet("window")) {
        auto win = a.getIntList("window");
        if (win.size() != 4) { a.reportError(5, "Invalid window"); return false; }
        x0 = (int)win[0]; y0 = (int)win[1]; w = (int)win[2]; h = (int)win[3];
        if (x0 < 0 || y0 < 0 || w <= 0 || h <= 0 || x0 + w > src.xsize || y0 + h > src.ysize) {
            a.reportError(5, "Window is out of raster bounds");
            return false;
        }
    } else if (a.isSet("bbox")) {
        auto bb = a.getRealList("bbox");
        if (bb.size() != 4) { a.reportError(5, "Invalid bbox"); return false; }
        if (!src.hasGeoTransform) { a.reportError(1, "Clipping with a bounding box requires a georeferenced dataset"); return false; }
        double xmin = bb[0], ymin = bb[1], xmax = bb[2], ymax = bb[3];
        if (a.isSet("bbox-crs") && src.hasCRS) {
            CRS bc;
            if (!bc.setFromUserInput(a.getString("bbox-crs"))) { a.reportError(5, "Invalid value for 'bbox-crs'"); return false; }
            CoordTransform ct;
            if (!ct.init(bc, src.crs)) { a.reportError(1, "Cannot create coordinate transformation"); return false; }
            double xs[4] = {xmin, xmin, xmax, xmax}, ys[4] = {ymin, ymax, ymin, ymax};
            double nxmin = 1e300, nymin = 1e300, nxmax = -1e300, nymax = -1e300;
            for (int i = 0; i < 4; i++) { double x = xs[i], y = ys[i]; if (!ct.transform(x, y)) { a.reportError(1, "Cannot transform bbox"); return false; } nxmin = std::min(nxmin, x); nxmax = std::max(nxmax, x); nymin = std::min(nymin, y); nymax = std::max(nymax, y); }
            xmin = nxmin; xmax = nxmax; ymin = nymin; ymax = nymax;
        }
        double px0, py0, px1, py1;
        src.geoToPixel(xmin, ymax, px0, py0);
        src.geoToPixel(xmax, ymin, px1, py1);
        if (px0 > px1) std::swap(px0, px1);
        if (py0 > py1) std::swap(py0, py1);
        const double eps = 1e-8;
        int ix0 = (int)std::floor(px0 + eps), iy0 = (int)std::floor(py0 + eps);
        int ix1 = (int)std::ceil(px1 - eps), iy1 = (int)std::ceil(py1 - eps);
        if (ix1 <= 0 || iy1 <= 0 || ix0 >= src.xsize || iy0 >= src.ysize) { a.reportError(1, "Clipping bounding box does not intersect raster extent"); return false; }
        ix0 = std::max(0, ix0); iy0 = std::max(0, iy0); ix1 = std::min(src.xsize, ix1); iy1 = std::min(src.ysize, iy1);
        x0 = ix0; y0 = iy0; w = ix1 - ix0; h = iy1 - iy0;
        if (w <= 0 || h <= 0) { a.reportError(1, "Clipping bounding box does not intersect raster extent"); return false; }
    } else if (a.isSet("like")) {
        std::string err; int code = 0;
        auto like = openRaster(a.getString("like"), err, code);
        if (!like) { cplError(code, err); return false; }
        if (!like->hasGeoTransform || !src.hasGeoTransform) { a.reportError(1, "Clipping with --like requires georeferenced datasets"); return false; }
        double lx0, ly0, lx1, ly1;
        like->pixelToGeo(0, 0, lx0, ly0); like->pixelToGeo(like->xsize, like->ysize, lx1, ly1);
        double px0, py0, px1, py1;
        src.geoToPixel(lx0, ly0, px0, py0); src.geoToPixel(lx1, ly1, px1, py1);
        if (px0 > px1) std::swap(px0, px1);
        if (py0 > py1) std::swap(py0, py1);
        int ix0 = std::max(0, (int)std::floor(px0 + 1e-8)), iy0 = std::max(0, (int)std::floor(py0 + 1e-8));
        int ix1 = std::min(src.xsize, (int)std::ceil(px1 - 1e-8)), iy1 = std::min(src.ysize, (int)std::ceil(py1 - 1e-8));
        x0 = ix0; y0 = iy0; w = ix1 - ix0; h = iy1 - iy0;
        if (w <= 0 || h <= 0) { a.reportError(1, "Clipping bounding box does not intersect raster extent"); return false; }
    } else {
        a.reportError(1, "Either --bbox, --like, --window or --geometry must be specified");
        return false;
    }
    auto out = cloneRasterHeader(src);
    out->xsize = w; out->ysize = h;
    if (src.hasGeoTransform) {
        out->gt[0] = src.gt[0] + x0 * src.gt[1] + y0 * src.gt[2];
        out->gt[3] = src.gt[3] + x0 * src.gt[4] + y0 * src.gt[5];
    }
    std::string err;
    for (auto& b : src.bands) {
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = b->type; mb->xsize = w; mb->ysize = h; mb->blockX = w; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->hasNoData = b->hasNoData; mb->noData = b->noData; mb->description = b->description; mb->metadata = b->metadata;
        mb->colorTable = b->colorTable; mb->hasColorTable = b->hasColorTable; mb->unitType = b->unitType; mb->hasOffset = b->hasOffset; mb->hasScale = b->hasScale; mb->offset = b->offset; mb->scale = b->scale;
        if (!b->readWindowRaw(x0, y0, w, h, mb->data, err)) { a.reportError(1, err); return false; }
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

static bool stepEdit(Algorithm& a, PipelineData& d) {
    std::string err;
    auto out = materializeRaster(*d.raster, err);
    if (!out) { a.reportError(1, err); return false; }
    if (a.isSet("crs")) {
        std::string c = a.getString("crs");
        if (iequals(c, "none") || iequals(c, "null")) out->hasCRS = false;
        else { CRS crs; if (!crs.setFromUserInput(c)) { a.reportError(5, "Invalid value for 'crs' argument"); return false; } out->hasCRS = true; out->crs = crs; }
    }
    if (a.isSet("bbox")) {
        auto bb = a.getRealList("bbox");
        if (bb.size() == 4) {
            out->hasGeoTransform = true;
            out->gt[0] = bb[0]; out->gt[1] = (bb[2] - bb[0]) / out->xsize; out->gt[2] = 0;
            out->gt[3] = bb[3]; out->gt[4] = 0; out->gt[5] = -(bb[3] - bb[1]) / out->ysize;
        }
    }
    for (auto& md : a.getStringList("metadata")) {
        size_t eq = md.find('=');
        if (eq == std::string::npos) { a.reportError(1, "Invalid value for argument 'metadata'. <KEY>=<VALUE> expected"); return false; }
        out->metadata.set("", md.substr(0, eq), md.substr(eq + 1));
    }
    for (auto& k : a.getStringList("unset-metadata")) { MetadataList* l = out->metadata.domain("", false); if (l) for (size_t i = 0; i < l->size(); i++) if ((*l)[i].first == k) { l->erase(l->begin() + i); break; } }
    if (a.isSet("nodata")) {
        std::string s = a.getString("nodata");
        for (auto& b : out->bands) {
            if (iequals(s, "none")) b->hasNoData = false;
            else { b->hasNoData = true; b->noData = iequals(s, "nan") ? NAN : (iequals(s, "inf") ? INFINITY : (iequals(s, "-inf") ? -INFINITY : strtod(s.c_str(), nullptr))); }
        }
    }
    d.raster = out;
    return true;
}

static bool stepScale(Algorithm& a, PipelineData& d) {
    RasterDataset& src = *d.raster;
    auto out = cloneRasterHeader(src);
    DataType dt = DataType::Unknown;
    if (a.isSet("output-data-type")) dt = dataTypeFromName(a.getString("output-data-type"));
    int band = a.isSet("band") ? (int)a.getInt("band") : 0;
    bool noClip = a.getBool("no-clip");
    double exponent = a.isSet("exponent") ? a.getReal("exponent") : 1.0;
    std::string err;
    for (auto& b : src.bands) {
        std::vector<double> vals;
        if (!b->readAsDouble(vals, err)) { a.reportError(1, err); return false; }
        DataType odt = dt == DataType::Unknown ? b->type : dt;
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = odt; mb->xsize = src.xsize; mb->ysize = src.ysize; mb->blockX = src.xsize; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->hasNoData = b->hasNoData; mb->noData = b->noData; mb->description = b->description;
        bool apply = band == 0 || band == b->number;
        if (apply) {
            double smin, smax;
            if (a.isSet("src-min") && a.isSet("src-max")) { smin = a.getReal("src-min"); smax = a.getReal("src-max"); }
            else {
                smin = 1e300; smax = -1e300;
                for (double v : vals) { if (b->hasNoData && v == b->noData) continue; if (std::isnan(v)) continue; smin = std::min(smin, v); smax = std::max(smax, v); }
                if (smin > smax) { smin = 0; smax = 0; }
            }
            double dmin, dmax;
            if (a.isSet("dst-min") && a.isSet("dst-max")) { dmin = a.getReal("dst-min"); dmax = a.getReal("dst-max"); }
            else {
                switch (odt) {
                    case DataType::Byte: dmin = 0; dmax = 255; break;
                    case DataType::Int8: dmin = -128; dmax = 127; break;
                    case DataType::UInt16: dmin = 0; dmax = 65535; break;
                    case DataType::Int16: dmin = -32768; dmax = 32767; break;
                    case DataType::UInt32: dmin = 0; dmax = 4294967295.0; break;
                    case DataType::Int32: dmin = -2147483648.0; dmax = 2147483647.0; break;
                    default: dmin = 0; dmax = 255;
                }
            }
            double scale = (smax == smin) ? 0 : (dmax - dmin) / (smax - smin);
            for (auto& v : vals) {
                if (b->hasNoData && v == b->noData) continue;
                double nv;
                if (exponent != 1.0) {
                    double t = smax == smin ? 0 : (v - smin) / (smax - smin);
                    if (t < 0) t = 0; if (t > 1) t = 1;
                    nv = dmin + pow(t, exponent) * (dmax - dmin);
                } else nv = (v - smin) * scale + dmin;
                if (!noClip) { if (nv < std::min(dmin, dmax)) nv = std::min(dmin, dmax); if (nv > std::max(dmin, dmax)) nv = std::max(dmin, dmax); }
                v = nv;
            }
        }
        int sz = dataTypeSizeBytes(odt);
        mb->data.assign(vals.size() * sz, 0);
        for (size_t i = 0; i < vals.size(); i++) doubleToSample(vals[i], mb->data.data() + i * sz, odt);
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

static bool stepResize(Algorithm& a, PipelineData& d) {
    RasterDataset& src = *d.raster;
    std::vector<std::string> size = a.getStringList("size");
    if (size.size() != 2) { a.reportError(5, "Invalid size"); return false; }
    auto parseDim = [&](const std::string& s, int full) -> int {
        if (!s.empty() && s.back() == '%') return (int)std::round(full * atof(s.c_str()) / 100.0);
        return atoi(s.c_str());
    };
    int W = parseDim(size[0], src.xsize), H = parseDim(size[1], src.ysize);
    if (W == 0 && H == 0) { a.reportError(5, "Invalid size"); return false; }
    if (W == 0) W = (int)std::round((double)H * src.xsize / src.ysize);
    if (H == 0) H = (int)std::round((double)W * src.ysize / src.xsize);
    std::string resampling = a.getString("resampling", "nearest");
    auto out = cloneRasterHeader(src);
    out->xsize = W; out->ysize = H;
    if (src.hasGeoTransform) {
        out->gt[1] = src.gt[1] * src.xsize / W; out->gt[2] = src.gt[2] * src.ysize / H;
        out->gt[4] = src.gt[4] * src.xsize / W; out->gt[5] = src.gt[5] * src.ysize / H;
    }
    std::string err;
    for (auto& b : src.bands) {
        std::vector<double> vals;
        if (!b->readAsDouble(vals, err)) { a.reportError(1, err); return false; }
        auto mb = std::make_shared<MemBand>();
        mb->number = b->number; mb->type = b->type; mb->xsize = W; mb->ysize = H; mb->blockX = W; mb->blockY = 1;
        mb->colorInterp = b->colorInterp; mb->hasNoData = b->hasNoData; mb->noData = b->noData; mb->description = b->description;
        mb->colorTable = b->colorTable; mb->hasColorTable = b->hasColorTable;
        int sz = dataTypeSizeBytes(b->type);
        mb->data.assign((size_t)W * H * sz, 0);
        double sx = (double)src.xsize / W, sy = (double)src.ysize / H;
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                double v;
                if (iequals(resampling, "nearest") || true) {
                    int srcx = std::min(src.xsize - 1, (int)((x + 0.5) * sx));
                    int srcy = std::min(src.ysize - 1, (int)((y + 0.5) * sy));
                    v = vals[(size_t)srcy * src.xsize + srcx];
                }
                doubleToSample(v, mb->data.data() + ((size_t)y * W + x) * sz, b->type);
            }
        }
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

void registerRasterSteps() {
    registerRasterStep("read", stepRead);
    registerRasterStep("write", stepWrite);
    registerRasterStep("info", stepInfo);
    registerRasterStep("select", stepSelect);
    registerRasterStep("set-type", stepSetType);
    registerRasterStep("clip", stepClip);
    registerRasterStep("edit", stepEdit);
    registerRasterStep("scale", stepScale);
    registerRasterStep("resize", stepResize);
}
