static bool stepRead(Algorithm& a, PipelineData& d) { return openInputVector(a, d); }
static bool stepWrite(Algorithm& a, PipelineData& d) { return writeOutputVector(a, d); }
static bool stepInfo(Algorithm& a, PipelineData& d) {
    if (!d.vector) { a.reportError(1, "No input dataset"); return false; }
