static std::shared_ptr<VectorDataset> cloneDataset(const VectorDataset& src) {
    auto ds = std::make_shared<VectorDataset>();
    ds->driverShort = "MEM"; ds->driverLong = "In Memory raster, vector and multidimensional raster";
    ds->description = src.description; ds->metadata = src.metadata;
    for (auto& l : src.layers) ds->layers.push_back(std::make_shared<Layer>(*l));
    return ds;
}

static bool layerActive(Algorithm& a, const Layer& l) {
    if (!a.isSet("active-layer")) return true;
    return a.getString("active-layer") == l.name;
}

static bool stepSelect(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::vector<std::string> fields = a.getStringList("fields");
    bool exclude = a.getBool("exclude");
    bool ignoreMissing = a.getBool("ignore-missing-fields");
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        std::vector<int> idx;
        std::vector<std::string> newNames;
        if (exclude) {
            std::set<std::string> ex;
            for (auto& f : fields) {
                if (l.findField(f) < 0 && !ignoreMissing) { a.reportError(1, "Field '" + f + "' does not exist in layer '" + l.name + "'. You may specify --ignore-missing-fields to skip it"); return false; }
                ex.insert(toLower(f));
            }
            for (size_t i = 0; i < l.fields.size(); i++) if (!ex.count(toLower(l.fields[i].name))) { idx.push_back((int)i); newNames.push_back(l.fields[i].name); }
        } else {
            for (auto& f : fields) {
                std::string src = f, dst;
                size_t as = toLower(f).find(" as ");
                if (as != std::string::npos) { src = trimString(f.substr(0, as)); dst = trimString(f.substr(as + 4)); }
                int i = l.findField(src);
                if (i < 0) {
                    if (ignoreMissing) continue;
                    a.reportError(1, "Field '" + src + "' does not exist in layer '" + l.name + "'. You may specify --ignore-missing-fields to skip it");
                    return false;
                }
                idx.push_back(i); newNames.push_back(dst.empty() ? l.fields[i].name : dst);
            }
        }
        std::vector<FieldDef> nf;
        for (size_t k = 0; k < idx.size(); k++) { FieldDef f = l.fields[idx[k]]; f.name = newNames[k]; nf.push_back(f); }
        for (auto& feat : l.features) {
            std::vector<FieldValue> v;
            for (int i : idx) v.push_back(i < (int)feat.fields.size() ? feat.fields[i] : FieldValue());
            feat.fields = v;
        }
        l.fields = nf;
        if (a.isSet("output-layer")) l.name = a.getString("output-layer");
    }
    d.vector = out;
    return true;
}

bool evalWhere(const Layer& l, const Feature& f, const std::string& where, bool& err);

static bool stepFilter(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::string where = a.getString("where");
    if (!where.empty() && where[0] == '@') { std::string c; if (readFile(where.substr(1), c)) where = trimString(c); }
    std::vector<double> bbox = a.getRealList("bbox");
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        std::vector<Feature> kept;
        for (auto& f : l.features) {
            bool ok = true;
            if (!where.empty()) { bool e = false; ok = evalWhere(l, f, where, e); if (e) { a.reportError(1, "Failed to evaluate WHERE expression"); return false; } }
            if (ok && bbox.size() == 4) {
                if (f.geoms.empty() || !f.geoms[0] || f.geoms[0]->isEmpty()) ok = false;
                else { Envelope e = f.geoms[0]->envelope(); ok = !(e.maxx < bbox[0] || e.minx > bbox[2] || e.maxy < bbox[1] || e.miny > bbox[3]); }
            }
            if (ok) kept.push_back(f);
        }
        l.features = kept;
    }
    d.vector = out;
    return true;
}

static void swapXY(Geometry& g) {
    for (auto& c : g.points) std::swap(c.x, c.y);
    for (auto& r : g.rings) for (auto& c : r) std::swap(c.x, c.y);
    for (auto& p : g.parts) swapXY(*p);
}

static bool stepSwapXY(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    for (auto& lp : out->layers) {
        if (!layerActive(a, *lp)) continue;
        for (auto& f : lp->features) for (auto& g : f.geoms) if (g) { auto ng = std::make_shared<Geometry>(*g); swapXY(*ng); g = ng; }
    }
    d.vector = out;
    return true;
}

static std::shared_ptr<Geometry> deepCopy(const Geometry& g) {
    auto n = std::make_shared<Geometry>(g);
    n->parts.clear();
    for (auto& p : g.parts) n->parts.push_back(deepCopy(*p));
    return n;
}

static bool stepExplode(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        std::vector<Feature> nf;
        long long fid = 0;
        for (auto& f : l.features) {
            std::shared_ptr<Geometry> g = f.geoms.empty() ? nullptr : f.geoms[0];
            if (g && (g->type == GeomType::MultiPoint || g->type == GeomType::MultiLineString || g->type == GeomType::MultiPolygon || g->type == GeomType::GeometryCollection) && !g->parts.empty()) {
                for (auto& p : g->parts) { Feature c = f; c.fid = fid++; c.geoms[0] = deepCopy(*p); nf.push_back(c); }
            } else { Feature c = f; c.fid = fid++; nf.push_back(c); }
        }
        l.features = nf;
        for (auto& gf : l.geomFields) {
            if (gf.type == GeomType::MultiPoint) gf.type = GeomType::Point;
            else if (gf.type == GeomType::MultiLineString) gf.type = GeomType::LineString;
            else if (gf.type == GeomType::MultiPolygon) gf.type = GeomType::Polygon;
            else if (gf.type == GeomType::GeometryCollection) gf.type = GeomType::Unknown;
        }
    }
    d.vector = out;
    return true;
}

static bool stepReproject(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    CRS dst;
    if (!dst.setFromUserInput(a.getString("dst-crs"))) { a.reportError(5, "Invalid value for 'dst-crs' argument"); return false; }
    CRS srcOverride;
    bool hasSrcOverride = false;
    if (a.isSet("src-crs")) { if (!srcOverride.setFromUserInput(a.getString("src-crs"))) { a.reportError(5, "Invalid value for 'src-crs' argument"); return false; } hasSrcOverride = true; }
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
