    for (auto& of : a.getStringList("offset")) if (!applyBandSpec(a, *ds, of, "offset", [](RasterBand& b, const std::string& v) { b.hasOffset = true; b.offset = strtod(v.c_str(), nullptr); })) return 1;
    for (auto& md : a.getStringList("metadata")) {
        size_t eq = md.find('=');
        if (eq == std::string::npos) { a.reportError(1, "Invalid value for argument 'metadata'. <KEY>=<VALUE> expected"); return 1; }
        ds->metadata.set("", md.substr(0, eq), md.substr(eq + 1));
    }
    for (auto& k : a.getStringList("unset-metadata")) { MetadataList* l = ds->metadata.domain("", false); if (l) for (size_t i = 0; i < l->size(); i++) if ((*l)[i].first == k) { l->erase(l->begin() + i); break; } }
    for (auto& dname : a.getStringList("unset-metadata-domain")) { for (size_t i = 0; i < ds->metadata.domains.size(); i++) if (ds->metadata.domains[i].first == dname) { ds->metadata.domains.erase(ds->metadata.domains.begin() + i); break; } }
    for (auto& g : a.getStringList("gcp")) {
        std::string spec = g;
        if (!spec.empty() && spec[0] == '@') { std::string c; if (!readFile(spec.substr(1), c)) { a.reportError(1, "Cannot open " + spec.substr(1)); return 1; } for (auto& line : splitString(c, '\n')) { std::string t = trimString(line); if (t.empty() || t[0] == '#') continue; auto parts = splitString(t, ','); if (parts.size() < 4) continue; GCP gcp; gcp.id = std::to_string(ds->gcps.size() + 1); gcp.pixel = atof(parts[0].c_str()); gcp.line = atof(parts[1].c_str()); gcp.x = atof(parts[2].c_str()); gcp.y = atof(parts[3].c_str()); if (parts.size() > 4) gcp.z = atof(parts[4].c_str()); ds->gcps.push_back(gcp); } continue; }
        auto parts = splitString(spec, ',');
        if (parts.size() < 4 || parts.size() > 5) { a.reportError(5, "Bad value for --gcp. It should be formatted as pixel,line,easting,northing[,elevation]"); return 1; }
        GCP gcp; gcp.id = std::to_string(ds->gcps.size() + 1); gcp.pixel = atof(parts[0].c_str()); gcp.line = atof(parts[1].c_str()); gcp.x = atof(parts[2].c_str()); gcp.y = atof(parts[3].c_str()); if (parts.size() > 4) gcp.z = atof(parts[4].c_str());
        ds->gcps.push_back(gcp);
    }
    if (!ds->gcps.empty() && ds->hasCRS) { ds->hasGcpCRS = true; ds->gcpCRS = ds->crs; }
    if (a.getBool("stats") || a.getBool("approx-stats")) {
        for (auto& b : ds->bands) {
            BandStats st = computeStats(*b, a.getBool("approx-stats"), err);
            if (st.ok) setBandStatistics(*b, st, a.getBool("approx-stats"), (uint64_t)b->xsize * b->ysize);
        }
    }
    if (a.getBool("hist")) {
        for (auto& b : ds->bands) {
            double hmin, hmax; std::vector<uint64_t> hist; int nBuckets = 256;
            if (b->type == DataType::Byte) { hmin = -0.5; hmax = 255.5; }
            else { double mn, mx; if (!computeMinMax(*b, true, mn, mx, err)) continue; double half = (mx - mn) / (2 * (nBuckets - 1)); hmin = mn - half; hmax = mx + half; }
            if (computeHistogram(*b, hmin, hmax, nBuckets, hist, false, err)) {
                std::string counts; for (size_t i = 0; i < hist.size(); i++) { if (i) counts += "|"; counts += std::to_string(hist[i]); }
                b->metadata.set("__pam_hist__", "hist", strprintf("%.14g", hmin) + "|" + strprintf("%.14g", hmax) + "|" + std::to_string(nBuckets) + "|0|0|" + counts);
            }
        }
    }
    if (aux || src->driverShort != "GTiff") {
        // write PAM
        XmlNode root; root.name = "PAMDataset";
        if (ds->hasCRS) { auto n = root.addChildWithText("SRS", ds->crs.exportWkt1(false)); auto m = ds->crs.dataAxisToSRSAxisMapping(); std::string ms; for (size_t i = 0; i < m.size(); i++) { if (i) ms += ","; ms += std::to_string(m[i]); } n->setAttr("dataAxisToSRSAxisMapping", ms); }
        if (ds->hasGeoTransform) { std::string g; for (int i = 0; i < 6; i++) { if (i) g += ", "; g += strprintf("%.16e", ds->gt[i]); } root.addChildWithText("GeoTransform", "  " + g); }
        for (auto& dom : ds->metadata.domains) {
            if (dom.first == "IMAGE_STRUCTURE" || dom.first == "__pam_hist__") continue;
            bool any = false; for (auto& kv : dom.second) if (!(dom.first.empty() && kv.first == "AREA_OR_POINT")) any = true;
            if (!any) continue;
            auto m = root.addChild("Metadata"); if (!dom.first.empty()) m->setAttr("domain", dom.first);
            for (auto& kv : dom.second) { if (dom.first.empty() && kv.first == "AREA_OR_POINT") continue; auto mdi = m->addChildWithText("MDI", kv.second); mdi->setAttr("key", kv.first); }
        }
        for (auto& b : ds->bands) {
            auto bn = root.addChild("PAMRasterBand"); bn->setAttr("band", std::to_string(b->number));
            if (b->hasNoData) bn->addChildWithText("NoDataValue", strprintf("%.14E", b->noData));
            if (b->hasOffset) bn->addChildWithText("Offset", strprintf("%.14E", b->offset));
            if (b->hasScale) bn->addChildWithText("Scale", strprintf("%.14E", b->scale));
            MetadataList* l = b->metadata.domain("", false);
            if (l && !l->empty()) { auto m = bn->addChild("Metadata"); for (auto& kv : *l) { auto mdi = m->addChildWithText("MDI", kv.second); mdi->setAttr("key", kv.first); } }
            std::string hist = b->metadata.get("__pam_hist__", "hist");
            if (!hist.empty()) { auto parts = splitString(hist, '|'); if (parts.size() == 6) { auto hs = bn->addChild("Histograms"); auto hi = hs->addChild("HistItem"); hi->addChildWithText("HistMin", parts[0]); hi->addChildWithText("HistMax", parts[1]); hi->addChildWithText("BucketCount", parts[2]); hi->addChildWithText("IncludeOutOfRange", parts[3]); hi->addChildWithText("Approximate", parts[4]); hi->addChildWithText("HistCounts", parts[5]); } }
            if (bn->children.empty()) root.children.pop_back();
        }
        writeFile(path + ".aux.xml", xmlSerialize(root));
        return 0;
    }
    GTiffWriteOptions o;
    std::vector<std::string> co;
    for (auto& kv : ds->creationHints) co.push_back(kv.first + "=" + kv.second);
    if (!parseGTiffOptions(a, co, o)) return 1;
    // Stats metadata into band metadata domain is kept by buildGdalMetadata? It skips STATISTICS_. Keep them via PAM-like inclusion:
    for (auto& b : ds->bands) {
        MetadataList* l = b->metadata.domain("", false);
        if (!l) continue;
        for (auto& kv : *l) if (startsWith(kv.first, "STATISTICS_")) b->metadata.set("__stats_in_tiff__", kv.first, kv.second);
    }
