#include "alg.h"
#include "raster.h"
#include "util.h"
#include <cstdio>
#include <cmath>

static int runPixelInfo(Algorithm& a) {
    std::vector<std::string> inputs = a.getStringList("input");
    std::string err; int code = 0;
    auto ds = openRaster(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
    if (!ds) { cplError(code, err); a.printUsageOnError(); return 1; }
    std::vector<double> pos = a.getRealList("position");
    if (pos.empty() || pos.size() % 2 != 0) { a.reportError(5, "Argument 'position' must be specified with pairs of values"); return 1; }
    std::string posCrs = a.getString("position-crs", "pixel");
    std::vector<long long> bands = a.getIntList("band");
    if (bands.empty()) for (size_t i = 0; i < ds->bands.size(); i++) bands.push_back((long long)i + 1);
    for (auto b : bands) if (b < 1 || b > (long long)ds->bands.size()) { a.reportError(5, strprintf("Invalid band number: %lld", b)); return 1; }
    CoordTransform ct;
    bool useCT = false;
    if (!iequals(posCrs, "pixel")) {
        if (!ds->hasGeoTransform) { a.reportError(1, "Dataset has no geotransform"); return 1; }
        if (!iequals(posCrs, "dataset")) {
            CRS pc;
            if (!pc.setFromUserInput(posCrs)) { a.reportError(5, "Invalid value for 'position-crs'"); return 1; }
            if (!ds->hasCRS) { a.reportError(1, "Dataset has no CRS"); return 1; }
            if (!ct.init(pc, ds->crs)) { a.reportError(1, "Cannot create coordinate transformation"); return 1; }
            useCT = true;
        }
    }
    JsonValue fc = JsonValue::object();
    fc.set("type", JsonValue::string("FeatureCollection"));
    JsonValue feats = JsonValue::array();
    for (size_t i = 0; i + 1 < pos.size(); i += 2) {
        double x = pos[i], y = pos[i + 1];
        double col, line;
        if (iequals(posCrs, "pixel")) { col = x; line = y; }
        else {
            double gx = x, gy = y;
            if (useCT && !ct.transform(gx, gy)) { a.reportError(1, "Cannot transform coordinate"); return 1; }
            ds->geoToPixel(gx, gy, col, line);
        }
        int icol = (int)std::floor(col), iline = (int)std::floor(line);
        JsonValue f = JsonValue::object();
        f.set("type", JsonValue::string("Feature"));
        JsonValue geom = JsonValue::object();
        geom.set("type", JsonValue::string("Point"));
        JsonValue coords = JsonValue::array();
        double gx, gy;
        if (ds->hasGeoTransform) ds->pixelToGeo(icol + 0.5, iline + 0.5, gx, gy); else { gx = icol + 0.5; gy = iline + 0.5; }
        coords.push(JsonValue::number(gx)); coords.push(JsonValue::number(gy));
        geom.set("coordinates", coords);
        f.set("geometry", geom);
        JsonValue props = JsonValue::object();
        JsonValue ic = JsonValue::array();
        ic.push(JsonValue::number(x)); ic.push(JsonValue::number(y));
        props.set("input_coordinate", ic);
        props.set("column", JsonValue::integer(icol));
        props.set("line", JsonValue::integer(iline));
        JsonValue bj = JsonValue::array();
        bool inside = icol >= 0 && iline >= 0 && icol < ds->xsize && iline < ds->ysize;
        for (auto bn : bands) {
            RasterBand& b = *ds->bands[bn - 1];
            JsonValue o = JsonValue::object();
            o.set("band_number", JsonValue::integer(bn));
            if (inside) {
                std::vector<double> v;
                if (!b.readWindowAsDouble(icol, iline, 1, 1, v, err)) { a.reportError(1, err); return 1; }
                double val = v[0];
                if (b.hasNoData && (val == b.noData || (std::isnan(b.noData) && std::isnan(val)))) o.set("value", JsonValue::null());
                else if (dataTypeIsInteger(b.type) && !dataTypeIsComplex(b.type)) o.set("value", JsonValue::integer((long long)val));
                else o.set("value", JsonValue::number(val));
                if ((b.hasScale && b.scale != 1.0) || (b.hasOffset && b.offset != 0.0)) {
                    o.set("raw_value", o.get("value"));
                    o.set("unscaled_value", JsonValue::number(val * (b.hasScale ? b.scale : 1.0) + (b.hasOffset ? b.offset : 0.0)));
                }
            } else {
                o.set("value", JsonValue::null());
            }
            bj.push(o);
        }
        props.set("bands", bj);
        f.set("properties", props);
        feats.push(f);
    }
    fc.set("features", feats);
    if (a.isSet("output")) {
        std::string out = a.getString("output");
        if (fileExists(out) && !a.getBool("overwrite")) { a.reportError(1, "Dataset '" + out + "' already exists. You may specify the --overwrite option."); return 1; }
        writeFile(out, fc.serialize(JsonValue::PRETTY, false) + "\n");
        return 0;
    }
    fputs(fc.serialize(JsonValue::PRETTY, false).c_str(), stdout);
    fputs("\n", stdout);
    return 0;
}

static std::string gtString(const double* gt) {
    std::string s;
    for (int i = 0; i < 6; i++) { if (i) s += ","; s += strprintf("%.17g", gt[i]); }
    return s;
}

static int runRasterCompare(Algorithm& a) {
    std::string refPath = a.getString("reference");
    std::vector<std::string> inputs = a.getStringList("input");
    std::string err; int code = 0;
    auto ref = openRaster(refPath, err, code);
    if (!ref) { cplError(code, err); a.printUsageOnError(); return 1; }
    auto in = openRaster(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
    if (!in) { cplError(code, err); a.printUsageOnError(); return 1; }
    int nDiffs = 0;
    std::string out;
    bool skipAll = a.getBool("skip-all-optional");
    if (ref->driverShort != in->driverShort) { out += "Reference driver is " + ref->driverShort + " and input driver is " + in->driverShort + ".\n"; nDiffs++; }
    if (ref->xsize != in->xsize || ref->ysize != in->ysize) { out += strprintf("Reference dataset has dimensions %dx%d, but input dataset has dimensions %dx%d.\n", ref->xsize, ref->ysize, in->xsize, in->ysize); nDiffs++; }
    if (ref->bands.size() != in->bands.size()) { out += strprintf("Reference dataset has %d bands, but input dataset has %d bands.\n", (int)ref->bands.size(), (int)in->bands.size()); nDiffs++; }
    if (!skipAll && !a.getBool("skip-crs")) {
        if (ref->hasCRS != in->hasCRS || (ref->hasCRS && !ref->crs.isSame(in->crs))) { out += "Reference and input datasets have different CRS.\n"; nDiffs++; }
    }
    if (!skipAll && !a.getBool("skip-geotransform")) {
        if (ref->hasGeoTransform != in->hasGeoTransform) { out += "Reference and input datasets have different geotransform.\n"; nDiffs++; }
        else if (ref->hasGeoTransform) { bool same = true; for (int i = 0; i < 6; i++) if (ref->gt[i] != in->gt[i]) same = false; if (!same) { out += "Reference dataset has geotransform (" + gtString(ref->gt) + "), but input dataset has geotransform (" + gtString(in->gt) + ").\n"; nDiffs++; } }
    }
    if (!skipAll && !a.getBool("skip-metadata")) {
        const MetadataList* r = ref->metadata.domain(""); const MetadataList* i2 = in->metadata.domain("");
        MetadataList e;
        if ((r ? *r : e) != (i2 ? *i2 : e)) { out += "Reference and input datasets have different metadata in default domain.\n"; nDiffs++; }
    }
    size_t nb = std::min(ref->bands.size(), in->bands.size());
    for (size_t i = 0; i < nb; i++) {
        RasterBand& rb = *ref->bands[i]; RasterBand& ib = *in->bands[i];
        if (rb.type != ib.type) { out += strprintf("Band %d of reference dataset has data type %s, but band %d of input dataset has data type %s.\n", (int)i + 1, dataTypeName(rb.type), (int)i + 1, dataTypeName(ib.type)); nDiffs++; }
        if (rb.hasNoData != ib.hasNoData || (rb.hasNoData && rb.noData != ib.noData && !(std::isnan(rb.noData) && std::isnan(ib.noData)))) { out += strprintf("Band %d of reference and input datasets have different nodata values.\n", (int)i + 1); nDiffs++; }
        if (rb.colorInterp != ib.colorInterp) { out += strprintf("Band %d of reference dataset has color interpretation %s, but band %d of input dataset has color interpretation %s.\n", (int)i + 1, rb.colorInterp.c_str(), (int)i + 1, ib.colorInterp.c_str()); nDiffs++; }
        if (ref->xsize == in->xsize && ref->ysize == in->ysize && rb.type == ib.type) {
            int c1 = computeChecksum(rb, 0, 0, rb.xsize, rb.ysize, err), c2 = computeChecksum(ib, 0, 0, ib.xsize, ib.ysize, err);
            if (c1 != c2) {
                std::vector<double> v1, v2;
                rb.readAsDouble(v1, err); ib.readAsDouble(v2, err);
                size_t nd = 0; double maxd = 0;
                for (size_t k = 0; k < v1.size() && k < v2.size(); k++) if (v1[k] != v2[k]) { nd++; maxd = std::max(maxd, fabs(v1[k] - v2[k])); }
                out += strprintf("Band %d of reference dataset has checksum %d, but band %d of input dataset has checksum %d. %d pixels differ.\n", (int)i + 1, c1, (int)i + 1, c2, (int)nd);
                nDiffs++;
            }
        }
    }
    if (!a.getBool("quiet")) fputs(out.c_str(), stdout);
    return nDiffs == 0 ? 0 : 1;
}

void registerPixelInfo(Algorithm* root) {
    if (Algorithm* r = root->findSub("raster")) {
        if (Algorithm* c = r->findSub("pixel-info")) c->runFn = runPixelInfo;
        if (Algorithm* c = r->findSub("compare")) c->runFn = runRasterCompare;
    }
}
