        JsonValue props = JsonValue::object();
        JsonValue ic = JsonValue::array();
        ic.push(JsonValue::number(x)); ic.push(JsonValue::number(y));
        props.set("input_coordinate", ic);
        props.set("column", JsonValue::integer(icol));
        props.set("line", JsonValue::integer(iline));
        JsonValue bj = JsonValue::array();
        bool inside = icol >= 0 && iline >= 0 && icol < ds->xsize && iline < ds->ysize;
        for (auto bn : bands) {
            RasterBand& b = *ds->bands[bn - 1];
            JsonValue o = JsonValue::object();
            o.set("band_number", JsonValue::integer(bn));
            if (inside) {
                std::vector<double> v;
                if (!b.readWindowAsDouble(icol, iline, 1, 1, v, err)) { a.reportError(1, err); return 1; }
                double val = v[0];
                if (b.hasNoData && (val == b.noData || (std::isnan(b.noData) && std::isnan(val)))) o.set("value", JsonValue::null());
