static bool stepMosaic(Algorithm& a, PipelineData& d) {
    if (d.rasterInputs.empty()) { a.reportError(1, "No input dataset"); return false; }
    // Compute union extent (requires georeferencing and same resolution)
    RasterDataset& first = *d.rasterInputs[0];
    if (!first.hasGeoTransform) { a.reportError(1, "Input datasets must be georeferenced"); return false; }
    double resx = first.gt[1], resy = first.gt[5];
    double xmin = 1e300, ymin = 1e300, xmax = -1e300, ymax = -1e300;
    for (auto& ds : d.rasterInputs) {
        if (!ds->hasGeoTransform) { a.reportError(1, "Input datasets must be georeferenced"); return false; }
        double x0, y0, x1, y1;
        ds->pixelToGeo(0, 0, x0, y0); ds->pixelToGeo(ds->xsize, ds->ysize, x1, y1);
        xmin = std::min(xmin, std::min(x0, x1)); xmax = std::max(xmax, std::max(x0, x1));
        ymin = std::min(ymin, std::min(y0, y1)); ymax = std::max(ymax, std::max(y0, y1));
    }
    std::vector<double> bbox = a.getRealList("bbox");
    if (bbox.size() == 4) { xmin = bbox[0]; ymin = bbox[1]; xmax = bbox[2]; ymax = bbox[3]; }
    int W = (int)std::round((xmax - xmin) / resx), H = (int)std::round((ymax - ymin) / -resy);
    if (W <= 0 || H <= 0) { a.reportError(1, "Invalid output size"); return false; }
    auto out = cloneRasterHeader(first);
    out->xsize = W; out->ysize = H;
    out->gt[0] = xmin; out->gt[3] = ymax; out->gt[1] = resx; out->gt[5] = resy; out->gt[2] = out->gt[4] = 0;
    std::vector<long long> bandSel = a.getIntList("band");
    std::vector<int> idx;
    if (bandSel.empty()) for (size_t i = 0; i < first.bands.size(); i++) idx.push_back((int)i);
    else for (auto b : bandSel) idx.push_back((int)b - 1);
    std::vector<double> dstNodata = a.getRealList("dst-nodata");
    std::vector<double> srcNodata = a.getRealList("src-nodata");
    std::string err;
    int n = 1;
    for (int bi : idx) {
        if (bi < 0 || bi >= (int)first.bands.size()) { a.reportError(5, strprintf("Invalid band number %d", bi + 1)); return false; }
        RasterBand& fb = *first.bands[bi];
        auto mb = std::make_shared<MemBand>();
        mb->number = n++; mb->type = fb.type; mb->xsize = W; mb->ysize = H; mb->blockX = W; mb->blockY = 1;
        mb->colorInterp = fb.colorInterp; mb->description = fb.description;
        int sz = dataTypeSizeBytes(fb.type);
        double fill = 0;
        if (!dstNodata.empty()) { mb->hasNoData = true; mb->noData = dstNodata[0]; fill = dstNodata[0]; }
        else if (fb.hasNoData) { mb->hasNoData = true; mb->noData = fb.noData; fill = fb.noData; }
        mb->data.assign((size_t)W * H * sz, 0);
        if (fill != 0) { std::vector<uint8_t> px(sz); doubleToSample(fill, px.data(), fb.type); for (size_t p = 0; p < (size_t)W * H; p++) memcpy(mb->data.data() + p * sz, px.data(), sz); }
        for (auto& ds : d.rasterInputs) {
            if (bi >= (int)ds->bands.size()) continue;
            RasterBand& sb = *ds->bands[bi];
            std::vector<double> vals;
            if (!sb.readAsDouble(vals, err)) { a.reportError(1, err); return false; }
            double ox, oy;
            ds->pixelToGeo(0, 0, ox, oy);
            int offx = (int)std::round((ox - xmin) / resx), offy = (int)std::round((oy - ymax) / resy);
            double snd = !srcNodata.empty() ? srcNodata[0] : (sb.hasNoData ? sb.noData : NAN);
            bool hasSnd = !srcNodata.empty() || sb.hasNoData;
            for (int y = 0; y < ds->ysize; y++) {
                int ty = y + offy; if (ty < 0 || ty >= H) continue;
                for (int x = 0; x < ds->xsize; x++) {
                    int tx = x + offx; if (tx < 0 || tx >= W) continue;
                    double v = vals[(size_t)y * ds->xsize + x];
                    if (hasSnd && (v == snd || (std::isnan(snd) && std::isnan(v)))) continue;
                    doubleToSample(v, mb->data.data() + ((size_t)ty * W + tx) * sz, fb.type);
                }
            }
        }
        mb->dataset = out.get();
        out->bands.push_back(mb);
    }
    d.raster = out;
    return true;
}

