static bool stepConcat(Algorithm& a, PipelineData& d) {
    std::vector<std::string> inputs = a.getStringList("input");
    std::string mode = a.getString("mode", "merge-per-layer-name");
    std::vector<std::shared_ptr<VectorDataset>> dss;
    for (auto& in : inputs) {
        std::string err; int code = 0;
        auto ds = openVector(in, err, code, a.getStringList("input-format"), a.getStringList("open-option"));
        if (!ds) { cplError(code, err); return false; }
        dss.push_back(ds);
    }
    if (dss.empty()) { a.reportError(1, "No input"); return false; }
    auto out = std::make_shared<VectorDataset>();
    out->driverShort = "MEM"; out->driverLong = "In Memory raster, vector and multidimensional raster";
    out->description = dss[0]->description;
    auto mergeInto = [&](Layer& target, const Layer& src) {
        // extend schema
        std::vector<int> map;
        for (auto& f : src.fields) {
            int idx = target.findField(f.name);
            if (idx < 0) { target.fields.push_back(f); idx = (int)target.fields.size() - 1; for (auto& ft : target.features) ft.fields.resize(target.fields.size()); }
            map.push_back(idx);
        }
        for (auto& f : src.features) {
            Feature nf; nf.fid = (long long)target.features.size(); nf.fields.resize(target.fields.size()); nf.geoms = f.geoms;
            for (size_t i = 0; i < map.size() && i < f.fields.size(); i++) nf.fields[map[i]] = f.fields[i];
            target.features.push_back(nf);
        }
        for (size_t gi = 0; gi < src.geomFields.size(); gi++) {
            if (gi >= target.geomFields.size()) target.geomFields.push_back(src.geomFields[gi]);
            else if (target.geomFields[gi].type != src.geomFields[gi].type) target.geomFields[gi].type = GeomType::Unknown;
        }
    };
    if (iequals(mode, "single")) {
        auto l = std::make_shared<Layer>();
        l->name = a.isSet("output-layer") ? a.getString("output-layer") : "merged";
        for (auto& ds : dss) for (auto& sl : ds->layers) mergeInto(*l, *sl);
        out->layers.push_back(l);
    } else if (iequals(mode, "stack")) {
        for (auto& ds : dss) for (auto& sl : ds->layers) out->layers.push_back(std::make_shared<Layer>(*sl));
    } else {
        for (auto& ds : dss) for (auto& sl : ds->layers) {
            auto existing = out->layerByName(sl->name);
            if (!existing) { out->layers.push_back(std::make_shared<Layer>(*sl)); }
            else mergeInto(*existing, *sl);
        }
    }
    d.vector = out;
    return true;
}

void registerVectorSteps2() { registerVectorStep("concat", stepConcat); }
