        size_t off = file.size();
        IFDBlob b;
        if (!buildIFDBlob(*ov, opts, off, true, false, err, false, b)) return false;
        if (!first) patch32(file, prevPtr, (uint32_t)off);
        first = false;
        prevPtr = off + b.nextPtrPos;
        file += b.data;
