bool writeGTiffWithOverviews(RasterDataset& src, const std::vector<std::shared_ptr<RasterDataset>>& overviews, const std::string& path, const GTiffWriteOptions& opts, std::string& err, bool progress) {
    std::string file = "II";
    file += (char)42; file += (char)0;
    file += std::string("\\x08\\x00\\x00\\x00", 4);
    IFDBlob main;
    if (!buildIFDBlob(src, opts, 8, false, true, err, progress, main)) return false;
    size_t prevPtr = 8 + main.nextPtrPos;
    file += main.data;
    for (auto& ov : overviews) {
        if (file.size() & 1) file += '\\0';
        size_t off = file.size();
        IFDBlob b;
        GTiffWriteOptions o2 = opts;
        if (!buildIFDBlob(*ov, o2, off, true, false, err, false, b)) return false;
        patch32(file, prevPtr, (uint32_t)off);
        prevPtr = off + b.nextPtrPos;
        file += b.data;
    }
    if (!writeFile(path, file)) { err = "Cannot create " + path; return false; }
    return true;
}

bool writeGTiff(RasterDataset& src, const std::string& path, const GTiffWriteOptions& opts, std::string& err, bool progress) {
