                    for (int yy = sy0; yy < sy1; yy++) for (int xx = sx0; xx < sx1; xx++) { double s = vals[(size_t)yy * src.xsize + xx]; if (b->hasNoData && (s == b->noData || (std::isnan(b->noData) && std::isnan(s)))) continue; sum += s; n++; }
