static int runOverviewAdd(Algorithm& a) {
    std::string path = a.getString("input");
    std::string err; int code = 0;
    auto src = openRaster(path, err, code, {}, a.getStringList("open-option"));
    if (!src) { cplError(code, err); a.printUsageOnError(); return 1; }
    if (src->driverShort != "GTiff") { a.reportError(6, "Only GTiff datasets are supported by this build"); return 1; }
    std::vector<long long> levels = a.getIntList("levels");
    if (levels.empty()) {
        int minSize = a.isSet("min-size") ? (int)a.getInt("min-size") : 256;
        int level = 2;
        while (std::max(src->xsize, src->ysize) / level >= minSize || (std::max(src->xsize, src->ysize) + level - 1) / level > minSize) {
            levels.push_back(level);
            level *= 2;
        }
    }
    for (auto l : levels) if (l < 2) { a.reportError(5, strprintf("Invalid overview level %lld. Should be >= 2", l)); return 1; }
    std::string resampling = a.getString("resampling", "nearest");
    bool external = a.getBool("external");
    bool progress = !a.getBool("quiet");
    bool started = false; int lastTick = -1;
    if (progress) printProgress(0.0, started, lastTick);
    auto base = materializeRaster(*src, err);
    if (!base) { a.reportError(1, err); return 1; }
    base->creationHints = src->creationHints; base->description = src->description;
    std::vector<std::shared_ptr<RasterDataset>> ovs;
    // keep existing overviews
    for (auto& ov : src->bands.empty() ? std::vector<std::shared_ptr<RasterBand>>() : src->bands[0]->overviews) {
        RasterDataset tmp; tmp.xsize = ov->xsize; tmp.ysize = ov->ysize;
        for (auto& b : src->bands) { for (auto& o2 : b->overviews) if (o2->xsize == ov->xsize) tmp.bands.push_back(o2); }
        auto m = materializeRaster(tmp, err);
        if (m) ovs.push_back(m);
    }
    size_t n = 0;
    for (auto l : levels) {
        bool exists = false;
        for (auto& ov : ovs) if (ov->xsize == (src->xsize + l - 1) / l) exists = true;
        if (exists) { n++; continue; }
        auto ov = buildOverview(*base, (int)l, resampling, err);
        if (!ov) { a.reportError(1, err); return 1; }
        ovs.push_back(ov);
        n++;
        if (progress) printProgress((double)n / levels.size() * 0.9, started, lastTick);
    }
    GTiffWriteOptions o;
    std::vector<std::string> co;
    for (auto& kv : base->creationHints) co.push_back(kv.first + "=" + kv.second);
    if (!parseGTiffOptions(a, co, o)) return 1;
    if (external) {
        GTiffWriteOptions oo;
        parseGTiffOptions(a, a.getStringList("creation-option"), oo);
        if (!writeOvrFile(ovs, path + ".ovr", oo, err)) { a.reportError(1, err); return 1; }
    } else {
        std::string tmp = path + ".tmp_ovr";
        for (auto& b : base->bands) b->overviews.clear();
        if (!writeGTiffWithOverviews(*base, ovs, tmp, o, err, false)) { a.reportError(1, err); unlink(tmp.c_str()); return 1; }
        rename(tmp.c_str(), path.c_str());
    }
    if (progress) printProgress(1.0, started, lastTick);
    return 0;
}

static int runOverviewDelete(Algorithm& a) {
    std::string path = a.getString("input");
