                else if (e->name == "ColorTable") { b->hasColorTable = true; for (auto& en : e->children) if (en->name == "Entry") { ColorEntry ce; ce.c1 = (short)atoi(en->attr("c1").c_str()); ce.c2 = (short)atoi(en->attr("c2").c_str()); ce.c3 = (short)atoi(en->attr("c3").c_str()); ce.c4 = (short)atoi(en->attr("c4", "255").c_str()); b->colorTable.push_back(ce); } }
                else if (e->name == "SimpleSource" || e->name == "ComplexSource" || e->name == "AveragedSource") {
                    VrtSource s;
                    s.complex = e->name == "ComplexSource";
                    auto fn = e->child("SourceFilename");
                    if (!fn) continue;
                    std::string f = fn->textContent();
                    bool rel = fn->attr("relativeToVRT") == "1";
                    std::string full = (rel && !dir.empty() && (f.empty() || f[0] != '/')) ? dir + "/" + f : f;
                    std::string e2; int c2;
                    s.ds = openRaster(full, e2, c2);
                    if (!s.ds) { cplWarning(1, e2); continue; }
                    bool known = false;
                    for (auto& ef : extraFiles) if (ef == full) known = true;
                    if (!known) extraFiles.push_back(full);
                    std::string sb = e->childText("SourceBand", "1");
                    if (startsWith(sb, "mask")) { s.isMask = true; s.band = 1; } else s.band = atoi(sb.c_str());
                    auto sr = e->child("SrcRect"), dr = e->child("DstRect");
