                    }
                    if (e->child("NODATA")) { s.hasNoData = true; s.noData = strtod(e->childText("NODATA").c_str(), nullptr); }
                    if (e->child("ScaleOffset") || e->child("ScaleRatio")) { s.hasScale = true; s.scaleOff = strtod(e->childText("ScaleOffset", "0").c_str(), nullptr); s.scaleRatio = strtod(e->childText("ScaleRatio", "1").c_str(), nullptr); }
                    b->sources.push_back(s);
                }
            }
