        }
    }
    ds->files.push_back(path);
    for (auto& f : extraFiles) ds->files.push_back(f);
    if (fileExists(path + ".aux.xml")) { ds->pamPath = path + ".aux.xml"; ds->files.push_back(ds->pamPath); } else ds->pamPath = path + ".aux.xml";
