}

// Writing a VRT referencing the source dataset bands
bool writeVRT(RasterDataset& src, const std::string& path, std::string& err) {
    XmlNode root;
    root.name = "VRTDataset";
    root.setAttr("rasterXSize", std::to_string(src.xsize));
    root.setAttr("rasterYSize", std::to_string(src.ysize));
    if (src.hasCRS) {
        std::string wkt = src.crs.exportWkt1(false);
        if (wkt.empty()) wkt = src.crs.exportWkt2_2019(false);
        auto n = root.addChildWithText("SRS", wkt);
        auto m = src.crs.dataAxisToSRSAxisMapping();
        std::string ms; for (size_t i = 0; i < m.size(); i++) { if (i) ms += ","; ms += std::to_string(m[i]); }
        n->setAttr("dataAxisToSRSAxisMapping", ms);
    }
    if (src.hasGeoTransform) {
        std::string g;
        for (int i = 0; i < 6; i++) { if (i) g += ","; g += strprintf("%24.16e", src.gt[i]); }
        root.addChildWithText("GeoTransform", g);
    }
    for (auto& dom : src.metadata.domains) {
        if (dom.first == "__pam_hist__" || dom.first == "IMAGE_STRUCTURE") continue;
        if (dom.second.empty()) continue;
        auto m = root.addChild("Metadata");
        if (!dom.first.empty()) m->setAttr("domain", dom.first);
        for (auto& kv : dom.second) { auto mdi = m->addChildWithText("MDI", kv.second); mdi->setAttr("key", kv.first); }
    }
    std::string dir = getDirname(path);
    std::string srcPath = src.description;
    bool relative = false;
    std::string relPath = srcPath;
    if (!srcPath.empty() && srcPath[0] != '/' && (dir.empty() || dir == ".")) { relative = true; }
    else if (!srcPath.empty() && !dir.empty() && startsWith(getAbsolutePath(srcPath), getAbsolutePath(dir) + "/")) { relative = true; relPath = getAbsolutePath(srcPath).substr(getAbsolutePath(dir).size() + 1); }
    for (auto& b : src.bands) {
        auto bn = root.addChild("VRTRasterBand");
        bn->setAttr("dataType", dataTypeName(b->type));
        bn->setAttr("band", std::to_string(b->number));
        if (b->hasNoData) bn->addChildWithText("NoDataValue", strprintf("%.14E", b->noData));
        if (!b->description.empty()) bn->addChildWithText("Description", b->description);
        if (b->colorInterp != "Undefined") bn->addChildWithText("ColorInterp", b->colorInterp);
        if (!b->unitType.empty()) bn->addChildWithText("UnitType", b->unitType);
        if (b->hasOffset) bn->addChildWithText("Offset", strprintf("%.16g", b->offset));
        if (b->hasScale) bn->addChildWithText("Scale", strprintf("%.16g", b->scale));
        if (b->hasColorTable) { auto ct = bn->addChild("ColorTable"); for (auto& e : b->colorTable) { auto en = ct->addChild("Entry"); en->setAttr("c1", std::to_string(e.c1)); en->setAttr("c2", std::to_string(e.c2)); en->setAttr("c3", std::to_string(e.c3)); en->setAttr("c4", std::to_string(e.c4)); } }
        auto s = bn->addChild("SimpleSource");
        auto fn = s->addChildWithText("SourceFilename", relative ? relPath : srcPath);
        fn->setAttr("relativeToVRT", relative ? "1" : "0");
        s->addChildWithText("SourceBand", std::to_string(b->number));
        auto sp = s->addChild("SourceProperties");
        sp->setAttr("RasterXSize", std::to_string(b->xsize)); sp->setAttr("RasterYSize", std::to_string(b->ysize)); sp->setAttr("DataType", dataTypeName(b->type)); sp->setAttr("BlockXSize", std::to_string(b->blockX)); sp->setAttr("BlockYSize", std::to_string(b->blockY));
        auto sr = s->addChild("SrcRect"); sr->setAttr("xOff", "0"); sr->setAttr("yOff", "0"); sr->setAttr("xSize", std::to_string(b->xsize)); sr->setAttr("ySize", std::to_string(b->ysize));
        auto dr = s->addChild("DstRect"); dr->setAttr("xOff", "0"); dr->setAttr("yOff", "0"); dr->setAttr("xSize", std::to_string(b->xsize)); dr->setAttr("ySize", std::to_string(b->ysize));
    }
    if (!writeFile(path, xmlSerialize(root))) { err = "Cannot create " + path; return false; }
    return true;
}
