struct VrtSource {
    std::shared_ptr<RasterDataset> ds;
    int band = 1;
    bool isMask = false;
    int srcX = 0, srcY = 0, srcW = 0, srcH = 0, dstX = 0, dstY = 0, dstW = 0, dstH = 0;
    bool hasRects = false;
    bool complex = false;
    bool hasNoData = false; double noData = 0;
    bool hasScale = false; double scaleOff = 0, scaleRatio = 1;
};

class VrtBand : public RasterBand {
public:
    std::vector<VrtSource> sources;
    bool readBlock(int bx, int by, std::vector<uint8_t>& buf, std::string& err) override {
        int sz = dataTypeSizeBytes(type);
        buf.assign((size_t)blockX * blockY * sz, 0);
        std::vector<double> vals((size_t)blockX * blockY, hasNoData ? noData : 0.0);
        int x0 = bx * blockX, y0 = by * blockY;
        for (auto& s : sources) {
            if (!s.ds || s.band < 1 || s.band > (int)s.ds->bands.size()) continue;
            RasterBand& sb = *s.ds->bands[s.band - 1];
            int sx = s.hasRects ? s.srcX : 0, sy = s.hasRects ? s.srcY : 0, sw = s.hasRects ? s.srcW : sb.xsize, sh = s.hasRects ? s.srcH : sb.ysize;
            int dx = s.hasRects ? s.dstX : 0, dy = s.hasRects ? s.dstY : 0, dw = s.hasRects ? s.dstW : xsize, dh = s.hasRects ? s.dstH : ysize;
            if (dw <= 0 || dh <= 0) continue;
            std::vector<double> src;
            if (!sb.readWindowAsDouble(sx, sy, sw, sh, src, err)) return false;
            for (int y = 0; y < blockY; y++) {
                int gy = y0 + y; if (gy < dy || gy >= dy + dh || gy >= ysize) continue;
                for (int x = 0; x < blockX; x++) {
                    int gx = x0 + x; if (gx < dx || gx >= dx + dw || gx >= xsize) continue;
                    int ssx = (int)((gx - dx + 0.5) * sw / dw), ssy = (int)((gy - dy + 0.5) * sh / dh);
                    ssx = std::min(sw - 1, std::max(0, ssx)); ssy = std::min(sh - 1, std::max(0, ssy));
                    double v = src[(size_t)ssy * sw + ssx];
                    if (s.hasNoData && (v == s.noData || (std::isnan(s.noData) && std::isnan(v)))) continue;
                    if (s.hasScale) v = v * s.scaleRatio + s.scaleOff;
                    vals[(size_t)y * blockX + x] = v;
                }
            }
        }
        for (size_t i = 0; i < vals.size(); i++) doubleToSample(vals[i], buf.data() + i * sz, type);
        return true;
    }
};

std::shared_ptr<RasterDataset> openVRT(const std::string& path, std::string& err, int& errCode) {
    std::string content;
    if (!readFile(path, content)) { err = "cannot read"; errCode = 4; return nullptr; }
    auto root = xmlParse(content, &err);
    if (!root || root->name != "VRTDataset") { err = "`" + path + "' not recognized as being in a supported file format."; errCode = 4; return nullptr; }
    auto ds = std::make_shared<RasterDataset>();
    ds->driverShort = "VRT"; ds->driverLong = "Virtual Raster";
