    ds->ysize = atoi(root->attr("rasterYSize").c_str());
    std::string dir = getDirname(path);
    std::vector<std::string> extraFiles;
    for (auto& c : root->children) {
        if (c->name == "SRS") { CRS crs; if (crs.setFromUserInput(c->textContent())) { ds->hasCRS = true; ds->crs = crs; } }
        else if (c->name == "GeoTransform") { auto parts = splitString(c->textContent(), ','); if (parts.size() == 6) { ds->hasGeoTransform = true; for (int i = 0; i < 6; i++) ds->gt[i] = strtod(parts[i].c_str(), nullptr); } }
        else if (c->name == "Metadata") { std::string dom = c->attr("domain"); for (auto& m : c->children) if (m->name == "MDI") ds->metadata.set(dom, m->attr("key"), m->textContent()); }
        else if (c->name == "VRTRasterBand") {
            auto b = std::make_shared<VrtBand>();
            b->number = (int)ds->bands.size() + 1;
            b->type = dataTypeFromName(c->attr("dataType", "Byte"));
            if (b->type == DataType::Unknown) b->type = DataType::Byte;
            b->xsize = ds->xsize; b->ysize = ds->ysize;
            b->blockX = c->hasAttr("blockXSize") ? atoi(c->attr("blockXSize").c_str()) : std::min(ds->xsize, 128);
            b->blockY = c->hasAttr("blockYSize") ? atoi(c->attr("blockYSize").c_str()) : std::min(ds->ysize, 128);
            for (auto& e : c->children) {
                if (e->name == "Description") b->description = e->textContent();
                else if (e->name == "ColorInterp") b->colorInterp = e->textContent();
                else if (e->name == "NoDataValue") { b->hasNoData = true; std::string t = trimString(e->textContent()); b->noData = iequals(t, "nan") ? NAN : strtod(t.c_str(), nullptr); }
                else if (e->name == "UnitType") b->unitType = e->textContent();
                else if (e->name == "Offset") { b->hasOffset = true; b->offset = strtod(e->textContent().c_str(), nullptr); }
                else if (e->name == "Scale") { b->hasScale = true; b->scale = strtod(e->textContent().c_str(), nullptr); }
                else if (e->name == "Metadata") { std::string dom = e->attr("domain"); for (auto& m : e->children) if (m->name == "MDI") b->metadata.set(dom, m->attr("key"), m->textContent()); }
                else if (e->name == "ColorTable") { b->hasColorTable = true; for (auto& en : e->children) if (en->name == "Entry") { ColorEntry ce; ce.c1 = (short)atoi(en->attr("c1").c_str()); ce.c2 = (short)atoi(en->attr("c2").c_str()); ce.c3 = (short)atoi(en->attr("c3").c_str()); ce.c4 = (short)atoi(en->attr("c4", "255").c_str()); b->colorTable.push_back(ce); } }
                else if (e->name == "SimpleSource" || e->name == "ComplexSource" || e->name == "AveragedSource") {
                    VrtSource s;
                    s.complex = e->name == "ComplexSource";
                    auto fn = e->child("SourceFilename");
                    if (!fn) continue;
                    std::string f = fn->textContent();
                    bool rel = fn->attr("relativeToVRT") == "1";
                    std::string full = (rel && !dir.empty() && (f.empty() || f[0] != '/')) ? dir + "/" + f : f;
                    std::string e2; int c2;
                    s.ds = openRaster(full, e2, c2);
                    if (!s.ds) { cplWarning(1, e2); continue; }
                    bool known = false;
                    for (auto& ef : extraFiles) if (ef == full) known = true;
