    if (orderPos != std::string::npos) { size_t e = (limitPos != std::string::npos && limitPos > orderPos) ? limitPos : rest.size(); orderBy = trimString(rest.substr(orderPos + 10, e - orderPos - 10)); std::string ou = toUpper(orderBy); if (endsWith(ou, " DESC")) { desc = true; orderBy = trimString(orderBy.substr(0, orderBy.size() - 5)); } else if (endsWith(ou, " ASC")) orderBy = trimString(orderBy.substr(0, orderBy.size() - 4)); if (!orderBy.empty() && orderBy[0] == '"') orderBy = orderBy.substr(1, orderBy.size() - 2); }
    if (limitPos != std::string::npos) limit = atoll(rest.c_str() + limitPos + 7);
    auto src = ds.layerByName(layerName);
    if (!src) { err = "SQL Expression Parsing Error: syntax error... Table " + layerName + " not recognised from " + layerName; return nullptr; }
    bool distinct = false;
    if (startsWith(toUpper(colsStr), "DISTINCT ")) { distinct = true; colsStr = trimString(colsStr.substr(9)); }
    auto out = std::make_shared<Layer>();
    out->name = "SELECT";
    out->geomFields = src->geomFields;
    out->fidColumn = src->fidColumn;
    struct Col { int idx; std::string alias; bool count = false; };
    std::vector<Col> cols;
    bool star = colsStr == "*";
    if (star) { for (size_t i = 0; i < src->fields.size(); i++) cols.push_back({(int)i, "", false}); }
    else {
        for (auto& c : splitString(colsStr, ',')) {
