        for (size_t i = 0; i < cols.size(); i++) { if (cols[i].count) { nf.fields[i].unset = false; nf.fields[i].i = (long long)sel.size(); } else if (!sel.empty()) nf.fields[i] = sel[0]->fields[cols[i].idx]; }
