static bool stepRenameLayer(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::string target = a.getString("input-layer");
    std::string newName = a.getString("output-layer");
    bool ascii = a.getBool("ascii"), lower = a.getBool("lower-case"), fnCompat = a.getBool("filename-compatible");
    std::string reserved = a.getString("reserved-characters");
    std::string repl = a.getString("replacement-character", "_");
    long long maxLen = a.isSet("max-length") ? a.getInt("max-length") : -1;
    for (auto& lp : out->layers) {
        if (!target.empty() && lp->name != target) continue;
        std::string n = lp->name;
        if (!newName.empty() && (target.empty() ? out->layers.size() == 1 : true)) n = newName;
        if (fnCompat) reserved += "/\\:*?\"<>|";
        if (ascii || fnCompat) { std::string r; for (unsigned char c : n) r += (c < 0x80) ? (char)c : repl[0]; n = r; }
        if (lower) for (auto& c : n) c = (char)tolower((unsigned char)c);
        if (!reserved.empty()) { std::string r; for (char c : n) r += (reserved.find(c) != std::string::npos) ? repl[0] : c; n = r; }
        if (maxLen > 0 && (long long)n.size() > maxLen) n = n.substr(0, (size_t)maxLen);
        lp->name = n;
    }
    d.vector = out;
    return true;
}

static bool parseFieldTypeSpec(const std::string& s, FieldType& t, FieldSubType& st) {
    st = FieldSubType::None;
    std::string u = s;
    size_t p = u.find('(');
    std::string base = u, sub;
    if (p != std::string::npos) { base = u.substr(0, p); sub = u.substr(p + 1, u.size() - p - 2); }
    static const FieldType all[] = {FieldType::Integer, FieldType::IntegerList, FieldType::Real, FieldType::RealList, FieldType::String, FieldType::StringList, FieldType::Binary, FieldType::Date, FieldType::Time, FieldType::DateTime, FieldType::Integer64, FieldType::Integer64List};
    bool found = false;
    for (auto ft : all) if (iequals(base, fieldTypeName(ft))) { t = ft; found = true; }
    if (!found) {
        if (iequals(base, "Boolean")) { t = FieldType::Integer; st = FieldSubType::Boolean; return true; }
        if (iequals(base, "Int16")) { t = FieldType::Integer; st = FieldSubType::Int16; return true; }
        if (iequals(base, "Float32")) { t = FieldType::Real; st = FieldSubType::Float32; return true; }
        if (iequals(base, "JSON")) { t = FieldType::String; st = FieldSubType::JSON; return true; }
        if (iequals(base, "UUID")) { t = FieldType::String; st = FieldSubType::UUID; return true; }
        return false;
    }
    if (!sub.empty()) st = fieldSubTypeFromName(sub);
    return true;
}

static void convertValue(FieldValue& v, const FieldDef& from, const FieldDef& to) {
    if (v.isNull() || v.unset) return;
    std::string s = fieldValueAsString(v, from);
    FieldValue nv; nv.unset = false;
    switch (to.type) {
        case FieldType::Integer: case FieldType::Integer64:
            if (from.type == FieldType::Real) nv.i = (long long)v.d; else if (from.type == FieldType::Integer || from.type == FieldType::Integer64) nv.i = v.i; else nv.i = atoll(s.c_str());
            if (to.subType == FieldSubType::Boolean) nv.i = nv.i != 0;
            break;
        case FieldType::Real:
            if (from.type == FieldType::Integer || from.type == FieldType::Integer64) nv.d = (double)v.i; else if (from.type == FieldType::Real) nv.d = v.d; else nv.d = strtod(s.c_str(), nullptr);
            break;
        case FieldType::String: nv.s = s; break;
        case FieldType::IntegerList: case FieldType::Integer64List: if (from.type == FieldType::IntegerList || from.type == FieldType::Integer64List) nv.il = v.il; else if (from.type == FieldType::RealList) for (auto x : v.dl) nv.il.push_back((long long)x); else nv.il.push_back(atoll(s.c_str())); break;
        case FieldType::RealList: if (from.type == FieldType::RealList) nv.dl = v.dl; else if (from.type == FieldType::IntegerList || from.type == FieldType::Integer64List) for (auto x : v.il) nv.dl.push_back((double)x); else nv.dl.push_back(strtod(s.c_str(), nullptr)); break;
        case FieldType::StringList: if (from.type == FieldType::StringList) nv.sl = v.sl; else nv.sl.push_back(s); break;
        default: nv = v; break;
    }
    v = nv;
}

static bool stepSetFieldType(Algorithm& a, PipelineData& d) {
    auto out = cloneDataset(*d.vector);
    std::string fieldName = a.getString("field-name");
    std::string srcType = a.getString("src-field-type");
    FieldType dt; FieldSubType dst;
    if (!parseFieldTypeSpec(a.getString("field-type"), dt, dst)) { a.reportError(5, "Invalid value for 'field-type' argument"); return false; }
    FieldType sft = FieldType::String; FieldSubType sst = FieldSubType::None;
    if (!srcType.empty() && !parseFieldTypeSpec(srcType, sft, sst)) { a.reportError(5, "Invalid value for 'src-field-type' argument"); return false; }
    for (auto& lp : out->layers) {
        Layer& l = *lp;
        if (!layerActive(a, l)) continue;
        for (size_t i = 0; i < l.fields.size(); i++) {
            FieldDef& f = l.fields[i];
            bool match = !fieldName.empty() ? iequals(f.name, fieldName) : (f.type == sft && (sst == FieldSubType::None || f.subType == sst));
            if (!match) continue;
            FieldDef nf = f; nf.type = dt; nf.subType = dst; nf.width = 0; nf.precision = 0;
            for (auto& feat : l.features) if (i < feat.fields.size()) convertValue(feat.fields[i], f, nf);
            f = nf;
        }
    }
    d.vector = out;
    return true;
}

static uint32_t hilbertIndex(uint32_t x, uint32_t y, int order) {
    uint32_t rx, ry, s, dd = 0;
    uint32_t n = 1u << order;
    for (s = n / 2; s > 0; s /= 2) {
        rx = (x & s) > 0; ry = (y & s) > 0;
