static bool parseGeomTypeName(const std::string& gt, GeomType& t, bool& z, bool& m) {
    std::string u = toUpper(trimString(gt));
    z = m = false;
    if (endsWith(u, "ZM")) { z = m = true; u = trimString(u.substr(0, u.size() - 2)); }
    else if (endsWith(u, "Z") && u != "Z") { z = true; u = trimString(u.substr(0, u.size() - 1)); }
    else if (endsWith(u, "M") && u != "M") { m = true; u = trimString(u.substr(0, u.size() - 1)); }
    if (u == "POINT") t = GeomType::Point; else if (u == "LINESTRING") t = GeomType::LineString; else if (u == "POLYGON") t = GeomType::Polygon;
    else if (u == "MULTIPOINT") t = GeomType::MultiPoint; else if (u == "MULTILINESTRING") t = GeomType::MultiLineString; else if (u == "MULTIPOLYGON") t = GeomType::MultiPolygon;
    else if (u == "GEOMETRYCOLLECTION") t = GeomType::GeometryCollection; else if (u == "GEOMETRY" || u == "UNKNOWN") t = GeomType::Unknown; else if (u == "NONE") t = GeomType::None;
    else return false;
    return true;
}

static int runVectorCreate(Algorithm& a) {
    std::string out = a.getString("output");
    auto ds = std::make_shared<VectorDataset>();
    ds->driverShort = "MEM"; ds->description = out;
    std::vector<std::string> inputs = a.getStringList("input");
    std::vector<std::shared_ptr<Layer>> layers;
    if (!inputs.empty()) {
        std::string err; int code = 0;
        auto like = openVector(inputs[0], err, code, a.getStringList("input-format"), a.getStringList("open-option"));
        if (!like) { cplError(code, err); a.printUsageOnError(); return 1; }
        std::vector<std::string> sel = a.getStringList("input-layer");
        for (auto& l : like->layers) {
            bool ok = sel.empty();
            for (auto& n : sel) if (n == l->name) ok = true;
            if (!ok) continue;
            auto nl = std::make_shared<Layer>(*l);
            nl->features.clear();
            layers.push_back(nl);
        }
    } else {
        auto l = std::make_shared<Layer>();
        l->name = a.isSet("output-layer") ? a.getString("output-layer") : stripExtension(getBasename(out));
        GeomFieldDef gf;
        gf.name = a.getString("geometry-field", "geom");
        gf.type = GeomType::Unknown;
        if (a.isSet("geometry-type")) {
            if (!parseGeomTypeName(a.getString("geometry-type"), gf.type, gf.hasZ, gf.hasM)) { a.reportError(5, "Invalid value for 'geometry-type' argument"); return 1; }
        }
        if (a.isSet("crs")) { CRS c; if (!c.setFromUserInput(a.getString("crs"))) { a.reportError(5, "Invalid value for 'crs' argument"); return 1; } gf.hasCRS = true; gf.crs = c; }
        if (gf.type != GeomType::None) l->geomFields.push_back(gf);
        for (auto& fs : a.getStringList("field")) {
            size_t c = fs.find(':');
            if (c == std::string::npos) { a.reportError(5, "Invalid value for argument 'field'. <NAME>:<TYPE>[(,<WIDTH>[,<PRECISION>])] expected"); return 1; }
            FieldDef f;
            f.name = fs.substr(0, c);
            std::string ts = fs.substr(c + 1);
            size_t p = ts.find('(');
            std::string tn = p == std::string::npos ? ts : ts.substr(0, p);
            if (p != std::string::npos) {
                std::string wp = ts.substr(p + 1);
                if (!wp.empty() && wp.back() == ')') wp.pop_back();
                auto parts = splitString(wp, ',');
                if (!parts.empty()) f.width = atoi(parts[0].c_str());
                if (parts.size() > 1) f.precision = atoi(parts[1].c_str());
            }
            static const FieldType all[] = {FieldType::Integer, FieldType::IntegerList, FieldType::Real, FieldType::RealList, FieldType::String, FieldType::StringList, FieldType::Binary, FieldType::Date, FieldType::Time, FieldType::DateTime, FieldType::Integer64, FieldType::Integer64List};
            bool found = false;
            for (auto ft : all) if (iequals(tn, fieldTypeName(ft))) { f.type = ft; found = true; }
            if (!found) {
                if (iequals(tn, "Boolean")) { f.type = FieldType::Integer; f.subType = FieldSubType::Boolean; }
                else if (iequals(tn, "Int16")) { f.type = FieldType::Integer; f.subType = FieldSubType::Int16; }
                else if (iequals(tn, "Float32")) { f.type = FieldType::Real; f.subType = FieldSubType::Float32; }
                else if (iequals(tn, "JSON")) { f.type = FieldType::String; f.subType = FieldSubType::JSON; }
                else if (iequals(tn, "UUID")) { f.type = FieldType::String; f.subType = FieldSubType::UUID; }
                else { a.reportError(5, "Invalid field type '" + tn + "'"); return 1; }
            }
            l->fields.push_back(f);
        }
        if (a.isSet("fid")) l->fidColumn = a.getString("fid");
        layers.push_back(l);
    }
    bool progress = !a.getBool("quiet");
    (void)progress;
    if (!writeVectorOutput(a, *ds, layers, out, a.getString("output-format"), a.getStringList("layer-creation-option"), false, a.getString("output-layer"))) return 1;
    return 0;
}

void registerVectorCreate(Algorithm* root) {
    if (Algorithm* v = root->findSub("vector")) if (Algorithm* c = v->findSub("create")) c->runFn = runVectorCreate;
}
