#include "pipeline.h"
#include "util.h"
#include <cmath>
#include <cstring>
#include <algorithm>
#include <functional>
#include <xmmintrin.h>
#include <emmintrin.h>

static const double kDeg2Rad = M_PI / 180.0;

static inline double approxADivByInvSqrtB(double a, double b) {
    __m128d regB = _mm_load_sd(&b);
    __m128d regB_half = _mm_mul_sd(regB, _mm_set1_pd(0.5));
    regB = _mm_cvtss_sd(regB, _mm_rsqrt_ss(_mm_cvtsd_ss(_mm_setzero_ps(), regB)));
    regB = _mm_mul_sd(regB, _mm_sub_sd(_mm_set1_pd(1.5), _mm_mul_sd(regB_half, _mm_mul_sd(regB, regB))));
    double dOut;
    _mm_store_sd(&dOut, regB);
    return a * dOut;
}

struct DemParams {
    double ewres = 1, nsres = -1, xscale = 1, yscale = 1, z = 1;
    bool zt = false;  // ZevenbergenThorne
    // slope
    bool percent = false;
    // aspect
    bool azimuth = true, zeroForFlat = false;
    // hillshade
    double az = 315, alt = 45;
    std::string variant = "regular";
};

typedef std::function<float(const double* w, float dstNoData, const DemParams& p)> DemFn;

static void gradient(const double* w, const DemParams& p, double& dx, double& dy) {
    if (p.zt) {
        dx = (w[3] - w[5]) / (2 * p.ewres * p.xscale);
        dy = (w[7] - w[1]) / (2 * p.nsres * p.yscale);
    } else {
        dx = ((w[0] + w[3] + w[3] + w[6]) - (w[2] + w[5] + w[5] + w[8])) / (8 * p.ewres * p.xscale);
        dy = ((w[6] + w[7] + w[7] + w[8]) - (w[0] + w[1] + w[1] + w[2])) / (8 * p.nsres * p.yscale);
    }
}

static float slopeAlg(const double* w, float, const DemParams& p) {
    double dx, dy;
    gradient(w, p, dx, dy);
    double key = dx * dx + dy * dy;
    if (!p.percent) return (float)(atan(sqrt(key)) * (180.0 / M_PI));
    return (float)(100 * sqrt(key));
}

static float aspectAlg(const double* w, float dstNoData, const DemParams& p) {
    double dx, dy;
    if (p.zt) { dx = w[5] - w[3]; dy = w[7] - w[1]; }
    else { dx = ((w[2] + w[5] + w[5] + w[8]) - (w[0] + w[3] + w[3] + w[6])); dy = ((w[6] + w[7] + w[7] + w[8]) - (w[0] + w[1] + w[1] + w[2])); }
    float aspect = (float)(atan2(dy, -dx) / kDeg2Rad);
    if (dx == 0 && dy == 0) return p.zeroForFlat ? 0.0f : dstNoData;
    if (p.azimuth) { if (aspect > 90.0f) aspect = 450.0f - aspect; else aspect = 90.0f - aspect; }
    else aspect += 180.0f;
    if (aspect == 360.0f) aspect = 0.0f;
    return aspect;
}

static float hillshadeAlg(const double* w, float, const DemParams& p) {
    double x, y;
    if (p.zt) { x = (w[3] - w[5]) / (p.ewres * p.xscale); y = (w[7] - w[1]) / (p.nsres * p.yscale); }
    else { x = ((w[0] + w[3] + w[3] + w[6]) - (w[2] + w[5] + w[5] + w[8])) / (p.ewres * p.xscale); y = ((w[6] + w[7] + w[7] + w[8]) - (w[0] + w[1] + w[1] + w[2])) / (p.nsres * p.yscale); }
    double zs = p.z / (p.zt ? 2.0 : 8.0);
    double altR = p.alt * kDeg2Rad, azR = p.az * kDeg2Rad;
    double xx_plus_yy = x * x + y * y;
    if (p.variant == "combined") {
        double slope = atan(sqrt(xx_plus_yy) * zs);
        double aspect = atan2(y, x);
        double cang = (sin(altR) * cos(slope) + cos(altR) * sin(slope) * cos(azR - M_PI / 2 - aspect)) / M_PI * acos(sqrt(xx_plus_yy) * zs / sqrt(1 + zs * zs * xx_plus_yy)) ;
        // GDAL: cang = acos(cang) ... simplified approximation
        cang = (sin(altR) - (y * cos(azR) * cos(altR) * zs - x * sin(azR) * cos(altR) * zs)) / sqrt(1 + zs * zs * xx_plus_yy);
        double slopeAngle = acos(1.0 / sqrt(1 + zs * zs * xx_plus_yy));
        cang = cang * (1 - slopeAngle / (M_PI / 2));
        return (float)(cang <= 0.0 ? 1.0 : 1.0 + 254.0 * cang);
    }
    if (p.variant == "multidirectional") {
        double sinAlt = sin(altR), cosAlt = cos(altR);
        double slope = sqrt(xx_plus_yy) * zs;
        double aspect = atan2(y, x);
        double sum = 0;
        double azimuths[4] = {225, 270, 315, 360};
        double weights[4];
        double wsum = 0;
        for (int i = 0; i < 4; i++) { double a = azimuths[i] * kDeg2Rad; weights[i] = pow(sin(aspect - a + M_PI / 2), 2); wsum += weights[i]; }
        (void)wsum;
        double denom = sqrt(1 + slope * slope);
        for (int i = 0; i < 4; i++) {
            double a = azimuths[i] * kDeg2Rad;
            double cang = (sinAlt - (y * cos(a) * cosAlt * zs - x * sin(a) * cosAlt * zs)) / denom;
            if (cang < 0) cang = 0;
            sum += weights[i] * cang;
        }
        double cang = sum / 2.0;
        return (float)(cang <= 0.0 ? 1.0 : 1.0 + 254.0 * cang);
    }
    if (p.variant == "Igor") {
        double slope = atan(sqrt(xx_plus_yy) * zs);
        double aspect = atan2(y, x);
        double slopeStrength = slope / (M_PI / 2);
        double aspectDiff = fmod(fabs(aspect - (azR - M_PI / 2)) , 2 * M_PI);
        if (aspectDiff > M_PI) aspectDiff = 2 * M_PI - aspectDiff;
        double aspectStrength = 1 - aspectDiff / M_PI;
        double shadow = slopeStrength * aspectStrength;
        return (float)(255.0 - shadow * 254.0);
    }
    double sinAlt254 = 254.0 * sin(altR);
    double cosAzCosAltZ254 = 254.0 * cos(azR) * cos(altR) * zs;
    double sinAzCosAltZ254 = 254.0 * sin(azR) * cos(altR) * zs;
    double cang254 = approxADivByInvSqrtB(sinAlt254 - (y * cosAzCosAltZ254 - x * sinAzCosAltZ254), 1 + zs * zs * xx_plus_yy);
    double cang = cang254 <= 0.0 ? 1.0 : 1.0 + cang254;
    return (float)cang;
}

static float triAlg(const double* w, float, const DemParams& p) {
    (void)p;
    // Wilson: mean of absolute differences
    double sum = 0;
    for (int i = 0; i < 9; i++) if (i != 4) sum += fabs(w[i] - w[4]);
    return (float)(sum / 8.0);
}
static float tpiAlg(const double* w, float, const DemParams&) {
    double sum = 0;
    for (int i = 0; i < 9; i++) if (i != 4) sum += w[i];
    return (float)(w[4] - sum / 8.0);
}
static float roughnessAlg(const double* w, float, const DemParams&) {
    double mn = w[0], mx = w[0];
    for (int i = 1; i < 9; i++) { mn = std::min(mn, w[i]); mx = std::max(mx, w[i]); }
    return (float)(mx - mn);
}

static bool runDem(Algorithm& a, PipelineData& d, DemFn fn, DataType outType, float dstNoData, DemParams& p, bool useScale) {
    if (!d.raster) { a.reportError(1, "No input dataset"); return false; }
    RasterDataset& src = *d.raster;
    int bandIdx = a.isSet("band") ? (int)a.getInt("band") : 1;
    if (bandIdx < 1 || bandIdx > (int)src.bands.size()) { a.reportError(5, strprintf("Invalid band number %d", bandIdx)); return false; }
    RasterBand& b = *src.bands[bandIdx - 1];
    bool computeEdges = !a.getBool("no-edges");
    if (src.hasGeoTransform) { p.ewres = src.gt[1]; p.nsres = src.gt[5]; }
    if (useScale) {
        bool xs = a.isSet("xscale"), ys = a.isSet("yscale");
        if (xs) p.xscale = a.getReal("xscale");
        if (ys) p.yscale = a.getReal("yscale");
        if (!xs && !ys && src.hasCRS && src.crs.isGeographic() && src.hasGeoTransform) {
            double cx, cy;
            src.pixelToGeo(src.xsize / 2.0, src.ysize / 2.0, cx, cy);
            p.yscale = 111120.0;
            p.xscale = 111120.0 * cos(cy * kDeg2Rad);
        }
    }
    std::string err;
    std::vector<double> vals;
    if (!b.readAsDouble(vals, err)) { a.reportError(1, err); return false; }
    int W = src.xsize, H = src.ysize;
    bool hasND = b.hasNoData;
    double nd = b.noData;
    bool ndNan = hasND && std::isnan(nd);
    auto isND = [&](double v) { return hasND && (ndNan ? std::isnan(v) : v == nd); };
    auto interp = [&](double x, double y) { if (hasND && (isND(x) || isND(y))) return nd; return 2 * x - y; };
    std::vector<float> out((size_t)W * H, dstNoData);
    auto compute = [&](double* w) -> float {
        if (isND(w[4])) return dstNoData;
        if (hasND) for (int k = 0; k < 9; k++) if (isND(w[k])) { if (computeEdges) w[k] = w[4]; else return dstNoData; }
        return fn(w, dstNoData, p);
    };
    auto V = [&](int y, int x) { return vals[(size_t)y * W + x]; };
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            double w[9];
            bool edgeRow = (y == 0 || y == H - 1), edgeCol = (x == 0 || x == W - 1);
            if (!edgeRow && !edgeCol) {
                w[0] = V(y - 1, x - 1); w[1] = V(y - 1, x); w[2] = V(y - 1, x + 1);
                w[3] = V(y, x - 1); w[4] = V(y, x); w[5] = V(y, x + 1);
                w[6] = V(y + 1, x - 1); w[7] = V(y + 1, x); w[8] = V(y + 1, x + 1);
            } else {
                if (!computeEdges || W < 2 || H < 2) { out[(size_t)y * W + x] = dstNoData; continue; }
                if (edgeRow) {
                    int jmin = x == 0 ? x : x - 1, jmax = x == W - 1 ? x : x + 1;
                    int y1 = y, y2 = (y == 0) ? 1 : H - 2;
                    double a0 = interp(V(y1, jmin), V(y2, jmin)), a1 = interp(V(y1, x), V(y2, x)), a2 = interp(V(y1, jmax), V(y2, jmax));
                    if (y == 0) {
                        w[0] = a0; w[1] = a1; w[2] = a2;
                        w[3] = V(y1, jmin); w[4] = V(y1, x); w[5] = V(y1, jmax);
                        w[6] = V(y2, jmin); w[7] = V(y2, x); w[8] = V(y2, jmax);
                    } else {
                        w[0] = V(y2, jmin); w[1] = V(y2, x); w[2] = V(y2, jmax);
                        w[3] = V(y1, jmin); w[4] = V(y1, x); w[5] = V(y1, jmax);
                        w[6] = a0; w[7] = a1; w[8] = a2;
                    }
                } else {
                    // edge column, interior row
                    int xo = x == 0 ? x + 1 : x - 1;
                    double l0 = interp(V(y - 1, x), V(y - 1, xo)), l1 = interp(V(y, x), V(y, xo)), l2 = interp(V(y + 1, x), V(y + 1, xo));
