                        w[6] = l2; w[7] = V(y + 1, x); w[8] = V(y + 1, xo);
                    } else {
                        w[0] = V(y - 1, xo); w[1] = V(y - 1, x); w[2] = l0;
                        w[3] = V(y, xo); w[4] = V(y, x); w[5] = l1;
                        w[6] = V(y + 1, xo); w[7] = V(y + 1, x); w[8] = l2;
                    }
                }
            }
            out[(size_t)y * W + x] = compute(w);
        }
    }
    auto ods = cloneRasterHeader(src);
    auto mb = std::make_shared<MemBand>();
    mb->number = 1; mb->type = outType; mb->xsize = W; mb->ysize = H; mb->blockX = W; mb->blockY = 1;
    mb->colorInterp = outType == DataType::Byte ? "Gray" : "Undefined";
    mb->hasNoData = true; mb->noData = dstNoData;
    int sz = dataTypeSizeBytes(outType);
    mb->data.assign((size_t)W * H * sz, 0);
    for (size_t i = 0; i < out.size(); i++) {
        if (outType == DataType::Byte) { float v = out[i]; int iv = (int)(v + 0.5f); if (iv < 0) iv = 0; if (iv > 255) iv = 255; mb->data[i] = (uint8_t)iv; }
