}
static bool stepHillshade(Algorithm& a, PipelineData& d) {
    DemParams p;
    p.zt = iequals(a.getString("gradient-alg", "Horn"), "ZevenbergenThorne");
    p.z = a.isSet("zfactor") ? a.getReal("zfactor") : 1.0;
