$E raster create --size 5,5 --ot Float32 --burn 100 --crs EPSG:32632 --bbox 0,0,50,50 dem.tif --overwrite; $E raster hillshade dem.tif hs.tif --overwrite -q; $E raster info --checksum hs.tif | tail -3; $E raster slope dem.tif sl.tif --overwrite -q; $E raster pixel-info -p 2,2 sl.tif | grep value

